/// Animation playback state for the editor.
#[derive(Debug, Clone)]
pub struct AnimationPlaybackState {
    /// Whether an animation is currently playing.
    pub playing: bool,
    /// The name of the animation being played.
    pub animation_name: Option<String>,
    /// The current playback time in seconds.
    pub current_time: f64,
    /// Whether keyframe recording mode is active.
    pub recording: bool,
    /// Secondary animation for blend preview (if any).
    pub blend_secondary: Option<String>,
    /// Blend weight: 0.0 = fully primary, 1.0 = fully secondary.
    pub blend_weight: f32,
}

/// A single function timing entry in a profiler frame snapshot.
#[derive(Debug, Clone)]
pub struct ProfilerFuncEntry {
    /// Function or subsystem name (e.g. "physics_step", "render_2d", "script_process").
    pub name: String,
    /// Inclusive time spent in this function in milliseconds (incl. callees).
    pub time_ms: f64,
    /// Self time — only the time spent in this function itself (pat-wykfm).
    pub self_ms: f64,
    /// Number of times this function was called this frame (pat-wykfm).
    pub calls: u64,
}

/// A snapshot of one frame's profiling data.
#[derive(Debug, Clone)]
pub struct ProfilerFrame {
    /// Frame number.
    pub frame_number: u64,
    /// Total frame time in milliseconds.
    pub total_ms: f64,
    /// CPU time in milliseconds.
    pub cpu_ms: f64,
    /// GPU time in milliseconds (estimated or 0 if unavailable).
    pub gpu_ms: f64,
    /// Physics process time in milliseconds (pat-wykfm: Physics Frame % mode).
    pub physics_ms: f64,
    /// Per-function timing breakdown.
    pub functions: Vec<ProfilerFuncEntry>,
}

/// State for an in-progress drag operation.
#[derive(Debug, Clone)]
pub struct DragState {
    /// The node being dragged.
    pub node_id: NodeId,
    /// The pixel position where the drag started.
    pub start_pixel: Vector2,
    /// The node's position when the drag started.
    pub start_node_pos: Vector2,
    /// Camera offset at drag start (frozen so bounds changes don't affect drag).
    pub camera_offset: Vector2,
}

/// A single log entry in the editor's operation log.
#[derive(Debug, Clone)]
pub struct LogEntry {
    /// Unix timestamp in milliseconds.
    pub timestamp: u64,
    /// Log level: "info", "warn", or "error".
    pub level: String,
    /// Human-readable log message.
    pub message: String,
}

/// Maximum number of log entries to keep.
const MAX_LOG_ENTRIES: usize = 100;

/// Maximum number of frame time entries to keep.
const MAX_FRAME_TIMES: usize = 120;

/// Editor display settings that can be persisted.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct EditorDisplaySettings {
    pub grid_snap_enabled: bool,
    pub grid_snap_size: u32,
    pub grid_visible: bool,
    pub rulers_visible: bool,
    pub background_color: [f64; 4],
    pub font_size: String,
    /// Color theme: "dark" or "light".
    pub theme: String,
    /// Physics ticks per second.
    pub physics_fps: u32,
    /// Saved panel sizes for layout persistence.
    pub panel_sizes: std::collections::HashMap<String, f64>,
    /// Whether smart snapping (alignment guides to sibling nodes) is enabled.
    pub smart_snap_enabled: bool,
    /// Distance threshold in world-space pixels for smart snap to engage.
    pub smart_snap_threshold: f32,
}
impl Default for EditorDisplaySettings {
    fn default() -> Self {
        Self {
            grid_snap_enabled: false,
            grid_snap_size: 8,
            grid_visible: true,
            rulers_visible: true,
            background_color: [0.08, 0.08, 0.1, 1.0],
            font_size: "medium".to_string(),
            theme: "dark".to_string(),
            physics_fps: 60,
            panel_sizes: std::collections::HashMap::new(),
            smart_snap_enabled: true,
            smart_snap_threshold: 5.0,
        }
    }
}

/// A snap guide line for rendering in the viewport.
#[derive(Debug, Clone, PartialEq)]
pub struct SnapGuide {
    /// "x" for vertical guide, "y" for horizontal guide.
    pub axis: &'static str,
    /// The world-space coordinate of the guide line.
    pub position: f32,
    /// The node being snapped to (for display purposes).
    pub target_node_id: NodeId,
}

/// Snap a position to the grid if grid snapping is enabled.
pub fn snap_to_grid(pos: Vector2, grid_size: u32) -> Vector2 {
    let g = grid_size as f32;
    Vector2::new((pos.x / g).round() * g, (pos.y / g).round() * g)
}

/// Compute smart snap guides by comparing a candidate position against sibling nodes.
pub fn compute_smart_snap(
    tree: &SceneTree,
    dragged_id: NodeId,
    candidate_pos: Vector2,
    threshold: f32,
) -> (Vector2, Vec<SnapGuide>) {
    use crate::scene_renderer::{extract_position, extract_size};

    let mut guides = Vec::new();
    let mut snapped = candidate_pos;
    let mut best_dx: f32 = threshold + 1.0;
    let mut best_dy: f32 = threshold + 1.0;

    let dragged_size = tree
        .get_node(dragged_id)
        .map(|n| extract_size(n))
        .unwrap_or(Vector2::ZERO);
    let parent_id = tree
        .get_node(dragged_id)
        .and_then(|n| n.parent())
        .unwrap_or_else(|| tree.root_id());
    let sibling_ids: Vec<NodeId> = tree
        .get_node(parent_id)
        .map(|n| n.children().to_vec())
        .unwrap_or_default();
    let siblings: Vec<(NodeId, Vector2, Vector2)> = sibling_ids
        .iter()
        .filter(|&&nid| nid != dragged_id)
        .filter_map(|&nid| {
            tree.get_node(nid)
                .map(|n| (nid, extract_position(n), extract_size(n)))
        })
        .collect();

    for &(nid, sib_pos, sib_size) in &siblings {
        let snap_xs: [(f32, f32); 3] = [
            (candidate_pos.x, sib_pos.x),
            (
                candidate_pos.x,
                sib_pos.x - sib_size.x / 2.0 + dragged_size.x / 2.0,
            ),
            (
                candidate_pos.x,
                sib_pos.x + sib_size.x / 2.0 - dragged_size.x / 2.0,
            ),
        ];
        for (cand_x, target_x) in snap_xs {
            let dx = (cand_x - target_x).abs();
            if dx < threshold && dx < best_dx {
                best_dx = dx;
                snapped.x = target_x;
                guides.retain(|g: &SnapGuide| g.axis != "x");
                guides.push(SnapGuide {
                    axis: "x",
                    position: target_x,
                    target_node_id: nid,
                });
            }
        }
        let snap_ys: [(f32, f32); 3] = [
            (candidate_pos.y, sib_pos.y),
            (
                candidate_pos.y,
                sib_pos.y - sib_size.y / 2.0 + dragged_size.y / 2.0,
            ),
            (
                candidate_pos.y,
                sib_pos.y + sib_size.y / 2.0 - dragged_size.y / 2.0,
            ),
        ];
        for (cand_y, target_y) in snap_ys {
            let dy = (cand_y - target_y).abs();
            if dy < threshold && dy < best_dy {
                best_dy = dy;
                snapped.y = target_y;
                guides.retain(|g: &SnapGuide| g.axis != "y");
                guides.push(SnapGuide {
                    axis: "y",
                    position: target_y,
                    target_node_id: nid,
                });
            }
        }
    }
    (snapped, guides)
}

/// Apply all enabled snap modes to a candidate position.
pub fn apply_snap(
    tree: &SceneTree,
    settings: &EditorDisplaySettings,
    ruler_guides: &crate::guides::GuideSet,
    dragged_id: NodeId,
    candidate_pos: Vector2,
) -> (Vector2, Vec<SnapGuide>) {
    let mut pos = candidate_pos;
    if settings.grid_snap_enabled {
        pos = snap_to_grid(pos, settings.grid_snap_size);
    }
    // Ruler-dragged guides (pat-0q2kx.172). `GuideSet` implemented
    // create/move/remove/snap with its own tests but had no callers anywhere, so
    // a guide could never affect a drag. Applied before smart-snap so an
    // explicitly placed guide wins over an inferred sibling alignment — placing
    // a guide is a deliberate act, sibling alignment is a guess.
    //
    // Gated on guides *existing* rather than on a new settings flag: with none
    // placed this is a no-op, so no existing drag behaviour changes and no
    // settings construction site needs updating.
    if !ruler_guides.is_empty() {
        pos = ruler_guides.snap(pos, settings.smart_snap_threshold, true);
    }
    if settings.smart_snap_enabled {
        let (snapped, guides) =
            compute_smart_snap(tree, dragged_id, pos, settings.smart_snap_threshold);
        return (snapped, guides);
    }
    (pos, Vec::new())
}
/// Serialized node data for the copy/paste clipboard.
#[derive(Debug, Clone)]
pub struct ClipboardEntry {
    pub name: String,
    pub class_name: String,
    pub properties: Vec<(String, Variant)>,
    pub children: Vec<ClipboardEntry>,
}

/// One recorded Movie Maker frame (pat-nzgdu.171). Godot's Movie Maker writes
/// each rendered frame to a video container; a runtime step here produces a
/// [`gdscene::main_loop::FrameOutput`] (frame number + timing), not pixels, so
/// the downloadable sequence is per-frame metadata captured at a fixed timestep.
/// Encoding the actual viewport pixels per frame is a follow-up (the runtime
/// step does not currently rasterize a frame; `GET /api/editor/viewport.png`
/// renders the editor viewport, not the running MainLoop's tree).
#[derive(Debug, Clone)]
pub struct MovieFrame {
    /// 1-indexed frame number, matching `runtime_frame_count`.
    pub index: u64,
    /// Game time at the end of this frame (seconds), accumulated at the fixed
    /// movie timestep.
    pub time: f64,
}

/// Shared editor state protected by a mutex.
pub struct EditorState {
    /// The plugin whose main screen is currently shown, if any (pat-s3rrv.66).
    ///
    /// Godot's main-screen bar shows one editor at a time — selecting a
    /// plugin's tab hides the one it replaced. Recording the choice is what
    /// lets a later request know which plugin to hide.
    pub main_screen_plugin: Option<String>,
    /// The scene tree being edited.
    pub scene_tree: SceneTree,
    /// The currently selected node, if any.
    pub selected_node: Option<NodeId>,
    /// Undo stack (most recent command on top).
    pub undo_stack: Vec<EditorCommand>,
    /// Redo stack (cleared on new command).
    pub redo_stack: Vec<EditorCommand>,
    /// The latest rendered frame, if any.
    pub frame_buffer: Option<FrameBuffer>,
    /// Cached PNG encoding of the frame buffer (avoids re-encoding on every poll).
    pub cached_png: Option<Vec<u8>>,
    /// Cached BMP encoding of the frame buffer.
    pub cached_bmp: Option<Vec<u8>>,
    /// Current drag operation, if any.
    pub drag_state: Option<DragState>,
    /// Viewport width for hit testing.
    pub viewport_width: u32,
    /// Viewport height for hit testing.
    pub viewport_height: u32,
    /// Browser-reported render size for the editor viewport, in CSS pixels.
    /// The frontend posts the real `#viewport-container` dimensions to
    /// `POST /api/viewport/resize` so the render loop draws at the panel's
    /// aspect ratio and fills it edge-to-edge — matching Godot, which renders
    /// into the whole viewport — instead of a fixed 640x480 frame that
    /// letterboxes into a centered square. Clamped to [64, 2048] per axis by
    /// the resize endpoint; readers treat values < 64 as "use the default".
    pub render_width: u32,
    /// See [`render_width`](Self::render_width).
    pub render_height: u32,
    /// Current viewport zoom level (1.0 = 100%).
    pub viewport_zoom: f64,
    /// Current viewport pan offset in pixels (x, y).
    pub viewport_pan: (f64, f64),
    /// Ring buffer of recent editor log entries.
    pub log_entries: VecDeque<LogEntry>,
    /// The currently loaded scene file path, if any.
    pub scene_file: Option<String>,
    /// Absolute path of the opened project root (the res:// root), if any.
    /// Set by `POST /api/project/open`; used to resolve a loaded scene's res://
    /// path so the inspector can emit SubResource `resource_path`s (pat-ghfv0.40).
    pub project_root: Option<String>,
    /// Whether the scene has unsaved modifications.
    pub scene_modified: bool,
    /// pat-m6rbm: undo-stack depth recorded at the last save/load point. The
    /// scene is considered clean when the current `undo_stack.len()` equals
    /// this value, so undoing back to the saved state clears the dirty flag
    /// and redoing past it sets it again (Godot save-point semantics). Forward
    /// mutations always set `scene_modified = true` explicitly, which also
    /// covers the case where a new edit lands at the saved depth after the
    /// redo stack was discarded.
    pub saved_undo_depth: usize,
    pub selected_nodes: Vec<NodeId>,
    /// Inspector navigation history: the stack of previously inspected nodes,
    /// with `inspector_history_index` pointing at the current position. Drives
    /// the inspector Back/Forward buttons.
    pub inspector_history: Vec<NodeId>,
    pub inspector_history_index: usize,
    /// pat-didnj: Monotonic per-node version counter for optimistic concurrency
    /// control on the PATCH endpoint. Missing entries are treated as version 0.
    pub node_versions: HashMap<NodeId, u64>,
    /// pat-zzgh5: WebSocket subscribers for `/api/events`. Each entry is a
    /// channel sender owned by an upgraded connection. `publish_event` clones
    /// the message into each sender and prunes entries whose receiver has
    /// hung up. Stored on the state so mutation handlers can broadcast under
    /// the same lock they already hold.
    pub event_subscribers: Vec<std::sync::mpsc::Sender<String>>,
    pub clipboard: Vec<ClipboardEntry>,
    pub display_settings: EditorDisplaySettings,
    /// Ruler-dragged guide lines (pat-0q2kx.172). Godot persists these as the
    /// `_edit_horizontal_guides_` / `_edit_vertical_guides_` scene metadata.
    pub guides: crate::guides::GuideSet,
    /// Cache of loaded textures for viewport rendering.
    pub texture_cache: TextureCache,
    /// Whether the game is currently playing.
    pub is_running: bool,
    /// Whether the game is paused.
    pub is_paused: bool,
    /// Engine-owned runtime loop for play mode.
    /// Contains the scene tree and drives the full frame pipeline.
    pub run_main_loop: Option<MainLoop>,
    /// Counts frames during runtime.
    pub runtime_frame_count: u64,
    /// pat-j9yqh: game-view runtime controls.
    /// Force-pause at the SceneTree level (Suspend).
    pub runtime_suspended: bool,
    /// Game time scale multiplier (1.0 = normal).
    pub runtime_time_scale: f64,
    /// Whether game audio is muted.
    pub runtime_muted: bool,
    /// Whether the editor camera overrides the in-game camera.
    pub runtime_camera_override: bool,
    /// Whether the editor selection is hidden in the running game.
    pub runtime_hide_selection: bool,
    /// Game-view interaction mode: "input" | "2d" | "3d".
    pub runtime_input_mode: String,
    /// pat-nzgdu.171: Movie Maker mode. Set by a `{"movie":true}` play request;
    /// while active the runtime steps at a fixed timestep (ignoring time_scale)
    /// and records each frame into `movie_frames`.
    pub movie_mode: bool,
    /// Frames captured during the current/last Movie Maker run — one per stepped
    /// frame. Kept after Stop so the sequence can still be downloaded; cleared on
    /// the next Play.
    pub movie_frames: Vec<MovieFrame>,
    /// Time between frames (fixed at 1/60).
    pub delta_time: f64,
    /// Named animations stored in the editor.
    pub animations: std::collections::HashMap<String, Animation>,
    /// Current animation playback state.
    pub animation_playback: AnimationPlaybackState,
    /// Editable AnimationTree graph backing the served state-machine editor
    /// (pat-nzgdu.103). States are nodes; transitions are the graph's links.
    pub anim_tree: crate::anim_tree_graph::AnimTreeGraph,
    /// Name of the state the AnimationTree is currently playing, if any. The
    /// served graph highlights it, mirroring Godot's live playback highlight.
    pub anim_tree_current_state: Option<String>,
    /// Currently pressed keyboard keys.
    pub pressed_keys: HashSet<String>,
    /// Keys pressed this frame (cleared each frame).
    pub just_pressed_keys: HashSet<String>,
    /// Keys released this frame (cleared each frame).
    pub just_released_keys: HashSet<String>,
    /// Current mouse position in viewport coordinates.
    pub mouse_position: (f64, f64),
    /// Currently pressed mouse buttons (0=left, 1=middle, 2=right).
    pub mouse_buttons: HashSet<u8>,
    /// Input action map: action name -> list of key names.
    pub input_map: HashMap<String, Vec<String>>,
    /// Last polled browser gamepad frame per device: `(buttons, axes)`
    /// (pat-0q2kx.88).
    ///
    /// The browser reports the *whole* pad state on every
    /// `navigator.getGamepads()` poll, but `_input` must only see an event when
    /// something actually changed — Godot's web layer emits a JoypadButton /
    /// JoypadMotion event per transition, not per poll. Keeping the previous
    /// frame here is what turns a level report into edge-triggered events.
    pub gamepad_prev: HashMap<u32, (Vec<bool>, Vec<f32>)>,
    pub tile_grid_store: gdscene::tilemap::TileGridStore,
    /// Per-cell alternative-tile ids (Godot's flip/rotate transform bits).
    ///
    /// `TileGrid` is a flat `Vec<i32>` of tile ids with nowhere to put them, so
    /// they ride alongside and are folded back in when the grid is encoded to
    /// `tile_map_data` (pat-0q2kx.75). Without this the toolbar's Flip/Rot
    /// buttons would post a value the server dropped on the floor.
    pub tile_alternatives: HashMap<NodeId, HashMap<(i32, i32), i32>>,
    /// Currently active editor mode: "2d", "3d", or "script".
    pub editor_mode: String,
    /// The editor mode that was active before Play switched to the game view.
    /// Set when Play launches the scene (pat-niu1j.1) so Stop can restore the
    /// prior editing view (pat-niu1j.3). `None` when not in a play session.
    pub pre_play_editor_mode: Option<String>,
    /// The editor's central main-screen pane (pat-nbakh).
    ///
    /// Holds the [`MainScreenSwitcher`](crate::main_screen) model that routes the
    /// central view to the active mode's component. `editor_mode` (above) stays
    /// the string source of truth the many mode readers (play/stop, 3D state,
    /// toolbars) use; this pane is the wired model that drives the served
    /// `GET /api/editor/main_view`, so the top-bar mode switch mounts a real
    /// per-mode view (2D canvas / 3D spatial / script / game / AssetLib) instead
    /// of being cosmetic. Previously orphaned (only exercised by unit tests).
    pub main_pane: crate::main_screen::MainPane,
    /// Active transform axis constraint: None, "x", or "y".
    pub transform_axis_constraint: Option<String>,
    /// Keyframe clipboard for copy/paste in animation editor.
    pub keyframe_clipboard: Vec<(usize, gdscene::animation::KeyFrame)>,
    /// Breakpoint lines per script path.
    pub breakpoints: HashMap<String, Vec<u32>>,
    /// Error lines per script path (line number + message).
    pub script_errors: HashMap<String, Vec<(u32, String)>>,
    /// Frame time history for monitors panel (ring buffer of last 120 frame times in ms).
    pub frame_times: VecDeque<f64>,
    /// Profiler frame snapshots (ring buffer of last 120 frames).
    pub profiler_frames: VecDeque<ProfilerFrame>,
    /// Whether the profiler is actively capturing frames (pat-wykfm).
    pub profiler_capturing: bool,
    /// Debug stack trace (populated when runtime hits a breakpoint or error).
    pub debug_stack_trace: Vec<String>,
    /// Debugger state: "detached", "running", or "paused".
    pub debug_state: String,
    /// Structured debug stack frames: (function, script, line).
    pub debug_frames: Vec<(String, String, usize)>,
    /// Debug breakpoints: (script, line).
    pub debug_breakpoints: Vec<(String, usize)>,
    /// Debug local variables for current frame: (name, type, value).
    pub debug_locals: Vec<(String, String, String)>,
    /// Debug global variables: (name, type, value).
    pub debug_globals: Vec<(String, String, String)>,
    /// pat-j906k: runtime errors/warnings for the Errors sub-tab: (level, message).
    pub debug_errors: Vec<(String, String)>,
    /// pat-j906k: whether the debugger skips breakpoints this session.
    pub debug_skip_breakpoints: bool,
    /// pat-s3rrv.27: whether a Play session wants the script debugger attached.
    ///
    /// This is the *desired* state, not the live one. `EngineDebugger` lives in
    /// a `thread_local!`, and the editor serves each connection on its own
    /// thread while frames may be advanced by the driver thread — so attaching
    /// inside the `/api/runtime/play` handler would bind the debugger to a
    /// connection thread that dies with the response, leaving `is_active()`
    /// false for the entire run. `advance_running_main_loop` reconciles the
    /// thread-local against this flag before each step, which is correct on
    /// whichever thread actually runs the scripts.
    pub debug_attached: bool,
    /// pat-s3rrv.27: `EngineDebugger.send_message()` captures drained from the
    /// running session: (name, stringified args). Godot delivers these to the
    /// editor's registered capture; Patina had them accumulating in a
    /// thread-local `DEBUG_MESSAGES` that nothing ever read.
    pub debug_messages: Vec<(String, Vec<String>)>,
    /// Misc debugger tab: Live Edit Root node path. Godot's ScriptEditorDebugger
    /// defaults this to "/root" and resets to it on "Clear"
    /// (script_editor_debugger.cpp:1603-1620).
    pub live_edit_root: String,
    /// Network Profiler — whether profiling is active (the Start/Stop toggle).
    /// Godot EditorNetworkProfiler::_activate_pressed emits "enable_profiling".
    pub net_profiler_profiling: bool,
    /// Network Profiler — the persisted Autostart checkbox. Godot stores this in
    /// project_metadata "debug_options/autostart_network_profiler"
    /// (editor_network_profiler.cpp:244-247).
    pub net_profiler_autostart: bool,
    /// Registered editor plugins.
    pub plugins: Vec<PluginEntry>,
    /// Running EditorPlugin instances, keyed by addon folder (pat-0q2kx.76).
    pub active_plugins: HashMap<String, GDScriptNodeInstance>,
    /// Per-scene plugin state from `_get_state`, keyed by scene path and then
    /// by plugin NAME (pat-s3rrv.66).
    ///
    /// Godot stores this in an `editstate` file in the editor metadata folder,
    /// keyed by the plugin's `_get_plugin_name()` — which is why its doc says
    /// "You must implement `_get_plugin_name` for the state to be stored and
    /// restored correctly". Keying by addon FOLDER instead would look identical
    /// until a project renamed a folder, then silently drop the state.
    pub plugin_scene_state: HashMap<String, HashMap<String, Variant>>,
    /// `@tool` scripts executing against the EDIT tree, keyed by their node.
    pub tool_scripts: HashMap<NodeId, GDScriptNodeInstance>,
    /// Editor keybindings for the settings dialog.
    pub keybindings: Vec<EditorKeyBinding>,
    /// Current viewport tool mode (select, move, rotate, scale).
    pub viewport_mode: ViewportMode,
    /// Output log from script print() calls.
    pub output_entries: VecDeque<String>,
    /// Project settings (pat-kj4 / pat-c4zlm).
    pub project_name: String,
    /// Project description.
    pub project_description: String,
    /// Project icon path.
    pub project_icon: String,
    /// Project main scene path.
    pub project_main_scene: String,
    /// Project display resolution width.
    pub project_resolution_w: u32,
    /// Project display resolution height.
    pub project_resolution_h: u32,
    /// Stretch mode.
    pub project_stretch_mode: String,
    /// Stretch aspect.
    pub project_stretch_aspect: String,
    /// Fullscreen mode.
    pub project_fullscreen: bool,
    /// V-Sync enabled.
    pub project_vsync: bool,
    /// `input_devices/pointing/emulate_mouse_from_touch` — ON by default in
    /// Godot, which is what lets a touch press a Button (pat-s3rrv.77).
    pub project_emulate_mouse_from_touch: bool,
    /// `input_devices/pointing/emulate_touch_from_mouse` — OFF by default; it
    /// exists so a desktop mouse can drive touch code during testing.
    pub project_emulate_touch_from_mouse: bool,
    /// Project physics FPS.
    pub project_physics_fps: u32,
    /// Project default gravity.
    pub project_gravity: f64,
    /// Default linear damp.
    pub project_linear_damp: f64,
    /// Default angular damp.
    pub project_angular_damp: f64,
    /// Default audio bus layout.
    pub project_bus_layout: String,
    /// Master volume in dB.
    pub project_master_volume_db: f64,
    /// Enable audio input.
    pub project_audio_input: bool,
    /// Renderer backend.
    pub project_renderer: String,
    /// Anti-aliasing mode.
    pub project_anti_aliasing: String,
    /// Default environment path.
    pub project_environment_default: String,
    /// Active smart snap alignment guides (cleared when drag ends).
    pub snap_guides: Vec<SnapGuide>,
    /// Open scene tabs: (tab_id, scene_path, display_name, modified).
    pub scene_tabs: Vec<SceneTab>,
    /// Index of the currently active scene tab.
    pub active_tab_index: usize,
    /// Node creation dialog with class search and filtering.
    pub create_node_dialog: CreateNodeDialog,
    /// Filesystem dock backing the asset browser panel. Default points at
    /// the current working directory; tests replace this with a temp-dir
    /// fixture before starting the server.
    pub asset_browser: FileSystemDock,
    /// Persistent 3D editor viewport: the spatial editor's camera (orbit / pan /
    /// zoom) and grid, used while `editor_mode == "3d"`. Kept on the state so
    /// navigation accumulates across frames and HTTP requests, matching Godot's
    /// spatial editor (pat-3dnav).
    pub editor_viewport_3d: crate::viewport_3d::Viewport3D,
    /// The selected node's global transform captured at the start of a 3D gizmo
    /// drag. Rotate/scale results are accumulated from the drag start, so this is
    /// the base they are applied to. `None` when no gizmo drag is active.
    pub gizmo_drag_start_3d: Option<gdcore::math3d::Transform3D>,
    /// Whether the in-progress 3D gizmo drag snaps to increments (Godot's
    /// Ctrl-drag). Set from `gizmo/begin`; applied in `gizmo/update`.
    pub gizmo_snap_active_3d: bool,
    /// Start (drag-begin) global transforms of every selected node, so a gizmo
    /// drag transforms the whole multi-selection together (Godot parity), not
    /// just the primary. Captured in `gizmo/begin`, cleared in `gizmo/end`.
    pub gizmo_drag_starts_3d: Vec<(NodeId, gdcore::math3d::Transform3D)>,
    /// The in-progress per-node gizmo *handle* drag — the one that edits a
    /// node's shape rather than its transform (pat-s3rrv.10). `None` when no
    /// handle drag is active.
    pub handle_drag_3d: Option<HandleDrag3D>,
    /// The project's audio bus layout, edited by the bottom-panel Audio editor
    /// (pat audio parity). Starts with a single `Master` bus.
    pub audio_bus_layout: crate::audio_bus_layout::AudioBusLayout,
    /// The Theme resource currently open in the Theme editor panel, plus its
    /// model wrapper (pat-nzgdu.102). Loaded from a `.tres` by
    /// `POST /api/theme/load`; item edits mutate this and are written back to
    /// [`theme_file`](Self::theme_file).
    pub theme_editor: crate::theme_editor::ThemeEditor,
    /// Filesystem path of the `.tres` backing [`theme_editor`](Self::theme_editor),
    /// if a Theme is open. Item-set/remove routes rewrite this file so edits
    /// persist. `None` when no Theme has been opened.
    pub theme_file: Option<String>,
}

/// A single scene tab in the editor.
#[derive(Debug, Clone)]
pub struct SceneTab {
    /// Unique tab identifier.
    pub id: u32,
    /// File path of the scene (empty for unsaved).
    pub path: String,
    /// Display name shown on the tab.
    pub name: String,
    /// Whether the scene has unsaved changes.
    pub modified: bool,
    /// This scene's inspector navigation stack, saved when the tab is
    /// deactivated and restored when it becomes active again so each open
    /// scene keeps its own back/forward history. Mirrors
    /// `EditorState.inspector_history`/`inspector_history_index`.
    pub inspector_history: Vec<NodeId>,
    /// Cursor into `inspector_history` for this scene's nav stack.
    pub inspector_history_index: usize,
}

/// Viewport tool modes for the editor.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ViewportMode {
    /// Select mode (Q).
    Select,
    /// Move mode (W).
    Move,
    /// Rotate mode (E).
    Rotate,
    /// Scale mode (S).
    Scale,
}

impl ViewportMode {
    /// Parses a mode from a string name.
    pub fn from_str_name(s: &str) -> Option<Self> {
        match s {
            "select" => Some(Self::Select),
            "move" => Some(Self::Move),
            "rotate" => Some(Self::Rotate),
            "scale" => Some(Self::Scale),
            _ => None,
        }
    }

    /// Returns the string name for this mode.
    pub fn as_str(&self) -> &'static str {
        match self {
            Self::Select => "select",
            Self::Move => "move",
            Self::Rotate => "rotate",
            Self::Scale => "scale",
        }
    }
}

/// A registered editor plugin entry.
