/// `POST /api/node/unique_name` — toggles a node's "Access as Unique Name"
/// (`%`) flag. Sets the `_unique_name_in_owner` meta; defaults to enabling.
/// Surfaced as `unique_name_in_owner` in the scene tree JSON, with a
/// `unique_name_collision` warning when another unique-named node in the same
/// owner shares this node's name.
fn api_set_unique_name(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let enabled = parsed
        .get("enabled")
        .and_then(|v| v.as_bool())
        .unwrap_or(true);

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    match state.scene_tree.get_node_mut(node_id) {
        Some(n) => {
            n.set_property("_unique_name_in_owner", Variant::Bool(enabled));
            // Keep the canonical `unique_name` flag in sync with the meta so
            // `%Name` path resolution and packed-scene serialization (both of
            // which read `is_unique_name()`) reflect the editor toggle.
            n.set_unique_name(enabled);
        }
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    }
    state.scene_modified = true;
    send_json(
        stream,
        &format!(r#"{{"ok":true,"unique_name_in_owner":{enabled}}}"#),
    );
}

/// Resolves the selection target for a viewport click: walks up from `node_id`
/// and returns the topmost ancestor with the `_edit_group_` meta set, so a
/// click on a grouped node's descendant selects the grouped ancestor. Returns
/// `node_id` unchanged when no ancestor is grouped.
fn resolve_group_selection(tree: &SceneTree, node_id: NodeId) -> NodeId {
    let mut target = node_id;
    let mut current = tree.get_node(node_id).and_then(|n| n.parent());
    while let Some(ancestor) = current {
        if matches!(
            tree.get_node(ancestor)
                .map(|n| n.get_property("_edit_group_")),
            Some(Variant::Bool(true))
        ) {
            target = ancestor;
        }
        current = tree.get_node(ancestor).and_then(|n| n.parent());
    }
    target
}

/// `POST /api/node/rename` — renames a node.
fn api_rename_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let new_name = match parsed.get("new_name").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing new_name");
            return;
        }
    };

    // Reject empty / whitespace-only names.
    if new_name.trim().is_empty() {
        send_error(stream, 400, "name cannot be empty");
        return;
    }

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    // Collision-safe uniquification: if a sibling already uses the requested
    // name, auto-suffix it (e.g. `Foo` -> `Foo2`).
    let unique_name = match state.scene_tree.get_node(node_id).and_then(|n| n.parent()) {
        Some(parent_id) => {
            let siblings: Vec<String> = state
                .scene_tree
                .get_node(parent_id)
                .map(|p| {
                    p.children()
                        .iter()
                        .filter(|&&c| c != node_id)
                        .filter_map(|&c| state.scene_tree.get_node(c).map(|n| n.name().to_string()))
                        .collect()
                })
                .unwrap_or_default();
            unique_sibling_name(&new_name, &siblings)
        }
        None => new_name.clone(),
    };

    let new_name_log = unique_name.clone();
    let mut cmd = EditorCommand::RenameNode {
        node_id,
        new_name: unique_name,
        old_name: String::new(),
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }

    let old_name_log = match &cmd {
        EditorCommand::RenameNode { old_name, .. } => old_name.clone(),
        _ => String::new(),
    };
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log(
        "info",
        format!("Renamed '{}' to '{}'", old_name_log, new_name_log),
    );

    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/node/batch_rename` — renames a multi-selection using a counter
/// pattern (`%d` → 1, 2, 3, …), mirroring `api_rename_node` per node
/// (pat-nzgdu.105). Body: `{"node_ids":[u64,...],"pattern":"node_%d"}`.
fn api_batch_rename(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let node_ids: Vec<u64> = match parsed.get("node_ids").and_then(|v| v.as_array()) {
        Some(arr) => arr.iter().filter_map(|v| v.as_u64()).collect(),
        None => {
            send_error(stream, 400, "missing node_ids");
            return;
        }
    };
    let pattern = match parsed.get("pattern").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing pattern");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let mut renamed = 0u32;
    for (i, raw) in node_ids.iter().enumerate() {
        let node_id = match find_node_by_raw_id(&state.scene_tree, *raw) {
            Some(id) => id,
            None => continue,
        };
        // `%d` expands to a 1-indexed counter over the selection (Godot's
        // batch-rename counter): node_%d -> node_1, node_2, node_3, ...
        let new_name = pattern.replace("%d", &(i + 1).to_string());
        if new_name.trim().is_empty() {
            continue;
        }
        let mut cmd = EditorCommand::RenameNode {
            node_id,
            new_name,
            old_name: String::new(),
        };
        if cmd.execute(&mut state.scene_tree).is_ok() {
            state.undo_stack.push(cmd);
            renamed += 1;
        }
    }
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log("info", format!("Batch-renamed {renamed} node(s)"));
    send_json(stream, &format!(r#"{{"ok":true,"renamed":{renamed}}}"#));
}

/// `POST /api/node/metadata` — Inspector dock "Add Metadata" (pat-s3rrv.151).
///
/// Body: `{"node_id":u64,"name":"foo","type":"int","value":42}`.
///
/// Written through `set_property("metadata/<name>")` rather than `set_meta`, so
/// the value lands in BOTH stores at once: the property row is what `TscnSaver`
/// serialises, and `Node::set_property` mirrors a `metadata/` key into the meta
/// map so `get_meta("foo")` sees it from GDScript without a reload.
fn api_set_node_metadata(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let raw_id = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let name = match parsed.get("name").and_then(|v| v.as_str()) {
        Some(v) if !v.trim().is_empty() => v.trim().to_string(),
        // An empty name would write a `metadata/` row with no key, which Godot
        // cannot express and `get_meta("")` could never read back.
        _ => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let ty = parsed
        .get("type")
        .and_then(|v| v.as_str())
        .unwrap_or("String");
    let raw_value = parsed.get("value");
    // The dialog sends a JSON value already shaped by the chosen type; the type
    // string decides the Variant so an int stays an int through the .tscn rather
    // than being re-read as a float.
    let value = match ty {
        "int" => gdvariant::Variant::Int(raw_value.and_then(|v| v.as_i64()).unwrap_or(0)),
        "float" => gdvariant::Variant::Float(raw_value.and_then(|v| v.as_f64()).unwrap_or(0.0)),
        "bool" => gdvariant::Variant::Bool(raw_value.and_then(|v| v.as_bool()).unwrap_or(false)),
        _ => gdvariant::Variant::String(
            raw_value
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .to_string(),
        ),
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, raw_id) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    match state.scene_tree.get_node_mut(node_id) {
        Some(node) => {
            node.set_property(&format!("metadata/{name}"), value);
        }
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    }
    state.scene_modified = true;
    state.add_log("info", format!("Added metadata/{name}"));
    send_json(stream, &format!(r#"{{"ok":true,"name":"{name}"}}"#));
}

/// `POST /api/node/duplicate` — duplicates a node and its subtree as a sibling.
fn api_duplicate_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    let mut cmd = EditorCommand::DuplicateNode {
        source_id: node_id,
        created_ids: Vec::new(),
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }

    let root_created = match &cmd {
        EditorCommand::DuplicateNode { created_ids, .. } => {
            created_ids.first().map(|id| id.raw()).unwrap_or(0)
        }
        _ => unreachable!(),
    };

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    // Focus the newly created duplicate.
    if let Some(id) = find_node_by_raw_id(&state.scene_tree, root_created) {
        state.selected_node = Some(id);
        state.selected_nodes = vec![id];
    }

    let json = format!(r#"{{"id":{root_created}}}"#);
    send_json(stream, &json);
}

/// Serializes a filtered class-tree node for the Create New Node dialog UI:
/// the nested hierarchy plus per-node instantiability (abstract ancestors are
/// greyed out client-side), Godot's brief description, and inheritance chain.
fn create_dialog_tree_json(
    dlg: &CreateNodeDialog,
    node: &crate::create_dialog::FilteredClassNode,
) -> serde_json::Value {
    let name = node.class_name();
    let children: Vec<serde_json::Value> = node
        .children()
        .iter()
        .map(|c| create_dialog_tree_json(dlg, c))
        .collect();
    serde_json::json!({
        "class_name": name,
        "matched": node.is_match(),
        "instantiable": dlg.is_candidate(name),
        "description": crate::create_dialog::brief_description(name).unwrap_or(""),
        "inheritance_chain": gdobject::class_db::inheritance_chain(name),
        "children": children,
    })
}

/// `POST /api/node/create_dialog` — returns classes from ClassDB with search, filter, favorites, and recent.
///
/// Response mirrors Godot's `CreateDialog::_update_search`: `tree` is the
/// hierarchy rooted at the base type (matches plus their ancestors, Godot's
/// subsequence rule), and `best_match` is the auto-selected highest-scoring
/// candidate for the current search.
fn api_create_dialog(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    use crate::create_dialog::NodeCategory;

    let mut st = state.lock().unwrap();
    // Persist favorites/recent under the project (Godot: project settings
    // dir). Lazily initialized once a real project root is known; without one
    // (e.g. unit-test servers) the lists stay in-memory only.
    if st.create_node_dialog.persist_dir().is_none() {
        if let Some(root) = st.project_root.clone() {
            st.create_node_dialog.set_persist_dir(Some(
                std::path::PathBuf::from(root)
                    .join(".patina")
                    .join("editor"),
            ));
        }
    }
    let dlg = &mut st.create_node_dialog;
    if !body.is_empty() {
        if let Some(parsed) = parse_json_body(body) {
            if let Some(search) = parsed.get("search").and_then(|v| v.as_str()) {
                dlg.set_search(search);
            } else {
                dlg.set_search("");
            }
            if let Some(base) = parsed.get("base_class").and_then(|v| v.as_str()) {
                if base.is_empty() {
                    dlg.set_base_class(None);
                } else {
                    dlg.set_base_class(Some(base.to_string()));
                }
            }
            if let Some(preferred) = parsed.get("preferred").and_then(|v| v.as_str()) {
                if preferred.is_empty() {
                    dlg.set_preferred_type(None);
                } else {
                    dlg.set_preferred_type(Some(preferred.to_string()));
                }
            }
            if let Some(cat) = parsed.get("category").and_then(|v| v.as_str()) {
                let category = match cat {
                    "Node2D" | "2D Nodes" => Some(NodeCategory::Node2D),
                    "Physics2D" | "2D Physics" => Some(NodeCategory::Physics2D),
                    "UI" | "UI Controls" => Some(NodeCategory::UI),
                    "Utility" => Some(NodeCategory::Utility),
                    _ => None,
                };
                dlg.set_category_filter(category);
            } else {
                dlg.set_category_filter(None);
            }
        }
    } else {
        dlg.set_search("");
        dlg.set_base_class(None);
        dlg.set_category_filter(None);
    }
    let classes = dlg.filtered_classes();
    let recent = dlg.recent_entries();
    let favorites: Vec<&str> = dlg.favorites().iter().map(|s| s.as_str()).collect();
    let class_names: Vec<&str> = classes.iter().map(|c| c.class_name.as_str()).collect();
    let class_entries: Vec<serde_json::Value> = classes
        .iter()
        .map(|c| {
            serde_json::json!({
                "class_name": c.class_name, "parent_class": c.parent_class,
                "inheritance_chain": c.inheritance_chain, "is_favorite": c.is_favorite,
                "description": c.description, "category": c.category.map(|cat| cat.label()),
            })
        })
        .collect();
    let recent_json: Vec<serde_json::Value> = recent
        .iter()
        .map(|c| serde_json::json!({ "class_name": c.class_name, "parent_class": c.parent_class }))
        .collect();
    // The Matches tree is always rooted at the dialog's base type ("Node"
    // for the scene dock), regardless of the flat-list filters above.
    let tree_base = dlg.base_class().unwrap_or("Node").to_string();
    let search_text = dlg.search_text().to_string();
    let tree = dlg
        .filtered_class_tree(&tree_base, &search_text)
        .map(|t| create_dialog_tree_json(dlg, &t));
    let best_match = dlg.best_match(&search_text);
    let json = serde_json::json!({
        "classes": class_names, "class_entries": class_entries, "favorites": favorites,
        "recent": recent_json, "match_count": class_names.len(),
        "tree": tree, "best_match": best_match, "search": search_text,
    })
    .to_string();
    send_json(stream, &json);
}

/// `GET /api/node/catalog_2d` — returns the 2D node catalog with categories and helper presets.
fn api_node_catalog_2d(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let st = state.lock().unwrap();
    let dlg = &st.create_node_dialog;
    if let Some(catalog) = dlg.catalog() {
        let entries: Vec<serde_json::Value> = catalog
            .entries()
            .iter()
            .map(|e| {
                serde_json::json!({
                    "class_name": e.class_name,
                    "category": e.category.label(),
                    "description": e.description,
                })
            })
            .collect();
        let helpers: Vec<serde_json::Value> = catalog
            .helpers()
            .iter()
            .map(|h| {
                serde_json::json!({
                    "name": h.name,
                    "description": h.description,
                    "root_class": h.root_class,
                    "children": h.children,
                })
            })
            .collect();
        let categories: Vec<&str> = catalog.categories().iter().map(|c| c.label()).collect();
        let json = serde_json::json!({
            "entries": entries, "helpers": helpers, "categories": categories,
        })
        .to_string();
        send_json(stream, &json);
    } else {
        send_json(stream, r#"{"entries":[],"helpers":[],"categories":[]}"#);
    }
}

