/// `POST /api/resource/property/set` — set a property within a resource sub-editor.
fn api_set_resource_property(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let resource_property = match parsed.get("resource_property").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing resource_property");
            return;
        }
    };
    let sub_property = match parsed.get("sub_property").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing sub_property");
            return;
        }
    };
    let value_json = match parsed.get("value") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing value");
            return;
        }
    };
    let new_sub_value = match from_json(value_json) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid variant value");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    let current = match state
        .scene_tree
        .get_node(node_id)
        .map(|n| n.get_property(&resource_property))
    {
        Some(v) => v,
        None => {
            send_error(stream, 404, "resource property not found");
            return;
        }
    };
    let new_value = match current {
        Variant::Resource(mut r) => {
            r.properties.insert(sub_property.clone(), new_sub_value);
            Variant::Resource(r)
        }
        _ => {
            send_error(stream, 400, "property is not a Resource type");
            return;
        }
    };
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: resource_property.clone(),
        new_value,
        old_value: Variant::Nil,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log(
        "info",
        format!(
            "Changed resource property '{}.{}'",
            resource_property, sub_property
        ),
    );
    send_json(stream, r#"{"ok":true}"#);
}

fn api_reorder_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let direction = match parsed.get("direction").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing direction (up or down)");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    let parent_id = match state.scene_tree.get_node(node_id).and_then(|n| n.parent()) {
        Some(pid) => pid,
        None => {
            send_error(stream, 400, "node has no parent");
            return;
        }
    };

    // Get parent's children and find index.
    let children: Vec<NodeId> = state
        .scene_tree
        .get_node(parent_id)
        .map(|n| n.children().to_vec())
        .unwrap_or_default();

    let idx = match children.iter().position(|&c| c == node_id) {
        Some(i) => i,
        None => {
            send_error(stream, 500, "node not found in parent children");
            return;
        }
    };

    let new_idx = match direction.as_str() {
        "up" => {
            if idx == 0 {
                send_json(stream, r#"{"ok":true}"#);
                return;
            }
            idx - 1
        }
        "down" => {
            if idx >= children.len() - 1 {
                send_json(stream, r#"{"ok":true}"#);
                return;
            }
            idx + 1
        }
        _ => {
            send_error(stream, 400, "direction must be 'up' or 'down'");
            return;
        }
    };

    // Reorder as an undoable step (pat-0q2kx.12). This used to swap the
    // parent's children directly, so moving a node up or down the scene dock
    // could not be undone. `MoveNode` captures the old index during `execute`
    // and restores it on undo. (Boundary no-ops returned early above without
    // reaching here, so they do not mark the scene modified.)
    let mut cmd = EditorCommand::MoveNode {
        parent_id,
        child_id: node_id,
        new_index: new_idx,
        old_index: idx,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;

    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// Theme resource editor (pat-nzgdu.102)
//
// Backs the served Theme editor panel with the previously-orphaned
// `theme_editor::ThemeEditor` model. `POST /api/theme/load` reads a `.tres`
// into `EditorState.theme_editor`; `GET /api/theme` returns its items; the
// item set/remove routes mutate the model AND rewrite the backing `.tres` so
// edits persist across a reload.
// ---------------------------------------------------------------------------

/// Serializes the open Theme (items flattened for the UI) as a JSON string.
fn theme_state_json(st: &EditorState) -> String {
    let theme = st.theme_editor.theme();
    let mut types = theme.control_types();
    types.sort_unstable();
    let mut items = Vec::new();
    for ct in &types {
        let mut names = theme.item_names(ct);
        names.sort_unstable();
        for name in names {
            if let Some(item) = theme.get_item(ct, name) {
                items.push(theme_item_json(ct, name, item));
            }
        }
    }
    serde_json::json!({
        "path": st.theme_file.clone(),
        "control_types": types,
        "revision": st.theme_editor.revision(),
        "items": items,
    })
    .to_string()
}

/// One flattened `{control_type, item_name, data_type, <value>}` entry.
fn theme_item_json(
    ct: &str,
    name: &str,
    item: &crate::theme_editor::ThemeItem,
) -> serde_json::Value {
    use crate::theme_editor::ThemeItem;
    let (data_type, value) = match item {
        ThemeItem::Color(c) => (
            "color",
            serde_json::json!({ "color": [c.0, c.1, c.2, c.3] }),
        ),
        ThemeItem::IconColor(c) => (
            "icon_color",
            serde_json::json!({ "color": [c.0, c.1, c.2, c.3] }),
        ),
        ThemeItem::Constant(n) => ("constant", serde_json::json!({ "value": n })),
        ThemeItem::FontSize(s) => ("font_size", serde_json::json!({ "value": s })),
        ThemeItem::StyleBox(sb) => ("stylebox", serde_json::json!({ "stylebox": sb })),
        ThemeItem::Font(f) => ("font", serde_json::json!({ "font": f })),
    };
    let mut obj = serde_json::json!({
        "control_type": ct,
        "item_name": name,
        "data_type": data_type,
    });
    if let (Some(dst), Some(src)) = (obj.as_object_mut(), value.as_object()) {
        for (k, v) in src {
            dst.insert(k.clone(), v.clone());
        }
    }
    obj
}

/// Parses a `{"color":[r,g,b,a]}` request field into a [`gdcore::math::Color`].
fn theme_req_color(parsed: &serde_json::Value) -> Option<gdcore::math::Color> {
    let arr = parsed.get("color")?.as_array()?;
    if arr.len() != 4 {
        return None;
    }
    let c = |i: usize| arr[i].as_f64().map(|x| x as f32);
    Some(gdcore::math::Color::new(c(0)?, c(1)?, c(2)?, c(3)?))
}

/// Builds a [`ThemeItem`](crate::theme_editor::ThemeItem) from a set-request
/// body for the named `data_type`, or `None` if the value is missing/malformed.
fn theme_item_from_request(
    data_type: &str,
    parsed: &serde_json::Value,
) -> Option<crate::theme_editor::ThemeItem> {
    use crate::theme_editor::{StyleBoxFlat, ThemeFont, ThemeItem};
    match data_type {
        "color" => theme_req_color(parsed).map(ThemeItem::color),
        "icon_color" => theme_req_color(parsed).map(ThemeItem::icon_color),
        "constant" => parsed
            .get("value")
            .and_then(|v| v.as_i64())
            .map(|n| ThemeItem::Constant(n as i32)),
        "font_size" => parsed
            .get("value")
            .and_then(|v| v.as_u64())
            .map(|n| ThemeItem::FontSize(n as u32)),
        "stylebox" => parsed
            .get("stylebox")
            .and_then(|v| serde_json::from_value::<StyleBoxFlat>(v.clone()).ok())
            .map(ThemeItem::StyleBox),
        "font" => parsed
            .get("font")
            .and_then(|v| serde_json::from_value::<ThemeFont>(v.clone()).ok())
            .map(ThemeItem::Font),
        _ => None,
    }
}

/// Writes the open Theme back to its `.tres` file. A no-op when no file backs
/// the Theme (e.g. a freshly-constructed, never-loaded editor).
fn persist_theme(st: &EditorState) -> std::io::Result<()> {
    if let Some(path) = &st.theme_file {
        atomic_write(
            std::path::Path::new(path),
            st.theme_editor.theme().to_tres().as_bytes(),
        )?;
    }
    Ok(())
}

/// `GET /api/theme` — returns the open Theme's items for the editor panel.
fn api_theme_get(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let st = state.lock().unwrap();
        theme_state_json(&st)
    };
    send_json(stream, &json);
}

/// `POST /api/theme/load` — opens a `.tres` Theme resource for editing.
fn api_theme_load(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = match parsed.get("path").and_then(|v| v.as_str()) {
        Some(p) => p.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            send_error(stream, 404, &format!("cannot read theme: {e}"));
            return;
        }
    };
    let theme = crate::theme_editor::ThemeResource::from_tres(&text);
    let json = {
        let mut st = state.lock().unwrap();
        st.theme_editor = crate::theme_editor::ThemeEditor::with_theme(theme);
        st.theme_file = Some(path);
        theme_state_json(&st)
    };
    send_json(stream, &json);
}

/// `POST /api/theme/item/set` — sets one Theme item and persists to the `.tres`.
///
/// Body: `{control_type, item_name, data_type, ...value}` where `data_type` is
/// one of `color`/`icon_color` (`{color:[r,g,b,a]}`), `constant`/`font_size`
/// (`{value:n}`), `stylebox` (`{stylebox:{...}}`), or `font` (`{font:{...}}`).
fn api_theme_item_set(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let control_type = match parsed.get("control_type").and_then(|v| v.as_str()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing control_type");
            return;
        }
    };
    let item_name = match parsed.get("item_name").and_then(|v| v.as_str()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing item_name");
            return;
        }
    };
    let data_type = match parsed.get("data_type").and_then(|v| v.as_str()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing data_type");
            return;
        }
    };
    let item = match theme_item_from_request(data_type, &parsed) {
        Some(i) => i,
        None => {
            send_error(stream, 400, "invalid or missing value for data_type");
            return;
        }
    };
    let (json, persist_err) = {
        let mut st = state.lock().unwrap();
        st.theme_editor.set_item(control_type, item_name, item);
        let err = persist_theme(&st).err();
        (theme_state_json(&st), err)
    };
    if let Some(e) = persist_err {
        send_error(
            stream,
            500,
            &format!("theme updated in memory but writing .tres failed: {e}"),
        );
        return;
    }
    send_json(stream, &json);
}

/// `POST /api/theme/item/remove` — removes one Theme item and persists.
///
/// Idempotent: removing an absent item is a 200 (the resulting theme is
/// returned either way), matching how the editor treats a cleared override.
fn api_theme_item_remove(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let control_type = match parsed.get("control_type").and_then(|v| v.as_str()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing control_type");
            return;
        }
    };
    let item_name = match parsed.get("item_name").and_then(|v| v.as_str()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing item_name");
            return;
        }
    };
    let (json, persist_err) = {
        let mut st = state.lock().unwrap();
        st.theme_editor.remove_item(control_type, item_name);
        let err = persist_theme(&st).err();
        (theme_state_json(&st), err)
    };
    if let Some(e) = persist_err {
        send_error(
            stream,
            500,
            &format!("theme updated in memory but writing .tres failed: {e}"),
        );
        return;
    }
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// Resource-valued properties (pat-0q2kx.13)
// ---------------------------------------------------------------------------
//
// A resource property is not an ordinary Variant. Godot stores it as a
// *reference* — `texture = ExtResource("1_icon")` for a file on disk,
// `shape = SubResource("Rect_1")` for an inline resource — with a matching
// `[ext_resource]` / `[sub_resource]` header. Patina keeps the reference on the
// node plus a companion the saver rebuilds the header from: `__extres__<prop>`
// carries the path (rebuilt by `scene_saver::collect_resource_tables`), and
// `__resref__<prop>` carries `Class::id` for inline resources.

/// Every resource id already referenced anywhere in the subtree, so a new
/// assignment cannot collide with one the scene loaded.
fn used_resource_ids(tree: &SceneTree, root: NodeId) -> std::collections::HashSet<String> {
    let mut ids = std::collections::HashSet::new();
    let mut subtree = Vec::new();
    tree.collect_subtree_top_down(root, &mut subtree);
    for nid in subtree {
        let Some(node) = tree.get_node(nid) else {
            continue;
        };
        for (key, value) in node.properties() {
            let Variant::String(s) = value else { continue };
            // `prop = ExtResource("id")` / `SubResource("id")`, the marker forms,
            // and the `Class::id` companions all carry an id.
            for prefix in ["ExtResource(\"", "SubResource(\""] {
                if let Some(rest) = s.strip_prefix(prefix) {
                    if let Some(id) = rest.strip_suffix("\")") {
                        ids.insert(id.to_string());
                    }
                }
            }
            for prefix in ["ExtResource:", "SubResource:"] {
                if let Some(id) = s.strip_prefix(prefix) {
                    ids.insert(id.to_string());
                }
            }
            if key.starts_with("__resref__") {
                if let Some((_, id)) = s.rsplit_once("::") {
                    ids.insert(id.to_string());
                }
            }
        }
    }
    ids
}

/// Allocates a Godot-style `<n>_<slug>` resource id that is free in this scene.
fn next_resource_id(used: &std::collections::HashSet<String>, slug: &str) -> String {
    let slug: String = slug
        .chars()
        .filter(|c| c.is_ascii_alphanumeric() || *c == '_')
        .take(16)
        .collect();
    let slug = if slug.is_empty() {
        "res".to_string()
    } else {
        slug.to_ascii_lowercase()
    };
    (1..)
        .map(|n| format!("{n}_{slug}"))
        .find(|id| !used.contains(id))
        .unwrap_or_default()
}

/// `POST /api/property/resource/assign` — points a resource property at a file on
/// disk, as Godot's resource picker "Load…"/"Quick Load" and a FileSystem drag do.
///
/// Body: `{"node_id": 123, "property": "texture", "path": "res://icon.png"}`.
/// A null/absent `path` clears the property, matching the picker's Clear.
fn api_assign_resource_property(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let Some(parsed) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let Some(node_raw) = parsed.get("node_id").and_then(|v| v.as_u64()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let Some(property) = parsed.get("property").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing property");
        return;
    };
    let property = property.to_string();
    // Absent or null clears; a non-empty string assigns.
    let res_path = parsed
        .get("path")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|p| !p.is_empty())
        .map(|p| {
            if p.starts_with("res://") {
                p.to_string()
            } else {
                format!("res://{}", p.trim_start_matches('/'))
            }
        });

    let mut state = state.lock().unwrap();
    let Some(node_id) = find_node_by_raw_id(&state.scene_tree, node_raw) else {
        send_error(stream, 404, "node not found");
        return;
    };

    let companion = format!("__extres__{property}");
    let (new_value, assigned_path) = match &res_path {
        Some(path) => {
            // Scan the whole tree, so a new id cannot collide with one already
            // referenced anywhere in the open scene.
            let tree_root = state.scene_tree.root_id();
            let used = used_resource_ids(&state.scene_tree, tree_root);
            let stem = std::path::Path::new(path)
                .file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_default();
            let id = next_resource_id(&used, &stem);
            (
                Variant::String(format!("ExtResource(\"{id}\")")),
                Some(path.clone()),
            )
        }
        None => (Variant::Nil, None),
    };

    // The visible property goes through the undo stack; the companion is
    // bookkeeping and rides along with it.
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: property.clone(),
        new_value,
        old_value: Variant::Nil,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    if let Some(node) = state.scene_tree.get_node_mut(node_id) {
        match &assigned_path {
            Some(path) => {
                node.set_property(&companion, Variant::String(path.clone()));
            }
            None => {
                node.set_property(&companion, Variant::Nil);
                node.set_property(&format!("__resref__{property}"), Variant::Nil);
            }
        }
    }

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    match &assigned_path {
        Some(path) => state.add_log("info", format!("Assigned {path} to '{property}'")),
        None => state.add_log("info", format!("Cleared '{property}'")),
    }
    let event = format!(
        r#"{{"type":"property_changed","node_id":{node_raw},"property":"{prop}"}}"#,
        prop = property.replace('"', "\\\""),
    );
    publish_event(&mut state, event);

    let json = match &assigned_path {
        Some(path) => format!(r#"{{"ok":true,"path":"{path}"}}"#),
        None => r#"{"ok":true,"path":null}"#.to_string(),
    };
    send_json(stream, &json);
}

/// `POST /api/property/resource/new` — creates a fresh inline resource of a named
/// class and assigns it, as Godot's picker "New <Type>" does.
///
/// Body: `{"node_id": 123, "property": "shape", "class_name": "RectangleShape2D"}`.
/// The resource is stored as `SubResource("id")` plus the `__resref__<prop>` =
/// `Class::id` companion the scene saver turns into a `[sub_resource]` section.
/// The companion-key prefix an inline sub-resource's body is flattened under for
/// `property`, or `None` for properties whose body is not cached on the node.
///
/// Mirrors `scene_saver::companion_prefix_for`, which is private to `gdscene`.
/// The two MUST agree: the saver rebuilds a `[sub_resource]` body from these
/// keys, so a prefix that is right here and wrong there would write a `.tres`
/// with different contents than the scene it replaces.
fn inline_resource_companion_prefix(property: &str) -> Option<&'static str> {
    match property {
        "shape" => Some("__shape__"),
        "curve" => Some("__curve__"),
        "material" | "material_override" | "surface_material_override/0" => Some("__material__"),
        _ => None,
    }
}

/// `POST /api/property/resource/save_as` — writes an inline resource out to a
/// `.tres` and repoints the property at it (pat-0q2kx.13).
///
/// Body: `{"node_id":N,"property":"shape","path":"res://shape.tres"}`.
///
/// After this the property holds a `res://` path exactly as an assign-by-path
/// would, so the existing scene save emits an `ext_resource` and **stops**
/// emitting a `[sub_resource]` for it — that swap is the point of the feature,
/// not the file write on its own.
fn api_save_resource_property_as(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let Some(parsed) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let Some(node_raw) = parsed.get("node_id").and_then(|v| v.as_u64()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let Some(property) = parsed.get("property").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing property");
        return;
    };
    let Some(res_path) = parsed.get("path").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing path");
        return;
    };
    let property = property.to_string();

    let mut state = state.lock().unwrap();
    // Resolved by walk, like every other node_id endpoint in this file: a raw id
    // that names no live node must 404 here rather than mint a `NodeId` that
    // later reads as "property holds no inline resource".
    let Some(node_id) = find_node_by_raw_id(&state.scene_tree, node_raw) else {
        send_error(stream, 404, "node not found");
        return;
    };
    let Some(root) = state.project_root.clone() else {
        send_error(stream, 400, "no project open");
        return;
    };
    let disk_path = match resolve_res_path(std::path::Path::new(&root), res_path) {
        Ok(p) => p,
        Err(e) => {
            send_error(stream, 400, e);
            return;
        }
    };

    // Only an INLINE resource can be saved out. A property already holding a
    // path has nothing to write, and reporting that plainly beats silently
    // rewriting the file it points at.
    let Some(node) = state.scene_tree.get_node(node_id) else {
        send_error(stream, 404, "node not found");
        return;
    };
    let current = node.get_property(&property);

    // An inline resource has TWO representations in this tree, and reading only
    // the first is what made this route reject its own picker's output:
    //
    //   (a) `Variant::Resource(ResourceRef)` — a resource loaded from a file and
    //       then edited in place by `api_set_resource_property`.
    //   (b) `SubResource("id")` on the property, `__resref__<prop>` = `Class::id`,
    //       and the body flattened into `<prefix><key>` companions — which is
    //       exactly what `api_new_resource_property` ("New <Type>") writes and
    //       what `.tscn` loading produces. This is the COMMON case: every
    //       resource the picker creates lands here, never in (a).
    let (class_name, res_props): (String, Vec<(String, Variant)>) = match &current {
        Variant::Resource(res_ref) => (
            res_ref.class_name.clone(),
            res_ref
                .properties
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect(),
        ),
        // Already external. Checked BEFORE the companion lookup because a stale
        // `__resref__` left over from a previous inline value would otherwise
        // make this route re-save — and overwrite — the file the property
        // already points at.
        Variant::String(s) if s.starts_with("ExtResource(") || s.starts_with("res://") => {
            send_error(stream, 400, "property is already an external resource");
            return;
        }
        Variant::String(_) => {
            let Variant::String(meta) = node.get_property(&format!("__resref__{property}")) else {
                send_error(stream, 400, "property holds no inline resource");
                return;
            };
            let Some((class, _id)) = meta.rsplit_once("::") else {
                send_error(stream, 400, "property holds no inline resource");
                return;
            };
            // `class` is the section's `type=`, not a property of the resource.
            let prefix = inline_resource_companion_prefix(&property);
            let props = prefix
                .map(|prefix| {
                    node.properties()
                        .filter_map(|(k, v)| {
                            let key = k.strip_prefix(prefix)?;
                            (key != "class").then(|| (key.to_string(), v.clone()))
                        })
                        .collect()
                })
                .unwrap_or_default();
            (class.to_string(), props)
        }
        _ => {
            send_error(stream, 400, "property holds no inline resource");
            return;
        }
    };

    // `Variant::Resource` carries a `gdvariant::ResourceRef`, while the saver
    // takes a `gdresource::Resource` — different types, and the latter's
    // `properties` map is private, so it is rebuilt through the public setter
    // rather than by struct literal.
    let mut resource = gdresource::Resource::new(&class_name);
    resource.path = res_path.to_string();
    for (key, value) in res_props {
        resource.set_property(key, value);
    }
    let text = match gdresource::TresSaver::new().save_to_string(&resource) {
        Ok(t) => t,
        Err(e) => {
            send_error(stream, 500, &format!("serialize failed: {e}"));
            return;
        }
    };
    if let Some(parent) = disk_path.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    if let Err(e) = std::fs::write(&disk_path, &text) {
        send_error(stream, 500, &format!("write failed: {e}"));
        return;
    }

    // Repoint the property, undoably, at the file just written — in the SAME
    // shape `api_assign_resource_property` produces, which is the only shape the
    // saver turns into an `[ext_resource]`: the property holds
    // `ExtResource("id")` and the resolved path rides in `__extres__<prop>`.
    // A bare `res://…` string here would round-trip as a plain string property
    // with no `[ext_resource]` header — the file would be written and the scene
    // would still not reference it.
    let tree_root = state.scene_tree.root_id();
    let used = used_resource_ids(&state.scene_tree, tree_root);
    let stem = std::path::Path::new(res_path)
        .file_stem()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_default();
    let ext_id = next_resource_id(&used, &stem);
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: property.clone(),
        new_value: Variant::String(format!("ExtResource(\"{ext_id}\")")),
        old_value: current,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    // Drop the inline sub-resource bookkeeping so the save does not ALSO emit a
    // `[sub_resource]` for a property that is now an external reference. The
    // flattened `<prefix>*` body companions stay: they are the physics/render
    // layer's cache of the shape's geometry and are still accurate, and the
    // saver already suppresses a `[sub_resource]` body once `__resref__` is Nil.
    if let Some(node) = state.scene_tree.get_node_mut(node_id) {
        node.set_property(&format!("__resref__{property}"), Variant::Nil);
        node.set_property(
            &format!("__extres__{property}"),
            Variant::String(res_path.to_string()),
        );
    }
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log("info", format!("Saved {property} to {res_path}"));

    send_json(stream, &format!(r#"{{"ok":true,"path":"{res_path}"}}"#));
}

fn api_new_resource_property(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(parsed) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let Some(node_raw) = parsed.get("node_id").and_then(|v| v.as_u64()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let Some(property) = parsed.get("property").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing property");
        return;
    };
    let Some(class_name) = parsed.get("class_name").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing class_name");
        return;
    };
    let (property, class_name) = (property.to_string(), class_name.to_string());
    // A bogus name would write a `[sub_resource type="…"]` section Godot cannot
    // load, so validate the name's shape before touching the scene.
    //
    // Deliberately NOT gated on ClassDB membership. `ClassDB` is populated by
    // explicit `register_*_classes()` calls, so at any moment it may hold every
    // class, none, or — the case that bit this route — a *subset* that omits the
    // resource classes: a server process had classes registered but not
    // `RectangleShape2D`, so a membership check rejected a name Godot accepts.
    // A partially-populated registry cannot answer "is this a real class?", and
    // the picker only ever sends names from its own subclass list.
    let well_formed = !class_name.is_empty()
        && class_name.starts_with(|c: char| c.is_ascii_uppercase())
        && class_name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_');
    if !well_formed {
        send_error(
            stream,
            400,
            &format!("unknown resource class '{class_name}'"),
        );
        return;
    }

    let mut state = state.lock().unwrap();
    let Some(node_id) = find_node_by_raw_id(&state.scene_tree, node_raw) else {
        send_error(stream, 404, "node not found");
        return;
    };

    let tree_root = state.scene_tree.root_id();
    let used = used_resource_ids(&state.scene_tree, tree_root);
    let id = next_resource_id(&used, &class_name);

    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: property.clone(),
        new_value: Variant::String(format!("SubResource(\"{id}\")")),
        old_value: Variant::Nil,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    if let Some(node) = state.scene_tree.get_node_mut(node_id) {
        node.set_property(
            &format!("__resref__{property}"),
            Variant::String(format!("{class_name}::{id}")),
        );
        // A file-backed reference and an inline one are mutually exclusive.
        node.set_property(&format!("__extres__{property}"), Variant::Nil);
    }

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log("info", format!("New {class_name} on '{property}'"));
    let event = format!(
        r#"{{"type":"property_changed","node_id":{node_raw},"property":"{prop}"}}"#,
        prop = property.replace('"', "\\\""),
    );
    publish_event(&mut state, event);

    send_json(
        stream,
        &format!(r#"{{"ok":true,"class_name":"{class_name}","id":"{id}"}}"#),
    );
}

/// `POST /api/property/set` — sets a property on a node.
fn api_set_property(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let property = match parsed.get("property").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing property");
            return;
        }
    };
    let value_json = match parsed.get("value") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing value");
            return;
        }
    };
    let new_value = match from_json(value_json) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid variant value");
            return;
        }
    };

    let mut state = state.lock().unwrap();

    // Live edit (pat-0q2kx.72): `{"runtime": true}` targets the RUNNING clone in
    // `run_main_loop`, which is a different tree from `state.scene_tree`. The
    // change lands on the next frame the game draws and — deliberately — does
    // NOT dirty the edit scene, matching Godot, where live-editing a running
    // game does not modify the saved scene.
    if parsed
        .get("runtime")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        if !state.is_running {
            send_error(stream, 400, "not running");
            return;
        }
        // ⚠️ Address the node by PATH, not by id. Play runs on a CLONE of the
        // scene, and cloning mints fresh `ObjectId`s — an id from the edit tree
        // matches nothing in the running one. Godot's live-edit protocol is
        // path-based for exactly this reason (scene/debugger live edit).
        //
        // An explicit `path` wins, which is what lets the inspector address a
        // node the script SPAWNED at runtime — it has no edit-tree twin, so no
        // id could be translated for it.
        let target_path = match parsed.get("path").and_then(|v| v.as_str()) {
            Some(p) => p.to_string(),
            None => {
                let Some(edit_id) = find_node_by_raw_id(&state.scene_tree, node_raw) else {
                    send_error(stream, 404, "node not found in the edit scene");
                    return;
                };
                absolute_node_path(&state.scene_tree, edit_id)
            }
        };
        let Some(main_loop) = state.run_main_loop.as_mut() else {
            send_error(stream, 400, "not running");
            return;
        };
        let tree = main_loop.tree_mut();
        let Some(node_id) = tree.get_node_by_path(&target_path) else {
            send_error(
                stream,
                404,
                &format!("node not found in the running scene: {target_path}"),
            );
            return;
        };
        let Some(node) = tree.get_node_mut(node_id) else {
            send_error(stream, 404, "node not found in the running scene");
            return;
        };
        node.set_property(&property, new_value);
        send_json(stream, r#"{"ok":true,"runtime":true}"#);
        return;
    }

    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    let prop_name = property.clone();
    // Cloned before the command takes ownership, so auto-key can record the
    // same value the edit applied.
    let keyed_value = new_value.clone();
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property,
        new_value,
        old_value: Variant::Nil,
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log("info", format!("Changed property '{}'", prop_name));

    // Editing an anchor/margin must REFLOW, not just store a number
    // (pat-0q2kx.19). `control_binding::invalidate_layout` re-resolves the
    // node's rect, re-arranges it if it is a container, and re-arranges its
    // parent when the parent is one — so a size-flag or min-size change
    // propagates to siblings. It had zero callers, which is why an anchor edit
    // in the inspector changed the stored value and moved nothing on screen.
    if crate::control_binding::is_layout_property(&prop_name) {
        let parent_size = Vector2::new(
            state.viewport_width.max(1) as f32,
            state.viewport_height.max(1) as f32,
        );
        crate::control_binding::invalidate_layout(&mut state.scene_tree, node_id, parent_size);
    }

    // Auto-key (pat-s3rrv.62): while armed, every property edit also records a
    // keyframe at the playhead. No-op when disarmed.
    auto_key_property(&mut state, node_id, &prop_name, &keyed_value);

    // pat-zzgh5: broadcast a mutation event to every `/api/events` subscriber.
    let event = format!(
        r#"{{"type":"property_changed","node_id":{node},"property":"{prop}"}}"#,
        node = node_raw,
        prop = prop_name.replace('"', "\\\""),
    );
    publish_event(&mut state, event);

    send_json(stream, r#"{"ok":true}"#);
}

/// pat-didnj: `PATCH /api/node/patch` — optimistic concurrency property update.
///
/// Body: `{"node_id": <u64>, "version": <u64>, "property": "<name>", "value": <variant>}`.
/// Returns `409 Conflict` if the supplied `version` does not match the node's
/// current monotonic version (a stale version indicates a concurrent write
/// landed first). On success bumps the version and returns
/// `{"ok":true,"version":<new>}`.
fn api_patch_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let supplied_version = match parsed.get("version").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing version");
            return;
        }
    };
    let property = match parsed.get("property").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing property");
            return;
        }
    };
    let value_json = match parsed.get("value") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing value");
            return;
        }
    };
    let new_value = match from_json(value_json) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid variant value");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    let current_version = state.node_versions.get(&node_id).copied().unwrap_or(0);
    if supplied_version != current_version {
        send_error(
            stream,
            409,
            &format!("stale version: supplied {supplied_version} != current {current_version}"),
        );
        return;
    }

    let prop_name = property.clone();
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property,
        new_value,
        old_value: Variant::Nil,
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    let new_version = current_version + 1;
    state.node_versions.insert(node_id, new_version);
    state.add_log(
        "info",
        format!("PATCH property '{prop_name}' v{current_version}->v{new_version}"),
    );

    send_json(stream, &format!(r#"{{"ok":true,"version":{new_version}}}"#));
}

/// The tile-layer node a command touches, if any.
///
/// Undo/redo has to write the grid back to `tile_map_data` as well, or the saved
/// scene keeps the state from before the Ctrl-Z while the editor shows the state
/// after it.
fn tilemap_node_of(cmd: &EditorCommand) -> Option<NodeId> {
    match cmd {
        EditorCommand::TileMapPaint { node_id, .. }
        | EditorCommand::TileMapFill { node_id, .. }
        | EditorCommand::TileMapResize { node_id, .. } => Some(*node_id),
        EditorCommand::Group { commands, .. } => commands.iter().find_map(tilemap_node_of),
        _ => None,
    }
}

/// `POST /api/undo` — undoes the last command.
fn api_undo(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    let mut cmd = match state.undo_stack.pop() {
        Some(c) => c,
        None => {
            send_error(stream, 400, "nothing to undo");
            return;
        }
    };

    if let Err(e) = cmd.undo(&mut state.scene_tree) {
        // Push it back if undo failed.
        state.undo_stack.push(cmd);
        send_error(stream, 500, &e.to_string());
        return;
    }

    let _ = cmd.undo_tilemap(&mut state.tile_grid_store);
    if let Some(nid) = tilemap_node_of(&cmd) {
        writeback_tile_grid(&mut state, nid);
    }
    state.redo_stack.push(cmd);
    // Undo may have removed nodes (e.g. undoing an add/duplicate); drop any
    // selected ids that no longer exist so the selection can't dangle.
    state.prune_selection();
    // pat-m6rbm: recompute the dirty flag against the saved revision so undoing
    // back to the save point clears `modified` (Godot semantics) rather than
    // leaving it latched true.
    state.scene_modified = state.undo_stack.len() != state.saved_undo_depth;
    state.add_log("info", "Undo");
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/redo` — redoes the last undone command.
fn api_redo(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    let mut cmd = match state.redo_stack.pop() {
        Some(c) => c,
        None => {
            send_error(stream, 400, "nothing to redo");
            return;
        }
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        state.redo_stack.push(cmd);
        send_error(stream, 500, &e.to_string());
        return;
    }

    let _ = cmd.execute_tilemap(&mut state.tile_grid_store);
    if let Some(nid) = tilemap_node_of(&cmd) {
        writeback_tile_grid(&mut state, nid);
    }
    state.undo_stack.push(cmd);
    // Redo may also remove nodes (e.g. redoing a delete); keep selection sane.
    state.prune_selection();
    // pat-m6rbm: recompute the dirty flag against the saved revision so redoing
    // past the save point re-marks the scene modified.
    state.scene_modified = state.undo_stack.len() != state.saved_undo_depth;
    state.add_log("info", "Redo");
    send_json(stream, r#"{"ok":true}"#);
}

/// Undoes a single command, mirroring `api_undo`'s scene-tree + tilemap +
/// selection bookkeeping but without touching the HTTP stream or logs. Returns
/// `Ok(false)` when the undo stack is empty (nothing more to undo), `Err` if the
/// command's own undo failed (in which case the command is pushed back intact).
fn undo_one(state: &mut EditorState) -> Result<bool, String> {
    let mut cmd = match state.undo_stack.pop() {
        Some(c) => c,
        None => return Ok(false),
    };
    if let Err(e) = cmd.undo(&mut state.scene_tree) {
        state.undo_stack.push(cmd);
        return Err(e.to_string());
    }
    let _ = cmd.undo_tilemap(&mut state.tile_grid_store);
    // Animation edits live in a second store, like tilemaps (pat-0q2kx.12).
    let _ = cmd.undo_animation(&mut state.animations);
    state.redo_stack.push(cmd);
    state.prune_selection();
    Ok(true)
}

/// Redoes a single command (the inverse of [`undo_one`]). Returns `Ok(false)`
/// when the redo stack is empty.
fn redo_one(state: &mut EditorState) -> Result<bool, String> {
    let mut cmd = match state.redo_stack.pop() {
        Some(c) => c,
        None => return Ok(false),
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        state.redo_stack.push(cmd);
        return Err(e.to_string());
    }
    let _ = cmd.execute_tilemap(&mut state.tile_grid_store);
    let _ = cmd.execute_animation(&mut state.animations);
    state.undo_stack.push(cmd);
    state.prune_selection();
    Ok(true)
}

/// `GET /api/history` — the undo/redo history for the History dock.
///
/// Models the edit timeline as a sequence of *versions*: version 0 is "The
/// Beginning" (the state before any action), and version `k` is the state after
/// the `k`-th action in chronological order. Already-applied actions live on the
/// undo stack (oldest first); undone actions live on the redo stack (its top is
/// the next action to redo), so the full chronological timeline is
/// `undo_stack ++ reverse(redo_stack)`. The current version is `undo_stack.len()`.
///
/// Entries are returned newest-first (Godot's History dock shows the most recent
/// action at the top and "The Beginning" at the bottom). Each entry carries its
/// `version`, human-readable `label`, whether it is the `current` version,
/// whether it is in the `future` (a redoable action shown dimmed), and a
/// `scope` ("scene" for scene-tree edits; "all" for the always-present
/// Beginning anchor) so the dock's Scene/Global filters can hide entries.
fn api_history(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        let esc = |s: &str| s.replace('\\', "\\\\").replace('"', "\\\"");
        let current = state.undo_stack.len();

        // Chronological timeline of (version, label): applied actions oldest
        // first, then undone actions in the order they would be redone.
        let mut timeline: Vec<(usize, String)> = Vec::new();
        for (i, cmd) in state.undo_stack.iter().enumerate() {
            timeline.push((i + 1, cmd.label()));
        }
        for (j, cmd) in state.redo_stack.iter().rev().enumerate() {
            timeline.push((current + 1 + j, cmd.label()));
        }
        let total = timeline.len();

        // Newest first for display, then the Beginning anchor at the bottom.
        let mut entries: Vec<String> = timeline
            .iter()
            .rev()
            .map(|(version, label)| {
                format!(
                    r#"{{"version":{},"label":"{}","current":{},"future":{},"scope":"scene"}}"#,
                    version,
                    esc(label),
                    *version == current,
                    *version > current
                )
            })
            .collect();
        entries.push(format!(
            r#"{{"version":0,"label":"The Beginning","current":{},"future":false,"scope":"all"}}"#,
            current == 0
        ));

        format!(
            r#"{{"current":{},"total":{},"entries":[{}]}}"#,
            current,
            total,
            entries.join(",")
        )
    };
    send_json(stream, &json);
}

/// `POST /api/history/goto` — jumps the edit state to a specific history
/// version (body `{"version": <n>}`), undoing or redoing as many steps as needed
/// to get there. Clicking any row in the History dock routes here. Out-of-range
/// versions are clamped to the valid `0..=total` range.
fn api_history_goto(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let target = match parsed.get("version").and_then(|v| v.as_u64()) {
        Some(v) => v as usize,
        None => {
            send_error(stream, 400, "missing version");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let total = state.undo_stack.len() + state.redo_stack.len();
    let target = target.min(total);
    let current = state.undo_stack.len();

    // Undo back toward the Beginning, or redo forward toward the latest action,
    // until the current version matches the requested one.
    if target < current {
        for _ in 0..(current - target) {
            match undo_one(&mut state) {
                Ok(true) => {}
                Ok(false) => break,
                Err(e) => {
                    send_error(stream, 500, &e);
                    return;
                }
            }
        }
    } else if target > current {
        for _ in 0..(target - current) {
            match redo_one(&mut state) {
                Ok(true) => {}
                Ok(false) => break,
                Err(e) => {
                    send_error(stream, 500, &e);
                    return;
                }
            }
        }
    }

    // Recompute the dirty flag against the saved revision (Godot semantics):
    // landing back on the save point clears `modified`, moving away re-marks it.
    state.scene_modified = state.undo_stack.len() != state.saved_undo_depth;
    state.add_log("info", "History");
    let json = format!(r#"{{"ok":true,"current":{}}}"#, state.undo_stack.len());
    send_json(stream, &json);
}

/// `GET /api/viewport` — returns the latest frame as BMP (from separate cache).
fn api_get_viewport_bmp(cache: &Arc<ViewportCache>, stream: &mut TcpStream) {
    let bmp = cache.bmp.lock().unwrap();
    match &*bmp {
        Some(data) => {
            send_binary(stream, "image/bmp", data);
        }
        None => {
            send_error(stream, 404, "no frame available");
        }
    }
}

/// `POST /api/viewport/resize` — the browser reports the real pixel size of the
/// viewport panel as `{ "w": <u32>, "h": <u32> }` so the render loop draws at
/// the panel's aspect ratio and fills it edge-to-edge, instead of a fixed
/// 640x480 frame that letterboxes into a centered square (Godot renders into the
/// whole viewport). Each axis is clamped to `[64, 2048]` to bound software-render
/// cost. The 3D camera's aspect is updated immediately so projection and gizmo
/// hit-testing match the new size even before the next frame is rendered.
/// Returns the accepted size: `{ "ok": true, "w": <u32>, "h": <u32> }`.
fn api_viewport_resize(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let clamp = |v: f64| (v.round() as i64).clamp(64, 2048) as u32;
    let mut state = state.lock().unwrap();
    if let Some(w) = p.get("w").and_then(|v| v.as_f64()) {
        state.render_width = clamp(w);
    }
    if let Some(h) = p.get("h").and_then(|v| v.as_f64()) {
        state.render_height = clamp(h);
    }
    let (w, h) = (state.render_width, state.render_height);
    // Keep the persistent 3D camera's aspect in sync right away.
    state.editor_viewport_3d.width = w;
    state.editor_viewport_3d.height = h;
    send_json(stream, &format!(r#"{{"ok":true,"w":{w},"h":{h}}}"#));
}

/// `GET /api/viewport/png` — returns the latest frame as PNG (from separate cache).
fn api_get_viewport_png(cache: &Arc<ViewportCache>, stream: &mut TcpStream) {
    let png = cache.png.lock().unwrap();
    match &*png {
        Some(data) => {
            send_binary(stream, "image/png", data);
        }
        None => {
            send_error(stream, 404, "no frame available");
        }
    }
}

/// pat-nzgdu.173: `GET /api/viewport/3d/camera_preview[?cinematic=1]` — renders a
/// PNG from a scene `Camera3D`'s viewpoint, distinct from the editor camera.
///
/// Without `cinematic`, previews the **selected** node (must be a Camera3D — the
/// Preview button only shows when one is selected). With `cinematic=1`, renders
/// through the scene's **active** camera (the first Camera3D in tree order).
/// 404 when there is no eligible camera.
fn api_viewport_3d_camera_preview(
    state: &Arc<Mutex<EditorState>>,
    query: &str,
    stream: &mut TcpStream,
) {
    let state = state.lock().unwrap();
    let is_camera = |id: NodeId| -> bool {
        state
            .scene_tree
            .get_node(id)
            .map(|n| n.class_name() == "Camera3D")
            .unwrap_or(false)
    };
    let camera = if query.contains("cinematic=1") {
        state
            .scene_tree
            .all_nodes_in_tree_order()
            .into_iter()
            .find(|id| is_camera(*id))
    } else {
        state.selected_node.filter(|id| is_camera(*id))
    };
    let camera = match camera {
        Some(c) => c,
        None => {
            send_error(stream, 404, "no Camera3D to preview");
            return;
        }
    };
    // A small 4:3 inset — this is a picture-in-picture overlay, not the main view.
    let fb =
        crate::viewport_3d_render::render_camera3d_preview(&state.scene_tree, camera, 320, 240);
    let png = encode_png_fast(&fb);
    send_binary(stream, "image/png", &png);
}

/// Crash-safe file write: writes `contents` to a sibling temp file,
/// fsyncs the data, then renames it over `path`. POSIX `rename(2)` is
/// atomic within a single filesystem, so a SIGKILL injected at any point
/// leaves either the previous file or the new file on disk — never a
/// partial or truncated target.
pub fn atomic_write(path: &std::path::Path, contents: &[u8]) -> std::io::Result<()> {
    let parent = path.parent().ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "path has no parent")
    })?;
    let file_name = path.file_name().and_then(|s| s.to_str()).ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::InvalidInput, "invalid file name")
    })?;
    let unique = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let tmp = parent.join(format!(
        ".{file_name}.atomic.{}.{unique}.tmp",
        std::process::id()
    ));

    let write_result = (|| -> std::io::Result<()> {
        let mut file = std::fs::File::create(&tmp)?;
        std::io::Write::write_all(&mut file, contents)?;
        file.sync_all()?;
        Ok(())
    })();
    if let Err(e) = write_result {
        let _ = std::fs::remove_file(&tmp);
        return Err(e);
    }

    if let Err(e) = std::fs::rename(&tmp, path) {
        let _ = std::fs::remove_file(&tmp);
        return Err(e);
    }

    if let Ok(dir) = std::fs::File::open(parent) {
        let _ = dir.sync_all();
    }
    Ok(())
}

/// `POST /api/scene/save` — saves the scene tree to a .tscn file.
fn api_save_scene(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let path = match parsed.get("path").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let root_id = state.scene_tree.root_id();

    // Find first child of root to use as scene root (the actual scene).
    let scene_root = state
        .scene_tree
        .get_node(root_id)
        .and_then(|n| n.children().first().copied());

    // Godot parity (`EditorNode::_save_scene` / `SCENE_SAVE_AS_SCENE`): an empty
    // scene has no root node, so it can't be saved. Godot shows "A root node is
    // required to save the scene." and aborts rather than writing a bare file.
    let save_root = match scene_root {
        Some(id) => id,
        None => {
            send_error(
                stream,
                400,
                "A root node is required to save the scene. You can add a root node using the Scene tree dock.",
            );
            return;
        }
    };
    // pat-s3rrv.66: Godot's `EditorNode::_save_scene` runs
    // `apply_changes_in_editors()` BEFORE serialising, so a plugin holding
    // unflushed edits can write them into the scene and have them land in the
    // file. Calling it after the save would be useless — the .tscn is already
    // written by then. Broadcast, not first-claim: every plugin must get it.
    dispatch_plugin_virtual(&mut state, "_apply_changes", &[], false);

    let tscn = TscnSaver::save_tree(&state.scene_tree, save_root);

    if let Err(e) = atomic_write(std::path::Path::new(&path), tscn.as_bytes()) {
        send_error(stream, 500, &format!("failed to write: {e}"));
        return;
    }

    // pat-s3rrv.66: `_save_external_data` runs AFTER the scene is written, not
    // before. The doc is explicit — "called after the editor saves the project
    // or when it's closed. It asks the plugin to save edited external
    // scenes/resources" — which is the opposite ordering from `_apply_changes`
    // above ("about to save"). Pairing them in one call site would have looked
    // tidy and put this one on the wrong side of the write.
    dispatch_plugin_virtual(&mut state, "_save_external_data", &[], false);

    // pat-s3rrv.66: `_get_state` is collected per scene on save, so reopening
    // the scene can hand each plugin its own view position / grid / folding back
    // through `_set_state`. Keyed by scene PATH here and by plugin NAME inside,
    // mirroring Godot's per-scene `editstate` metadata file.
    let plugin_state = collect_plugin_state(&mut state);
    if !plugin_state.is_empty() {
        state.plugin_scene_state.insert(path.clone(), plugin_state);
    }

    state.scene_file = Some(path.clone());
    state.scene_modified = false;
    // pat-m6rbm: the current undo-stack depth is now the clean save point, so
    // future undo/redo can clear/set `modified` relative to it.
    state.saved_undo_depth = state.undo_stack.len();
    // Godot parity: reflect the saved file on the active tab so `Save As` (and the
    // first save of an untitled scene) updates the tab's title from "Untitled" to
    // the filename and clears its modified marker (`set_scene_file_path` +
    // `set_scene_as_saved` + `scene_tabs->update_scene_tabs`).
    let filename = path
        .rsplit(['/', '\\'])
        .next()
        .filter(|s| !s.is_empty())
        .unwrap_or(&path)
        .to_string();
    let active = state.active_tab_index;
    if let Some(tab) = state.scene_tabs.get_mut(active) {
        tab.path = path.clone();
        tab.name = filename;
        tab.modified = false;
    }
    state.add_log("info", format!("Saved scene to '{}'", path));

    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/scene/load` — loads a .tscn file into the scene tree.
/// Resolves the scene's `WorldEnvironment` node (if any) into an
/// [`Environment3D`](gdserver3d::environment::Environment3D), following Godot's
/// resource indirection: the node's `environment = SubResource(...)` →
/// `Environment` fields → its `sky = SubResource(...)` → `Sky` →
/// `sky_material = SubResource(...)` → the concrete sky material. This lets the
/// editor viewport preview a scene's *own* environment (background, tonemap,
/// glow, fog, ambient) exactly as it would render at runtime, instead of the
/// generic preview environment. Returns `None` when the scene has no
/// `WorldEnvironment` or its environment can't be resolved.
fn world_environment_from_scene(
    scene: &gdscene::packed_scene::PackedScene,
    tree: &gdscene::SceneTree,
    project_root: Option<&str>,
) -> Option<gdserver3d::environment::Environment3D> {
    use gdserver3d::environment::Environment3D;
    use gdserver3d::sky::{Sky, SkyMaterial};

    // Parse a `"Class::id"` resref (from `__resref__<prop>`) or a raw
    // `"SubResource:id"` value into the sub-resource id.
    let resref_id = |v: &gdvariant::Variant| -> Option<String> {
        if let gdvariant::Variant::String(s) = v {
            if let Some((_, id)) = s.rsplit_once("::") {
                return Some(id.to_string());
            }
            if let Some(id) = s.strip_prefix("SubResource:") {
                return Some(id.to_string());
            }
        }
        None
    };

    // Find the first WorldEnvironment node and its `environment` sub-resource.
    let env_id = tree.all_nodes_in_tree_order().into_iter().find_map(|nid| {
        let node = tree.get_node(nid)?;
        if !node.is_class("WorldEnvironment") {
            return None;
        }
        resref_id(&node.get_property("__resref__environment"))
            .or_else(|| resref_id(&node.get_property("environment")))
    })?;

    let env_props = scene.sub_resource_props(&env_id)?;
    let mut env = Environment3D::from_properties(env_props.iter().map(|(k, v)| (k.as_str(), v)));

    // Resolve the nested Sky → sky material.
    if let Some(sky_id) = env_props.get("sky").and_then(resref_id) {
        if let Some(sky_props) = scene.sub_resource_props(&sky_id) {
            let mut material = sky_props
                .get("sky_material")
                .and_then(resref_id)
                .and_then(|mat_id| {
                    let mat_props = scene.sub_resource_props(&mat_id)?;
                    let props = mat_props.iter().map(|(k, v)| (k.as_str(), v));
                    Some(match scene.sub_resource_type(&mat_id) {
                        Some("PhysicalSkyMaterial") => SkyMaterial::Physical(
                            gdserver3d::sky::PhysicalSkyMaterial::from_properties(props),
                        ),
                        Some("PanoramaSkyMaterial") => SkyMaterial::Panoramic(
                            gdserver3d::sky::PanoramicSkyMaterial::from_properties(props),
                        ),
                        // A custom `shader_type sky` ShaderMaterial
                        // (pat-0q2kx.224). Without this arm it fell through to
                        // `_ => Procedural` below, so a scene with a shader sky
                        // silently rendered the default procedural one — the
                        // "unwired" symptom this bead is about.
                        Some("ShaderMaterial") => {
                            // `shader = SubResource("Shader_x")` names a sibling
                            // sub-resource whose `code` holds the source. An
                            // inline `code` on the material itself is also
                            // accepted, since the .tscn flattener sometimes
                            // lands it there.
                            //
                            // An `ExtResource` shader (a separate .gdshader file)
                            // is NOT resolved here — that needs the ext-resource
                            // path table, and `ShaderSkyMaterial::is_inert()`
                            // makes the miss fall back to a procedural sky rather
                            // than render black.
                            let code = mat_props
                                .get("shader")
                                .and_then(resref_id)
                                .and_then(|sid| scene.sub_resource_props(&sid))
                                .and_then(|sp| match sp.get("code") {
                                    Some(gdvariant::Variant::String(c)) => Some(c.clone()),
                                    _ => None,
                                })
                                .or_else(|| match mat_props.get("code") {
                                    Some(gdvariant::Variant::String(c)) => Some(c.clone()),
                                    _ => None,
                                })
                                .unwrap_or_default();

                            let mut m = gdserver3d::shader::ShaderMaterial3D::new();
                            m.shader = Some(gdserver3d::shader::Shader3D::new(
                                gdserver3d::shader::ShaderType3D::Sky,
                                &code,
                            ));
                            for (k, v) in mat_props.iter() {
                                if let Some(name) = k.strip_prefix("shader_parameter/") {
                                    if v != &gdvariant::Variant::Nil {
                                        m.set_shader_parameter(name, v.clone());
                                    }
                                }
                            }
                            SkyMaterial::Shader(gdserver3d::sky::ShaderSkyMaterial::new(m))
                        }
                        _ => SkyMaterial::Procedural(
                            gdserver3d::sky::ProceduralSkyMaterial::from_properties(props),
                        ),
                    })
                })
                .unwrap_or_else(|| {
                    SkyMaterial::Procedural(gdserver3d::sky::ProceduralSkyMaterial::default())
                });

            // Load any panorama / sky_cover / night_sky texture the material
            // references. The `.tscn` parser only records each texture's resource
            // path; decode it here (sRGB→linear) so the layer actually renders.
            // Requires a known project res:// root — without one (e.g. a bare
            // scene load), the layer is left unset, exactly as Godot draws a Sky
            // whose cover texture failed to load.
            if let Some(root) = project_root {
                let root = std::path::Path::new(root);
                gdserver3d::sky::resolve_sky_material_textures(&mut material, |ref_str| {
                    let res_path = resolve_texture_ref_to_res_path(scene, ref_str)?;
                    let fs_path = resolve_res_path(root, &res_path).ok()?;
                    let (width, height, pixels) =
                        gdresource::importers::load_color_texture_linear(&fs_path).ok()?;
                    Some(gdserver3d::sky::PanoramaTexture {
                        width,
                        height,
                        pixels,
                    })
                });
            }

            env.sky = Some(Sky {
                material,
                ..Sky::default()
            });
        }
    }

    Some(env)
}

/// Resolves a sky-material texture reference — as stored by the `.tscn` parser —
/// to a `res://` path. The parser normalizes `sky_cover = ExtResource("id")` to
/// the string `"ExtResource:<id>"`, which we resolve via the scene's
/// ext-resource table; a directly-embedded `res://…` path passes through.
/// Returns `None` for anything else (e.g. an inline `SubResource` texture, which
/// carries no file path).
fn resolve_texture_ref_to_res_path(
    scene: &gdscene::packed_scene::PackedScene,
    ref_str: &str,
) -> Option<String> {
    if let Some(id) = ref_str.strip_prefix("ExtResource:") {
        return scene.ext_resources().get(id).map(|e| e.path.clone());
    }
    if ref_str.starts_with("res://") {
        return Some(ref_str.to_string());
    }
    None
}

fn api_load_scene(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let path = match parsed.get("path").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };

    let source = match std::fs::read_to_string(&path) {
        Ok(s) => s,
        Err(e) => {
            send_error(stream, 400, &format!("failed to read: {e}"));
            return;
        }
    };

    let scene = match PackedScene::from_tscn(&source) {
        Ok(s) => s,
        Err(e) => {
            send_error(stream, 400, &format!("failed to parse: {e}"));
            return;
        }
    };

    let mut state = state.lock().unwrap();

    // Replace the scene tree with a fresh one.
    let mut new_tree = SceneTree::new();
    let root_id = new_tree.root_id();

    match add_packed_scene_to_tree(&mut new_tree, root_id, &scene) {
        Ok(_) => {
            // If the scene has a WorldEnvironment, preview *its* environment
            // (background, tonemap, glow, fog, ambient) like Godot; otherwise
            // restore the default editor preview environment. Only the inner
            // Environment3D is swapped — the preview sun/toggles are kept.
            // Cloned so the res:// root can be read while the match arms below
            // mutably borrow `state`.
            let project_root = state.project_root.clone();
            match world_environment_from_scene(&scene, &new_tree, project_root.as_deref()) {
                Some(env) => state
                    .editor_viewport_3d
                    .environment
                    .load_from_environment(env),
                None => {
                    state.editor_viewport_3d.environment.environment =
                        crate::viewport_3d::EnvironmentPreview3D::default().environment;
                }
            }
            state.scene_tree = new_tree;
            // The loaded scene's AnimationPlayer clips become the panel's list
            // (pat-0q2kx.54); before this, opening a .tscn with animations
            // showed an empty animation panel.
            sync_animations_from_scene(&mut state);
            // The loaded scene's tile layers become paintable grids
            // (pat-0q2kx.75); before this the store was never populated from a
            // scene, so every paint into an opened .tscn was silently dropped.
            sync_tile_grids_from_scene(&mut state);
            // pat-0q2kx.76: `@tool` scripts in the opened scene run in edit
            // mode, exactly as Godot does.
            sync_tool_scripts_from_scene(&mut state);
            state.selected_node = None;
            state.selected_nodes.clear();
            state.undo_stack.clear();
            state.redo_stack.clear();
            state.scene_file = Some(path.clone());
            state.scene_modified = false;
            // pat-m6rbm: the undo stack was just cleared, so depth 0 is the
            // clean save point for the freshly loaded scene.
            state.saved_undo_depth = 0;
            // Reflect the loaded scene on its tab: the active tab now shows the
            // scene's filename (not "Untitled") and is no longer modified. If the
            // scene is already open in another tab, focus that tab instead of
            // duplicating it.
            if let Some(existing) = state
                .scene_tabs
                .iter()
                .position(|t| !t.path.is_empty() && t.path == path)
            {
                state.active_tab_index = existing;
            } else if state.active_tab_index < state.scene_tabs.len() {
                let name = path.rsplit('/').next().unwrap_or(&path).to_string();
                let idx = state.active_tab_index;
                let tab = &mut state.scene_tabs[idx];
                tab.path = path.clone();
                tab.name = name;
                tab.modified = false;
            }
            // pat-s3rrv.66: hand each plugin back the state it saved for THIS
            // scene. Cloned out first because `restore_plugin_state` needs
            // `&mut state` to call into the plugin instances, and the map lives
            // on the same struct.
            if let Some(saved) = state.plugin_scene_state.get(&path).cloned() {
                restore_plugin_state(&mut state, &saved);
            }
            state.add_log("info", format!("Loaded scene from '{}'", path));
            send_json(stream, r#"{"ok":true}"#);
        }
        Err(e) => {
            send_error(stream, 500, &format!("failed to instance: {e}"));
        }
    }
}

// ---------------------------------------------------------------------------
// Viewport interaction endpoints
// ---------------------------------------------------------------------------

/// `POST /api/viewport/click` — hit-test and select node at pixel coords.
fn api_viewport_click(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    let mut state = state.lock().unwrap();

    // pat-s3rrv.66: plugins get the click BEFORE the editor's own select tool.
    // A plugin returning true has CONSUMED the event, so the selection must not
    // change — that is the whole point of `_forward_canvas_gui_input`, and a
    // plugin implementing its own click-to-place tool is unusable without it.
    let event = canvas_click_event(x, y);
    if let Some(folder) =
        dispatch_plugin_virtual(&mut state, "_forward_canvas_gui_input", &[event], true)
    {
        let selected = match state.selected_node {
            Some(id) => id.raw().to_string(),
            None => "null".to_string(),
        };
        send_json(
            stream,
            &format!(
                r#"{{"selected":{selected},"consumed_by":"{}"}}"#,
                folder.replace('"', "")
            ),
        );
        return;
    }

    let vw = state.viewport_width;
    let vh = state.viewport_height;
    let zoom = state.viewport_zoom;
    let pan = state.viewport_pan;
    let hit =
        crate::scene_renderer::hit_test_with_zoom_pan(&state.scene_tree, vw, vh, zoom, pan, x, y);

    // Edit-locked nodes are unpickable in the viewport: drop a locked hit so
    // clicking it selects nothing (matches Godot's lock behavior).
    let hit = hit.filter(|&id| {
        state.scene_tree.get_node(id).map_or(true, |n| {
            !(matches!(n.get_property("_edit_lock_"), Variant::Bool(true))
                || matches!(n.get_property("_locked"), Variant::Bool(true)))
        })
    });

    // Children-selection lock: a click on a grouped node's descendant selects
    // the grouped ancestor instead of the descendant.
    let hit = hit.map(|id| resolve_group_selection(&state.scene_tree, id));

    state.selected_node = hit;
    state.selected_nodes = hit.into_iter().collect();

    match hit {
        Some(id) => send_json(stream, &format!(r#"{{"selected":{}}}"#, id.raw())),
        None => send_json(stream, r#"{"selected":null}"#),
    }
}

/// `POST /api/viewport/drag_start` — begin dragging a node.
fn api_viewport_drag_start(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    let mut state = state.lock().unwrap();

    // pat-s3rrv.66: plugins get the press that BEGINS a drag, before the
    // editor's own hit test. Only the click route forwarded before this, so a
    // plugin could consume a click and then watch the editor drag the node out
    // from under it on the very next gesture.
    //
    // Consuming here means `drag_state` is never set, so the editor's drag
    // never starts and `drag_end` finds nothing to commit — the plugin owns the
    // whole gesture rather than half of it.
    let event = canvas_button_event(x, y, true);
    if let Some(folder) =
        dispatch_plugin_virtual(&mut state, "_forward_canvas_gui_input", &[event], true)
    {
        send_json(
            stream,
            &format!(
                r#"{{"ok":true,"consumed_by":"{}"}}"#,
                folder.replace('"', "")
            ),
        );
        return;
    }

    let vw = state.viewport_width;
    let vh = state.viewport_height;
    let zoom = state.viewport_zoom;
    let pan = state.viewport_pan;
    let hit =
        crate::scene_renderer::hit_test_with_zoom_pan(&state.scene_tree, vw, vh, zoom, pan, x, y);

    match hit {
        Some(node_id) => {
            let offset = crate::scene_renderer::camera_offset_with_zoom_pan(
                &state.scene_tree,
                vw,
                vh,
                zoom,
                pan,
            );
            let node_pos = state
                .scene_tree
                .get_node(node_id)
                .map(|n| match n.get_property("position") {
                    Variant::Vector2(v) => v,
                    _ => Vector2::ZERO,
                })
                .unwrap_or(Vector2::ZERO);

            state.selected_node = Some(node_id);
            state.drag_state = Some(DragState {
                node_id,
                start_pixel: Vector2::new(x, y),
                start_node_pos: node_pos,
                camera_offset: offset,
            });

            send_json(
                stream,
                &format!(r#"{{"dragging":true,"node_id":{}}}"#, node_id.raw()),
            );
        }
        None => {
            state.drag_state = None;
            send_json(stream, r#"{"dragging":false}"#);
        }
    }
}

/// `POST /api/viewport/drag` — update node position during drag.
fn api_viewport_drag(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    let mut state = state.lock().unwrap();

    let drag = match &state.drag_state {
        Some(d) => d.clone(),
        None => {
            send_json(stream, r#"{"dragging":false}"#);
            return;
        }
    };

    // Pixel delta divided by zoom gives world-space delta.
    let zoom = state.viewport_zoom as f32;
    let pixel_delta = Vector2::new(x - drag.start_pixel.x, y - drag.start_pixel.y);
    let world_delta = Vector2::new(pixel_delta.x / zoom, pixel_delta.y / zoom);
    let candidate_pos = drag.start_node_pos + world_delta;

    // Apply grid snap and smart snap.
    let settings = state.display_settings.clone();
    let (new_pos, guides) = apply_snap(
        &state.scene_tree,
        &settings,
        &state.guides,
        drag.node_id,
        candidate_pos,
    );
    state.snap_guides = guides;

    if let Some(node) = state.scene_tree.get_node_mut(drag.node_id) {
        node.set_property("position", Variant::Vector2(new_pos));
    }

    send_json(
        stream,
        &format!(r#"{{"dragging":true,"x":{},"y":{}}}"#, new_pos.x, new_pos.y),
    );
}

/// `POST /api/viewport/drag_end` — finalize drag, clear drag state.
fn api_viewport_drag_end(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    let mut state = state.lock().unwrap();

    // The RELEASE half of the same gesture, forwarded as `pressed: false`.
    //
    // ⚠️ Placed BEFORE `drag_state.take()`. A plugin that claimed the press
    // left `drag_state` unset, so this only ever reaches a gesture the EDITOR
    // owns; consuming it therefore means "do not commit the move", which is
    // well-defined because nothing has been applied yet — the delta is computed
    // and written below.
    let release = canvas_button_event(x, y, false);
    if let Some(folder) =
        dispatch_plugin_virtual(&mut state, "_forward_canvas_gui_input", &[release], true)
    {
        state.drag_state = None;
        send_json(
            stream,
            &format!(
                r#"{{"ok":true,"consumed_by":"{}"}}"#,
                folder.replace('"', "")
            ),
        );
        return;
    }

    let drag = match state.drag_state.take() {
        Some(d) => d,
        None => {
            send_json(stream, r#"{"ok":true}"#);
            return;
        }
    };

    // Pixel delta divided by zoom gives world-space delta.
    let zoom = state.viewport_zoom as f32;
    let pixel_delta = Vector2::new(x - drag.start_pixel.x, y - drag.start_pixel.y);
    let world_delta = Vector2::new(pixel_delta.x / zoom, pixel_delta.y / zoom);
    let candidate_pos = drag.start_node_pos + world_delta;

    let settings = state.display_settings.clone();
    let (new_pos, _) = apply_snap(
        &state.scene_tree,
        &settings,
        &state.guides,
        drag.node_id,
        candidate_pos,
    );
    state.snap_guides.clear();

    // Commit the drag as an undoable step (pat-0q2kx.12).
    //
    // Godot's EditorUndoRedoManager records every transform drag, so Ctrl+Z
    // puts the node back where it started. This wrote the position directly, so
    // a drag was permanent — the highest-harm undo gap in the editor.
    //
    // `/api/viewport/drag` writes `position` live for visual feedback, so the
    // node currently holds the LAST MID-DRAG value, not where the drag began.
    // `SetProperty::execute` captures `old_value` from whatever is stored, so
    // the pre-drag position has to go back first — otherwise undo would restore
    // the final drag-move frame and appear to do nothing at all.
    if let Some(node) = state.scene_tree.get_node_mut(drag.node_id) {
        node.set_property("position", Variant::Vector2(drag.start_node_pos));
    }
    let mut cmd = EditorCommand::SetProperty {
        node_id: drag.node_id,
        property: "position".to_string(),
        new_value: Variant::Vector2(new_pos),
        old_value: Variant::Nil,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;

    send_json(
        stream,
        &format!(r#"{{"ok":true,"x":{},"y":{}}}"#, new_pos.x, new_pos.y),
    );
}

// ---------------------------------------------------------------------------
// Viewport zoom/pan endpoints
// ---------------------------------------------------------------------------

/// `GET /api/viewport/zoom_pan` — returns current zoom and pan state.
fn api_get_zoom_pan(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        format!(
            r#"{{"zoom":{},"pan_x":{},"pan_y":{}}}"#,
            state.viewport_zoom, state.viewport_pan.0, state.viewport_pan.1
        )
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/zoom` — sets the viewport zoom level.
fn api_set_zoom(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let zoom = parsed.get("zoom").and_then(|v| v.as_f64()).unwrap_or(1.0);
    let mut state = state.lock().unwrap();
    state.viewport_zoom = zoom.clamp(0.1, 16.0);
    let json = format!(
        r#"{{"zoom":{},"pan_x":{},"pan_y":{}}}"#,
        state.viewport_zoom, state.viewport_pan.0, state.viewport_pan.1
    );
    send_json(stream, &json);
}

/// `POST /api/viewport/pan` — sets the viewport pan offset.
fn api_set_pan(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0);
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0);
    let mut state = state.lock().unwrap();
    state.viewport_pan = (x, y);
    let json = format!(
        r#"{{"zoom":{},"pan_x":{},"pan_y":{}}}"#,
        state.viewport_zoom, x, y
    );
    send_json(stream, &json);
}

/// `POST /api/viewport/pan_by` — pans the viewport by a cursor delta
/// (middle-drag / space-drag): accumulates `dx`/`dy` onto the current pan
/// offset. Panning never changes the current selection.
fn api_pan_by(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let dx = parsed.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0);
    let dy = parsed.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0);
    let mut state = state.lock().unwrap();
    state.viewport_pan = (state.viewport_pan.0 + dx, state.viewport_pan.1 + dy);
    let json = format!(
        r#"{{"zoom":{},"pan_x":{},"pan_y":{}}}"#,
        state.viewport_zoom, state.viewport_pan.0, state.viewport_pan.1
    );
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// 3D spatial-editor camera navigation (pat-3dnav)
//
// These drive the persistent `editor_viewport_3d` camera so the spatial editor
// orbits / pans / zooms like Godot's 3D viewport. Deltas are raw mouse pixels;
// the camera applies its own orbit/pan/zoom sensitivities. They are *navigation*
// (not scene edits), so they stay usable while the runtime is playing.
// ---------------------------------------------------------------------------

/// Serializes the 3D editor camera state to JSON (yaw / pitch / distance and the
/// focus point) so the frontend can label the view and draw an axis gizmo.
fn editor_viewport_3d_json(state: &EditorState) -> String {
    let c = &state.editor_viewport_3d.camera;
    // The view-space directions of the world X/Y/Z axes are the columns of the
    // view transform's basis. The frontend uses them to draw the top-right
    // navigation gizmo (the colored axis ball) the way Godot does.
    let v = c.view_transform();
    let ortho = matches!(c.projection, crate::viewport_3d::Projection::Orthographic);
    let vp = &state.editor_viewport_3d;
    format!(
        r#"{{"yaw":{},"pitch":{},"distance":{},"focus_x":{},"focus_y":{},"focus_z":{},"ortho":{},"bx":[{},{},{}],"by":[{},{},{}],"bz":[{},{},{}],"sun":{},"environ":{},"grid":{},"origin":{},"local":{},"snap":{},"snap_t":{},"snap_r":{},"snap_s":{},"fly_speed":{}}}"#,
        c.yaw,
        c.pitch,
        c.distance,
        c.focus_point.x,
        c.focus_point.y,
        c.focus_point.z,
        ortho,
        v.basis.x.x,
        v.basis.x.y,
        v.basis.x.z,
        v.basis.y.x,
        v.basis.y.y,
        v.basis.y.z,
        v.basis.z.x,
        v.basis.z.y,
        v.basis.z.z,
        vp.environment.sun_enabled,
        vp.environment.enabled,
        vp.grid.visible,
        vp.show_origin,
        vp.use_local_space,
        vp.use_snap,
        vp.snap_translate,
        vp.snap_rotate,
        vp.snap_scale,
        c.fly_speed,
    )
}

/// Collects the node ids the spatial toolbar acts on: the full multi-selection
/// when any, otherwise the single primary selection.
fn selection_node_ids(state: &EditorState) -> Vec<NodeId> {
    if !state.selected_nodes.is_empty() {
        state.selected_nodes.clone()
    } else {
        state.selected_node.into_iter().collect()
    }
}

/// `POST /api/viewport/3d/view_flag` — toggles a boolean 3D viewport view/preview
/// flag from the spatial toolbar: `{ "flag": "<name>", "value": <bool?> }`, where
/// `<name>` is `sun`, `environment`, `grid`, `origin`, `local_space`, or `snap`.
/// `value` is optional; when omitted the flag is flipped. Returns the full 3D
/// viewport state so the toolbar re-syncs its button states.
fn api_viewport_3d_view_flag(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let flag = p
        .get("flag")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let want = p.get("value").and_then(|v| v.as_bool());
    let mut state = state.lock().unwrap();
    let vp = &mut state.editor_viewport_3d;
    let set = |b: &mut bool| *b = want.unwrap_or(!*b);
    let ok = match flag.as_str() {
        "sun" => {
            set(&mut vp.environment.sun_enabled);
            true
        }
        "environment" => {
            set(&mut vp.environment.enabled);
            true
        }
        "grid" => {
            set(&mut vp.grid.visible);
            true
        }
        "origin" => {
            set(&mut vp.show_origin);
            true
        }
        "local_space" => {
            set(&mut vp.use_local_space);
            true
        }
        "snap" => {
            set(&mut vp.use_snap);
            true
        }
        _ => false,
    };
    if !ok {
        send_error(stream, 400, "unknown flag");
        return;
    }
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/snap_config` — sets the transform snap increments
/// (Godot's Configure Snap dialog): `{ "translate": <f>, "rotate": <deg>,
/// "scale": <frac> }`. Any omitted field is left unchanged. Returns 3D state.
fn api_viewport_3d_snap_config(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mut state = state.lock().unwrap();
    let vp = &mut state.editor_viewport_3d;
    if let Some(t) = p.get("translate").and_then(|v| v.as_f64()) {
        vp.snap_translate = (t as f32).max(0.0);
    }
    if let Some(r) = p.get("rotate").and_then(|v| v.as_f64()) {
        vp.snap_rotate = (r as f32).max(0.0);
    }
    if let Some(s) = p.get("scale").and_then(|v| v.as_f64()) {
        vp.snap_scale = (s as f32).max(0.0);
    }
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/sun_config` — sets preview-sun parameters (Godot's Sun
/// and Environment settings): `{ "energy": <f>, "dx","dy","dz": <dir> }`. Any
/// omitted field is unchanged; the direction is renormalized. Returns 3D state.
fn api_viewport_3d_sun_config(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mut state = state.lock().unwrap();
    let env = &mut state.editor_viewport_3d.environment;
    if let Some(e) = p.get("energy").and_then(|v| v.as_f64()) {
        env.sun_energy = (e as f32).max(0.0);
    }
    let mut dir = env.sun_direction;
    if let Some(v) = p.get("dx").and_then(|v| v.as_f64()) {
        dir.x = v as f32;
    }
    if let Some(v) = p.get("dy").and_then(|v| v.as_f64()) {
        dir.y = v as f32;
    }
    if let Some(v) = p.get("dz").and_then(|v| v.as_f64()) {
        dir.z = v as f32;
    }
    let len = (dir.x * dir.x + dir.y * dir.y + dir.z * dir.z).sqrt();
    if len > 1e-5 {
        env.sun_direction = gdcore::math::Vector3::new(dir.x / len, dir.y / len, dir.z / len);
    }
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/translate_selection` — adds a world-space translation
/// `{ "dx","dy","dz" }` to every selected spatial node (Godot's Transform Dialog
/// relative translate). Non-3D nodes are skipped. Returns the moved count.
fn api_viewport_3d_translate_selection(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let dx = p.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dy = p.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dz = p.get("dz").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let mut state = state.lock().unwrap();
    let ids = selection_node_ids(&state);
    let mut moved = 0u32;
    for id in ids {
        let is3d = matches!(
            state
                .scene_tree
                .get_node(id)
                .map(|n| n.get_property("position")),
            Some(Variant::Vector3(_))
        ) || matches!(
            state
                .scene_tree
                .get_node(id)
                .map(|n| n.get_property("transform")),
            Some(Variant::Transform3D(_))
        );
        if !is3d {
            continue;
        }
        let gt = gdscene::node3d::get_global_transform(&state.scene_tree, id);
        set_node_world_origin(
            &mut state.scene_tree,
            id,
            gdcore::math::Vector3::new(gt.origin.x + dx, gt.origin.y + dy, gt.origin.z + dz),
        );
        moved += 1;
    }
    if moved > 0 {
        state.scene_modified = true;
    }
    send_json(stream, &format!(r#"{{"ok":true,"moved":{moved}}}"#));
}

/// `POST /api/viewport/3d/snap_to_floor` — drops every selected spatial node to
/// the ground plane (y = 0), keeping its x/z (Godot's Transform → Snap Object to
/// Floor). Non-3D nodes (no Vector3 `position`) are skipped. Returns the count.
fn api_viewport_3d_snap_to_floor(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    let ids = selection_node_ids(&state);
    let mut moved = 0u32;
    for id in ids {
        let is3d = matches!(
            state
                .scene_tree
                .get_node(id)
                .map(|n| n.get_property("position")),
            Some(Variant::Vector3(_))
        );
        if !is3d {
            continue;
        }
        let gt = gdscene::node3d::get_global_transform(&state.scene_tree, id);
        gdscene::node3d::set_global_position(
            &mut state.scene_tree,
            id,
            gdcore::math::Vector3::new(gt.origin.x, 0.0, gt.origin.z),
        );
        moved += 1;
    }
    if moved > 0 {
        state.scene_modified = true;
    }
    send_json(stream, &format!(r#"{{"ok":true,"moved":{moved}}}"#));
}

/// `POST /api/viewport/3d/ground_point` — projects a viewport pixel `{x,y}` onto
/// the ground plane (y = 0) and returns the world point, for the Ruler tool's
/// distance measurement. Returns `{ "hit": false }` when the ray is parallel to
/// or points away from the plane.
fn api_viewport_3d_ground_point(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let x = p.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = p.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let state = state.lock().unwrap();
    let ray = state.editor_viewport_3d.screen_to_ray(x, y);
    if ray.direction.y.abs() < 1e-6 {
        send_json(stream, r#"{"hit":false}"#);
        return;
    }
    let t = -ray.origin.y / ray.direction.y;
    if t < 0.0 {
        send_json(stream, r#"{"hit":false}"#);
        return;
    }
    let px = ray.origin.x + ray.direction.x * t;
    let pz = ray.origin.z + ray.direction.z * t;
    send_json(
        stream,
        &format!(r#"{{"hit":true,"x":{px},"y":0.0,"z":{pz}}}"#),
    );
}

/// `POST /api/viewport/3d/lock` — locks or unlocks every selected node
/// (`{ "locked": <bool> }`), setting Godot's `_edit_lock_` meta. Returns count.
fn api_viewport_3d_lock(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let locked = p.get("locked").and_then(|v| v.as_bool()).unwrap_or(true);
    let mut state = state.lock().unwrap();
    let ids = selection_node_ids(&state);
    let mut count = 0u32;
    for id in ids {
        if let Some(n) = state.scene_tree.get_node_mut(id) {
            n.set_property("_edit_lock_", Variant::Bool(locked));
            count += 1;
        }
    }
    if count > 0 {
        state.scene_modified = true;
    }
    send_json(
        stream,
        &format!(r#"{{"ok":true,"locked":{locked},"count":{count}}}"#),
    );
}

/// `POST /api/viewport/3d/group` — groups or ungroups every selected node
/// (`{ "grouped": <bool> }`), setting Godot's `_edit_group_` meta. Returns count.
fn api_viewport_3d_group(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let grouped = p.get("grouped").and_then(|v| v.as_bool()).unwrap_or(true);
    let mut state = state.lock().unwrap();
    let ids = selection_node_ids(&state);
    let mut count = 0u32;
    for id in ids {
        if let Some(n) = state.scene_tree.get_node_mut(id) {
            n.set_property("_edit_group_", Variant::Bool(grouped));
            count += 1;
        }
    }
    if count > 0 {
        state.scene_modified = true;
    }
    send_json(
        stream,
        &format!(r#"{{"ok":true,"grouped":{grouped},"count":{count}}}"#),
    );
}

/// `POST /api/viewport/3d/orbit` — orbit the 3D editor camera by a mouse delta
/// (`dx`, `dy` in pixels), rotating around the focus point.
fn api_viewport_3d_orbit(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let dx = parsed.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dy = parsed.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let mut state = state.lock().unwrap();
    state.editor_viewport_3d.camera.orbit(dx, dy);
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/pan` — pan the 3D editor camera by a mouse delta
/// (`dx`, `dy` in pixels), sliding the focus point in the camera plane.
fn api_viewport_3d_pan(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let dx = parsed.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dy = parsed.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let mut state = state.lock().unwrap();
    state.editor_viewport_3d.camera.pan(dx, dy);
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/fly/begin` — enters Godot's right-mouse free-look mode
/// (look around in place + WASD/QE fly), instead of orbiting a focus point.
fn api_viewport_3d_fly_begin(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let mut s = state.lock().unwrap();
        s.editor_viewport_3d.camera.begin_fly();
        editor_viewport_3d_json(&s)
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/fly/look` — rotates the free-look camera in place by a
/// mouse delta `{dx,dy}` (the camera turns without orbiting a pivot).
fn api_viewport_3d_fly_look(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let dx = p.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dy = p.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let json = {
        let mut s = state.lock().unwrap();
        s.editor_viewport_3d.camera.fly_look(dx, dy);
        editor_viewport_3d_json(&s)
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/fly/move` — flies the camera by a local direction
/// `{x:right, y:up, z:forward}` (Godot's WASD/QE while right-mouse is held).
///
/// The optional `speed` field is a per-event movement multiplier so the client
/// can apply Godot's free-look modifiers: Shift speeds movement up (×3) and Alt
/// slows it down (×0.333). It defaults to 1.0 and is clamped to a sane range.
fn api_viewport_3d_fly_move(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let x = p.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = p.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let z = p.get("z").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let speed = (p.get("speed").and_then(|v| v.as_f64()).unwrap_or(1.0) as f32).clamp(0.01, 100.0);
    let json = {
        let mut s = state.lock().unwrap();
        // A fixed step per key event; browser key-repeat makes holding continuous.
        // `speed` scales the per-event step (Godot's Shift/Alt freelook modifiers).
        s.editor_viewport_3d
            .on_fly_move(gdcore::math::Vector3::new(x, y, z), 0.08 * speed);
        editor_viewport_3d_json(&s)
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/fly/speed` — scales the free-look flight speed by
/// `{factor}` (Godot's mouse-wheel-while-right-held). Factor > 1 speeds up,
/// < 1 slows down. Returns the full 3D state (including the new `fly_speed`).
fn api_viewport_3d_fly_speed(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let factor = p.get("factor").and_then(|v| v.as_f64()).unwrap_or(1.0) as f32;
    let json = {
        let mut s = state.lock().unwrap();
        s.editor_viewport_3d.camera.scale_fly_speed(factor);
        editor_viewport_3d_json(&s)
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/fly/end` — exits free-look (right mouse released).
fn api_viewport_3d_fly_end(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let mut s = state.lock().unwrap();
        s.editor_viewport_3d.camera.end_fly();
        editor_viewport_3d_json(&s)
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/zoom` — dolly the 3D editor camera in/out by a scroll
/// `delta` (positive = zoom in, negative = zoom out).
fn api_viewport_3d_zoom(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let delta = parsed.get("delta").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let mut state = state.lock().unwrap();
    state.editor_viewport_3d.camera.zoom(delta);
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/reset` — restore the default 3/4 floor framing.
fn api_viewport_3d_reset(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    let w = state.editor_viewport_3d.width;
    let h = state.editor_viewport_3d.height;
    state.editor_viewport_3d = default_editor_viewport_3d();
    state.editor_viewport_3d.width = w;
    state.editor_viewport_3d.height = h;
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/select` — raycast-select the `Node3D` under a viewport
/// click at pixel (`x`, `y`). Mirrors the 2D `viewport/click`: the hit becomes
/// the editor's selection (so the tree + inspector update), and its id (or null)
/// is returned. A click on empty space clears the selection.
fn api_viewport_3d_select(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    // Shift/Ctrl-click adds (toggles) the hit node to the selection (multi-select).
    let add = parsed.get("add").and_then(|v| v.as_bool()).unwrap_or(false);

    let mut state = state.lock().unwrap();

    // pat-s3rrv.66: plugins get the 3D event before the editor's own selection.
    //
    // ⚠️ Godot passes `_forward_3d_gui_input(camera, event)` — arity TWO, and a
    // different shape from the canvas sibling's single argument. The camera is
    // the viewport's, so a plugin can unproject the event itself.
    let camera = editor_camera_3d_value(&state.editor_viewport_3d.camera);
    let event = canvas_button_event(x, y, true);
    let after = dispatch_forward_3d_gui_input(&mut state, &[camera, event]);
    if !after.allows_editor_selection() {
        // STOP and CUSTOM both suppress the selection; they differ only in
        // whether the remaining plugins were still offered the event, which
        // `dispatch_forward_3d_gui_input` has already handled.
        send_json(
            stream,
            &format!(
                r#"{{"ok":true,"after_gui_input":"{}"}}"#,
                match after {
                    AfterGuiInput::Stop => "stop",
                    AfterGuiInput::Custom => "custom",
                    AfterGuiInput::Pass => "pass",
                }
            ),
        );
        return;
    }

    // Take a single &mut to the state so the viewport (mut) and scene tree (shared)
    // borrows are seen as disjoint fields, not two derefs of the MutexGuard.
    let st = &mut *state;
    // Pick radius in world units — node markers are ~0.5-unit boxes, so a slightly
    // larger radius makes them comfortably clickable. `click_select` mutates the
    // viewport selection, but the render loop re-syncs it from `selected_nodes`,
    // so the editor's `selected_nodes` below is the source of truth.
    let hit_raw = st
        .editor_viewport_3d
        .click_select(&st.scene_tree, x, y, 0.8);
    let hit = hit_raw
        .map(|raw| NodeId::from_object_id(gdcore::id::ObjectId::from_raw(raw)))
        .filter(|id| st.scene_tree.get_node(*id).is_some());

    if add {
        // Toggle the hit node; a miss leaves the existing selection untouched.
        if let Some(id) = hit {
            if let Some(pos) = st.selected_nodes.iter().position(|&n| n == id) {
                st.selected_nodes.remove(pos);
            } else {
                st.selected_nodes.push(id);
            }
            st.selected_node = st.selected_nodes.first().copied();
        }
    } else {
        st.selected_node = hit;
        st.selected_nodes = hit.into_iter().collect();
    }

    let nodes: Vec<String> = st
        .selected_nodes
        .iter()
        .map(|id| id.raw().to_string())
        .collect();
    let primary = st
        .selected_node
        .map(|id| id.raw().to_string())
        .unwrap_or_else(|| "null".to_string());
    send_json(
        stream,
        &format!(
            r#"{{"selected":{primary},"selected_nodes":[{}]}}"#,
            nodes.join(",")
        ),
    );
}

/// `POST /api/viewport/3d/box_select` — rubber-band (marquee) multi-select in
/// the 3D viewport (Godot parity): selects every `Node3D` whose origin projects
/// inside the screen rectangle `{x1,y1,x2,y2}`. `add: true` unions the hits with
/// the current selection (Shift-drag); otherwise the rectangle replaces it.
fn api_viewport_3d_box_select(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let x1 = parsed.get("x1").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y1 = parsed.get("y1").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let x2 = parsed.get("x2").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y2 = parsed.get("y2").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let add = parsed.get("add").and_then(|v| v.as_bool()).unwrap_or(false);

    let mut state = state.lock().unwrap();

    // pat-s3rrv.66: a rubber-band select is a SELECTION event, so it gets the
    // same `_forward_3d_gui_input` offer that click-select does.
    //
    // ⚠️ Forwarding one and not the other is worse than forwarding neither: a
    // sub-gizmo plugin returning CUSTOM would suppress click-select while a
    // rubber-band drag went on stealing the selection out from under it, and
    // the inconsistency only shows up on the gesture the author happened not to
    // test.
    //
    // The event carries the drag's END point, which is where the pointer
    // actually is when the box closes.
    let camera = editor_camera_3d_value(&state.editor_viewport_3d.camera);
    let event = canvas_button_event(x2, y2, false);
    let after = dispatch_forward_3d_gui_input(&mut state, &[camera, event]);
    if !after.allows_editor_selection() {
        send_json(
            stream,
            &format!(
                r#"{{"ok":true,"after_gui_input":"{}"}}"#,
                match after {
                    AfterGuiInput::Stop => "stop",
                    AfterGuiInput::Custom => "custom",
                    AfterGuiInput::Pass => "pass",
                }
            ),
        );
        return;
    }

    let st = &mut *state;
    let hits = st
        .editor_viewport_3d
        .box_select_hits(&st.scene_tree, x1, y1, x2, y2);
    let ids: Vec<NodeId> = hits
        .into_iter()
        .map(|raw| NodeId::from_object_id(gdcore::id::ObjectId::from_raw(raw)))
        .filter(|id| st.scene_tree.get_node(*id).is_some())
        .collect();

    if !add {
        st.selected_nodes.clear();
    }
    for id in ids {
        if !st.selected_nodes.contains(&id) {
            st.selected_nodes.push(id);
        }
    }
    st.selected_node = st.selected_nodes.first().copied();

    let nodes: Vec<String> = st
        .selected_nodes
        .iter()
        .map(|id| id.raw().to_string())
        .collect();
    let primary = st
        .selected_node
        .map(|id| id.raw().to_string())
        .unwrap_or_else(|| "null".to_string());
    send_json(
        stream,
        &format!(
            r#"{{"selected":{primary},"selected_nodes":[{}]}}"#,
            nodes.join(",")
        ),
    );
}

/// The global (world) transform of `node_id`'s parent, or identity if it has no
/// parent. Used to convert gizmo results from world space back into the node's
/// local space (so nested, non-identity-parent nodes transform correctly).
fn parent_global_3d(tree: &SceneTree, node_id: NodeId) -> gdcore::math3d::Transform3D {
    tree.get_node(node_id)
        .and_then(|n| n.parent())
        .map(|pid| gdscene::node3d::get_global_transform(tree, pid))
        .unwrap_or(gdcore::math3d::Transform3D::IDENTITY)
}

/// Sets `node_id`'s world-space origin. The world position is converted to the
/// node's local space via the parent's inverse transform, then written to the
/// `transform` origin (basis preserved) if the node stores a full transform,
/// else to `position`. Correct for nested nodes with non-identity parents.
fn set_node_world_origin(tree: &mut SceneTree, node_id: NodeId, world_pos: gdcore::math::Vector3) {
    let local = parent_global_3d(tree, node_id).inverse().xform(world_pos);
    if let Some(node) = tree.get_node_mut(node_id) {
        if let Variant::Transform3D(mut t) = node.get_property("transform") {
            t.origin = local;
            node.set_property("transform", Variant::Transform3D(t));
        } else {
            node.set_property("position", Variant::Vector3(local));
        }
    }
}

/// `POST /api/viewport/3d/gizmo_mode` — sets the 3D transform tool (gizmo mode):
/// `"select"`, `"move"`, `"rotate"`, or `"scale"`.
fn api_viewport_3d_gizmo_mode(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    use crate::viewport_3d::GizmoMode3D;
    let mode = parse_json_body(body)
        .and_then(|p| p.get("mode").and_then(|v| v.as_str().map(String::from)))
        .unwrap_or_default();
    let gm = match mode.as_str() {
        "move" => GizmoMode3D::Move,
        "rotate" => GizmoMode3D::Rotate,
        "scale" => GizmoMode3D::Scale,
        _ => GizmoMode3D::Select,
    };
    let mut state = state.lock().unwrap();
    // set_gizmo_mode cancels any in-progress viewport drag; also drop the matching
    // server-side drag bookkeeping so a tool switch mid-drag can't leave it stale.
    state.editor_viewport_3d.selection.set_gizmo_mode(gm);
    state.gizmo_drag_start_3d = None;
    state.gizmo_drag_starts_3d.clear();
    state.gizmo_snap_active_3d = false;
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/viewport/3d/gizmo/begin` — begins a transform-gizmo drag if the
/// click at (`x`, `y`) hits a gizmo axis of the selected node. Returns whether a
/// drag started and which axis.
fn api_viewport_3d_gizmo_begin(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    use crate::viewport_3d::GizmoAxis;
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    let mut state = state.lock().unwrap();
    let st = &mut *state;
    let node = match st.selected_node {
        Some(n) => n,
        None => {
            send_json(stream, r#"{"dragging":false}"#);
            return;
        }
    };
    let center = gdscene::node3d::get_global_transform(&st.scene_tree, node).origin;
    // Match the hit-test geometry to the rendered gizmo size (which is scaled by
    // camera distance) so rings/handles are clickable where they are drawn.
    let len = crate::viewport_3d_render::gizmo_arrow_length(&st.editor_viewport_3d);
    let mut cfg = crate::viewport_3d::GizmoConfig3D::default();
    cfg.arrow_length = len;
    cfg.ring_radius = len;
    cfg.scale_handle_length = len;
    let axis = st
        .editor_viewport_3d
        .hit_test_gizmo_full(x, y, center, &cfg);
    if axis == GizmoAxis::None {
        send_json(stream, r#"{"dragging":false}"#);
        return;
    }
    // Remember the node's transform at drag start: rotate/scale deltas accumulate
    // from here, so this is the base they are composed onto.
    st.gizmo_drag_start_3d = Some(gdscene::node3d::get_global_transform(&st.scene_tree, node));
    // Capture every selected node's start transform so the whole multi-selection
    // transforms together (Godot parity). The primary's origin is the shared
    // pivot for rotate/scale; move applies the same world delta to each.
    let starts: Vec<(NodeId, gdcore::math3d::Transform3D)> = st
        .selected_nodes
        .iter()
        .map(|&id| {
            (
                id,
                gdscene::node3d::get_global_transform(&st.scene_tree, id),
            )
        })
        .collect();
    st.gizmo_drag_starts_3d = if starts.is_empty() {
        vec![(
            node,
            gdscene::node3d::get_global_transform(&st.scene_tree, node),
        )]
    } else {
        starts
    };
    // Ctrl-drag snaps to increments (Godot's transform snap); the toolbar's
    // persistent "Use Snap" toggle (Y) snaps every drag without holding Ctrl.
    st.gizmo_snap_active_3d = parsed
        .get("snap")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
        || st.editor_viewport_3d.use_snap;
    st.editor_viewport_3d.begin_gizmo_drag(x, y, center, axis);
    let axis_name = match axis {
        GizmoAxis::X => "x",
        GizmoAxis::Y => "y",
        GizmoAxis::Z => "z",
        GizmoAxis::XY => "xy",
        GizmoAxis::XZ => "xz",
        GizmoAxis::YZ => "yz",
        GizmoAxis::None => "none",
    };
    send_json(
        stream,
        &format!(r#"{{"dragging":true,"axis":"{axis_name}"}}"#),
    );
}

/// `POST /api/viewport/3d/gizmo/update` — updates an in-progress gizmo drag with
/// the cursor at (`x`, `y`), applying the resulting transform to the selected node.
fn api_viewport_3d_gizmo_update(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    use crate::viewport_3d::{GizmoSnap3D, GizmoTransform3D};
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    use crate::viewport_3d::GizmoAxis;
    let mut state = state.lock().unwrap();
    let st = &mut *state;
    // Snap to the configured increments while snapping is active (Godot's
    // Configure Snap values, default 1 m / 15° / 10%).
    let snap = if st.gizmo_snap_active_3d {
        GizmoSnap3D {
            translate_step: st.editor_viewport_3d.snap_translate,
            rotate_step: st.editor_viewport_3d.snap_rotate.to_radians(),
            scale_step: st.editor_viewport_3d.snap_scale,
        }
    } else {
        GizmoSnap3D::default()
    };
    let result = st.editor_viewport_3d.update_gizmo_drag(x, y, &snap);
    let primary_start = st.gizmo_drag_start_3d;
    let starts = st.gizmo_drag_starts_3d.clone();
    match (primary_start, result) {
        (Some(pivot_tf), Some(t)) => {
            // Transform the whole multi-selection together (Godot parity).
            apply_gizmo_to_selection(&mut st.scene_tree, &starts, pivot_tf.origin, t);
            st.scene_modified = true;
            let p = pivot_tf.origin;
            let resp = match t {
                GizmoTransform3D::Move(d) => {
                    format!(
                        r#"{{"x":{},"y":{},"z":{}}}"#,
                        p.x + d.x,
                        p.y + d.y,
                        p.z + d.z
                    )
                }
                GizmoTransform3D::Rotate { angle, .. } => format!(r#"{{"angle":{angle}}}"#),
                GizmoTransform3D::Scale { factor, .. } => format!(r#"{{"factor":{factor}}}"#),
            };
            send_json(stream, &resp);
        }
        _ => send_json(stream, r#"{"ok":false}"#),
    }
}

/// Applies a finished gizmo delta to every node in `starts` (each paired with
/// its drag-start *global* transform). Move applies the same world translation
/// to each node; Rotate/Scale pivot about `pivot` (the primary's origin, where
/// the gizmo is drawn) so the whole selection transforms as a rigid group —
/// Godot's multi-node transform. For a single selection whose origin equals the
/// pivot, the offset is zero and this reduces to an in-place transform.
fn apply_gizmo_to_selection(
    tree: &mut SceneTree,
    starts: &[(NodeId, gdcore::math3d::Transform3D)],
    pivot: gdcore::math::Vector3,
    t: crate::viewport_3d::GizmoTransform3D,
) {
    use crate::viewport_3d::{GizmoAxis, GizmoTransform3D};
    match t {
        GizmoTransform3D::Move(d) => {
            for (id, s) in starts {
                let np = gdcore::math::Vector3::new(
                    s.origin.x + d.x,
                    s.origin.y + d.y,
                    s.origin.z + d.z,
                );
                set_node_world_origin(tree, *id, np);
            }
        }
        GizmoTransform3D::Rotate { axis, angle } => {
            let dir = axis.direction();
            let rot = gdcore::math3d::Basis::IDENTITY.rotated(dir, angle);
            for (id, s) in starts {
                let new_basis = s.basis.rotated(dir, angle);
                let off = gdcore::math::Vector3::new(
                    s.origin.x - pivot.x,
                    s.origin.y - pivot.y,
                    s.origin.z - pivot.z,
                );
                let r = rot.xform(off);
                let new_origin =
                    gdcore::math::Vector3::new(pivot.x + r.x, pivot.y + r.y, pivot.z + r.z);
                set_node_local_transform(
                    tree,
                    *id,
                    gdcore::math3d::Transform3D {
                        basis: new_basis,
                        origin: new_origin,
                    },
                );
            }
        }
        GizmoTransform3D::Scale { axis, factor } => {
            let sv = match axis {
                GizmoAxis::X => gdcore::math::Vector3::new(factor, 1.0, 1.0),
                GizmoAxis::Y => gdcore::math::Vector3::new(1.0, factor, 1.0),
                GizmoAxis::Z => gdcore::math::Vector3::new(1.0, 1.0, factor),
                _ => gdcore::math::Vector3::new(factor, factor, factor),
            };
            for (id, s) in starts {
                let b = s.basis;
                let new_basis = gdcore::math3d::Basis {
                    x: gdcore::math::Vector3::new(b.x.x * sv.x, b.x.y * sv.x, b.x.z * sv.x),
                    y: gdcore::math::Vector3::new(b.y.x * sv.y, b.y.y * sv.y, b.y.z * sv.y),
                    z: gdcore::math::Vector3::new(b.z.x * sv.z, b.z.y * sv.z, b.z.z * sv.z),
                };
                let off = gdcore::math::Vector3::new(
                    s.origin.x - pivot.x,
                    s.origin.y - pivot.y,
                    s.origin.z - pivot.z,
                );
                let new_origin = gdcore::math::Vector3::new(
                    pivot.x + off.x * sv.x,
                    pivot.y + off.y * sv.y,
                    pivot.z + off.z * sv.z,
                );
                set_node_local_transform(
                    tree,
                    *id,
                    gdcore::math3d::Transform3D {
                        basis: new_basis,
                        origin: new_origin,
                    },
                );
            }
        }
    }
}

/// Sets a node's transform from a desired *world* transform, converting it to
/// local space via the parent's inverse (`local = parent_global_inverse * world`)
/// so nested nodes with non-identity parents transform correctly.
fn set_node_local_transform(
    tree: &mut SceneTree,
    node_id: NodeId,
    world_tf: gdcore::math3d::Transform3D,
) {
    let local = parent_global_3d(tree, node_id).inverse() * world_tf;
    if let Some(node) = tree.get_node_mut(node_id) {
        node.set_property("transform", Variant::Transform3D(local));
    }
}

/// `POST /api/viewport/3d/gizmo/end` — finalizes the current gizmo drag.
fn api_viewport_3d_gizmo_end(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    state.editor_viewport_3d.end_gizmo_drag();
    state.gizmo_drag_start_3d = None;
    state.gizmo_snap_active_3d = false;

    // Commit the gizmo drag as an undoable step (pat-0q2kx.12).
    //
    // Godot records every gizmo transform with EditorUndoRedoManager; this only
    // cleared the drag bookkeeping, so a 3D translate/rotate/scale could not be
    // undone. `gizmo/update` writes `transform` live during the drag, so the
    // node now holds the last mid-drag value — the pre-drag transform has to be
    // restored before `execute` captures `old_value`, or undo would restore the
    // final drag frame and appear to do nothing.
    //
    // `gizmo_drag_starts_3d` holds GLOBAL transforms (that is what the drag math
    // works in), while the node stores a LOCAL one, so each is converted through
    // its parent exactly as `apply_world_transform_3d` does.
    let starts = std::mem::take(&mut state.gizmo_drag_starts_3d);
    let mut steps: Vec<EditorCommand> = Vec::new();
    for (node_id, start_global) in starts {
        let start_local = parent_global_3d(&state.scene_tree, node_id).inverse() * start_global;
        let current_local = match state
            .scene_tree
            .get_node(node_id)
            .map(|n| n.get_property("transform"))
        {
            Some(Variant::Transform3D(t)) => t,
            _ => continue,
        };
        // A click that did not move anything should not litter the history.
        if current_local == start_local {
            continue;
        }
        if let Some(node) = state.scene_tree.get_node_mut(node_id) {
            node.set_property("transform", Variant::Transform3D(start_local));
        }
        let mut cmd = EditorCommand::SetProperty {
            node_id,
            property: "transform".to_string(),
            new_value: Variant::Transform3D(current_local),
            old_value: Variant::Nil,
        };
        if cmd.execute(&mut state.scene_tree).is_ok() {
            steps.push(cmd);
        }
    }
    if !steps.is_empty() {
        // One drag is one undo step even when it moved a multi-selection, as in
        // Godot — otherwise Ctrl+Z would peel the nodes back one at a time.
        let cmd = if steps.len() == 1 {
            steps.pop().expect("len checked")
        } else {
            EditorCommand::Group {
                label: format!("Move {} nodes", steps.len()),
                commands: steps,
            }
        };
        state.undo_stack.push(cmd);
        state.redo_stack.clear();
        state.scene_modified = true;
    }

    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// Per-node 3D gizmo handles (pat-s3rrv.10)
// ---------------------------------------------------------------------------
//
// Godot gives every selected 3D node its own gizmo with draggable handles that
// edit the node's SHAPE rather than its transform: box face handles on a
// CollisionShape3D (`collision_shape_3d_gizmo_plugin.cpp` via `Gizmo3DHelper`)
// and a range handle on an OmniLight3D (`light_3d_gizmo_plugin.cpp`).
//
// Patina had the parity-exact geometry in `viewport_3d_handles.rs` with ZERO
// non-test callers and no route to reach it, so the served 3D viewport offered
// only the shared transform gizmo. These three endpoints are that missing
// wiring; the math itself stays in the ported module.

/// What kind of node gizmo a selection exposes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HandleKind3D {
    /// `CollisionShape3D` holding a `BoxShape3D`: six face handles.
    Box,
    /// `OmniLight3D`: a single range handle.
    OmniRange,
}

/// An in-progress handle drag, capturing everything needed to (a) recompute the
/// shape from the drag start on every update and (b) restore the pre-drag state
/// so the undo step records a real `old_value`.
///
/// Godot resolves each drag frame from the state at drag START, not from the
/// last frame's result — accumulating would make the box creep as the mouse
/// jitters. That is why the initial size/transform are captured here rather
/// than re-read during `update`.
#[derive(Debug, Clone)]
pub struct HandleDrag3D {
    /// The node being edited.
    pub node_id: NodeId,
    /// Which handle (a box face id 0..6, or 0 for the omni range).
    pub handle: usize,
    /// Which gizmo the handle belongs to.
    pub kind: HandleKind3D,
    /// Box size at drag start.
    pub initial_size: gdcore::math::Vector3,
    /// Omni range at drag start.
    pub initial_range: f32,
    /// The node's global transform at drag start.
    pub initial_transform: gdcore::math3d::Transform3D,
    /// The stored `__shape__size` at drag start, restored before the undo step
    /// is captured.
    pub initial_size_prop: Variant,
    /// The name and value of the node's stored placement property (`transform`
    /// or `position`) at drag start — a non-symmetric box drag re-centres the
    /// node, so the position edit is part of the same undoable action.
    pub initial_place_prop: (String, Variant),
}

/// Reads the node's stored placement property, matching what
/// [`set_node_world_origin`] writes: a node loaded with a full `transform`
/// keeps using it, otherwise `position`.
fn place_prop_of(tree: &SceneTree, node_id: NodeId) -> (String, Variant) {
    let node = match tree.get_node(node_id) {
        Some(n) => n,
        None => return ("position".to_string(), Variant::Nil),
    };
    match node.get_property("transform") {
        Variant::Transform3D(t) => ("transform".to_string(), Variant::Transform3D(t)),
        _ => ("position".to_string(), node.get_property("position")),
    }
}

/// Classifies a node's gizmo, with the geometry it exposes.
///
/// Returns `None` for a node with no node gizmo — a plain `Node3D`, or a
/// `CollisionShape3D` whose shape is not a box — which the route reports as
/// `editable:false` rather than an error, mirroring the 2D
/// `/api/viewport/shape_handles`.
fn node_gizmo_kind(
    tree: &SceneTree,
    node_id: NodeId,
) -> Option<(HandleKind3D, Vec<(String, gdcore::math::Vector3)>)> {
    let node = tree.get_node(node_id)?;
    match node.class_name() {
        "CollisionShape3D" => {
            // The shape class comes from the flattened companion a loaded scene
            // leaves behind, or straight off `shape` for a hand-built node.
            let shape_class = match node.get_property("__shape__class") {
                Variant::String(c) => c,
                _ => match node.get_property("shape") {
                    Variant::String(c) if !c.starts_with("SubResource") => c,
                    _ => String::new(),
                },
            };
            if shape_class != "BoxShape3D" {
                return None;
            }
            let size = match node.get_property("__shape__size") {
                Variant::Vector3(v) => v,
                _ => return None,
            };
            let names = ["+x", "-x", "+y", "-y", "+z", "-z"];
            let handles = crate::viewport_3d_handles::box_get_handles(size)
                .into_iter()
                .enumerate()
                .map(|(i, local)| (names[i].to_string(), local))
                .collect();
            Some((HandleKind3D::Box, handles))
        }
        "OmniLight3D" => {
            let range = match node.get_property("omni_range") {
                Variant::Float(f) => f as f32,
                Variant::Int(i) => i as f32,
                // Godot's OmniLight3D.omni_range default.
                _ => 5.0,
            };
            // Godot puts the omni range handle on +X at the range distance
            // (`light_3d_gizmo_plugin.cpp` pushes `Vector3(r, 0, 0)`).
            Some((
                HandleKind3D::OmniRange,
                vec![(
                    "range".to_string(),
                    gdcore::math::Vector3::new(range, 0.0, 0.0),
                )],
            ))
        }
        _ => None,
    }
}

/// `GET /api/viewport/3d/handles?node_id=` — the node-gizmo handles for a 3D
/// node, projected to viewport pixels so the client can draw and hit-test them.
///
/// The projection happens here because only the server has the editor camera;
/// the client would otherwise need a duplicate of the whole view/projection
/// chain just to place six dots.
fn api_viewport_3d_handles(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let Some(raw) = query_param(query, "node_id").and_then(|v| v.parse::<u64>().ok()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let s = state.lock().unwrap();
    let Some(node_id) = find_node_by_raw_id(&s.scene_tree, raw) else {
        send_error(stream, 404, "node not found");
        return;
    };
    let Some((kind, handles)) = node_gizmo_kind(&s.scene_tree, node_id) else {
        send_json(stream, r#"{"ok":true,"editable":false,"handles":[]}"#);
        return;
    };
    let xform = gdscene::node3d::get_global_transform(&s.scene_tree, node_id);
    let kind_name = match kind {
        HandleKind3D::Box => "box",
        HandleKind3D::OmniRange => "omni_range",
    };
    let items: Vec<String> = handles
        .iter()
        .enumerate()
        .map(|(id, (name, local))| {
            let world = xform.xform(*local);
            let (px, py) = s.editor_viewport_3d.world_to_screen(world);
            // A handle behind the camera can project to a non-finite pixel, and
            // `NaN`/`inf` are not JSON — the response would fail to parse rather
            // than merely misplace a dot.
            let fin = |v: f32| if v.is_finite() { v } else { 0.0 };
            format!(
                r#"{{"id":{id},"name":"{name}","x":{},"y":{},"world":[{},{},{}]}}"#,
                fin(px),
                fin(py),
                world.x,
                world.y,
                world.z
            )
        })
        .collect();
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"editable":true,"kind":"{kind_name}","handles":[{}]}}"#,
            items.join(",")
        ),
    );
}

/// `POST /api/viewport/3d/handle/begin` — starts a handle drag on `node_id`'s
/// handle `handle`. The client hit-tests in the DOM (each handle is a dot), so
/// the handle id arrives explicitly rather than being re-derived from the pixel.
fn api_viewport_3d_handle_begin(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let Some(parsed) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let handle = parsed
        .get("handle")
        .and_then(|v| v.as_u64())
        .unwrap_or(u64::MAX) as usize;
    let mut state = state.lock().unwrap();
    let st = &mut *state;
    // Fall back to the current selection so the route matches how the transform
    // gizmo behaves when the client omits the id.
    let node_id = match parsed
        .get("node_id")
        .and_then(|v| v.as_u64())
        .and_then(|raw| find_node_by_raw_id(&st.scene_tree, raw))
        .or(st.selected_node)
    {
        Some(n) => n,
        None => {
            send_json(stream, r#"{"dragging":false}"#);
            return;
        }
    };
    let Some((kind, handles)) = node_gizmo_kind(&st.scene_tree, node_id) else {
        send_json(stream, r#"{"dragging":false}"#);
        return;
    };
    if handle >= handles.len() {
        send_json(stream, r#"{"dragging":false}"#);
        return;
    }
    let node = match st.scene_tree.get_node(node_id) {
        Some(n) => n,
        None => {
            send_json(stream, r#"{"dragging":false}"#);
            return;
        }
    };
    let initial_size = match node.get_property("__shape__size") {
        Variant::Vector3(v) => v,
        _ => gdcore::math::Vector3::ZERO,
    };
    let initial_range = match node.get_property("omni_range") {
        Variant::Float(f) => f as f32,
        Variant::Int(i) => i as f32,
        _ => 5.0,
    };
    st.handle_drag_3d = Some(HandleDrag3D {
        node_id,
        handle,
        kind,
        initial_size,
        initial_range,
        initial_transform: gdscene::node3d::get_global_transform(&st.scene_tree, node_id),
        initial_size_prop: node.get_property("__shape__size"),
        initial_place_prop: place_prop_of(&st.scene_tree, node_id),
    });
    send_json(stream, &format!(r#"{{"dragging":true,"handle":{handle}}}"#));
}

/// `POST /api/viewport/3d/handle/update` — resolves the cursor to a new shape
/// and writes it live, so the viewport follows the drag.
///
/// `symmetric` is Godot's Alt modifier (resize about the centre instead of
/// moving one face); `snap` applies the editor's translate snap.
fn api_viewport_3d_handle_update(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let Some(parsed) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let symmetric = parsed
        .get("symmetric")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let want_snap = parsed
        .get("snap")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let mut state = state.lock().unwrap();
    let st = &mut *state;
    let Some(drag) = st.handle_drag_3d.clone() else {
        send_json(stream, r#"{"ok":false,"dragging":false}"#);
        return;
    };
    let snap_step = if want_snap || st.editor_viewport_3d.use_snap {
        Some(st.editor_viewport_3d.snap_translate)
    } else {
        None
    };

    // The drag point is the point on the handle's own axis closest to the mouse
    // ray — Godot's `get_closest_points_between_segments` against an axis
    // segment. Solving in WORLD space and transforming back keeps the math
    // correct for a rotated or nested node.
    let ray = st.editor_viewport_3d.screen_to_ray(x, y);
    let inv = drag.initial_transform.inverse();

    match drag.kind {
        HandleKind3D::Box => {
            let (axis, _) = crate::viewport_3d_handles::box_handle_axis_sign(drag.handle);
            let mut local_axis = gdcore::math::Vector3::ZERO;
            match axis {
                0 => local_axis.x = 1.0,
                1 => local_axis.y = 1.0,
                _ => local_axis.z = 1.0,
            }
            let world_axis = drag.initial_transform.basis.xform(local_axis);
            let t = crate::viewport_3d::ray_closest_to_line(
                &ray,
                drag.initial_transform.origin,
                world_axis,
            );
            let world_point = gdcore::math::Vector3::new(
                drag.initial_transform.origin.x + world_axis.x * t,
                drag.initial_transform.origin.y + world_axis.y * t,
                drag.initial_transform.origin.z + world_axis.z * t,
            );
            let ra = inv.xform(world_point);
            let (new_size, new_world_origin) = crate::viewport_3d_handles::box_set_handle(
                drag.initial_size,
                &drag.initial_transform,
                drag.handle,
                ra,
                symmetric,
                snap_step,
            );
            if let Some(node) = st.scene_tree.get_node_mut(drag.node_id) {
                node.set_property("__shape__size", Variant::Vector3(new_size));
            }
            set_node_world_origin(&mut st.scene_tree, drag.node_id, new_world_origin);
        }
        HandleKind3D::OmniRange => {
            // The range handle rides +X; its distance from the light IS the range.
            let world_axis = drag
                .initial_transform
                .basis
                .xform(gdcore::math::Vector3::new(1.0, 0.0, 0.0));
            let t = crate::viewport_3d::ray_closest_to_line(
                &ray,
                drag.initial_transform.origin,
                world_axis,
            );
            let range = t.max(0.0);
            if let Some(node) = st.scene_tree.get_node_mut(drag.node_id) {
                node.set_property("omni_range", Variant::Float(f64::from(range)));
            }
        }
    }
    send_json(stream, r#"{"ok":true,"dragging":true}"#);
}

/// `POST /api/viewport/3d/handle/end` — commits the handle drag as ONE undo step.
///
/// `update` wrote the shape live, so the node currently holds the last mid-drag
/// value. The pre-drag state is restored first and the commands re-executed, or
/// each command would capture the final drag frame as its `old_value` and undo
/// would appear to do nothing — the same trap `gizmo/end` documents.
fn api_viewport_3d_handle_end(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    let Some(drag) = state.handle_drag_3d.take() else {
        send_json(stream, r#"{"ok":true,"committed":false}"#);
        return;
    };

    // Snapshot what the drag produced, then rewind to the drag-start values.
    let node_id = drag.node_id;
    let (final_size, final_place, final_range) = match state.scene_tree.get_node(node_id) {
        Some(n) => (
            n.get_property("__shape__size"),
            n.get_property(&drag.initial_place_prop.0),
            n.get_property("omni_range"),
        ),
        None => {
            send_json(stream, r#"{"ok":true,"committed":false}"#);
            return;
        }
    };
    // Rewind ONLY what this gizmo edits. Restoring every property unconditionally
    // would write an `omni_range` onto a CollisionShape3D (and a `__shape__size`
    // onto a light) — invented properties that the saver would then persist into
    // the .tscn.
    if let Some(node) = state.scene_tree.get_node_mut(node_id) {
        match drag.kind {
            HandleKind3D::Box => {
                node.set_property("__shape__size", drag.initial_size_prop.clone());
                node.set_property(
                    &drag.initial_place_prop.0,
                    drag.initial_place_prop.1.clone(),
                );
            }
            HandleKind3D::OmniRange => {
                node.set_property("omni_range", Variant::Float(f64::from(drag.initial_range)));
            }
        }
    }

    // The (property, final value) pairs this drag actually changed. A click that
    // resized nothing contributes none, so it does not litter the history.
    let mut edits: Vec<(String, Variant)> = Vec::new();
    match drag.kind {
        HandleKind3D::Box => {
            if final_size != drag.initial_size_prop {
                edits.push(("__shape__size".to_string(), final_size));
            }
            if final_place != drag.initial_place_prop.1 {
                edits.push((drag.initial_place_prop.0.clone(), final_place));
            }
        }
        HandleKind3D::OmniRange => {
            let unchanged = match &final_range {
                Variant::Float(f) => (*f as f32 - drag.initial_range).abs() < 1e-6,
                _ => true,
            };
            if !unchanged {
                edits.push(("omni_range".to_string(), final_range));
            }
        }
    }

    let mut steps: Vec<EditorCommand> = Vec::new();
    for (property, new_value) in edits {
        let mut cmd = EditorCommand::SetProperty {
            node_id,
            property,
            new_value,
            old_value: Variant::Nil,
        };
        // `execute` captures the (now restored) pre-drag value as `old_value`,
        // which is what makes the undo below restore the drag start rather than
        // the last mid-drag frame.
        if cmd.execute(&mut state.scene_tree).is_ok() {
            steps.push(cmd);
        }
    }

    if !steps.is_empty() {
        // One drag is one undo step even though a box resize writes both the
        // size and the re-centred position — Ctrl+Z must not peel them apart.
        let cmd = if steps.len() == 1 {
            steps.pop().expect("len checked")
        } else {
            EditorCommand::Group {
                label: "Resize gizmo handle".to_string(),
                commands: steps,
            }
        };
        state.undo_stack.push(cmd);
        state.redo_stack.clear();
        state.scene_modified = true;
        send_json(stream, r#"{"ok":true,"committed":true}"#);
        return;
    }
    send_json(stream, r#"{"ok":true,"committed":false}"#);
}

/// `POST /api/viewport/3d/frame` — frames the selected node (Godot's "F"): moves
/// the camera focus to the node and pulls in to a fit distance, keeping the
/// current orientation. With no selection it frames the world origin.
fn api_viewport_3d_frame(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    let st = &mut *state;
    let target = st
        .selected_node
        .map(|n| gdscene::node3d::get_global_transform(&st.scene_tree, n).origin)
        .unwrap_or(gdcore::math::Vector3::ZERO);
    st.editor_viewport_3d
        .camera
        .focus_on_with_distance(target, 5.0);
    let json = editor_viewport_3d_json(st);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/view_preset` — snaps the camera to a standard view:
/// `"front"`, `"top"`, or `"right"` (Godot's numpad views).
fn api_viewport_3d_view_preset(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    use crate::viewport_3d_overlay::ViewPreset;
    let preset = parse_json_body(body)
        .and_then(|p| p.get("preset").and_then(|v| v.as_str().map(String::from)))
        .unwrap_or_default();
    let p = match preset.as_str() {
        "top" => ViewPreset::Top,
        "bottom" => ViewPreset::Bottom,
        "right" => ViewPreset::Right,
        "left" => ViewPreset::Left,
        "rear" => ViewPreset::Rear,
        _ => ViewPreset::Front,
    };
    let mut state = state.lock().unwrap();
    state.editor_viewport_3d.toolbar_set_view(p);
    let json = editor_viewport_3d_json(&state);
    send_json(stream, &json);
}

/// `POST /api/viewport/3d/projection` — toggles the editor camera between
/// perspective and orthographic projection (Godot's Perspective/Orthogonal
/// switch). Returns the updated 3D camera state.
fn api_viewport_3d_projection(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let mut state = state.lock().unwrap();
        state.editor_viewport_3d.toolbar_toggle_projection();
        editor_viewport_3d_json(&state)
    };
    send_json(stream, &json);
}

/// `GET /api/viewport/3d/state` — current 3D editor camera state.
fn api_viewport_3d_state(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        editor_viewport_3d_json(&state)
    };
    send_json(stream, &json);
}

/// `POST /api/viewport/frame_selection` — frame-selection (F): centers the
/// current selection in the viewport and adjusts zoom to fit its bounds. With
/// no selection it frames the scene origin at the default zoom.
fn api_frame_selection(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    let vw = s.viewport_width as f32;
    let vh = s.viewport_height as f32;

    // Bounding box of the selected nodes' positions; fall back to the origin
    // when nothing is selected.
    let mut found = false;
    let (mut min_x, mut min_y, mut max_x, mut max_y) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    for &nid in &s.selected_nodes {
        if let Some(n) = s.scene_tree.get_node(nid) {
            let p = crate::scene_renderer::extract_position(n);
            found = true;
            min_x = min_x.min(p.x);
            min_y = min_y.min(p.y);
            max_x = max_x.max(p.x);
            max_y = max_y.max(p.y);
        }
    }
    let (center_x, center_y, bounds_w, bounds_h) = if found {
        (
            (min_x + max_x) / 2.0,
            (min_y + max_y) / 2.0,
            max_x - min_x,
            max_y - min_y,
        )
    } else {
        (0.0, 0.0, 0.0, 0.0)
    };

    // Zoom to fit the bounds with a small margin; a point/degenerate bounds
    // keeps the default zoom.
    const MARGIN: f32 = 1.2;
    let zoom = if bounds_w > 0.0 || bounds_h > 0.0 {
        let zx = if bounds_w > 0.0 {
            vw / (bounds_w * MARGIN)
        } else {
            f32::INFINITY
        };
        let zy = if bounds_h > 0.0 {
            vh / (bounds_h * MARGIN)
        } else {
            f32::INFINITY
        };
        zx.min(zy).clamp(0.1, 16.0)
    } else {
        1.0
    };

    // Pan so the selection center lands at the viewport center, accounting for
    // the scene-centered camera offset.
    let scene_bounds = crate::scene_renderer::compute_scene_bounds(&s.scene_tree);
    let scene_cx = scene_bounds.position.x + scene_bounds.size.x / 2.0;
    let scene_cy = scene_bounds.position.y + scene_bounds.size.y / 2.0;
    let pan_x = ((scene_cx - center_x) * zoom) as f64;
    let pan_y = ((scene_cy - center_y) * zoom) as f64;

    s.viewport_zoom = zoom as f64;
    s.viewport_pan = (pan_x, pan_y);
    let json = format!(
        r#"{{"zoom":{},"pan_x":{},"pan_y":{}}}"#,
        s.viewport_zoom, pan_x, pan_y
    );
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// Log and scene info endpoints
// ---------------------------------------------------------------------------

/// `GET /api/logs` — returns recent editor operation log entries.
fn api_get_logs(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        let entries: Vec<String> = state
            .log_entries
            .iter()
            .map(|e| {
                // pat-d6uah: tag each message with a Godot EditorLog category so
                // the std/error/warning/editor type filters reflect real
                // categories. Editor-emitted info messages are "editor";
                // game stdout would be "std".
                let category = match e.level.as_str() {
                    "error" => "error",
                    "warn" | "warning" => "warning",
                    "print" | "std" | "stdout" => "std",
                    _ => "editor",
                };
                format!(
                    r#"{{"timestamp":{},"level":"{}","category":"{}","message":"{}"}}"#,
                    e.timestamp,
                    e.level,
                    category,
                    e.message.replace('\\', "\\\\").replace('"', "\\\"")
                )
            })
            .collect();
        format!("[{}]", entries.join(","))
    };
    send_json(stream, &json);
}

/// `GET /api/scene/info` — returns scene statistics and metadata.
fn api_get_scene_info(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        let total_nodes = state.scene_tree.node_count();

        // Count nodes by type.
        let mut type_counts = std::collections::HashMap::<String, usize>::new();
        let all_nodes = state.scene_tree.all_nodes_in_tree_order();
        for nid in &all_nodes {
            if let Some(node) = state.scene_tree.get_node(*nid) {
                *type_counts
                    .entry(node.class_name().to_string())
                    .or_default() += 1;
            }
        }
        let types_json: Vec<String> = type_counts
            .iter()
            .map(|(k, v)| format!(r#""{}": {}"#, k, v))
            .collect();

        let scene_file = state
            .scene_file
            .as_deref()
            .map(|s| format!(r#""{}""#, s.replace('\\', "\\\\").replace('"', "\\\"")))
            .unwrap_or_else(|| "null".to_string());

        format!(
            r#"{{"node_count":{},"type_breakdown":{{{}}},"scene_file":{},"modified":{}}}"#,
            total_nodes,
            types_json.join(","),
            scene_file,
            state.scene_modified,
        )
    };
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// Filesystem endpoint
// ---------------------------------------------------------------------------

/// A filesystem entry for the JSON response.
#[derive(Debug)]
struct FsEntry {
    name: String,
    path: String,
    is_dir: bool,
    children: Vec<FsEntry>,
    /// File size in bytes (0 for directories).
    size: u64,
    /// File type string (e.g. "GDScript", "Scene", "Resource").
    file_type: String,
}

impl FsEntry {
    fn to_json(&self) -> String {
        if self.is_dir {
            let children_json: Vec<String> = self.children.iter().map(|c| c.to_json()).collect();
            format!(
                r#"{{"name":"{}","path":"{}","is_dir":true,"children":[{}]}}"#,
                self.name.replace('\\', "\\\\").replace('"', "\\\""),
                self.path.replace('\\', "\\\\").replace('"', "\\\""),
                children_json.join(",")
            )
        } else {
            format!(
                r#"{{"name":"{}","path":"{}","is_dir":false,"size":{},"file_type":"{}"}}"#,
                self.name.replace('\\', "\\\\").replace('"', "\\\""),
                self.path.replace('\\', "\\\\").replace('"', "\\\""),
                self.size,
                self.file_type,
            )
        }
    }
}

fn file_type_for_ext(ext: &str) -> &str {
    match ext {
        "gd" => "GDScript",
        "tscn" => "Scene",
        "tres" => "Resource",
        "png" | "jpg" | "jpeg" | "webp" | "svg" => "Image",
        "wav" | "ogg" | "mp3" => "Audio",
        "ttf" | "otf" => "Font",
        _ => "File",
    }
}

/// Recursively scan a directory for .tscn, .gd, .tres files up to `max_depth` levels.
fn scan_directory(
    dir: &std::path::Path,
    prefix: &str,
    depth: usize,
    max_depth: usize,
) -> Vec<FsEntry> {
    if depth > max_depth {
        return Vec::new();
    }
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return Vec::new(),
    };

    let mut dirs = Vec::new();
    let mut files = Vec::new();

    for entry in entries.flatten() {
        let path = entry.path();
        let name = entry.file_name().to_string_lossy().to_string();

        // Skip hidden files/directories.
        //
        // pat-iixwj: also skip build / dependency directories that are never
        // part of a Godot project's res:// tree. Without this guard a bare
        // `GET /api/filesystem` rooted at a Cargo workspace recurses into
        // `target/` (tens of GB, ~millions of entries) and stats every one,
        // so the request never completes and the 1 Hz UI poll saturates the
        // connection pool. The sibling script-search walker (`search_dir`)
        // already skips `target` for the same reason.
        if name.starts_with('.') || name == "target" || name == "node_modules" || name == ".git" {
            continue;
        }

        if path.is_dir() {
            let child_prefix = if prefix.is_empty() {
                name.clone()
            } else {
                format!("{}/{}", prefix, name)
            };
            let children = scan_directory(&path, &child_prefix, depth + 1, max_depth);
            // Only include directories that have relevant files (directly or nested).
            if !children.is_empty() {
                dirs.push(FsEntry {
                    name,
                    path: format!("res://{}", child_prefix),
                    is_dir: true,
                    children,
                    size: 0,
                    file_type: "Directory".to_string(),
                });
            }
        } else if path.is_file() {
            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
            if matches!(
                ext,
                "tscn"
                    | "gd"
                    | "tres"
                    | "png"
                    | "jpg"
                    | "jpeg"
                    | "webp"
                    | "svg"
                    | "gdshader"
                    | "glsl"
                    | "cfg"
            ) {
                let file_path = if prefix.is_empty() {
                    format!("res://{}", name)
                } else {
                    format!("res://{}/{}", prefix, name)
                };
                let size = std::fs::metadata(&path).map(|m| m.len()).unwrap_or(0);
                files.push(FsEntry {
                    name,
                    path: file_path,
                    is_dir: false,
                    children: Vec::new(),
                    size,
                    file_type: file_type_for_ext(ext).to_string(),
                });
            }
        }
    }

    // Sort: directories first, then files, both alphabetically.
    dirs.sort_by(|a, b| a.name.to_lowercase().cmp(&b.name.to_lowercase()));
    files.sort_by(|a, b| a.name.to_lowercase().cmp(&b.name.to_lowercase()));
    dirs.extend(files);
    dirs
}

