/// `GET /api/capabilities` — returns a deterministic JSON document listing
/// every registered route with its method, path, params, request body schema,
/// and response shape. Entries are emitted in sorted (method, path) order so
/// the output is byte-stable across runs.
fn api_get_capabilities(stream: &mut TcpStream) {
    let mut entries: Vec<(&str, &str, &str, &str, &str)> = CAPABILITIES.to_vec();
    entries.sort_by(|a, b| (a.0, a.1).cmp(&(b.0, b.1)));
    let routes: Vec<String> = entries
        .iter()
        .map(|(method, path, params, body, response)| {
            format!(
                r#"{{"method":"{method}","path":"{path}","params":{params},"body_schema":{body},"response_shape":{response}}}"#,
            )
        })
        .collect();
    let json = format!(r#"{{"version":1,"routes":[{}]}}"#, routes.join(","));
    send_json(stream, &json);
}

/// `GET /api/node/warnings?node_id=<id>` — returns the node's configuration
/// warnings (from `_get_configuration_warnings`), driving the scene-tree
/// warning triangle and its hover tooltip. `has_warning` is true when the
/// list is non-empty.
fn api_get_node_warnings(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let node_raw: u64 = match query_param(query, "node_id").and_then(|s| s.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing or invalid node_id");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    let warnings = state.scene_tree.node_configuration_warnings(node_id);
    let items: Vec<String> = warnings
        .iter()
        .map(|w| format!("\"{}\"", w.replace('\\', "\\\\").replace('"', "\\\"")))
        .collect();
    send_json(
        stream,
        &format!(
            r#"{{"node_id":{node_raw},"has_warning":{},"warnings":[{}]}}"#,
            !warnings.is_empty(),
            items.join(",")
        ),
    );
}

/// `GET /api/filesystem` -- returns project files (.tscn, .gd, .tres) as a tree.
fn api_get_filesystem(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    // pat-aivim: when a `path` query is supplied, sandbox-validate it. Empty
    // or absent `path` keeps the legacy behavior of scanning from cwd.
    if let Some(raw) = query_param(query, "path") {
        if let Err(why) = sandbox_path(raw) {
            send_sandbox_violation(stream, why);
            return;
        }
    }
    // pat-v89tw: root the listing at the opened project so the dock shows that
    // project's res:// tree. When no project has been opened the dock keeps its
    // default "." root, in which case we fall back to the process cwd (legacy
    // behavior preserved for tests and the example backend).
    let (root, favorites_json, display_mode) = {
        let s = state.lock().unwrap();
        let pr = s.asset_browser.filesystem().project_root().to_path_buf();
        let root = if pr.as_os_str().is_empty() || pr.as_os_str() == "." {
            std::env::current_dir().unwrap_or_default()
        } else {
            pr
        };
        // pat-96yv4: the dock's split display mode (tree-only vs split), so the
        // client lays out the tree/file-list to match.
        let display_mode = s.asset_browser.display_mode().as_str();
        // pat-k6600: surface the dock's favorites so the served Favorites
        // header can pin them. Each favorite carries its display name and
        // whether it points at a directory (so the client picks the folder vs
        // file icon).
        let favs: Vec<String> = s
            .asset_browser
            .favorites()
            .iter()
            .map(|fav| {
                let rel = fav
                    .strip_prefix("res://")
                    .unwrap_or(fav)
                    .trim_end_matches('/');
                let name = if rel.is_empty() {
                    "res://".to_string()
                } else {
                    rel.rsplit('/').next().unwrap_or(rel).to_string()
                };
                let disk = if rel.is_empty() {
                    root.clone()
                } else {
                    root.join(rel)
                };
                let is_dir = disk.is_dir() || fav.ends_with('/') || rel.is_empty();
                format!(
                    r#"{{"path":"{}","name":"{}","is_dir":{}}}"#,
                    fav.replace('\\', "\\\\").replace('"', "\\\""),
                    name.replace('\\', "\\\\").replace('"', "\\\""),
                    is_dir
                )
            })
            .collect();
        (root, favs, display_mode)
    };
    let entries = scan_directory(&root, "", 0, 3);
    let entries_json: Vec<String> = entries.iter().map(|e| e.to_json()).collect();
    let json = format!(
        r#"{{"root":"{}","files":[{}],"favorites":[{}],"display_mode":"{}"}}"#,
        root.display()
            .to_string()
            .replace('\\', "\\\\")
            .replace('"', "\\\""),
        entries_json.join(","),
        favorites_json.join(","),
        display_mode
    );
    send_json(stream, &json);
}

/// `POST /api/filesystem/display_mode` — set or cycle the FileSystem dock's
/// split display mode and persist it (pat-96yv4).
///
/// Body: `{"action":"cycle"}` (default) advances TreeOnly → VSplit → HSplit →
/// TreeOnly like Godot's `_change_split_mode`; `{"mode":"tree_only|vsplit|hsplit"}`
/// sets it directly. Returns the new mode.
fn api_filesystem_display_mode(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mode = {
        let mut s = state.lock().unwrap();
        let dock = &mut s.asset_browser;
        if let Some(m) = p.get("mode").and_then(|v| v.as_str()) {
            dock.set_display_mode(crate::filesystem::FsDisplayMode::from_str(m));
            dock.display_mode()
        } else {
            // Default action is to cycle.
            dock.cycle_display_mode()
        }
    };
    send_json(
        stream,
        &format!(r#"{{"ok":true,"display_mode":"{}"}}"#, mode.as_str()),
    );
}

// ---------------------------------------------------------------------------
// pat-ypgqq: full FileSystem dock context-menu backends
// ---------------------------------------------------------------------------

/// The project root the dock is currently showing, falling back to the process
/// cwd for the default/example backend (mirrors `api_get_filesystem`).
fn fs_project_root(state: &Arc<Mutex<EditorState>>) -> std::path::PathBuf {
    let s = state.lock().unwrap();
    let pr = s.asset_browser.filesystem().project_root().to_path_buf();
    if pr.as_os_str().is_empty() || pr.as_os_str() == "." {
        std::env::current_dir().unwrap_or_default()
    } else {
        pr
    }
}

/// Resolve a `res://` path against the project root, rejecting traversal so a
/// context-menu action can only touch files inside the project.
/// `GET /api/visual_shader?path=res://x.tres` — the node graph behind a
/// VisualShader resource (pat-s3rrv.154).
///
/// The runtime has read these resources for a while (`visual_shader_load.rs`),
/// but the editor had no route to them at all, so a project could RUN a
/// VisualShader that the user could not see. This serves the graph the loader
/// already understands: nodes with their concrete Godot class, the flat
/// connection quads, and the compiled shader source for a preview pane.
///
/// The node `type` reported here is the **sub-resource class name**
/// (`VisualShaderNodeColorConstant`), not the 9-variant codegen enum. The enum
/// collapses whole families together — every unrecognised class becomes `None`
/// and is dropped — so reporting it would tell the editor far less than the
/// file actually says, and a node the codegen cannot yet compile would vanish
/// from the graph rather than showing up as an unsupported node.
fn api_visual_shader_get(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let Some(res_path) = query_param(query, "path") else {
        send_error(stream, 400, "missing path");
        return;
    };
    let res_path = url_decode(res_path);
    let root = {
        let state = state.lock().unwrap();
        match state.project_root.clone() {
            Some(r) => r,
            None => {
                send_error(stream, 400, "no project open");
                return;
            }
        }
    };
    let disk_path = match resolve_res_path(std::path::Path::new(&root), &res_path) {
        Ok(p) => p,
        Err(e) => {
            send_error(stream, 400, e);
            return;
        }
    };
    let text = match std::fs::read_to_string(&disk_path) {
        Ok(t) => t,
        Err(e) => {
            send_error(stream, 404, &format!("cannot read resource: {e}"));
            return;
        }
    };
    let resource = match gdresource::loader::TresLoader::new().parse_str(&text, &res_path) {
        Ok(r) => r,
        Err(e) => {
            send_error(stream, 400, &format!("cannot parse resource: {e}"));
            return;
        }
    };
    if resource.class_name != "VisualShader" {
        send_error(stream, 400, "not a VisualShader resource");
        return;
    }

    // Node rows: `nodes/<func>/<id>/node` -> SubResource(...). The position is a
    // sibling key, and Godot omits it at the origin, so a missing one is (0, 0)
    // rather than a reason to skip the node.
    let mut nodes: Vec<String> = Vec::new();
    for (key, value) in resource.properties() {
        let Some(rest) = key.strip_prefix("nodes/") else {
            continue;
        };
        let Some(id_part) = rest.strip_suffix("/node") else {
            continue;
        };
        let Some((func, id_str)) = id_part.rsplit_once('/') else {
            continue;
        };
        let Ok(id) = id_str.parse::<u32>() else {
            continue;
        };
        let class = visual_shader_sub_class(&resource, value).unwrap_or("VisualShaderNode");
        let (px, py) = match resource.get_property(&format!("nodes/{func}/{id}/position")) {
            Some(gdvariant::Variant::Vector2(v)) => (v.x, v.y),
            _ => (0.0, 0.0),
        };
        nodes.push(format!(
            r#"{{"id":{id},"func":"{}","type":"{}","position":[{},{}]}}"#,
            json_escape(func),
            json_escape(class),
            px,
            py
        ));
    }
    nodes.sort();

    let mut conns: Vec<String> = Vec::new();
    for (key, value) in resource.properties() {
        if !key.starts_with("nodes/") || !key.ends_with("/connections") {
            continue;
        }
        let gdvariant::Variant::PackedInt32Array(quads) = value else {
            continue;
        };
        // Flat quads: from_node, from_port, to_node, to_port — the same shape
        // `visual_shader_load` reads, kept verbatim so a round trip cannot drift.
        for q in quads.chunks_exact(4) {
            conns.push(format!(
                r#"{{"from":{},"from_port":{},"to":{},"to_port":{}}}"#,
                q[0].max(0),
                q[1].max(0),
                q[2].max(0),
                q[3].max(0)
            ));
        }
    }

    let code = gdscene::visual_shader_load::visual_shader_from_resource(&resource)
        .map(|vs| vs.get_code())
        .unwrap_or_default();

    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"path":"{}","nodes":[{}],"connections":[{}],"code":"{}"}}"#,
            json_escape(&res_path),
            nodes.join(","),
            conns.join(","),
            json_escape(&code)
        ),
    );
}

/// Loads a VisualShader `.tres` for editing: the on-disk path plus an owned,
/// mutable copy of the parsed resource.
///
/// Editing works on the RAW `Resource` rather than the compiled `VisualShader`,
/// because the compiled form is lossy — its node enum has 9 variants and drops
/// every class it does not recognise, so saving from it would silently delete
/// the user's graph. Round-tripping the resource keeps classes, positions and
/// unknown properties verbatim.
fn visual_shader_open(
    state: &Arc<Mutex<EditorState>>,
    res_path: &str,
) -> Result<(std::path::PathBuf, gdresource::resource::Resource), (u16, String)> {
    let root = {
        let state = state.lock().unwrap();
        state
            .project_root
            .clone()
            .ok_or((400u16, "no project open".to_string()))?
    };
    let disk_path = resolve_res_path(std::path::Path::new(&root), res_path)
        .map_err(|e| (400u16, e.to_string()))?;
    let text = std::fs::read_to_string(&disk_path)
        .map_err(|e| (404u16, format!("cannot read resource: {e}")))?;
    let parsed = gdresource::loader::TresLoader::new()
        .parse_str(&text, res_path)
        .map_err(|e| (400u16, format!("cannot parse resource: {e}")))?;
    if parsed.class_name != "VisualShader" {
        return Err((400, "not a VisualShader resource".to_string()));
    }
    Ok((disk_path, (*parsed).clone()))
}

/// Serialises an edited graph back over its own file.
fn visual_shader_save(
    disk_path: &std::path::Path,
    resource: &gdresource::resource::Resource,
) -> Result<(), (u16, String)> {
    let text = gdresource::saver::TresSaver::new()
        .save_to_string(resource)
        .map_err(|e| (500u16, format!("cannot serialise resource: {e}")))?;
    std::fs::write(disk_path, text).map_err(|e| (500u16, format!("cannot write resource: {e}")))
}

/// The graph function a node belongs to. Godot keys every node row by the
/// shader function it lives in; `fragment` is where the editor adds by default.
const VISUAL_SHADER_DEFAULT_FUNC: &str = "fragment";

/// `POST /api/visual_shader/node` — adds a node to the graph (pat-s3rrv.154).
///
/// Body: `{"path":"res://x.tres","type":"VisualShaderNodeColorConstant","position":[x,y]}`.
fn api_visual_shader_add_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let Some(res_path) = parsed.get("path").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing path");
        return;
    };
    let Some(class) = parsed.get("type").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing type");
        return;
    };
    let (px, py) = match parsed.get("position").and_then(|v| v.as_array()) {
        Some(a) if a.len() == 2 => (
            a[0].as_f64().unwrap_or(0.0) as f32,
            a[1].as_f64().unwrap_or(0.0) as f32,
        ),
        _ => (0.0, 0.0),
    };
    let (disk_path, mut resource) = match visual_shader_open(state, res_path) {
        Ok(v) => v,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };

    // ⚠️ Ids start at 2, never 0 or 1: Godot does not serialise the output node
    // and treats it as an implicit id 0, so reusing 0 would collide with a node
    // that is invisible in the file. `visual_shader_load` synthesises it on read.
    let next_id = visual_shader_next_node_id(&resource);
    let sub_id = format!("n{next_id}");
    let sub = gdresource::resource::Resource::new(class);
    resource.subresources.insert(sub_id.clone(), Arc::new(sub));
    let func = VISUAL_SHADER_DEFAULT_FUNC;
    resource.set_property(
        format!("nodes/{func}/{next_id}/node"),
        gdvariant::Variant::String(format!("SubResource:{sub_id}")),
    );
    resource.set_property(
        format!("nodes/{func}/{next_id}/position"),
        gdvariant::Variant::Vector2(gdcore::math::Vector2::new(px, py)),
    );

    if let Err((code, msg)) = visual_shader_save(&disk_path, &resource) {
        send_error(stream, code, &msg);
        return;
    }
    {
        let mut state = state.lock().unwrap();
        state.add_log("info", format!("Added {class} to {res_path}"));
    }
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"id":{next_id},"type":"{}"}}"#,
            json_escape(class)
        ),
    );
}

/// The lowest unused node id, never below 2.
fn visual_shader_next_node_id(resource: &gdresource::resource::Resource) -> u32 {
    let mut max = 1u32;
    for (key, _) in resource.properties() {
        let Some(rest) = key.strip_prefix("nodes/") else {
            continue;
        };
        let Some(id_part) = rest.strip_suffix("/node") else {
            continue;
        };
        let Some((_func, id_str)) = id_part.rsplit_once('/') else {
            continue;
        };
        if let Ok(id) = id_str.parse::<u32>() {
            max = max.max(id);
        }
    }
    max + 1
}

/// `POST /api/visual_shader/connect` — joins two ports (pat-s3rrv.154).
///
/// Body: `{"path":"res://x.tres","from":2,"from_port":0,"to":0,"to_port":0}`.
fn api_visual_shader_connect(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let Some(res_path) = parsed.get("path").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "missing path");
        return;
    };
    let field = |name: &str| parsed.get(name).and_then(|v| v.as_i64()).unwrap_or(-1);
    let (from, from_port, to, to_port) = (
        field("from"),
        field("from_port"),
        field("to"),
        field("to_port"),
    );
    // A negative id is not a node; accepting it would append a quad the loader
    // clamps to 0, silently wiring something to the output node.
    if from < 0 || from_port < 0 || to < 0 || to_port < 0 {
        send_error(stream, 400, "missing or negative connection field");
        return;
    }
    let (disk_path, mut resource) = match visual_shader_open(state, res_path) {
        Ok(v) => v,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };

    // Append to whichever function already holds connections, so an existing
    // graph keeps its single row rather than growing a second one.
    let key = resource
        .properties()
        .find(|(k, _)| k.starts_with("nodes/") && k.ends_with("/connections"))
        .map(|(k, _)| k.clone())
        .unwrap_or_else(|| format!("nodes/{VISUAL_SHADER_DEFAULT_FUNC}/connections"));
    let mut quads: Vec<i32> = match resource.get_property(&key) {
        Some(gdvariant::Variant::PackedInt32Array(v)) => v.clone(),
        _ => Vec::new(),
    };
    quads.extend_from_slice(&[from as i32, from_port as i32, to as i32, to_port as i32]);
    resource.set_property(key, gdvariant::Variant::PackedInt32Array(quads));

    if let Err((code, msg)) = visual_shader_save(&disk_path, &resource) {
        send_error(stream, code, &msg);
        return;
    }
    {
        let mut state = state.lock().unwrap();
        state.add_log(
            "info",
            format!("Connected {from}:{from_port} -> {to}:{to_port}"),
        );
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// Resolves a `nodes/.../node` value to the class name of the sub-resource it
/// points at.
///
/// ⚠️ The .tres parser rewrites `SubResource("X")` to the STRING
/// `"SubResource:X"` rather than keeping the call text, which is the same trap
/// documented on `visual_shader_load::sub_resource_id`. Both forms are accepted
/// so a hand-built `Resource` behaves like a parsed one.
fn visual_shader_sub_class<'a>(
    resource: &'a gdresource::resource::Resource,
    value: &gdvariant::Variant,
) -> Option<&'a str> {
    let gdvariant::Variant::String(s) = value else {
        return None;
    };
    let id = match s.strip_prefix("SubResource:") {
        Some(rest) => rest.to_string(),
        None => s
            .strip_prefix("SubResource(\"")
            .and_then(|r| r.strip_suffix("\")"))
            .map(|r| r.to_string())?,
    };
    resource
        .subresources
        .get(&id)
        .map(|sub| sub.class_name.as_str())
}

fn resolve_res_path(
    root: &std::path::Path,
    res_path: &str,
) -> Result<std::path::PathBuf, &'static str> {
    let raw = res_path.strip_prefix("res://").unwrap_or(res_path);
    if raw.is_empty() {
        return Err("empty path");
    }
    if std::path::Path::new(raw).is_absolute() {
        return Err("absolute path outside project root");
    }
    if raw.split(['/', '\\']).any(|seg| seg == "..") {
        return Err("path contains traversal segment");
    }
    Ok(root.join(raw))
}

/// Extract a Godot resource UID (`uid://...`) from a scene/resource header, or
/// synthesize a stable one from the path when the file has none. Mirrors the
/// effect of `FILE_MENU_COPY_UID` (a path always maps to a copyable UID here).
fn file_uid(res_path: &str, content: Option<&str>) -> String {
    if let Some(c) = content {
        for line in c.lines().take(8) {
            if let Some(i) = line.find("uid=\"") {
                let rest = &line[i + 5..];
                if let Some(u) = rest.split('"').next() {
                    if u.starts_with("uid://") {
                        return u.to_string();
                    }
                }
            }
        }
    }
    // Deterministic fallback: djb2 hash of the res:// path in base36-ish hex.
    let mut hash: u64 = 5381;
    for b in res_path.bytes() {
        hash = (hash.wrapping_mul(33)) ^ b as u64;
    }
    format!("uid://{hash:x}")
}

/// Parse `[ext_resource ... path="res://..."]` dependency lines from a
/// scene/resource file body (the resources it references).
fn file_dependencies(content: &str) -> Vec<String> {
    let mut deps = Vec::new();
    for line in content.lines() {
        let t = line.trim_start();
        if t.starts_with("[ext_resource") {
            if let Some(i) = line.find("path=\"") {
                let rest = &line[i + 6..];
                if let Some(p) = rest.split('"').next() {
                    if p.starts_with("res://") && !deps.contains(&p.to_string()) {
                        deps.push(p.to_string());
                    }
                }
            }
        }
    }
    deps
}

/// Walk the project for `.tscn`/`.tres` files that reference `target` (its
/// owners), mirroring `FILE_MENU_OWNERS`. Bounded recursive scan.
fn file_owners(root: &std::path::Path, target: &str) -> Vec<String> {
    fn walk(dir: &std::path::Path, root: &std::path::Path, target: &str, out: &mut Vec<String>) {
        let rd = match std::fs::read_dir(dir) {
            Ok(r) => r,
            Err(_) => return,
        };
        for e in rd.flatten() {
            let p = e.path();
            let name = e.file_name().to_string_lossy().to_string();
            if name.starts_with('.') || name == "target" || name == "node_modules" {
                continue;
            }
            if p.is_dir() {
                walk(&p, root, target, out);
            } else if matches!(
                p.extension().and_then(|x| x.to_str()),
                Some("tscn") | Some("tres") | Some("scn") | Some("res")
            ) {
                if let Ok(c) = std::fs::read_to_string(&p) {
                    if file_dependencies(&c).iter().any(|d| d == target) {
                        if let Ok(rel) = p.strip_prefix(root) {
                            out.push(format!(
                                "res://{}",
                                rel.display().to_string().replace('\\', "/")
                            ));
                        }
                    }
                }
            }
        }
    }
    let mut out = Vec::new();
    walk(root, root, target, &mut out);
    out
}

/// `POST /api/filesystem/duplicate` — copy a file (or directory) next to itself
/// under a new name (`FILE_MENU_DUPLICATE`). Body: `{"path":"res://...",
/// "new_name":"copy.tscn"}`. When `new_name` is omitted, a `<stem>_copy.<ext>`
/// name is derived. Returns the new res:// path.
fn api_filesystem_duplicate(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = match p.get("path").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    let root = fs_project_root(state);
    let src = match resolve_res_path(&root, &path) {
        Ok(p) => p,
        Err(why) => {
            send_sandbox_violation(stream, why);
            return;
        }
    };
    if !src.exists() {
        send_error(stream, 404, "file not found");
        return;
    }
    // Derive the destination name.
    let default_name = {
        let stem = src.file_stem().and_then(|s| s.to_str()).unwrap_or("copy");
        match src.extension().and_then(|e| e.to_str()) {
            Some(ext) if !src.is_dir() => format!("{stem}_copy.{ext}"),
            _ => format!("{stem}_copy"),
        }
    };
    let new_name = p
        .get("new_name")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or(default_name);
    if new_name.contains('/') || new_name.contains('\\') || new_name.split('/').any(|s| s == "..") {
        send_sandbox_violation(stream, "new_name contains path separator or traversal");
        return;
    }
    let parent = src.parent().unwrap_or(&root);
    let dst = parent.join(&new_name);
    if dst.exists() {
        send_error(stream, 409, "destination already exists");
        return;
    }
    let result = if src.is_dir() {
        copy_dir_recursive(&src, &dst)
    } else {
        std::fs::copy(&src, &dst).map(|_| ())
    };
    match result {
        Ok(_) => {
            let rel = dst.strip_prefix(&root).unwrap_or(&dst);
            let new_path = format!("res://{}", rel.display().to_string().replace('\\', "/"));
            send_json(
                stream,
                &format!(
                    r#"{{"ok":true,"new_path":"{}"}}"#,
                    new_path.replace('"', "\\\"")
                ),
            );
        }
        Err(e) => send_error(stream, 500, &format!("duplicate failed: {e}")),
    }
}

/// Recursively copy a directory tree.
fn copy_dir_recursive(src: &std::path::Path, dst: &std::path::Path) -> std::io::Result<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let from = entry.path();
        let to = dst.join(entry.file_name());
        if from.is_dir() {
            copy_dir_recursive(&from, &to)?;
        } else {
            std::fs::copy(&from, &to)?;
        }
    }
    Ok(())
}

/// `GET /api/filesystem/file_info?path=res://...` — the data the context-menu
/// copy/dependency/owners actions operate on: the res:// path, the absolute
/// on-disk path (`FILE_MENU_COPY_ABSOLUTE_PATH`), the resource UID
/// (`FILE_MENU_COPY_UID`), the file's dependencies (`FILE_MENU_DEPENDENCIES`),
/// and its owners (`FILE_MENU_OWNERS`).
fn api_filesystem_file_info(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let path = match query_param(query, "path") {
        Some(p) => p
            .replace("%3A", ":")
            .replace("%2F", "/")
            .replace("%20", " "),
        None => {
            send_error(stream, 400, "missing path parameter");
            return;
        }
    };
    let root = fs_project_root(state);
    let abs = match resolve_res_path(&root, &path) {
        Ok(p) => p,
        Err(why) => {
            send_sandbox_violation(stream, why);
            return;
        }
    };
    let content = if abs.is_file() {
        std::fs::read_to_string(&abs).ok()
    } else {
        None
    };
    let uid = file_uid(&path, content.as_deref());
    let deps = content
        .as_deref()
        .map(file_dependencies)
        .unwrap_or_default();
    let owners = file_owners(&root, &path);

    let to_arr = |v: &[String]| -> String {
        v.iter()
            .map(|s| format!(r#""{}""#, s.replace('\\', "\\\\").replace('"', "\\\"")))
            .collect::<Vec<_>>()
            .join(",")
    };
    let abs_str = abs
        .display()
        .to_string()
        .replace('\\', "\\\\")
        .replace('"', "\\\"");
    send_json(
        stream,
        &format!(
            r#"{{"res_path":"{}","abs_path":"{}","uid":"{}","dependencies":[{}],"owners":[{}]}}"#,
            path.replace('"', "\\\""),
            abs_str,
            uid.replace('"', "\\\""),
            to_arr(&deps),
            to_arr(&owners),
        ),
    );
}

/// `POST /api/filesystem/favorite` — add, remove, or toggle a favorite path
// ---------------------------------------------------------------------------
// Export presets (pat-0q2kx.11)
//
// The served Export dialog (editor_ui.rs) has always called these four routes;
// none of them existed, so every call hit the `_ => serve_404` fallback and the
// dialog rendered empty while silently dropping every edit.
//
// `export_presets.cfg` in the project root is the single source of truth: each
// request loads it, mutates, and writes it back. That keeps the file and the UI
// from diverging, survives an editor restart, and means no new `EditorState`
// field (Godot likewise treats the .cfg as authoritative).
// ---------------------------------------------------------------------------

/// Path of the project's `export_presets.cfg`.
fn export_presets_cfg_path(state: &Arc<Mutex<EditorState>>) -> std::path::PathBuf {
    fs_project_root(state).join("export_presets.cfg")
}

/// Loads the project's presets. A missing or unparseable file yields an empty
/// list rather than an error — the dialog must still open on a fresh project.
fn load_export_dialog(state: &Arc<Mutex<EditorState>>) -> crate::ExportDialog {
    let mut dialog = crate::ExportDialog::new();
    if let Ok(text) = std::fs::read_to_string(export_presets_cfg_path(state)) {
        dialog.from_godot_cfg(&text);
    }
    dialog
}

/// Writes the presets back to `export_presets.cfg`.
fn save_export_dialog(
    state: &Arc<Mutex<EditorState>>,
    dialog: &crate::ExportDialog,
) -> std::io::Result<()> {
    std::fs::write(export_presets_cfg_path(state), dialog.to_godot_cfg())
}

/// Renders a preset in the exact shape `editor_ui.rs` reads.
fn export_preset_to_json(p: &crate::ExportPreset) -> serde_json::Value {
    serde_json::json!({
        "name": p.name,
        "platform": p.platform.id(),
        "build_profile": p.build_profile.as_str(),
        "export_path": p.export_path,
        "app_name": p.app_name,
        "icon_path": p.icon_path,
        "include_filters": p.include_filters,
        "exclude_filters": p.exclude_filters,
        "custom_properties": p.custom_properties,
    })
}

/// Builds a preset from the dialog's JSON payload. `name` and a known
/// `platform` are required; everything else falls back to the platform default.
fn export_preset_from_json(v: &serde_json::Value) -> Result<crate::ExportPreset, &'static str> {
    let name = v.get("name").and_then(|x| x.as_str()).unwrap_or("").trim();
    if name.is_empty() {
        return Err("missing name");
    }
    let platform_id = v.get("platform").and_then(|x| x.as_str()).unwrap_or("");
    let platform = crate::ExportPlatform::from_id(platform_id).ok_or("unknown platform")?;

    let mut preset = crate::ExportPreset::new(name, platform);
    if let Some(bp) = v
        .get("build_profile")
        .and_then(|x| x.as_str())
        .and_then(crate::ExportBuildProfile::from_str_name)
    {
        preset.build_profile = bp;
    }
    // An empty export_path keeps `ExportPreset::new`'s platform default rather
    // than blanking it — a preset with no path cannot be exported at all.
    if let Some(p) = v.get("export_path").and_then(|x| x.as_str()) {
        if !p.is_empty() {
            preset.export_path = p.to_string();
        }
    }
    if let Some(s) = v.get("app_name").and_then(|x| x.as_str()) {
        preset.app_name = s.to_string();
    }
    if let Some(s) = v.get("icon_path").and_then(|x| x.as_str()) {
        preset.icon_path = s.to_string();
    }
    let str_list = |key: &str| -> Option<Vec<String>> {
        v.get(key)?.as_array().map(|a| {
            a.iter()
                .filter_map(|x| x.as_str())
                .map(String::from)
                .collect()
        })
    };
    if let Some(f) = str_list("include_filters") {
        preset.include_filters = f;
    }
    if let Some(f) = str_list("exclude_filters") {
        preset.exclude_filters = f;
    }
    if let Some(obj) = v.get("custom_properties").and_then(|x| x.as_object()) {
        preset.custom_properties = obj
            .iter()
            .filter_map(|(k, val)| val.as_str().map(|s| (k.clone(), s.to_string())))
            .collect();
    }
    Ok(preset)
}

/// `GET /api/export/presets` — the project's presets, as a JSON array.
fn api_export_presets_list(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let dialog = load_export_dialog(state);
    let arr: Vec<serde_json::Value> = dialog.presets().iter().map(export_preset_to_json).collect();
    send_json(stream, &serde_json::Value::Array(arr).to_string());
}

/// `POST /api/export/presets` — creates a preset and persists it.
fn api_export_presets_create(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(v) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let preset = match export_preset_from_json(&v) {
        Ok(p) => p,
        Err(e) => {
            send_error(stream, 400, e);
            return;
        }
    };
    let mut dialog = load_export_dialog(state);
    // `add_preset` rejects duplicate names, which is also Godot's rule.
    if let Err(e) = dialog.add_preset(preset) {
        send_error(stream, 400, &format!("{e:?}"));
        return;
    }
    if let Err(e) = save_export_dialog(state, &dialog) {
        send_error(
            stream,
            500,
            &format!("failed to write export_presets.cfg: {e}"),
        );
        return;
    }
    send_json(
        stream,
        &format!(r#"{{"ok":true,"count":{}}}"#, dialog.preset_count()),
    );
}

/// `POST /api/export/presets/update` — replaces one preset in place.
///
/// Identified by `index` when the dialog sends it (which is what makes a rename
/// work), else by `name`.
fn api_export_presets_update(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(v) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let updated = match export_preset_from_json(&v) {
        Ok(p) => p,
        Err(e) => {
            send_error(stream, 400, e);
            return;
        }
    };
    let mut dialog = load_export_dialog(state);
    let target = v
        .get("index")
        .and_then(|x| x.as_u64())
        .map(|i| i as usize)
        .filter(|&i| i < dialog.preset_count())
        .or_else(|| dialog.find_preset(&updated.name));
    let Some(index) = target else {
        send_error(stream, 404, "preset not found");
        return;
    };
    if !dialog.replace_preset(index, updated) {
        send_error(stream, 404, "preset not found");
        return;
    }
    if let Err(e) = save_export_dialog(state, &dialog) {
        send_error(
            stream,
            500,
            &format!("failed to write export_presets.cfg: {e}"),
        );
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/export/presets/delete` — removes a preset by `name`.
fn api_export_presets_delete(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(v) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let Some(name) = v.get("name").and_then(|x| x.as_str()) else {
        send_error(stream, 400, "missing name");
        return;
    };
    let mut dialog = load_export_dialog(state);
    let Some(index) = dialog.find_preset(name) else {
        send_error(stream, 404, "preset not found");
        return;
    };
    dialog.remove_preset(index);
    if let Err(e) = save_export_dialog(state, &dialog) {
        send_error(
            stream,
            500,
            &format!("failed to write export_presets.cfg: {e}"),
        );
        return;
    }
    send_json(
        stream,
        &format!(r#"{{"ok":true,"count":{}}}"#, dialog.preset_count()),
    );
}

/// `POST /api/export/run` — runs the export for a preset (by `name`).
///
/// Web presets go through `gdplatform`'s `PackageExecutor::generate_web_bundle`,
/// which **requires a compiled `.wasm` payload** — supply it as `wasm_path` (or
/// a `patina/wasm_path` custom property). Without one it fails loudly rather
/// than writing a bundle that looks runnable but is not (pat-nzgdu.24 removed
/// exactly that fake). Desktop presets use the existing one-click manifest path.
fn api_export_run(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(v) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON");
        return;
    };
    let Some(name) = v.get("name").and_then(|x| x.as_str()) else {
        send_error(stream, 400, "missing name");
        return;
    };
    let dialog = load_export_dialog(state);
    let Some(index) = dialog.find_preset(name) else {
        send_error(stream, 404, "preset not found");
        return;
    };
    let preset = dialog.presets()[index].clone();
    let project_root = fs_project_root(state);
    let project_name = project_root
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "project".to_string());

    if preset.platform == crate::ExportPlatform::Web {
        let wasm_path = v
            .get("wasm_path")
            .and_then(|x| x.as_str())
            .map(String::from)
            .or_else(|| preset.custom_properties.get("patina/wasm_path").cloned());
        let Some(wasm_path) = wasm_path.filter(|p| !p.is_empty()) else {
            send_error(
                stream,
                400,
                "web export needs a compiled wasm payload: pass wasm_path \
                 (or set the preset's patina/wasm_path custom property)",
            );
            return;
        };
        let out_dir = project_root.join(
            std::path::Path::new(&preset.export_path)
                .parent()
                .unwrap_or(std::path::Path::new("export")),
        );
        if let Err(e) = std::fs::create_dir_all(&out_dir) {
            send_error(stream, 500, &format!("cannot create output dir: {e}"));
            return;
        }
        let config = preset.to_export_config(&project_name);
        let mut executor =
            gdplatform::PackageExecutor::new(config, project_root.clone(), out_dir.clone());
        match executor.generate_web_bundle(Some(std::path::Path::new(&wasm_path))) {
            Ok(index_html) => send_json(
                stream,
                &serde_json::json!({
                    "ok": true,
                    "platform": "web",
                    "output_path": index_html.display().to_string(),
                    "messages": executor.messages(),
                })
                .to_string(),
            ),
            Err(e) => send_error(stream, 500, &format!("web export failed: {e:?}")),
        }
        return;
    }

    match dialog.export_one_click(index, &project_name) {
        Ok(result) => send_json(
            stream,
            &serde_json::json!({
                "ok": result.success,
                "platform": preset.platform.id(),
                "output_path": result.output_path,
                "messages": result.messages,
            })
            .to_string(),
        ),
        Err(e) => send_error(stream, 400, &format!("{e:?}")),
    }
}

/// in the FileSystem dock and persist the list to disk (pat-k6600).
///
/// Body: `{"path":"res://scenes","action":"add"|"remove"|"toggle"}`.
/// `action` defaults to `"toggle"`. Returns the updated favorites list and
/// whether the path is now favorited.
fn api_filesystem_favorite(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = match p.get("path").and_then(|v| v.as_str()) {
        Some(p) if p.starts_with("res://") => p.to_string(),
        Some(_) => {
            send_error(stream, 400, "path must be a res:// path");
            return;
        }
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    let action = p.get("action").and_then(|v| v.as_str()).unwrap_or("toggle");

    let (is_favorite, favorites) = {
        let mut s = state.lock().unwrap();
        let dock = &mut s.asset_browser;
        let now_fav = match action {
            "add" => {
                dock.add_favorite(path.clone());
                true
            }
            "remove" => {
                dock.remove_favorite(&path);
                false
            }
            "toggle" => {
                if dock.is_favorite(&path) {
                    dock.remove_favorite(&path);
                    false
                } else {
                    dock.add_favorite(path.clone());
                    true
                }
            }
            _ => {
                drop(s);
                send_error(stream, 400, "action must be add, remove, or toggle");
                return;
            }
        };
        // Persist so the favorite survives an editor reload/restart.
        let _ = dock.save_favorites();
        let favs: Vec<String> = dock
            .favorites()
            .iter()
            .map(|f| format!(r#""{}""#, f.replace('\\', "\\\\").replace('"', "\\\"")))
            .collect();
        (now_fav, favs)
    };
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"is_favorite":{},"favorites":[{}]}}"#,
            is_favorite,
            favorites.join(",")
        ),
    );
}

/// `POST /api/project/open` -- root the editor at a real game project.
///
/// Body: `{"path":"/abs/project/dir"}`. Validates that the directory exists
/// and contains a `project.godot` manifest, then re-roots the FileSystem dock
/// and texture cache at that path. Afterwards `GET /api/filesystem` lists the
/// project's `res://` tree and `.tscn` files can be opened from it. pat-v89tw.
fn api_open_project(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = parsed.get("path").and_then(|v| v.as_str()).unwrap_or("");
    if path.is_empty() {
        send_error(stream, 400, "path required");
        return;
    }
    let dir = std::path::PathBuf::from(path);
    if !dir.is_dir() {
        send_error(stream, 404, "project directory not found");
        return;
    }
    // A Godot project is identified by a `project.godot` manifest. Require it
    // so we root at a real project rather than an arbitrary folder.
    if !dir.join("project.godot").is_file() {
        send_error(stream, 400, "no project.godot in directory");
        return;
    }
    // Build and scan the dock outside the state lock (disk IO).
    let mut dock = FileSystemDock::new(EditorFileSystem::new(dir.clone()));
    let count = match dock.refresh() {
        Ok(c) => c,
        Err(e) => {
            send_error(stream, 500, &format!("failed to scan project: {e:?}"));
            return;
        }
    };
    let root_str = dir.display().to_string();
    {
        let mut s = state.lock().unwrap();
        s.asset_browser = dock;
        s.texture_cache.set_project_root(root_str.clone());
        s.project_root = Some(root_str.clone());
        // Create-dialog favorites/recent follow the project, like Godot's
        // per-project settings dir.
        s.create_node_dialog
            .set_persist_dir(Some(dir.join(".patina").join("editor")));
        // pat-0q2kx.76: fill the plugin list from addons/*/plugin.cfg and start
        // whatever `project.godot` says is already enabled, so an enabled addon
        // survives a server restart.
        sync_plugins_from_project(&mut s);
    }
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"project_root":"{}","file_count":{}}}"#,
            root_str.replace('\\', "\\\\").replace('"', "\\\""),
            count
        ),
    );
}

// ---------------------------------------------------------------------------
// File preview endpoint
// ---------------------------------------------------------------------------

/// `GET /api/preview/file?path=res://...` -- returns a preview for the given file.
///
/// For images: returns the raw image bytes with appropriate content type.
/// For scripts (.gd): returns JSON with first N lines of the file.
/// For scenes (.tscn): returns JSON with node count and root type.
/// For resources (.tres): returns JSON with resource type info.
fn api_get_file_preview(query: &str, stream: &mut TcpStream) {
    let path = match query_param(query, "path") {
        Some(p) => {
            // URL-decode the path (handle %20, etc.)
            let decoded = p.replace("%20", " ").replace("%2F", "/");
            decoded.replace("res://", "")
        }
        None => {
            send_error(stream, 400, "missing path parameter");
            return;
        }
    };

    let cwd = std::env::current_dir().unwrap_or_default();
    let full_path = cwd.join(&path);

    if !full_path.exists() {
        send_error(stream, 404, "file not found");
        return;
    }

    let ext = full_path
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("")
        .to_lowercase();

    match ext.as_str() {
        // Image files: serve raw bytes with content type
        "png" => serve_binary_file(stream, &full_path, "image/png"),
        "jpg" | "jpeg" => serve_binary_file(stream, &full_path, "image/jpeg"),
        "webp" => serve_binary_file(stream, &full_path, "image/webp"),
        "svg" => serve_binary_file(stream, &full_path, "image/svg+xml"),

        // Script files: return first 30 lines as JSON
        "gd" | "gdshader" | "glsl" => {
            let content = std::fs::read_to_string(&full_path).unwrap_or_default();
            let lines: Vec<&str> = content.lines().take(30).collect();
            let line_count = content.lines().count();
            let escaped = lines
                .join("\n")
                .replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace('\n', "\\n")
                .replace('\t', "\\t");
            let json = format!(
                r#"{{"type":"script","lines":{},"preview":"{}"}}"#,
                line_count, escaped
            );
            send_json(stream, &json);
        }

        // Scene files: parse and return summary
        "tscn" => {
            let content = std::fs::read_to_string(&full_path).unwrap_or_default();
            let node_count = content.matches("[node").count();
            let root_type = content
                .lines()
                .find(|l| l.starts_with("[node") && !l.contains("parent="))
                .and_then(|l| {
                    l.split("type=")
                        .nth(1)
                        .map(|t| t.split('"').nth(1).unwrap_or("Node").to_string())
                })
                .unwrap_or_else(|| "Node".to_string());
            let ext_res_count = content.matches("[ext_resource").count();
            let sub_res_count = content.matches("[sub_resource").count();
            let json = format!(
                r#"{{"type":"scene","node_count":{},"root_type":"{}","ext_resources":{},"sub_resources":{}}}"#,
                node_count, root_type, ext_res_count, sub_res_count
            );
            send_json(stream, &json);
        }

        // Resource files: return resource type
        "tres" => {
            let content = std::fs::read_to_string(&full_path).unwrap_or_default();
            let res_type = content
                .lines()
                .find(|l| l.starts_with("[gd_resource"))
                .and_then(|l| {
                    l.split("type=")
                        .nth(1)
                        .map(|t| t.split('"').nth(1).unwrap_or("Resource").to_string())
                })
                .unwrap_or_else(|| "Resource".to_string());
            let sub_res_count = content.matches("[sub_resource").count();
            let size = std::fs::metadata(&full_path).map(|m| m.len()).unwrap_or(0);
            let json = format!(
                r#"{{"type":"resource","resource_type":"{}","sub_resources":{},"size":{}}}"#,
                res_type, sub_res_count, size
            );
            send_json(stream, &json);
        }

        // Config files: show first 20 lines
        "cfg" => {
            let content = std::fs::read_to_string(&full_path).unwrap_or_default();
            let lines: Vec<&str> = content.lines().take(20).collect();
            let escaped = lines
                .join("\n")
                .replace('\\', "\\\\")
                .replace('"', "\\\"")
                .replace('\n', "\\n")
                .replace('\t', "\\t");
            let json = format!(r#"{{"type":"config","preview":"{}"}}"#, escaped);
            send_json(stream, &json);
        }

        _ => {
            send_json(stream, r#"{"type":"unknown"}"#);
        }
    }
}

/// Serve a binary file with the given content type.
fn serve_binary_file(stream: &mut TcpStream, path: &std::path::Path, content_type: &str) {
    match std::fs::read(path) {
        Ok(data) => {
            let header = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: {content_type}\r\nContent-Length: {len}\r\nAccess-Control-Allow-Origin: {origin}\r\nCache-Control: max-age=60\r\nConnection: close\r\n\r\n",
                len = data.len(),
                origin = cors_current_allow_origin(),
            );
            let _ = stream.write_all(header.as_bytes());
            let _ = stream.write_all(&data);
        }
        Err(_) => {
            // pat-f23vr: emit the standardized error envelope for thumbnail
            // misses so every non-2xx response carries the same shape.
            send_error_coded(stream, 404, "not_found", "thumbnail not found");
        }
    }
}

// ---------------------------------------------------------------------------
// Script endpoint
// ---------------------------------------------------------------------------

/// Parse a query string parameter by name.
fn query_param<'a>(query: &'a str, name: &str) -> Option<&'a str> {
    for pair in query.split('&') {
        if let Some((key, value)) = pair.split_once('=') {
            if key == name {
                return Some(value);
            }
        }
    }
    None
}

/// URL-decode a percent-encoded string.
fn url_decode(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    let mut chars = s.bytes();
    while let Some(b) = chars.next() {
        if b == b'%' {
            let hi = chars.next().unwrap_or(0);
            let lo = chars.next().unwrap_or(0);
            let hex = [hi, lo];
            if let Ok(s) = std::str::from_utf8(&hex) {
                if let Ok(val) = u8::from_str_radix(s, 16) {
                    result.push(val as char);
                    continue;
                }
            }
            result.push('%');
            result.push(hi as char);
            result.push(lo as char);
        } else if b == b'+' {
            result.push(' ');
        } else {
            result.push(b as char);
        }
    }
    result
}

/// `GET /api/script?path=<path>` -- reads a .gd file and returns its content.
/// `GET /api/assetlib/list` -- the Asset Library catalog (pat-0q2kx.240,
/// pat-s3rrv.227).
///
/// Serves whatever catalog the project configures via
/// [`ASSETLIB_INDEX_URL_SETTING`], and an HONEST EMPTY STATE when it configures
/// none. This endpoint previously served twelve hardcoded entries ("Pixel
/// Platformer Kit", "Dialogue System", …) that looked like a real catalog and
/// were not: none of them existed and none could be installed. Fabricated
/// listings are worse than an empty browser — they invite a user to try to
/// install something that cannot be installed, and they make the feature look
/// finished to anyone auditing it. So the unconfigured answer stays
/// `configured: false`, which lets the frontend render an empty state with an
/// install-from-file affordance rather than a broken grid.
///
/// Godot browses godotengine.org over HTTPS. Patina has no baked-in host, and
/// ⚠️ cannot reach an HTTPS one yet regardless — `HttpClient::perform` refuses
/// TLS before it connects. A configured catalog must be plaintext `http://`
/// until a TLS backend lands; `fetch_catalog` says so explicitly rather than
/// surfacing a bare connection failure.
fn api_get_assetlib_list(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let Some(url) = assetlib_index_url(state) else {
        let body = serde_json::json!({
            "assets": [],
            // Distinguishes "no catalog source configured" from "the catalog is
            // configured and happens to return nothing", which the frontend must
            // present differently.
            "configured": false,
            "reason": "no asset catalog configured",
            // Named so the eventual editor setting and the UI agree on one key.
            "setting": ASSETLIB_INDEX_URL_SETTING,
        });
        send_json(stream, &body.to_string());
        return;
    };

    match fetch_catalog(&url) {
        Ok(assets) => {
            let body = serde_json::json!({
                "assets": assets,
                "configured": true,
                "source": url,
            });
            send_json(stream, &body.to_string());
        }
        Err(reason) => {
            // A configured-but-unreachable catalog is NOT the same as an
            // unconfigured one, and flattening the two would send the user
            // hunting for a setting they have already set. `configured` stays
            // true and the reason says what actually failed.
            let body = serde_json::json!({
                "assets": [],
                "configured": true,
                "source": url,
                "reason": reason,
            });
            send_json(stream, &body.to_string());
        }
    }
}

/// The project setting naming the asset catalog to query.
///
/// Godot browses `godotengine.org`; Patina has no baked-in host, so the catalog
/// is opt-in per project.
const ASSETLIB_INDEX_URL_SETTING: &str = "editor/assetlib/index_url";

/// Reads [`ASSETLIB_INDEX_URL_SETTING`] out of `project.godot`.
///
/// Returns `None` when unset or blank, which is the honest-empty-state path.
fn assetlib_index_url(state: &Arc<Mutex<EditorState>>) -> Option<String> {
    let root = {
        let s = state.lock().expect("editor state");
        s.project_root.clone()?
    };
    let text = std::fs::read_to_string(std::path::Path::new(&root).join("project.godot")).ok()?;
    let pf = GodotProjectFile::parse(&text).ok()?;
    // The key is stored as `[editor] assetlib/index_url`, matching how Godot
    // splits a slashed setting path into section + remainder.
    let (section, key) = ASSETLIB_INDEX_URL_SETTING.split_once('/')?;
    let raw = pf.get(section, key)?.trim().trim_matches('"').to_string();
    if raw.is_empty() {
        None
    } else {
        Some(raw)
    }
}

/// GETs `url` and maps the catalog it returns into the asset shape the AssetLib
/// grid already renders.
///
/// ⚠️ `https://` CANNOT work yet: `HttpClient::perform` refuses TLS before it
/// connects, because no TLS backend is wired. A catalog URL therefore has to be
/// plaintext `http://` today — the error text says so rather than reporting a
/// bare connection failure.
fn fetch_catalog(url: &str) -> Result<Vec<serde_json::Value>, String> {
    if url.starts_with("https://") {
        return Err(
            "https catalogs are not supported yet (no TLS backend); use an http:// URL".to_string(),
        );
    }
    let config = gdplatform::HttpRequestConfig {
        url: url.to_string(),
        method: gdplatform::HttpMethod::Get,
        timeout_seconds: 10.0,
        ..Default::default()
    };
    let resp = gdplatform::HttpClient::perform(&config);
    if resp.status_code != 200 {
        return Err(format!("catalog returned HTTP {}", resp.status_code));
    }
    let parsed: serde_json::Value = serde_json::from_slice(&resp.body)
        .map_err(|e| format!("catalog is not valid JSON: {e}"))?;
    Ok(map_catalog_assets(&parsed))
}

/// Normalises a catalog payload into the grid's asset shape.
///
/// Accepts Godot's own `{"result": [...]}` envelope, a `{"assets": [...]}` one,
/// or a bare array, so a hand-written catalog does not have to imitate the
/// upstream service exactly.
fn map_catalog_assets(parsed: &serde_json::Value) -> Vec<serde_json::Value> {
    let rows = parsed
        .get("result")
        .or_else(|| parsed.get("assets"))
        .and_then(|v| v.as_array())
        .or_else(|| parsed.as_array());
    let Some(rows) = rows else {
        return Vec::new();
    };
    rows.iter()
        .map(|a| {
            let text = |keys: &[&str]| -> String {
                keys.iter()
                    .find_map(|k| a.get(*k).and_then(|v| v.as_str()))
                    .unwrap_or("")
                    .to_string()
            };
            serde_json::json!({
                "title": text(&["title", "name"]),
                "author": text(&["author"]),
                "category": text(&["category"]),
                // Upstream calls the licence "cost"; the grid calls it "license".
                "license": text(&["cost", "license"]),
                "version": text(&["version_string", "version"]),
                "download_url": text(&["download_url"]),
                "icon": "\u{1f4e6}",
            })
        })
        .collect()
}

/// `POST /api/assetlib/download` — fetches an asset's zip and installs it.
///
/// Body: `{"url": "http://.../asset.zip"}`. The fetch happens server-side, which
/// is what makes the per-asset Download button work at all: the browser cannot
/// read a cross-origin zip, and the unpack has to touch the project on disk.
fn api_assetlib_download(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(p) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON body");
        return;
    };
    let Some(url) = p.get("url").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "url is required");
        return;
    };
    if url.starts_with("https://") {
        send_error(
            stream,
            400,
            "https downloads are not supported yet (no TLS backend); use an http:// URL",
        );
        return;
    }
    let config = gdplatform::HttpRequestConfig {
        url: url.to_string(),
        method: gdplatform::HttpMethod::Get,
        timeout_seconds: 30.0,
        ..Default::default()
    };
    let resp = gdplatform::HttpClient::perform(&config);
    if resp.status_code != 200 {
        send_error(
            stream,
            502,
            &format!("download returned HTTP {}", resp.status_code),
        );
        return;
    }
    let skip: Vec<String> = p
        .get("skip")
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();

    match install_zip_bytes(state, resp.body, &skip) {
        Ok(outcome) => send_install_outcome(stream, outcome),
        Err((status, message)) => send_error(stream, status, &message),
    }
}

/// `POST /api/assetlib/install` — unpacks an uploaded `.zip` into the project
/// (pat-s3rrv.227).
///
/// Body: `{"zip_base64": "...", "skip": ["addons/demo/README.md"]}`. The zip
/// arrives base64-encoded because `HttpRequest.body` is a `String` and raw zip
/// bytes are not valid UTF-8 — they would be mangled before this ever ran.
///
/// `skip` is Godot's per-entry opt-out from `EditorAssetInstaller`: the dialog
/// previews the file list and lets the user untick entries before installing.
///
/// ⚠️ Every entry goes through `sandbox_path`, so a zip containing `../../etc`
/// cannot escape the project. A malicious archive is exactly the threat model
/// here — the file list comes from an untrusted download.
/// What an archive install produced, shared by the upload and download routes.
struct InstallOutcome {
    installed: Vec<String>,
    skipped: Vec<String>,
    plugins: Vec<String>,
}

/// Unpacks `bytes` into the project (pat-s3rrv.227).
///
/// `Err` carries an HTTP status and a message ready for [`send_error`], so both
/// callers refuse a bad archive identically instead of each inventing wording.
///
/// ⚠️ Every entry goes through `sandbox_path`, and destinations are ALL resolved
/// before anything is written — a hostile entry halfway through an archive must
/// not leave the first half unpacked. The file list comes from an untrusted
/// download, which is exactly the threat model here.
fn install_zip_bytes(
    state: &Arc<Mutex<EditorState>>,
    bytes: Vec<u8>,
    skip: &[String],
) -> Result<InstallOutcome, (u16, String)> {
    let mut zip = gdresource::zip::ZipReader::new();
    if zip.open_from_bytes(bytes).is_err() {
        return Err((400, "not a readable zip archive".to_string()));
    }

    let mut planned: Vec<(String, std::path::PathBuf)> = Vec::new();
    let mut skipped: Vec<String> = Vec::new();
    for entry in zip.get_files() {
        // A directory entry carries no bytes; the parent dirs are created for
        // each file below, so these are simply not interesting.
        if entry.ends_with('/') {
            continue;
        }
        if skip.iter().any(|s| s == &entry) {
            skipped.push(entry);
            continue;
        }
        let Ok(dest) = sandbox_path(&entry) else {
            // A traversal attempt is reported, not silently dropped: the user
            // asked to install this archive and deserves to know it was hostile.
            return Err((400, format!("unsafe path in archive: {entry}")));
        };
        planned.push((entry, dest));
    }

    let mut installed: Vec<String> = Vec::new();
    for (entry, dest) in planned {
        let Ok(data) = zip.read_file(&entry, true) else {
            return Err((400, format!("could not read {entry} from archive")));
        };
        if let Some(parent) = dest.parent() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                return Err((500, format!("mkdir failed: {e}")));
            }
        }
        if let Err(e) = std::fs::write(&dest, &data) {
            return Err((500, format!("write failed: {e}")));
        }
        installed.push(entry);
    }

    // Rescan so a freshly installed `addons/<name>/plugin.cfg` appears in
    // `/api/plugins` immediately — without this the plugin exists on disk and
    // the editor cannot see it until a restart.
    let plugins: Vec<String> = {
        let mut s = state.lock().expect("editor state");
        sync_plugins_from_project(&mut s);
        s.plugins.iter().map(|pl| pl.folder.clone()).collect()
    };

    Ok(InstallOutcome {
        installed,
        skipped,
        plugins,
    })
}

/// Serialises an [`InstallOutcome`] the one way both install routes report it.
fn send_install_outcome(stream: &mut TcpStream, outcome: InstallOutcome) {
    let payload = serde_json::json!({
        "ok": true,
        "installed": outcome.installed,
        "skipped": outcome.skipped,
        "plugins": outcome.plugins,
    });
    send_json(stream, &payload.to_string());
}

/// `POST /api/assetlib/install` — unpacks an uploaded `.zip` into the project
/// (pat-s3rrv.227).
///
/// Body: `{"zip_base64": "...", "skip": ["addons/demo/README.md"]}`. The zip
/// arrives base64-encoded because `HttpRequest.body` is a `String` and raw zip
/// bytes are not valid UTF-8 — they would be mangled before this ever ran.
///
/// `skip` is Godot's per-entry opt-out from `EditorAssetInstaller`: the dialog
/// previews the file list and lets the user untick entries before installing.
fn api_assetlib_install(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(p) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON body");
        return;
    };
    let Some(b64) = p.get("zip_base64").and_then(|v| v.as_str()) else {
        send_error(stream, 400, "zip_base64 is required");
        return;
    };
    let Some(bytes) = base64_decode(b64) else {
        send_error(stream, 400, "zip_base64 is not valid base64");
        return;
    };
    let skip: Vec<String> = p
        .get("skip")
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();

    match install_zip_bytes(state, bytes, &skip) {
        Ok(outcome) => send_install_outcome(stream, outcome),
        Err((status, message)) => send_error(stream, status, &message),
    }
}

/// The directory `res://` resolves against for template lookup.
///
/// Mirrors the sibling script routes, which resolve `res://` against the
/// process CWD, and prefers an explicitly configured project root when the
/// editor was pointed at one.
fn script_project_root(state: &EditorState) -> std::path::PathBuf {
    match &state.project_root {
        Some(root) if !root.is_empty() => std::path::PathBuf::from(root),
        _ => std::env::current_dir().unwrap_or_default(),
    }
}

/// `GET /api/script/templates?base_class=Control`
///
/// Every template applicable to `base_class`, nearest ancestor first, so the
/// Create-Script dialog can populate its Template dropdown. Godot searches the
/// whole ancestor chain, which is why a `Sprite2D` still sees `Node`'s default.
fn api_script_templates(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let base_class = query_param(query, "base_class")
        .map(url_decode)
        .unwrap_or_else(|| "Node".to_string());
    let root = {
        let s = state.lock().unwrap();
        script_project_root(&s)
    };
    let templates = crate::script_templates::templates_for(&base_class, &root);
    let items: Vec<serde_json::Value> = templates
        .iter()
        .map(|t| {
            serde_json::json!({
                "id": t.id,
                "name": t.name,
                "inherit": t.inherit,
                "description": t.description,
                "origin": t.origin.as_str(),
            })
        })
        .collect();
    // Length BEFORE the macro: `items` is moved in at "templates", so reading
    // it afterwards would not compile.
    let count = items.len();
    let json = serde_json::json!({
        "base_class": base_class,
        "templates": items,
        "count": count,
    });
    send_json(stream, &json.to_string());
}

/// `POST /api/script/create`
///
/// Generates a new script body from the chosen template and base class and
/// writes it. The body is produced HERE rather than in the browser: the client
/// used to build it as a string literal, which is why every new script carried
/// the same hardcoded `extends Node2D` whatever the node's real class was.
///
/// Attaching the result to a node stays a separate `/api/property/set`, so this
/// route does not duplicate the undo bookkeeping that already lives there.
fn api_script_create(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let json = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = match json.get("path").and_then(|p| p.as_str()) {
        Some(p) => p.trim().to_string(),
        None => {
            send_error(stream, 400, "missing path field");
            return;
        }
    };
    // Validate BEFORE touching the disk, and report which rule broke — the old
    // flow failed silently after the fact, leaving no clue what was wrong.
    if let Some(problem) = crate::script_templates::script_path_problem(&path) {
        send_error(stream, 400, &problem);
        return;
    }
    let base_class = json
        .get("base_class")
        .and_then(|b| b.as_str())
        .filter(|b| !b.is_empty())
        .unwrap_or("Node")
        .to_string();
    let class_name = json
        .get("class_name")
        .and_then(|c| c.as_str())
        .filter(|c| !c.is_empty())
        .map(|c| c.to_string())
        .unwrap_or_else(|| {
            // Godot defaults the class name to the file's base name.
            path.rsplit('/')
                .next()
                .unwrap_or("NewScript")
                .trim_end_matches(".gd")
                .to_string()
        });
    let template_id = json
        .get("template")
        .and_then(|t| t.as_str())
        .filter(|t| !t.is_empty());

    let root = {
        let s = state.lock().unwrap();
        script_project_root(&s)
    };
    let content = crate::script_templates::generate_script(
        &base_class,
        &class_name,
        template_id,
        &root,
        crate::script_templates::DEFAULT_INDENT,
    );

    let file_path = match path.strip_prefix("res://") {
        Some(stripped) => root.join(stripped),
        None => std::path::PathBuf::from(&path),
    };
    if file_path.exists() {
        // Godot reuses an existing file rather than clobbering it, and says so.
        let json = serde_json::json!({
            "ok": true,
            "path": path,
            "created": false,
            "content": std::fs::read_to_string(&file_path).unwrap_or_default(),
        });
        send_json(stream, &json.to_string());
        return;
    }
    if let Some(parent) = file_path.parent() {
        if let Err(e) = std::fs::create_dir_all(parent) {
            send_error(stream, 500, &format!("could not create directory: {e}"));
            return;
        }
    }
    if let Err(e) = std::fs::write(&file_path, &content) {
        send_error(stream, 500, &format!("could not write script: {e}"));
        return;
    }
    let json = serde_json::json!({
        "ok": true,
        "path": path,
        "created": true,
        "base_class": base_class,
        "content": content,
    });
    send_json(stream, &json.to_string());
}

fn api_get_script(query: &str, stream: &mut TcpStream) {
    let raw_path = match query_param(query, "path") {
        Some(p) => url_decode(p),
        None => {
            send_error(stream, 400, "missing path parameter");
            return;
        }
    };

    // Resolve res:// paths relative to cwd.
    let file_path = if let Some(stripped) = raw_path.strip_prefix("res://") {
        let cwd = std::env::current_dir().unwrap_or_default();
        cwd.join(stripped)
    } else {
        std::path::PathBuf::from(&raw_path)
    };

    // Security: only allow .gd files.
    match file_path.extension().and_then(|e| e.to_str()) {
        Some("gd") => {}
        _ => {
            send_error(stream, 400, "only .gd files are supported");
            return;
        }
    }

    match std::fs::read_to_string(&file_path) {
        Ok(content) => {
            let json = serde_json::json!({
                "path": raw_path,
                "content": content,
                "lines": content.lines().count()
            });
            send_json(stream, &json.to_string());
        }
        Err(e) => {
            send_error(stream, 404, &format!("failed to read script: {e}"));
        }
    }
}

/// `POST /api/script/save` -- writes content to a .gd file.
/// `GET /api/script/goto` — resolves a symbol to the script and line that
/// defines it, backing the editor's Ctrl+Click goto-definition (pat-0q2kx.14).
///
/// Query: `path` (the open script, `res://` or absolute) plus **either**
/// `symbol=foo` **or** `line=<text>&col=<n>` to have the server pick the
/// identifier under the caret (`goto_definition::symbol_at`).
///
/// Looks in the open script first — Godot resolves locally before searching —
/// then falls back to scanning the project's other `.gd` files, so a method
/// defined in another script still jumps. The response always names the `file`
/// the definition landed in, since it need not be the file you clicked in.
/// A symbol with no definition is `{"found":false}` and **not** an error: an
/// unresolved Ctrl+Click is a no-op in Godot, not a failure.
fn api_script_goto(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    use crate::goto_definition::{find_definition, symbol_at};

    let Some(raw_path) = query_param(query, "path").map(url_decode) else {
        send_error(stream, 400, "missing path parameter");
        return;
    };
    let project_root = fs_project_root(state);
    let resolve = |p: &str| -> std::path::PathBuf {
        match p.strip_prefix("res://") {
            Some(rest) => project_root.join(rest),
            None => std::path::PathBuf::from(p),
        }
    };
    let file_path = resolve(&raw_path);

    // The symbol is either given outright or read from the caret position.
    let symbol = match query_param(query, "symbol").map(url_decode) {
        Some(s) if !s.is_empty() => s,
        _ => {
            let line = query_param(query, "line")
                .map(url_decode)
                .unwrap_or_default();
            let col = query_param(query, "col")
                .and_then(|c| c.parse::<usize>().ok())
                .unwrap_or(0);
            match symbol_at(&line, col) {
                Some(s) => s,
                // Not on an identifier — a no-op, exactly like Godot.
                None => {
                    send_json(stream, r#"{"found":false}"#);
                    return;
                }
            }
        }
    };

    // 1. The open script.
    if let Ok(source) = std::fs::read_to_string(&file_path) {
        if let Some(line) = find_definition(&source, &symbol) {
            send_json(
                stream,
                &serde_json::json!({
                    "found": true,
                    "file": raw_path,
                    "line": line,
                    "symbol": symbol,
                })
                .to_string(),
            );
            return;
        }
    }

    // 2. Other `.gd` files in the project, in a stable order so the answer does
    //    not depend on directory iteration order.
    let mut scripts = Vec::new();
    collect_gd_scripts(&project_root, 0, &mut scripts);
    scripts.sort();
    for path in scripts {
        if path == file_path {
            continue;
        }
        let Ok(source) = std::fs::read_to_string(&path) else {
            continue;
        };
        if let Some(line) = find_definition(&source, &symbol) {
            // Report the project-relative `res://` form the editor opens with.
            let rel = path
                .strip_prefix(&project_root)
                .ok()
                .and_then(|p| p.to_str())
                .map(|p| format!("res://{}", p.replace('\\', "/")))
                .unwrap_or_else(|| path.display().to_string());
            send_json(
                stream,
                &serde_json::json!({
                    "found": true,
                    "file": rel,
                    "line": line,
                    "symbol": symbol,
                })
                .to_string(),
            );
            return;
        }
    }

    send_json(
        stream,
        &serde_json::json!({ "found": false, "symbol": symbol }).to_string(),
    );
}

/// Collects `.gd` files under `dir`, bounded in depth so a deep or symlinked
/// tree cannot stall the request.
fn collect_gd_scripts(dir: &std::path::Path, depth: usize, out: &mut Vec<std::path::PathBuf>) {
    if depth > 8 || out.len() > 2000 {
        return;
    }
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = entry.file_name();
        let name = name.to_string_lossy();
        // Skip VCS/build/editor-state dirs — they hold no project scripts.
        if name.starts_with('.') || name == "target" || name == "node_modules" {
            continue;
        }
        if path.is_dir() {
            collect_gd_scripts(&path, depth + 1, out);
        } else if path.extension().and_then(|e| e.to_str()) == Some("gd") {
            out.push(path);
        }
    }
}

fn api_save_script(body: &str, stream: &mut TcpStream) {
    let json = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let raw_path = match json.get("path").and_then(|p| p.as_str()) {
        Some(p) => p.to_string(),
        None => {
            send_error(stream, 400, "missing path field");
            return;
        }
    };
    let content_str = match json.get("content").and_then(|c| c.as_str()) {
        Some(c) => c.to_string(),
        None => {
            send_error(stream, 400, "missing content field");
            return;
        }
    };
    let file_path = if let Some(stripped) = raw_path.strip_prefix("res://") {
        let cwd = std::env::current_dir().unwrap_or_default();
        cwd.join(stripped)
    } else {
        std::path::PathBuf::from(&raw_path)
    };
    match file_path.extension().and_then(|e| e.to_str()) {
        Some("gd") => {}
        _ => {
            send_error(stream, 400, "only .gd files are supported");
            return;
        }
    }
    if let Some(parent) = file_path.parent() {
        if !parent.exists() {
            if let Err(e) = std::fs::create_dir_all(parent) {
                send_error(stream, 500, &format!("failed to create directory: {e}"));
                return;
            }
        }
    }
    match std::fs::write(&file_path, &content_str) {
        Ok(()) => send_json(stream, r#"{"ok":true}"#),
        Err(e) => send_error(stream, 500, &format!("failed to write script: {e}")),
    }
}

// ---------------------------------------------------------------------------
// Signals endpoint
// ---------------------------------------------------------------------------

/// Returns the list of common signals for a given node class name.
fn signals_for_class(class_name: &str) -> Vec<&'static str> {
    let mut signals = vec!["tree_entered", "tree_exiting", "ready"];

    match class_name {
        "Button" => {
            signals.extend(&["pressed", "toggled", "button_down", "button_up"]);
        }
        "Area2D" => {
            signals.extend(&["body_entered", "body_exited", "area_entered", "area_exited"]);
        }
        "Timer" => {
            signals.push("timeout");
        }
        "CollisionObject2D" => {
            signals.extend(&["input_event", "mouse_entered", "mouse_exited"]);
        }
        _ => {}
    }

    signals
}

/// `GET /api/node/signals?node_id=<id>` -- returns signals for a node.
fn api_get_node_signals(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let node_raw: u64 = match query_param(query, "node_id").and_then(|s| s.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing or invalid node_id");
            return;
        }
    };

    let json = {
        let state = state.lock().unwrap();
        let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
            Some(id) => id,
            None => {
                send_error(stream, 404, "node not found");
                return;
            }
        };

        let node = state.scene_tree.get_node(node_id).unwrap();
        let class_name = node.class_name().to_string();

        // Get signals available for this class.
        let available = signals_for_class(&class_name);

        // Check for connections (stored as property signal_connections).
        let connections_variant = node.get_property("signal_connections");
        let connections_str = match &connections_variant {
            Variant::String(s) => s.clone(),
            _ => String::new(),
        };

        // Get groups from the node's real membership so the Groups dock shows
        // groups added here, loaded from a `.tscn`, or copied on duplicate.
        let mut groups: Vec<String> = node.groups().iter().cloned().collect();
        groups.sort();

        let signals_json: Vec<String> = available
            .iter()
            .map(|sig| {
                // Parse connections to get details for this signal
                let connections: Vec<String> = connections_str
                    .split(',')
                    .filter(|c| !c.is_empty() && c.starts_with(&format!("{}:", sig)))
                    .map(|c| {
                        let method = c.splitn(2, ':').nth(1).unwrap_or("");
                        format!(r#"{{"method":"{}"}}"#, method.replace('"', "\\\""))
                    })
                    .collect();
                let connected = !connections.is_empty();
                format!(
                    r#"{{"name":"{}","connected":{},"connection_count":{},"connections":[{}]}}"#,
                    sig,
                    connected,
                    connections.len(),
                    connections.join(",")
                )
            })
            .collect();

        let groups_json: Vec<String> = groups
            .iter()
            .map(|g| format!(r#""{}""#, g.replace('\\', "\\\\").replace('"', "\\\"")))
            .collect();

        let total_connected = signals_json
            .iter()
            .filter(|s| s.contains(r#""connected":true"#))
            .count();
        format!(
            r#"{{"node_id":{},"class":"{}","signals":[{}],"groups":[{}],"connected_count":{}}}"#,
            node_raw,
            class_name.replace('"', "\\\""),
            signals_json.join(","),
            groups_json.join(","),
            total_connected,
        )
    };
    send_json(stream, &json);
}

/// `POST /api/node/signals/connect` -- connect a signal on a node.
fn api_connect_signal(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let signal_name = match parsed.get("signal").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing signal");
            return;
        }
    };
    let _target_raw = parsed.get("target_id").and_then(|v| v.as_u64());
    let method = match parsed.get("method").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing method");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    // Store connection info as a property string (signal_connections), as an
    // undoable step (pat-0q2kx.12).
    //
    // Note this handler keeps connections in a node property rather than via
    // `SceneTree::connect_signal`, so the existing `ConnectSignal` command —
    // which drives the tree's own signal table — would undo the wrong thing.
    // `SetProperty` restores exactly the string this route writes. Letting
    // `execute` capture `old_value` is safe here (unlike the viewport drag):
    // nothing else has written the property during this request.
    let existing = match state
        .scene_tree
        .get_node(node_id)
        .map(|n| n.get_property("signal_connections"))
    {
        Some(Variant::String(s)) => s,
        _ => String::new(),
    };
    let new_entry = format!("{}:{}", signal_name, method);
    let updated = if existing.is_empty() {
        new_entry
    } else {
        format!("{},{}", existing, new_entry)
    };
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: "signal_connections".to_string(),
        new_value: Variant::String(updated),
        old_value: Variant::Nil,
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log(
        "info",
        format!("Connected signal '{}' to method '{}'", signal_name, method),
    );

    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// Groups endpoints
// ---------------------------------------------------------------------------

/// `POST /api/node/groups/add` -- add a group to a node.
fn api_add_group(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let group = match parsed.get("group").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing group");
            return;
        }
    };

    if group.is_empty() {
        send_error(stream, 400, "group name cannot be empty");
        return;
    }

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    // Operate on the node's real group membership so the Groups dock stays in
    // sync with the engine's group system (`get_nodes_in_group`, `.tscn` save,
    // and the scene-tree group badge) instead of a disconnected property string.
    let already = state
        .scene_tree
        .get_node(node_id)
        .is_some_and(|n| n.is_in_group(&group));
    if already {
        send_json(stream, r#"{"ok":true,"added":false}"#);
        return;
    }

    // Undoable step (pat-0q2kx.12): `AddToGroup` drives the same group system
    // this route does, so its undo (remove_from_group) is an exact inverse.
    let mut cmd = EditorCommand::AddToGroup {
        node_id,
        group: group.clone(),
    };
    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log("info", format!("Added group '{}'", group));

    send_json(stream, r#"{"ok":true,"added":true}"#);
}

/// `POST /api/node/groups/remove` -- remove a group from a node.
fn api_remove_group(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let group = match parsed.get("group").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing group");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    let node = state.scene_tree.get_node_mut(node_id).unwrap();
    // Remove from the node's real group membership (mirrors `api_add_group`).
    node.remove_from_group(&group);

    state.scene_modified = true;
    state.add_log("info", format!("Removed group '{}'", group));

    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// Multi-select, copy/paste, settings, box select, multi-drag
// ---------------------------------------------------------------------------

fn api_select_multi(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    if let Some(ids_arr) = parsed.get("node_ids").and_then(|v| v.as_array()) {
        let mut nids = Vec::new();
        for iv in ids_arr {
            if let Some(r) = iv.as_u64() {
                if let Some(n) = find_node_by_raw_id(&state.scene_tree, r) {
                    nids.push(n);
                }
            }
        }
        state.selected_nodes = nids.clone();
        state.selected_node = nids.first().copied();
        // pat-s3rrv.66 (h): multi-select ran the plugin handshake nowhere, so a
        // plugin's panel went stale the moment the user ctrl-clicked. Godot
        // dispatches on the FIRST selected object; an empty selection passes
        // None, which hides every plugin via `_make_visible(false)`.
        notify_plugins_of_selection(&mut state, nids.first().copied());
        let j: Vec<String> = nids.iter().map(|i| i.raw().to_string()).collect();
        send_json(
            stream,
            &format!(r#"{{"selected_nodes":[{}]}}"#, j.join(",")),
        );
        return;
    }
    let raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id or node_ids");
            return;
        }
    };
    let mode = parsed.get("mode").and_then(|v| v.as_str()).unwrap_or("set");
    let nid = match find_node_by_raw_id(&state.scene_tree, raw) {
        Some(i) => i,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    match mode {
        "add" => {
            if !state.selected_nodes.contains(&nid) {
                state.selected_nodes.push(nid);
            }
        }
        "remove" => {
            state.selected_nodes.retain(|&i| i != nid);
        }
        "toggle" => {
            if state.selected_nodes.contains(&nid) {
                state.selected_nodes.retain(|&i| i != nid);
            } else {
                state.selected_nodes.push(nid);
            }
        }
        "range" => {
            // Shift-select: select the contiguous span (in scene-tree order)
            // between the active anchor (current focused node) and the target,
            // inclusive. Falls back to a single selection if the anchor is gone.
            let order = state.scene_tree.all_nodes_in_tree_order();
            let anchor = state.selected_node.unwrap_or(nid);
            let ai = order.iter().position(|&n| n == anchor);
            let ti = order.iter().position(|&n| n == nid);
            match (ai, ti) {
                (Some(a), Some(t)) => {
                    let (lo, hi) = if a <= t { (a, t) } else { (t, a) };
                    state.selected_nodes = order[lo..=hi].to_vec();
                }
                _ => state.selected_nodes = vec![nid],
            }
        }
        _ => {
            state.selected_nodes = vec![nid];
        }
    }
    state.selected_node = state.selected_nodes.first().copied();
    // Same handshake for the add/remove/toggle/range modes — this is the path
    // ctrl-click and shift-click actually take.
    let first = state.selected_nodes.first().copied();
    notify_plugins_of_selection(&mut state, first);
    let j: Vec<String> = state
        .selected_nodes
        .iter()
        .map(|i| i.raw().to_string())
        .collect();
    send_json(
        stream,
        &format!(r#"{{"selected_nodes":[{}]}}"#, j.join(",")),
    );
}

fn api_get_selected_nodes(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let j = {
        let s = state.lock().unwrap();
        let ids: Vec<String> = s
            .selected_nodes
            .iter()
            .map(|i| i.raw().to_string())
            .collect();
        format!(
            r#"{{"selected_nodes":[{}],"count":{}}}"#,
            ids.join(","),
            s.selected_nodes.len()
        )
    };
    send_json(stream, &j);
}

fn node_to_clipboard(tree: &SceneTree, nid: NodeId) -> Option<ClipboardEntry> {
    let n = tree.get_node(nid)?;
    let props: Vec<(String, Variant)> = n
        .properties()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    let ch: Vec<ClipboardEntry> = n
        .children()
        .iter()
        .filter_map(|&c| node_to_clipboard(tree, c))
        .collect();
    Some(ClipboardEntry {
        name: n.name().to_string(),
        class_name: n.class_name().to_string(),
        properties: props,
        children: ch,
    })
}

/// Pastes one clipboard entry under `pid` and uniquifies the new top-level
/// node's name among its siblings, returning the created node.
///
/// Shared by `POST /api/node/paste` and [`EditorCommand::PasteNodes`]'s redo so
/// that redoing a paste reproduces the same names the original paste produced
/// (pat-0q2kx.12). Children keep their names, matching Godot.
pub(crate) fn paste_entry_with_unique_name(
    tree: &mut SceneTree,
    pid: NodeId,
    e: &ClipboardEntry,
) -> Result<NodeId, gdcore::error::EngineError> {
    let id = paste_clipboard_entry(tree, pid, e)?;
    let siblings: Vec<String> = tree
        .get_node(pid)
        .map(|p| {
            p.children()
                .iter()
                .filter(|&&c| c != id)
                .filter_map(|&c| tree.get_node(c).map(|n| n.name().to_string()))
                .collect()
        })
        .unwrap_or_default();
    let base = tree
        .get_node(id)
        .map(|n| n.name().to_string())
        .unwrap_or_default();
    let unique = unique_sibling_name(&base, &siblings);
    if let Some(n) = tree.get_node_mut(id) {
        n.set_name(unique);
    }
    Ok(id)
}

fn paste_clipboard_entry(
    tree: &mut SceneTree,
    pid: NodeId,
    e: &ClipboardEntry,
) -> Result<NodeId, gdcore::error::EngineError> {
    let mut node = Node::new(&e.name, &e.class_name);
    for (k, v) in &e.properties {
        node.set_property(k, v.clone());
    }
    let new_id = tree.add_child(pid, node)?;
    for c in &e.children {
        paste_clipboard_entry(tree, new_id, c)?;
    }
    Ok(new_id)
}

/// Pick a name not already used by `siblings`, appending/incrementing a numeric
/// suffix (e.g. `Foo` → `Foo2` → `Foo3`). Used to uniquify pasted nodes.
fn unique_sibling_name(base: &str, siblings: &[String]) -> String {
    if !siblings.iter().any(|s| s == base) {
        return base.to_string();
    }
    let stem = base.trim_end_matches(|c: char| c.is_ascii_digit());
    let stem = if stem.is_empty() { base } else { stem };
    let mut n = 2;
    loop {
        let candidate = format!("{stem}{n}");
        if !siblings.iter().any(|s| s == &candidate) {
            return candidate;
        }
        n += 1;
    }
}

fn api_copy_nodes(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = parse_json_body(body);
    let mut state = state.lock().unwrap();
    let raws: Vec<u64> = if let Some(a) = parsed
        .as_ref()
        .and_then(|p| p.get("node_ids"))
        .and_then(|v| v.as_array())
    {
        a.iter().filter_map(|v| v.as_u64()).collect()
    } else if let Some(i) = parsed
        .as_ref()
        .and_then(|p| p.get("node_id"))
        .and_then(|v| v.as_u64())
    {
        vec![i]
    } else {
        state.selected_nodes.iter().map(|i| i.raw()).collect()
    };
    let mut cb = Vec::new();
    for r in &raws {
        if let Some(n) = find_node_by_raw_id(&state.scene_tree, *r) {
            if let Some(e) = node_to_clipboard(&state.scene_tree, n) {
                cb.push(e);
            }
        }
    }
    let c = cb.len();
    state.clipboard = cb;
    state.add_log("info", format!("Copied {} node(s)", c));
    send_json(stream, &format!(r#"{{"ok":true,"copied":{c}}}"#));
}

fn api_paste_nodes(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = parse_json_body(body);
    let mut state = state.lock().unwrap();
    if state.clipboard.is_empty() {
        send_error(stream, 400, "clipboard is empty");
        return;
    }
    let pr = parsed
        .as_ref()
        .and_then(|p| p.get("parent_id"))
        .and_then(|v| v.as_u64());
    let pid = if let Some(r) = pr {
        match find_node_by_raw_id(&state.scene_tree, r) {
            Some(i) => i,
            None => {
                send_error(stream, 404, "parent not found");
                return;
            }
        }
    } else if let Some(s) = state.selected_node {
        s
    } else {
        state.scene_tree.root_id()
    };
    let cb = state.clipboard.clone();
    let mut ids = Vec::new();
    for e in &cb {
        match paste_entry_with_unique_name(&mut state.scene_tree, pid, e) {
            Ok(i) => {
                ids.push(i);
            }
            Err(e) => {
                send_error(stream, 500, &e.to_string());
                return;
            }
        }
    }
    // Undoable step (pat-0q2kx.12): paste created nodes with no way to take
    // them back. The nodes are already in the tree, so the command is pushed
    // pre-executed — its `undo` removes `created_ids`, and its `execute`
    // (redo) re-pastes from the captured entries.
    let cmd = EditorCommand::PasteNodes {
        parent_id: pid,
        entries: cb.clone(),
        created_ids: ids.clone(),
    };
    state.undo_stack.push(cmd);
    state.redo_stack.clear();

    state.scene_modified = true;
    let c = ids.len();
    state.selected_nodes = ids.clone();
    state.selected_node = ids.first().copied();
    state.add_log("info", format!("Pasted {} node(s)", c));
    let j: Vec<String> = ids.iter().map(|i| i.raw().to_string()).collect();
    send_json(
        stream,
        &format!(r#"{{"ok":true,"pasted":{c},"ids":[{}]}}"#, j.join(",")),
    );
}

fn api_cut_nodes(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = parse_json_body(body);
    let mut state = state.lock().unwrap();
    let raws: Vec<u64> = if let Some(a) = parsed
        .as_ref()
        .and_then(|p| p.get("node_ids"))
        .and_then(|v| v.as_array())
    {
        a.iter().filter_map(|v| v.as_u64()).collect()
    } else if let Some(i) = parsed
        .as_ref()
        .and_then(|p| p.get("node_id"))
        .and_then(|v| v.as_u64())
    {
        vec![i]
    } else {
        state.selected_nodes.iter().map(|i| i.raw()).collect()
    };
    let mut cb = Vec::new();
    let mut del = Vec::new();
    for r in &raws {
        if let Some(n) = find_node_by_raw_id(&state.scene_tree, *r) {
            if let Some(e) = node_to_clipboard(&state.scene_tree, n) {
                cb.push(e);
                del.push(n);
            }
        }
    }
    let c = cb.len();
    state.clipboard = cb;
    for d in del {
        let _ = state.scene_tree.remove_node(d);
    }
    state.selected_nodes.clear();
    state.selected_node = None;
    state.scene_modified = true;
    state.add_log("info", format!("Cut {} node(s)", c));
    send_json(stream, &format!(r#"{{"ok":true,"cut":{c}}}"#));
}

fn api_get_settings(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let j = {
        let s = state.lock().unwrap();
        serde_json::to_string(&s.display_settings).unwrap_or_else(|_| "{}".to_string())
    };
    send_json(stream, &j);
}

/// Where a project's editor layout is persisted (pat-s3rrv.228).
///
/// `<project_root>/.patina/editor/` is the established per-project editor state
/// dir — `create_dialog` already keeps favorites/recent there. Godot writes its
/// own `editor_layout.cfg` into the editor data dir, but a served editor is
/// per-project, so the arrangement belongs with the project.
fn editor_layout_path(state: &Arc<Mutex<EditorState>>) -> Option<std::path::PathBuf> {
    let root = {
        let s = state.lock().expect("editor state");
        s.project_root.clone()?
    };
    Some(
        std::path::PathBuf::from(root)
            .join(".patina")
            .join("editor")
            .join("editor_layout.json"),
    )
}

/// The shipped arrangement, restored by Editor > Reset to Default Layout.
///
/// Mirrors the DOM the editor ships with: Scene and FileSystem stacked in the
/// left column, the Inspector on the right.
fn default_editor_layout() -> serde_json::Value {
    serde_json::json!({
        "splits": { "left": 280, "right": 320, "bottom": 200 },
        "docks": {
            "left": ["scene-panel", "filesystem-panel"],
            "right": ["inspector-panel"]
        }
    })
}

/// `GET /api/editor/layout` — the saved arrangement, or the shipped default.
///
/// ⚠️ Reads from DISK rather than from `EditorState`, which is what makes the
/// arrangement survive a server restart. `display_settings.panel_sizes` already
/// round-tripped sizes through `/api/settings`, but it lives in memory only, so
/// it was lost the moment the process ended.
fn api_get_editor_layout(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let saved = editor_layout_path(state)
        .and_then(|p| std::fs::read_to_string(p).ok())
        .and_then(|t| serde_json::from_str::<serde_json::Value>(&t).ok());
    let body = serde_json::json!({
        "layout": saved.clone().unwrap_or_else(default_editor_layout),
        // Lets the client tell "never saved" from "saved, and happens to equal
        // the default" — Reset should be a no-op in the second case only.
        "saved": saved.is_some(),
    });
    send_json(stream, &body.to_string());
}

/// `POST /api/editor/layout` — saves the arrangement, or resets it.
///
/// Body is either `{"reset": true}` (delete the saved layout and answer with the
/// shipped default) or `{"layout": {...}}`.
fn api_set_editor_layout(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(p) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON body");
        return;
    };
    let Some(path) = editor_layout_path(state) else {
        send_error(stream, 400, "no project is open");
        return;
    };

    if p.get("reset").and_then(|v| v.as_bool()) == Some(true) {
        // A missing file is already "default", so only a real removal failure is
        // an error worth reporting.
        if path.exists() {
            if let Err(e) = std::fs::remove_file(&path) {
                send_error(stream, 500, &format!("could not reset layout: {e}"));
                return;
            }
        }
        let body = serde_json::json!({
            "ok": true,
            "layout": default_editor_layout(),
            "saved": false,
        });
        send_json(stream, &body.to_string());
        return;
    }

    let Some(layout) = p.get("layout") else {
        send_error(stream, 400, "layout is required");
        return;
    };
    if let Some(parent) = path.parent() {
        if let Err(e) = std::fs::create_dir_all(parent) {
            send_error(stream, 500, &format!("mkdir failed: {e}"));
            return;
        }
    }
    if let Err(e) = std::fs::write(&path, layout.to_string()) {
        send_error(stream, 500, &format!("could not save layout: {e}"));
        return;
    }
    let body = serde_json::json!({ "ok": true, "saved": true });
    send_json(stream, &body.to_string());
}

fn api_set_settings(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    if let Some(v) = p.get("grid_snap_enabled").and_then(|v| v.as_bool()) {
        s.display_settings.grid_snap_enabled = v;
    }
    if let Some(v) = p.get("grid_snap_size").and_then(|v| v.as_u64()) {
        s.display_settings.grid_snap_size = v as u32;
    }
    if let Some(v) = p.get("grid_visible").and_then(|v| v.as_bool()) {
        s.display_settings.grid_visible = v;
    }
    if let Some(v) = p.get("rulers_visible").and_then(|v| v.as_bool()) {
        s.display_settings.rulers_visible = v;
    }
    if let Some(a) = p.get("background_color").and_then(|v| v.as_array()) {
        if a.len() == 4 {
            s.display_settings.background_color = [
                a[0].as_f64().unwrap_or(0.08),
                a[1].as_f64().unwrap_or(0.08),
                a[2].as_f64().unwrap_or(0.1),
                a[3].as_f64().unwrap_or(1.0),
            ];
        }
    }
    if let Some(v) = p.get("font_size").and_then(|v| v.as_str()) {
        s.display_settings.font_size = v.to_string();
    }
    if let Some(v) = p.get("theme").and_then(|v| v.as_str()) {
        s.display_settings.theme = v.to_string();
    }
    if let Some(v) = p.get("physics_fps").and_then(|v| v.as_u64()) {
        s.display_settings.physics_fps = v as u32;
    }
    if let Some(obj) = p.get("panel_sizes").and_then(|v| v.as_object()) {
        for (k, v) in obj {
            if let Some(f) = v.as_f64() {
                s.display_settings.panel_sizes.insert(k.clone(), f);
            }
        }
    }
    if let Some(v) = p.get("smart_snap_enabled").and_then(|v| v.as_bool()) {
        s.display_settings.smart_snap_enabled = v;
    }
    if let Some(v) = p.get("smart_snap_threshold").and_then(|v| v.as_f64()) {
        s.display_settings.smart_snap_threshold = v as f32;
    }
    let j = serde_json::to_string(&s.display_settings).unwrap_or_else(|_| "{}".to_string());
    send_json(stream, &j);
}

fn api_box_select(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let x1 = p.get("x1").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y1 = p.get("y1").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let x2 = p.get("x2").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y2 = p.get("y2").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let add = p.get("add").and_then(|v| v.as_bool()).unwrap_or(false);
    let mut s = state.lock().unwrap();
    let (vw, vh, zm, pn) = (
        s.viewport_width,
        s.viewport_height,
        s.viewport_zoom,
        s.viewport_pan,
    );
    let p1 =
        crate::scene_renderer::pixel_to_scene_with_zoom_pan(&s.scene_tree, vw, vh, zm, pn, x1, y1);
    let p2 =
        crate::scene_renderer::pixel_to_scene_with_zoom_pan(&s.scene_tree, vw, vh, zm, pn, x2, y2);
    let (mnx, mny, mxx, mxy) = (
        p1.x.min(p2.x),
        p1.y.min(p2.y),
        p1.x.max(p2.x),
        p1.y.max(p2.y),
    );
    let mut sel: Vec<NodeId> = if add {
        s.selected_nodes.clone()
    } else {
        Vec::new()
    };
    for &nid in &s.scene_tree.all_nodes_in_tree_order() {
        if let Some(n) = s.scene_tree.get_node(nid) {
            if n.parent().is_none() {
                continue;
            }
            let pos = crate::scene_renderer::extract_position(n);
            if pos.x >= mnx && pos.x <= mxx && pos.y >= mny && pos.y <= mxy && !sel.contains(&nid) {
                sel.push(nid);
            }
        }
    }
    s.selected_nodes = sel.clone();
    s.selected_node = sel.first().copied();
    let j: Vec<String> = sel.iter().map(|i| i.raw().to_string()).collect();
    send_json(
        stream,
        &format!(
            r#"{{"selected_nodes":[{}],"count":{}}}"#,
            j.join(","),
            sel.len()
        ),
    );
}

fn api_viewport_drag_multi(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let dx = p.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dy = p.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let snap = p.get("snap").and_then(|v| v.as_bool()).unwrap_or(false);
    let mut s = state.lock().unwrap();
    let z = s.viewport_zoom as f32;
    let (mut wdx, mut wdy) = (dx / z, dy / z);
    if snap && s.display_settings.grid_snap_enabled {
        let g = s.display_settings.grid_snap_size as f32;
        wdx = (wdx / g).round() * g;
        wdy = (wdy / g).round() * g;
    }
    let sel = s.selected_nodes.clone();
    for &nid in &sel {
        if let Some(n) = s.scene_tree.get_node_mut(nid) {
            let pos = match n.get_property("position") {
                Variant::Vector2(v) => v,
                _ => Vector2::ZERO,
            };
            n.set_property(
                "position",
                Variant::Vector2(Vector2::new(pos.x + wdx, pos.y + wdy)),
            );
        }
    }
    send_json(stream, &format!(r#"{{"ok":true,"moved":{}}}"#, sel.len()));
}

// ---------------------------------------------------------------------------
// Animation endpoints
// ---------------------------------------------------------------------------

fn loop_mode_to_str(mode: LoopMode) -> &'static str {
    match mode {
        LoopMode::None => "none",
        LoopMode::Linear => "loop",
        LoopMode::PingPong => "pingpong",
    }
}

fn loop_mode_from_str(s: &str) -> LoopMode {
    match s {
        "loop" => LoopMode::Linear,
        "pingpong" => LoopMode::PingPong,
        _ => LoopMode::None,
    }
}

fn variant_to_simple_json(v: &Variant) -> String {
    to_json(v).to_string()
}

// ---------------------------------------------------------------------------
// Editor animations <-> the scene's AnimationPlayer (pat-0q2kx.54)
//
// `EditorState.animations` used to be a disconnected `HashMap`: the HTTP routes
// mutated it, nothing read it back into the scene, `scene_saver` never wrote it,
// and scene load never populated it. So an animation authored in the editor
// vanished on save/re-open, and pressing play moved nothing in the viewport.
// These three helpers are the binding.
// ---------------------------------------------------------------------------

/// The scene's AnimationPlayer node, if it has one.
///
/// Godot's animation panel edits the clips of the *selected* player; with one
/// player in the scene (the common case) that is unambiguous, so the first one
/// in tree order is used.
fn scene_animation_player(s: &EditorState) -> Option<NodeId> {
    s.scene_tree
        .all_nodes_in_tree_order()
        .into_iter()
        .find(|&id| s.scene_tree.get_animation_player(id).is_some())
}

/// Mirrors the clips of the scene's AnimationPlayer into `state.animations`.
///
/// Called after a scene loads, so opening a `.tscn` that carries animations
/// shows them in the panel instead of an empty list. The scene load path already
/// rebuilt the players themselves (`attach_scene_animation_players`).
fn sync_animations_from_scene(s: &mut EditorState) {
    let Some(player_node) = scene_animation_player(s) else {
        return;
    };
    let Some(player) = s.scene_tree.get_animation_player(player_node) else {
        return;
    };
    let clips: Vec<(String, Animation)> = player
        .animations
        .iter()
        .map(|(name, anim)| (name.clone(), anim.clone()))
        .collect();
    for (name, anim) in clips {
        s.animations.insert(name, anim);
    }
}

/// Writes an edited clip back onto the scene's AnimationPlayer so the change
/// reaches the scene tree — and therefore the saved `.tscn` — rather than living
/// only in editor state. Returns whether a player took it.
/// Records a keyframe for a property edit while **auto-key** is armed
/// (pat-s3rrv.62).
///
/// Godot's auto-key writes a key on every inspector edit while the toggle is
/// on, which is what makes "move the node, get a keyframe" work. Patina already
/// had the flag — `AnimationPlaybackState::recording`, settable by a route,
/// reported in `/api/animation/status` and read by the panel — but **nothing
/// consumed it**: `api_set_property` never looked at it, so arming auto-key
/// flipped a boolean and recorded nothing.
///
/// A missing animation, or none selected, is a no-op rather than an error:
/// editing a property with auto-key left on but no clip open is an ordinary
/// thing to do, not a failure.
///
/// ⚠️ Deliberately does NOT push its own undo entry. The property edit that
/// triggered it already pushed one, and a second would make a single user
/// action take two undos to reverse.
fn auto_key_property(state: &mut EditorState, node_id: NodeId, property: &str, value: &Variant) {
    if !state.animation_playback.recording {
        return;
    }
    let Some(anim_name) = state.animation_playback.animation_name.clone() else {
        return;
    };
    let time = state.animation_playback.current_time;
    // Tracks address nodes by PATH, not by id — and that path is RELATIVE to the
    // player's `root_node`, which is what both playback and the preview resolve
    // against. Writing the absolute path here stored a track that addressed
    // nothing and did not match how Godot writes tracks to `.tscn`.
    let base = animation_track_base(state);
    let Some(node_path) = relative_node_path(&state.scene_tree, base, node_id) else {
        state.add_log(
            "warn",
            "auto-key: the edited node is outside the AnimationPlayer's root, so no track path addresses it".to_string(),
        );
        return;
    };
    let Some(anim) = state.animations.get_mut(&anim_name) else {
        return;
    };
    let existing = anim.tracks.iter().position(|t| {
        t.node_path == node_path
            && t.property_path == property
            && t.track_type == TrackType::Property
    });
    let idx = match existing {
        Some(i) => i,
        None => {
            anim.tracks.push(AnimationTrack::with_type(
                &node_path,
                property,
                TrackType::Property,
            ));
            anim.tracks.len() - 1
        }
    };
    anim.tracks[idx].add_keyframe(KeyFrame::linear(time, value.clone()));
    // Push the edited clip onto the scene's AnimationPlayer so saving persists
    // it, exactly as an explicit keyframe add does.
    write_animation_through(state, &anim_name);
}

fn write_animation_through(s: &mut EditorState, name: &str) -> bool {
    let Some(anim) = s.animations.get(name).cloned() else {
        return false;
    };
    let Some(player_node) = scene_animation_player(s) else {
        // No AnimationPlayer in the scene: the clip stays editor-only. Saving
        // cannot persist it, so say so rather than silently dropping it later.
        s.add_log(
            "warn",
            format!("animation '{name}' has no AnimationPlayer in the scene to store it"),
        );
        return false;
    };
    if let Some(player) = s.scene_tree.get_animation_player_mut(player_node) {
        player.add_animation(anim);
        return true;
    }
    false
}

/// Samples the playing clip at `animation_playback.current_time` and writes the
/// values onto the live scene-tree nodes, which is what makes the editor
/// viewport preview the motion.
///
/// Track paths resolve against the AnimationPlayer's owner the same way the
/// runtime resolves them, so a track on `Sprite2D:position` moves that sprite.
/// The node that animation track paths are relative to: the AnimationPlayer's
/// `root_node`, which a `.tscn`-loaded player defaults to `".."` — Godot's
/// AnimationMixer default, the player's PARENT.
///
/// Both playback (`SceneTree::process_animations`) and the editor preview
/// resolve tracks against this node, so anything that WRITES a track has to
/// produce a path relative to the very same base or the track will not resolve.
/// Hardcoding the parent instead would disagree with playback for any scene
/// that sets `root_node` explicitly (pat-0q2kx.54).
fn animation_track_base(s: &EditorState) -> NodeId {
    match scene_animation_player(s) {
        Some(player_node) => {
            let root_node = s
                .scene_tree
                .get_animation_player(player_node)
                .map(|p| p.root_node.clone())
                .unwrap_or_default();
            if root_node.is_empty() || root_node == "." {
                player_node
            } else {
                s.scene_tree
                    .get_node_or_null(player_node, &root_node)
                    .unwrap_or(player_node)
            }
        }
        None => s.scene_tree.root_id(),
    }
}

/// Path of `node_id` relative to `base`, in the form animation tracks store.
///
/// Returns `None` when `base` is not an ancestor of `node_id`. There is no
/// valid relative form in that case, and inventing one would store a track that
/// silently resolves to nothing at playback.
fn relative_node_path(tree: &SceneTree, base: NodeId, node_id: NodeId) -> Option<String> {
    if node_id == base {
        return Some(String::new());
    }
    let mut parts: Vec<String> = Vec::new();
    let mut cursor = Some(node_id);
    while let Some(id) = cursor {
        if id == base {
            parts.reverse();
            return Some(parts.join("/"));
        }
        let node = tree.get_node(id)?;
        parts.push(node.name().to_string());
        cursor = node.parent();
    }
    None
}

fn apply_animation_preview(s: &mut EditorState) {
    let Some(name) = s.animation_playback.animation_name.clone() else {
        return;
    };
    let Some(anim) = s.animations.get(&name).cloned() else {
        return;
    };
    let time = s.animation_playback.current_time;
    let base = animation_track_base(s);

    for (idx, track) in anim.tracks.iter().enumerate() {
        // `sample_track` addresses tracks by index, not by reference.
        let Some(value) = anim.sample_track(idx, time) else {
            continue;
        };
        if track.property_path.is_empty() {
            continue;
        }
        let target = if track.node_path.is_empty() {
            Some(base)
        } else {
            s.scene_tree.get_node_or_null(base, &track.node_path)
        };
        if let Some(target) = target {
            if let Some(node) = s.scene_tree.get_node_mut(target) {
                node.set_property(&track.property_path, value);
            }
        }
    }
}

/// `GET /api/animations` -- list all animations (names + lengths).
fn api_get_animations(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        let entries: Vec<String> = state
            .animations
            .values()
            .map(|a| {
                format!(
                    r#"{{"name":"{}","length":{},"loop_mode":"{}","track_count":{}}}"#,
                    a.name.replace('"', "\\\""),
                    a.length,
                    loop_mode_to_str(a.loop_mode),
                    a.tracks.len()
                )
            })
            .collect();
        format!("[{}]", entries.join(","))
    };
    send_json(stream, &json);
}

/// `GET /api/animation?name=<name>` -- get full animation data.
fn api_get_animation(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let name = match query_param(query, "name") {
        Some(n) => url_decode(n),
        None => {
            send_error(stream, 400, "missing name parameter");
            return;
        }
    };
    let json = {
        let state = state.lock().unwrap();
        let anim = match state.animations.get(&name) {
            Some(a) => a,
            None => {
                send_error(stream, 404, "animation not found");
                return;
            }
        };
        let tracks_json: Vec<String> = anim
            .tracks
            .iter()
            .enumerate()
            .map(|(idx, track)| {
                let kf_json: Vec<String> = track
                    .keyframes()
                    .iter()
                    .map(|kf| {
                        let transition_json = match kf.transition {
                            gdscene::animation::TransitionType::Linear => r#""linear""#.to_string(),
                            gdscene::animation::TransitionType::Nearest => r#""nearest""#.to_string(),
                            gdscene::animation::TransitionType::CubicBezier(x1, y1, x2, y2) => {
                                format!(r#"{{"type":"cubic_bezier","x1":{},"y1":{},"x2":{},"y2":{}}}"#, x1, y1, x2, y2)
                            }
                        };
                        format!(
                            r#"{{"time":{},"value":{},"transition":{}}}"#,
                            kf.time,
                            variant_to_simple_json(&kf.value),
                            transition_json
                        )
                    })
                    .collect();
                format!(
                    r#"{{"index":{},"node_path":"{}","property":"{}","track_type":"{}","keyframes":[{}]}}"#,
                    idx,
                    track.node_path.replace('"', "\\\""),
                    track.property_path.replace('"', "\\\""),
                    track.track_type.as_str(),
                    kf_json.join(",")
                )
            })
            .collect();
        format!(
            r#"{{"name":"{}","length":{},"loop_mode":"{}","tracks":[{}]}}"#,
            anim.name.replace('"', "\\\""),
            anim.length,
            loop_mode_to_str(anim.loop_mode),
            tracks_json.join(",")
        )
    };
    send_json(stream, &json);
}

/// `POST /api/animation/create` -- create a new animation.
fn api_create_animation(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match parsed.get("name").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let length = parsed.get("length").and_then(|v| v.as_f64()).unwrap_or(1.0);
    let loop_mode = parsed
        .get("loop_mode")
        .and_then(|v| v.as_str())
        .map(loop_mode_from_str)
        .unwrap_or(LoopMode::None);
    if name.is_empty() {
        send_error(stream, 400, "animation name cannot be empty");
        return;
    }
    let mut state = state.lock().unwrap();
    if state.animations.contains_key(&name) {
        send_error(stream, 400, "animation already exists");
        return;
    }
    let mut anim = Animation::new(name.clone(), length.max(0.1));
    anim.loop_mode = loop_mode;
    state.animations.insert(name.clone(), anim);
    state.add_log("info", format!("Created animation '{}'", name));
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/delete` -- delete an animation.
fn api_delete_animation(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match parsed.get("name").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    if state.animations.remove(&name).is_none() {
        send_error(stream, 404, "animation not found");
        return;
    }
    if state.animation_playback.animation_name.as_deref() == Some(&name) {
        state.animation_playback.playing = false;
        state.animation_playback.animation_name = None;
        state.animation_playback.current_time = 0.0;
    }
    state.add_log("info", format!("Deleted animation '{}'", name));
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/keyframe/add` -- add a keyframe to a track.
fn api_add_keyframe(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let anim_name = match parsed.get("animation").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing animation");
            return;
        }
    };
    let node_path = match parsed.get("track_node").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing track_node");
            return;
        }
    };
    let property = match parsed.get("track_property").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing track_property");
            return;
        }
    };
    let time = match parsed.get("time").and_then(|v| v.as_f64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing time");
            return;
        }
    };
    let value_json = match parsed.get("value") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing value");
            return;
        }
    };
    let value = match from_json(value_json) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid variant value");
            return;
        }
    };
    let track_type = parsed
        .get("track_type")
        .and_then(|v| v.as_str())
        .and_then(TrackType::from_str_name)
        .unwrap_or(TrackType::Property);
    let mut state = state.lock().unwrap();
    // Snapshot before mutating so the edit can be undone (pat-0q2kx.12).
    let before = state.animations.get(&anim_name).cloned();
    let anim = match state.animations.get_mut(&anim_name) {
        Some(a) => a,
        None => {
            send_error(stream, 404, "animation not found");
            return;
        }
    };
    let track_idx = anim.tracks.iter().position(|t| {
        t.node_path == node_path && t.property_path == property && t.track_type == track_type
    });
    let track_idx = match track_idx {
        Some(idx) => idx,
        None => {
            let track = AnimationTrack::with_type(&node_path, &property, track_type);
            anim.tracks.push(track);
            anim.tracks.len() - 1
        }
    };
    anim.tracks[track_idx].add_keyframe(KeyFrame::linear(time, value));

    // Adding a keyframe (and any track it implicitly created) is one undo step.
    let after = anim.clone();
    state.undo_stack.push(EditorCommand::AnimationEdit {
        animation: anim_name.clone(),
        before: before.map(Box::new),
        after: Box::new(after),
        label: format!("Add keyframe to '{anim_name}'"),
    });
    state.redo_stack.clear();
    state.scene_modified = true;
    // Push the edited clip onto the scene's AnimationPlayer so saving the scene
    // persists it (pat-0q2kx.54).
    write_animation_through(&mut state, &anim_name);

    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"track_index":{},"track_type":"{}"}}"#,
            track_idx,
            track_type.as_str()
        ),
    );
}

/// `POST /api/animation/track/add` -- add an explicit typed track to an animation.
fn api_add_track(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let anim_name = match parsed.get("animation").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing animation");
            return;
        }
    };
    let node_path = match parsed.get("node_path").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing node_path");
            return;
        }
    };
    let property = match parsed.get("property").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing property");
            return;
        }
    };
    let track_type = match parsed.get("track_type").and_then(|v| v.as_str()) {
        Some(s) => match TrackType::from_str_name(s) {
            Some(tt) => tt,
            None => {
                send_error(
                    stream,
                    400,
                    "invalid track_type (use property, method, or audio)",
                );
                return;
            }
        },
        None => TrackType::Property,
    };
    let mut state = state.lock().unwrap();
    let anim = match state.animations.get_mut(&anim_name) {
        Some(a) => a,
        None => {
            send_error(stream, 404, "animation not found");
            return;
        }
    };
    // Check for duplicate track
    let exists = anim.tracks.iter().any(|t| {
        t.node_path == node_path && t.property_path == property && t.track_type == track_type
    });
    if exists {
        send_error(stream, 400, "track already exists");
        return;
    }
    let track = AnimationTrack::with_type(&node_path, &property, track_type);
    anim.tracks.push(track);
    let idx = anim.tracks.len() - 1;
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"track_index":{},"track_type":"{}"}}"#,
            idx,
            track_type.as_str()
        ),
    );
}

/// `POST /api/animation/track/delete` -- remove a track from an animation.
fn api_delete_track(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let anim_name = match parsed.get("animation").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing animation");
            return;
        }
    };
    let track_index = match parsed.get("track_index").and_then(|v| v.as_u64()) {
        Some(v) => v as usize,
        None => {
            send_error(stream, 400, "missing track_index");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let anim = match state.animations.get_mut(&anim_name) {
        Some(a) => a,
        None => {
            send_error(stream, 404, "animation not found");
            return;
        }
    };
    if track_index >= anim.tracks.len() {
        send_error(stream, 400, "track_index out of range");
        return;
    }
    anim.tracks.remove(track_index);
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/keyframe/remove` -- remove a keyframe from a track.
fn api_remove_keyframe(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let anim_name = match parsed.get("animation").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing animation");
            return;
        }
    };
    let track_index = match parsed.get("track_index").and_then(|v| v.as_u64()) {
        Some(v) => v as usize,
        None => {
            send_error(stream, 400, "missing track_index");
            return;
        }
    };
    let keyframe_index = match parsed.get("keyframe_index").and_then(|v| v.as_u64()) {
        Some(v) => v as usize,
        None => {
            send_error(stream, 400, "missing keyframe_index");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let anim = match state.animations.get_mut(&anim_name) {
        Some(a) => a,
        None => {
            send_error(stream, 404, "animation not found");
            return;
        }
    };
    if track_index >= anim.tracks.len() {
        send_error(stream, 400, "track_index out of range");
        return;
    }
    if !anim.tracks[track_index].remove_keyframe(keyframe_index) {
        send_error(stream, 400, "keyframe_index out of range");
        return;
    }
    if anim.tracks[track_index].keyframe_count() == 0 {
        anim.tracks.remove(track_index);
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/play` -- start playing an animation.
fn api_play_animation(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match parsed.get("name").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    if !state.animations.contains_key(&name) {
        send_error(stream, 404, "animation not found");
        return;
    }
    state.animation_playback.playing = true;
    state.animation_playback.animation_name = Some(name.clone());
    state.animation_playback.current_time = 0.0;
    // Sample the clip onto the live scene nodes so the viewport previews the
    // motion; this used to set flags and touch nothing (pat-0q2kx.54).
    apply_animation_preview(&mut state);
    state.add_log("info", format!("Playing animation '{}'", name));
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/stop` -- stop animation playback.
fn api_stop_animation(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    state.animation_playback.playing = false;
    send_json(stream, r#"{"ok":true}"#);
}

/// `GET /api/animation/status` -- returns current playback state.
fn api_animation_status(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        let pb = &state.animation_playback;
        let name_json = match &pb.animation_name {
            Some(n) => format!(r#""{}""#, n.replace('"', "\\\"")),
            None => "null".to_string(),
        };
        let blend_json = match &pb.blend_secondary {
            Some(n) => format!(r#""{}""#, n.replace('"', "\\\"")),
            None => "null".to_string(),
        };
        format!(
            r#"{{"playing":{},"current_time":{},"animation_name":{},"recording":{},"blend_secondary":{},"blend_weight":{}}}"#,
            pb.playing, pb.current_time, name_json, pb.recording, blend_json, pb.blend_weight
        )
    };
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// AnimationTree state-machine editor (pat-nzgdu.103)
// ---------------------------------------------------------------------------

/// Escapes a string for embedding in a JSON string literal.
fn json_escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace('"', "\\\"")
}

/// Maps a node kind to the string the served graph uses.
fn anim_tree_kind_str(kind: crate::anim_tree_graph::NodeKind) -> &'static str {
    use crate::anim_tree_graph::NodeKind;
    match kind {
        NodeKind::StateMachine => "state_machine",
        NodeKind::BlendSpace1D => "blend_space_1d",
        NodeKind::BlendSpace2D => "blend_space_2d",
        NodeKind::Blend2 => "blend2",
        NodeKind::Animation => "animation",
    }
}

/// Parses the `kind` field of a tree request, defaulting to an animation leaf
/// (the kind a plain state-machine state holds).
fn anim_tree_kind_from_str(s: &str) -> crate::anim_tree_graph::NodeKind {
    use crate::anim_tree_graph::NodeKind;
    match s {
        "state_machine" => NodeKind::StateMachine,
        "blend_space_2d" => NodeKind::BlendSpace2D,
        // `blend_space` is the pre-split spelling; it maps to 1D, the simpler
        // of the two, so an older client keeps working.
        "blend_space_1d" | "blend_space" => NodeKind::BlendSpace1D,
        "blend2" => NodeKind::Blend2,
        _ => NodeKind::Animation,
    }
}

/// `GET /api/animation/tree` -- the AnimationTree graph: states, transitions,
/// blend-tree connections, and the live playback state (Godot highlights the
/// currently playing state in its state-machine editor).
/// `POST /api/animation/tree/apply` — build the authored graph into a runtime
/// state machine and attach it to an `AnimationTree` node (pat-s3rrv.1).
///
/// # Why this route exists
///
/// `AnimTreeGraph` was pure editor state: 16 call sites mutated it, one GET read
/// it back, and nothing ever turned it into something the runtime could play.
/// Every state, transition and blend point authored in the served editor
/// evaporated while each route returned 200. `to_state_machine()` closed half of
/// that; this is the half that makes it reach a frame, because
/// `SceneTree::process_animation_trees` drives whatever is attached here.
///
/// Body: `{"node":"AnimationTree"}` — the node to attach to. Omitted, it uses
/// the selected node.
///
/// ⚠️ The target must actually be an `AnimationTree`. Attaching to anything else
/// would store a graph that `process_animation_trees` never looks at, which is
/// the same silent no-op this route exists to remove.
/// Resolves the `AnimationTree` node an animation-tree route targets, by the
/// request's `node` name or the current selection, and answers the request
/// itself when it cannot (pat-s3rrv.1).
///
/// ⚠️ The class check is not a formality: attaching to — or reading from —
/// anything else silently does nothing, since `process_animation_trees` only
/// looks at `AnimationTree` nodes. Returning `None` means a response has
/// already been written and the caller must return.
fn anim_tree_target(s: &EditorState, body: &str, stream: &mut TcpStream) -> Option<NodeId> {
    let requested = parse_json_body(body)
        .and_then(|p| p.get("node").and_then(|v| v.as_str()).map(str::to_string));

    let node_id = match requested {
        Some(name) => {
            let root = s.scene_tree.root_id();
            match s.scene_tree.find_child(root, &name, true) {
                Some(id) => id,
                None => {
                    send_error(stream, 404, &format!("no node named {name}"));
                    return None;
                }
            }
        }
        None => match s.selected_node {
            Some(id) => id,
            None => {
                send_error(stream, 400, "no node selected and no `node` given");
                return None;
            }
        },
    };

    let class = s
        .scene_tree
        .get_node(node_id)
        .map(|n| n.class_name().to_string())
        .unwrap_or_default();
    if class != "AnimationTree" {
        send_error(
            stream,
            400,
            &format!("target is a {class}, not an AnimationTree"),
        );
        return None;
    }
    Some(node_id)
}

/// `POST /api/animation/tree/load` — replaces the editor graph with the state
/// machine a scene's `AnimationTree` already holds (pat-s3rrv.1).
///
/// # Why this exists
///
/// The graph could only ever be authored, never loaded. Opening a project whose
/// scene already had an `AnimationTree` showed an empty canvas, and once
/// `/apply` landed, saving that canvas replaced a real machine with nothing.
/// This route is what lets the editor show what is actually in the scene.
fn api_anim_tree_load(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    let Some(node_id) = anim_tree_target(&s, body, stream) else {
        return;
    };

    let machine = match s
        .scene_tree
        .get_animation_tree(node_id)
        .and_then(|t| t.root.as_ref())
    {
        Some(gdscene::animation_tree::AnimationNode::StateMachine(m)) => m.clone(),
        // A blend tree is a real graph the editor has no surface for. Loading
        // nothing and reporting 200 would leave the user one `apply` away from
        // overwriting it — the exact failure this route exists to prevent.
        Some(_) => {
            send_error(
                stream,
                400,
                "that AnimationTree's root is not a state machine",
            );
            return;
        }
        None => {
            send_error(stream, 404, "that node has no AnimationTree to load");
            return;
        }
    };

    let graph = crate::anim_tree_graph::AnimTreeGraph::from_state_machine(&machine);
    let states = graph.node_count();
    let transitions = graph.transitions().len();
    s.anim_tree = graph;
    // An empty `current` means the machine never started; leaving the highlight
    // unset is truer than pointing it at a state named "".
    s.anim_tree_current_state = (!machine.current.is_empty()).then(|| machine.current.clone());
    s.add_log(
        "info",
        format!("loaded animation graph from AnimationTree ({states} states)"),
    );
    send_json(
        stream,
        &format!(r#"{{"ok":true,"states":{states},"transitions":{transitions}}}"#),
    );
}

fn api_anim_tree_apply(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    let Some(node_id) = anim_tree_target(&s, body, stream) else {
        return;
    };

    let machine = s.anim_tree.to_state_machine();
    let states = machine.states.len();
    let transitions = machine.transitions.len();
    let mut anim_tree = gdscene::animation_tree::AnimationTree::new();
    anim_tree.set_root(gdscene::animation_tree::AnimationNode::StateMachine(
        machine,
    ));

    if let Err(e) = s.scene_tree.attach_animation_tree(node_id, anim_tree) {
        send_error(stream, 500, &format!("{e:?}"));
        return;
    }
    s.add_log(
        "info",
        format!("applied animation graph to AnimationTree ({states} states)"),
    );
    send_json(
        stream,
        &format!(r#"{{"ok":true,"states":{states},"transitions":{transitions}}}"#),
    );
}

fn api_get_anim_tree(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        let g = &state.anim_tree;
        let states: Vec<String> = g
            .nodes()
            .iter()
            .map(|n| {
                // `x`/`y` are the graph-canvas position the client persists via
                // `state/move` (pat-0q2kx.166); without them the canvas would
                // re-lay-out from scratch on every poll.
                // pat-s3rrv.1: `params` carries a blend space's points and
                // ranges. `AnimTreeGraph` has stored them since pat-0q2kx.166
                // and the graph endpoint never emitted them, so the client had
                // no way to see — let alone edit — anything but a node's name
                // and position. `BTreeMap` order makes this deterministic.
                let params: Vec<String> = n
                    .params
                    .iter()
                    .map(|(k, v)| format!(r#""{}":"{}""#, json_escape(k), json_escape(v)))
                    .collect();
                format!(
                    r#"{{"id":{},"name":"{}","kind":"{}","x":{},"y":{},"params":{{{}}}}}"#,
                    n.id,
                    json_escape(&n.name),
                    anim_tree_kind_str(n.kind),
                    n.x,
                    n.y,
                    params.join(",")
                )
            })
            .collect();
        // Transitions carry `xfade` (Godot's `xfade_time`); connections below do
        // not, because a blend-tree connection has no crossfade (pat-0q2kx.166).
        let transitions: Vec<String> = g
            .transitions()
            .iter()
            .map(|l| format!(r#"{{"from":{},"to":{},"xfade":{}}}"#, l.from, l.to, l.xfade))
            .collect();
        let connections: Vec<String> = g
            .connections()
            .iter()
            .map(|l| format!(r#"{{"from":{},"to":{}}}"#, l.from, l.to))
            .collect();
        let current = match &state.anim_tree_current_state {
            Some(n) => format!(r#""{}""#, json_escape(n)),
            None => "null".to_string(),
        };
        format!(
            r#"{{"states":[{}],"transitions":[{}],"connections":[{}],"current_state":{}}}"#,
            states.join(","),
            transitions.join(","),
            connections.join(","),
            current
        )
    };
    send_json(stream, &json);
}

/// Reads a required non-empty string field from a parsed JSON body.
fn anim_tree_name_field(parsed: &serde_json::Value, key: &str) -> Option<String> {
    parsed
        .get(key)
        .and_then(|v| v.as_str())
        .map(str::to_string)
        .filter(|s| !s.is_empty())
}

/// `POST /api/animation/tree/state/add` -- add a state to the state machine.
/// Body: `{"name":"Idle","kind":"animation"}` (kind optional).
fn api_anim_tree_add_state(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match anim_tree_name_field(&parsed, "name") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let kind = anim_tree_kind_from_str(parsed.get("kind").and_then(|v| v.as_str()).unwrap_or(""));

    let mut state = state.lock().unwrap();
    // Godot's state names are unique within a state machine.
    if state.anim_tree.node_id_by_name(&name).is_some() {
        send_error(stream, 400, "state already exists");
        return;
    }
    let id = state.anim_tree.add_node(name.clone(), kind);
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"id":{},"name":"{}"}}"#,
            id,
            json_escape(&name)
        ),
    );
}

/// `POST /api/animation/tree/state/remove` -- remove a state and any
/// transitions touching it. Body: `{"name":"Idle"}`.
/// `POST /api/animation/tree/state/move` -- persist a state's graph-canvas
/// position (pat-0q2kx.166). Body: `{"name":"Idle","x":120,"y":40}`.
///
/// The canvas needs positions to survive a reload, so dragging a node posts here
/// and `GET /api/animation/tree` returns `x`/`y` on each state.
fn api_anim_tree_move_state(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match anim_tree_name_field(&parsed, "name") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    // Both coordinates are required: a move with one axis missing is a
    // malformed request, not "leave that axis alone" — silently half-moving a
    // node would be worse than refusing.
    let (x, y) = match (
        parsed.get("x").and_then(|v| v.as_f64()),
        parsed.get("y").and_then(|v| v.as_f64()),
    ) {
        (Some(x), Some(y)) => (x, y),
        _ => {
            send_error(stream, 400, "x and y required");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let id = match state.anim_tree.node_id_by_name(&name) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "unknown state");
            return;
        }
    };
    if !state.anim_tree.move_node(id, x, y) {
        send_error(stream, 404, "unknown state");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

fn api_anim_tree_remove_state(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match anim_tree_name_field(&parsed, "name") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let id = match state.anim_tree.node_id_by_name(&name) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "unknown state");
            return;
        }
    };
    state.anim_tree.remove_node(id);
    send_json(stream, r#"{"ok":true}"#);
}

/// Resolves the `from`/`to` state names of a transition request.
fn anim_tree_endpoints(
    parsed: &serde_json::Value,
    state: &EditorState,
    stream: &mut TcpStream,
) -> Option<(u64, u64)> {
    let from_name = match anim_tree_name_field(parsed, "from") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing from");
            return None;
        }
    };
    let to_name = match anim_tree_name_field(parsed, "to") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing to");
            return None;
        }
    };
    let from = match state.anim_tree.node_id_by_name(&from_name) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "unknown from state");
            return None;
        }
    };
    let to = match state.anim_tree.node_id_by_name(&to_name) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "unknown to state");
            return None;
        }
    };
    Some((from, to))
}

/// `POST /api/animation/tree/transition/add` -- connect two states.
/// Body: `{"from":"Idle","to":"Run"}`.
fn api_anim_tree_add_transition(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let (from, to) = match anim_tree_endpoints(&parsed, &state, stream) {
        Some(pair) => pair,
        None => return,
    };
    // Optional crossfade in seconds — Godot's `xfade_time`, defaulting to its
    // `0.0` (pat-0q2kx.166). Absent means "no crossfade", not "invalid body", so
    // the pre-existing two-field callers keep working unchanged.
    let xfade = parsed.get("xfade").and_then(|v| v.as_f64()).unwrap_or(0.0);
    // Rejects self-transitions and duplicates (see AnimTreeGraph::add_link).
    if !state.anim_tree.add_transition_with_xfade(from, to, xfade) {
        send_error(stream, 400, "invalid or duplicate transition");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/tree/transition/remove` -- drop a transition.
/// Body: `{"from":"Idle","to":"Run"}`.
fn api_anim_tree_remove_transition(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let (from, to) = match anim_tree_endpoints(&parsed, &state, stream) {
        Some(pair) => pair,
        None => return,
    };
    if !state.anim_tree.remove_transition(from, to) {
        send_error(stream, 404, "unknown transition");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/tree/connect` -- link two blend-tree nodes
/// (pat-s3rrv.1). Body: `{"from":"Blend2","to":"Output"}`.
///
/// A connection is NOT a transition: a state machine's edges carry a crossfade
/// and fire on a condition, while a blend-tree edge is a permanent wire feeding
/// one node's output into another. `AnimTreeGraph` has always kept the two in
/// separate lists and `GET /api/animation/tree` has always served both; only
/// the transition list had endpoints, so a blend tree could not be drawn.
fn api_anim_tree_connect(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let (from, to) = match anim_tree_endpoints(&parsed, &state, stream) {
        Some(pair) => pair,
        None => return,
    };
    // Rejects self-links and duplicates, the same way `add_transition` does.
    if !state.anim_tree.connect(from, to) {
        send_error(stream, 400, "invalid or duplicate connection");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/tree/disconnect` -- drop a blend-tree link
/// (pat-s3rrv.1). Body: `{"from":"Blend2","to":"Output"}`.
fn api_anim_tree_disconnect(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let (from, to) = match anim_tree_endpoints(&parsed, &state, stream) {
        Some(pair) => pair,
        None => return,
    };
    if !state.anim_tree.disconnect(from, to) {
        send_error(stream, 404, "unknown connection");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/tree/node/param` -- set one parameter on a graph node
/// (pat-s3rrv.1). Body: `{"name":"Space","key":"blend_point_0/pos","value":"0.5"}`.
///
/// This is what makes a blend space editable. Godot's `AnimationNodeBlendSpace1D`
/// / `BlendSpace2D` keep their points as indexed resource properties —
/// `blend_point_N/node` and `blend_point_N/pos` — alongside `min_space`,
/// `max_space`, `snap` and `blend_position`, and this endpoint uses those exact
/// key names so the served graph and the Godot resource describe a blend space
/// the same way.
///
/// Values are strings: `AnimTreeGraph::params` is a `BTreeMap<String, String>`
/// and a blend space's `pos` is a scalar in 1D but a pair in 2D, so a typed
/// numeric field here would have to be one or the other.
fn api_anim_tree_set_node_param(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match anim_tree_name_field(&parsed, "name") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing name");
            return;
        }
    };
    let key = match anim_tree_name_field(&parsed, "key") {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing key");
            return;
        }
    };
    // An empty value is legitimate (clearing a point's animation), so this reads
    // the raw field rather than the non-empty helper above.
    let value = match parsed.get("value").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing value");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let id = match state.anim_tree.node_id_by_name(&name) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "unknown node");
            return;
        }
    };
    if !state.anim_tree.set_param(id, key, value) {
        send_error(stream, 404, "unknown node");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/tree/transition/set` -- edit an existing transition's
/// crossfade (pat-0q2kx.166). Body: `{"from":"Idle","to":"Run","xfade":0.3}`.
///
/// Editing is separate from `add` on purpose: `add` refuses duplicates, so the
/// UI needs a way to change a transition it already created without deleting and
/// re-adding it (which would lose any other per-transition state).
///
/// A missing transition is a 404 rather than an implicit create — otherwise a
/// typo'd endpoint pair would silently add a transition the user never drew.
fn api_anim_tree_set_transition(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let (from, to) = match anim_tree_endpoints(&parsed, &state, stream) {
        Some(pair) => pair,
        None => return,
    };
    // `xfade` is required here: unlike `add`, an edit with no value to set is a
    // malformed request rather than "use the default".
    let xfade = match parsed.get("xfade").and_then(|v| v.as_f64()) {
        Some(x) if x >= 0.0 => x,
        Some(_) => {
            send_error(stream, 400, "xfade must be >= 0");
            return;
        }
        None => {
            send_error(stream, 400, "xfade required");
            return;
        }
    };
    if !state.anim_tree.set_transition_xfade(from, to, xfade) {
        send_error(stream, 404, "unknown transition");
        return;
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/seek` -- set the current playback time (for scrubbing).
fn api_seek_animation(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let time = match parsed.get("time").and_then(|v| v.as_f64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing time");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    state.animation_playback.current_time = time.max(0.0);
    // Scrubbing the timeline re-poses the scene (pat-0q2kx.54).
    apply_animation_preview(&mut state);
    // Apply interpolated values to scene tree nodes when scrubbing.
    if let Some(anim_name) = state.animation_playback.animation_name.clone() {
        if let Some(anim) = state.animations.get(&anim_name) {
            let values: Vec<(String, String, Variant)> = anim
                .tracks
                .iter()
                .filter_map(|track| {
                    track
                        .sample(time)
                        .map(|v| (track.node_path.clone(), track.property_path.clone(), v))
                })
                .collect();
            for (node_path, property, value) in values {
                let node_id = find_node_by_name(&state.scene_tree, &node_path);
                if let Some(nid) = node_id {
                    if let Some(node) = state.scene_tree.get_node_mut(nid) {
                        node.set_property(&property, value);
                    }
                }
            }
        }
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/record` -- toggle keyframe recording mode.
fn api_toggle_recording(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let enabled = parsed
        .get("enabled")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let mut state = state.lock().unwrap();
    state.animation_playback.recording = enabled;
    state.add_log(
        "info",
        if enabled {
            "Recording mode ON"
        } else {
            "Recording mode OFF"
        },
    );
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/animation/blend` -- set blend preview between two animations.
///
/// Body: `{"secondary": "anim_name", "weight": 0.5}` or `{"secondary": null}` to clear.
fn api_animation_blend(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut state = state.lock().unwrap();
    let secondary = parsed
        .get("secondary")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());
    let weight = parsed.get("weight").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;

    // Validate the secondary animation exists (if provided).
    if let Some(ref name) = secondary {
        if !state.animations.contains_key(name) {
            send_error(stream, 404, "secondary animation not found");
            return;
        }
    }

    state.animation_playback.blend_secondary = secondary.clone();
    state.animation_playback.blend_weight = weight.clamp(0.0, 1.0);

    // Apply blended values to scene tree for preview.
    let primary_name = state.animation_playback.animation_name.clone();
    let time = state.animation_playback.current_time;
    let blend_w = state.animation_playback.blend_weight;

    if let (Some(ref prim), Some(ref sec)) = (&primary_name, &secondary) {
        if let (Some(prim_anim), Some(sec_anim)) = (
            state.animations.get(prim).cloned(),
            state.animations.get(sec).cloned(),
        ) {
            let prim_values = prim_anim.sample_all(time);
            let sec_values = sec_anim.sample_all(time);

            // Build map from secondary animation.
            let sec_map: std::collections::HashMap<String, gdvariant::Variant> =
                sec_values.into_iter().collect();

            for (prop, prim_val) in &prim_values {
                if let Some(sec_val) = sec_map.get(prop) {
                    let blended =
                        gdscene::animation::interpolate_variant(prim_val, sec_val, blend_w)
                            .unwrap_or_else(|| prim_val.clone());
                    // Find the track's node path from the primary animation.
                    if let Some(track) = prim_anim.tracks.iter().find(|t| t.property_path == *prop)
                    {
                        let node_id = find_node_by_name(&state.scene_tree, &track.node_path);
                        if let Some(nid) = node_id {
                            if let Some(node) = state.scene_tree.get_node_mut(nid) {
                                node.set_property(prop, blended);
                            }
                        }
                    }
                }
            }
        }
    }

    let action = if secondary.is_some() {
        format!("Blend preview: weight={:.0}%", weight * 100.0)
    } else {
        "Blend preview cleared".to_string()
    };
    state.add_log("info", action);
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"blend_weight":{}}}"#,
            state.animation_playback.blend_weight
        ),
    );
}

/// Find a node by name anywhere in the scene tree (simple linear search).
fn find_node_by_name(tree: &SceneTree, name: &str) -> Option<NodeId> {
    let mut stack = vec![tree.root_id()];
    while let Some(nid) = stack.pop() {
        if let Some(node) = tree.get_node(nid) {
            if node.name() == name {
                return Some(nid);
            }
            for &child in node.children() {
                stack.push(child);
            }
        }
    }
    None
}

// ---------------------------------------------------------------------------
// Runtime API endpoints
// ---------------------------------------------------------------------------

/// pat-niu1j.2: Returns true for routes that mutate the *edited* scene — tree
/// structure, inspector property values, or node transforms via the viewport.
/// While the runtime is playing the editor is edit-locked and these routes are
/// rejected with 409. Selection (`/api/node/select`, `select_multi`,
/// `box_select`, `viewport/click`), navigation (`viewport/pan*`,
/// `viewport/zoom`, `frame_selection`, inspector history), read-only GETs, and
/// every `/api/runtime/*` control route are intentionally NOT locked so the
/// user can still inspect and navigate the scene while it runs.
fn route_is_edit_locked(method: &str, path: &str) -> bool {
    if method != "POST" {
        return false;
    }
    matches!(
        path,
        // Tree structure
        "/api/node/add"
            | "/api/node/delete"
            | "/api/node/reparent"
            | "/api/node/change_type"
            | "/api/node/make_local"
            | "/api/node/rename"
            | "/api/node/duplicate"
            | "/api/node/reorder"
            | "/api/node/group"
            | "/api/node/unique_name"
            | "/api/node/create_dialog/confirm"
            | "/api/node/paste"
            | "/api/node/cut"
            | "/api/node/groups/add"
            | "/api/node/groups/remove"
            | "/api/node/editable_children"
            | "/api/node/lock"
            | "/api/scene/instance"
            | "/api/scene/load"
            // Inspector
            | "/api/property/set"
            | "/api/resource/property/set"
            // Viewport transforms
            | "/api/viewport/drag_start"
            | "/api/viewport/drag"
            | "/api/viewport/drag_end"
            | "/api/viewport/drag_axis"
            | "/api/viewport/rotate_node"
            | "/api/viewport/scale_node"
            | "/api/viewport/shape_resize"
            | "/api/viewport/drop"
            | "/api/viewport/drag_multi"
            | "/api/viewport/3d/snap_to_floor"
            | "/api/viewport/3d/translate_selection"
            | "/api/viewport/3d/lock"
            | "/api/viewport/3d/group"
            // Edit history
            | "/api/undo"
            | "/api/redo"
            | "/api/history/goto"
    )
}

/// Instantiates the project's `[autoload]` singletons into `tree` under
/// `/root` for a Play session, attaching their scripts. Returns the node ids
/// of the instantiated autoload roots (in declaration order).
///
/// Mirrors Godot's boot: autoload nodes exist and their scripts are attached
/// before any `_ready` runs, so scene scripts can reference `/root/<Autoload>`.
/// The caller drives `_ready` (see [`api_runtime_play`]). pat-nzgdu.3.
fn instantiate_play_autoloads(tree: &mut SceneTree, project_root: &str) -> Vec<NodeId> {
    let root = std::path::Path::new(project_root);
    let autoloads = match gdresource::ProjectLoader::load(root) {
        Ok(loader) => loader.get_autoloads(),
        Err(_) => return Vec::new(),
    };
    if autoloads.is_empty() {
        return Vec::new();
    }
    let root_id = tree.root_id();
    gdscene::autoload::instantiate_autoloads(tree, root_id, &autoloads, root)
        .nodes
        .into_iter()
        .map(|(_, id)| id)
        .collect()
}

fn api_runtime_play(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    // pat-nzgdu.171: an optional `{"movie":true}` body enables Movie Maker mode
    // for this run — fixed-timestep stepping with a per-frame capture.
    let movie = parse_json_body(body)
        .and_then(|v| v.get("movie").and_then(|m| m.as_bool()))
        .unwrap_or(false);
    let mut state = state.lock().unwrap();
    if state.is_running {
        send_json(stream, r#"{"ok":true,"already_running":true}"#);
        return;
    }
    // pat-s3rrv.66: every plugin's `_build()` runs before the project does, and
    // a `false` return ABORTS the run. Placed before the debugger attach and the
    // tree build so a veto costs nothing — Godot's doc calls the run "aborted
    // immediately", and a plugin that refuses to build should not leave a
    // half-attached debugger or a constructed play tree behind.
    if let Some(refuser) = plugin_build_refusal(&mut state) {
        let name = plugin_display_name(&mut state, &refuser);
        state.add_log(
            "error",
            format!("Play aborted: plugin '{name}' _build() returned false"),
        );
        send_json(
            stream,
            &serde_json::json!({
                "ok": false,
                "build_failed": true,
                "plugin": name,
            })
            .to_string(),
        );
        return;
    }

    // pat-s3rrv.27: the debugger must be live BEFORE the tree is built, because
    // `build_play_tree` dispatches `_enter_tree`/`_ready` inline on this thread.
    // A script asking `EngineDebugger.is_active()` in `_ready` — the acceptance
    // case — is answered during that call, so attaching afterwards would report
    // false for the very first scripts to run.
    state.debug_attached = true;
    state.debug_state = "running".to_string();
    state.debug_messages.clear();
    bind_engine_debugger(&state);

    let cloned = build_play_tree(&mut state);
    // `_ready` has now run on THIS thread, so its `send_message` captures are in
    // this thread's buffer. Drain them here; the per-frame drain runs on the
    // driver thread and would never see them.
    drain_engine_debugger_into(&mut state);

    let mut main_loop = MainLoop::new(cloned);
    main_loop.set_input_map(state.build_engine_input_map());
    // pat-s3rrv.77: the pointer-emulation settings were declared and read by
    // nobody, so `InputState` kept its hard-coded values whatever project.godot
    // said. Applied here, at the same point as the input map, because both are
    // project configuration the running scene must see from its first frame.
    main_loop
        .input_state_mut()
        .set_emulate_mouse_from_touch(state.project_emulate_mouse_from_touch);
    main_loop
        .input_state_mut()
        .set_emulate_touch_from_mouse(state.project_emulate_touch_from_mouse);
    state.run_main_loop = Some(main_loop);
    state.is_running = true;
    state.is_paused = false;
    state.runtime_frame_count = 0;
    // pat-nzgdu.171: start (or clear) the Movie Maker recording for this run.
    state.movie_mode = movie;
    state.movie_frames.clear();
    // Launching the scene switches the main screen to the game view so the
    // running scene is shown where the editor viewport was (pat-niu1j.1).
    // Remember the mode we came from so Stop can restore it (pat-niu1j.3).
    if state.editor_mode != "game" {
        state.pre_play_editor_mode = Some(state.editor_mode.clone());
    }
    state.editor_mode = "game".to_string();
    // Route the wired MainPane to the game view too, so the served central view
    // (GET /api/editor/main_view) matches without waiting for a reconcile — same
    // as api_set_editor_mode does for a user-driven switch.
    state.main_pane.route_to(crate::EditorMode::Game);
    state.add_log("info", "Runtime: play started");
    send_json(
        stream,
        r#"{"ok":true,"running":true,"main_view":"game_view"}"#,
    );
}

/// Assembles the tree a Play run executes: the edited scene cloned, its scripts
/// attached, the project's `[autoload]` singletons instantiated, and the full
/// Godot lifecycle dispatched over the result.
///
/// Split out of [`api_runtime_play`] so the lifecycle contract is testable
/// without an HTTP round-trip. The editor Play flow is the product loop, so the
/// callback sequence a script observes here must equal the runner's and Godot's:
/// `_enter_tree` parent-first, `_ready` child-first, each exactly once
/// (`upstream/godot/scene/main/node.cpp` `_propagate_enter_tree`/
/// `_propagate_ready`). It previously called `process_script_ready` per scripted
/// node in `all_nodes_in_tree_order()` — parent-first, so a parent's `_ready` ran
/// before its children existed to it — and never dispatched `_enter_tree` at all
/// (pat-0q2kx.46).
pub fn build_play_tree(state: &mut EditorState) -> SceneTree {
    use gdscene::lifecycle::LifecycleManager;

    let mut cloned = clone_scene_tree(&state.scene_tree);

    // Attach GDScripts to nodes that have a `_script_path` property. Done before
    // any dispatch below, so every script is present for its own `_enter_tree`.
    let project_root = state.texture_cache.project_root().to_string();
    attach_scripts_to_tree(&mut cloned, &project_root, state);

    // Instantiate project [autoload] singletons under /root (pat-nzgdu.3). This
    // also binds their global names, so `Global.score` resolves from any script.
    let autoload_ids = instantiate_play_autoloads(&mut cloned, &project_root);

    let root_id = cloned.root_id();
    let subtree_roots: Vec<NodeId> = cloned
        .get_node(root_id)
        .map(|n| n.children().to_vec())
        .unwrap_or_default();
    // Both the clone and the autoload instantiation build with `add_child` under
    // a live root, which enters each node as it is inserted — childless and
    // scriptless. Drop that pass so the dispatch below is the only one the tree
    // and its scripts observe.
    for id in &subtree_roots {
        LifecycleManager::rewind_for_redispatch(&mut cloned, *id);
    }

    // Godot's boot order: each autoload is added to /root before the main scene,
    // and `add_child` propagates ENTER_TREE then READY across a whole subtree
    // before returning — so every autoload is fully `_ready` before the main
    // scene enters, and can be referenced from its `_ready`. Dispatching one
    // subtree at a time reproduces that. A single pass from /root would not: the
    // autoloads are appended *after* the scene here, so the bottom-up READY walk
    // would ready the main scene first.
    for id in &autoload_ids {
        LifecycleManager::enter_tree(&mut cloned, *id);
    }
    for id in subtree_roots.iter().filter(|id| !autoload_ids.contains(id)) {
        LifecycleManager::enter_tree(&mut cloned, *id);
    }

    cloned
}

/// Walks all nodes in `tree`, finds those with `_script_path`, resolves
/// the path relative to `project_root`, loads the `.gd` file, parses it,
/// and attaches a `GDScriptNodeInstance` to the node.
fn attach_scripts_to_tree(tree: &mut SceneTree, project_root: &str, state: &mut EditorState) {
    let mut scripts_to_load: Vec<(NodeId, std::path::PathBuf)> = Vec::new();

    for node_id in tree.all_nodes_in_tree_order() {
        if let Some(node) = tree.get_node(node_id) {
            if let Variant::String(res_path) = node.get_property("_script_path") {
                let relative = res_path.strip_prefix("res://").unwrap_or(&res_path);
                let abs_path = std::path::Path::new(project_root).join(relative);
                scripts_to_load.push((node_id, abs_path));
            }
        }
    }

    for (node_id, path) in scripts_to_load {
        match std::fs::read_to_string(&path) {
            Ok(source) => match GDScriptNodeInstance::from_source(&source, node_id) {
                Ok(instance) => {
                    tree.attach_script(node_id, Box::new(instance));
                    state.add_log("info", format!("Script loaded: {}", path.display()));
                }
                Err(e) => {
                    state.add_log(
                        "error",
                        format!("Script parse error in {}: {}", path.display(), e),
                    );
                }
            },
            Err(e) => {
                state.add_log(
                    "error",
                    format!("Failed to read script {}: {}", path.display(), e),
                );
            }
        }
    }
}

/// Tears down the running instance and restores the editable editor state.
///
/// Extracted from [`api_runtime_stop`] so a script calling `get_tree().quit()`
/// ends the run through exactly the same path as the Stop button, rather than a
/// near-copy that drifts from it (pat-0q2kx.47).
fn stop_running_instance(state: &mut EditorState) {
    // pat-niu1j.3: Stop tears down the running instance and restores the
    // editable editor state. Clearing `is_running` also lifts the play-mode
    // edit-lock (pat-niu1j.2): the tree/inspector/viewport mutation routes are
    // gated on `is_running`, so they become writable again the moment we drop
    // it here. Dropping `run_main_loop` discards the cloned runtime scene tree
    // and its scripts so the next Play starts from the edited scene afresh.
    state.is_running = false;
    state.is_paused = false;
    state.run_main_loop = None;
    state.runtime_frame_count = 0;
    // pat-s3rrv.27: the debugger belongs to the session, so it goes away with
    // it — `is_active()` must report false again once the game is not running.
    // Set here rather than in `api_runtime_stop` so a script-requested quit,
    // which shares this teardown, detaches too. The drained messages are kept:
    // the editor's debugger panel should still show what the finished run sent,
    // and the next Play clears them.
    state.debug_attached = false;
    state.debug_state = "detached".to_string();
    gdscript_interop::interpreter::engine_debugger_detach();
    // pat-nzgdu.171: stop recording, but keep `movie_frames` so the finished
    // run's sequence can still be downloaded until the next Play clears it.
    state.movie_mode = false;
    state.clear_all_input();
    // Restore the main-screen view that Play switched away from (Play set
    // `editor_mode = "game"` and stashed the prior mode in
    // `pre_play_editor_mode`). If no pre-play mode was recorded, leave the
    // current mode untouched.
    if let Some(prev) = state.pre_play_editor_mode.take() {
        state.editor_mode = prev;
    }
    // Keep the wired MainPane in lock-step with the restored mode (Godot
    // _stop_pressed returns to screen_index_before_start).
    if let Some(m) = crate::EditorMode::from_str_key(&state.editor_mode) {
        state.main_pane.route_to(m);
    }
}

fn api_runtime_stop(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    // pat-niu1j.3: Stop tears down the running instance and restores the
    // editable editor state. Clearing `is_running` also lifts the play-mode
    // edit-lock (pat-niu1j.2), and dropping `run_main_loop` discards the cloned
    // runtime tree so the next Play starts from the edited scene afresh — see
    // `stop_running_instance`, which a script-requested quit shares.
    stop_running_instance(&mut state);
    let editor_mode = state.editor_mode.clone();
    state.add_log("info", "Runtime: stopped");
    send_json(
        stream,
        &format!(r#"{{"ok":true,"running":false,"editor_mode":"{editor_mode}"}}"#),
    );
}

fn api_runtime_pause(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    state.is_paused = !state.is_paused;
    let paused = state.is_paused;
    state.add_log(
        "info",
        format!("Runtime: {}", if paused { "paused" } else { "resumed" }),
    );
    send_json(stream, &format!(r#"{{"ok":true,"paused":{paused}}}"#));
}

/// Advances the running [`MainLoop`] by exactly one frame and returns the new
/// frame count. Shared by the manual single-step endpoint (`/api/runtime/step`)
/// and the continuous runtime driver thread ([`run_runtime_driver`],
/// pat-nzgdu.19).
///
/// The caller owns the running/pause/suspend gating and the state lock; this
/// only performs the tick. The per-frame delta is scaled by
/// `runtime_time_scale` (Godot's `Engine.time_scale` semantics: the wall-clock
/// cadence is unchanged, but each frame advances game time by
/// `delta * time_scale`). Engine input is drained after scripts run, mirroring
/// the original step handler.
/// Binds the thread-local `EngineDebugger` to this thread if the session wants
/// one (pat-s3rrv.27).
///
/// `EngineDebugger` lives in a `thread_local!`, and the editor runs scripts on
/// more than one thread: `_ready` is dispatched by `build_play_tree` on the
/// connection thread serving `/api/runtime/play`, while `_process` runs on the
/// driver thread (or on another connection thread via `/api/runtime/step`).
/// Attaching in one place only would leave `is_active()` false for scripts run
/// by the other. `attach()` is idempotent, so every script-running entry point
/// calls this first.
fn bind_engine_debugger(state: &EditorState) {
    if state.debug_attached {
        gdscript_interop::interpreter::engine_debugger_attach();
        gdscript_interop::interpreter::engine_debugger_set_skipping_breakpoints(
            state.debug_skip_breakpoints,
        );
    }
}

/// Drains what the scripts that just ran told the debugger, into the editor
/// state the debugger panel reads (pat-s3rrv.27).
///
/// **Must be called on the same thread that ran the scripts.** `DEBUG_MESSAGES`
/// is thread-local, so a `send_message` from `_ready` (connection thread) is
/// invisible to a drain on the driver thread — draining only per-frame would
/// silently strand exactly the messages the acceptance case sends.
fn drain_engine_debugger_into(state: &mut EditorState) {
    if !state.debug_attached {
        return;
    }
    for (name, args) in gdscript_interop::interpreter::drain_engine_debugger_messages() {
        let rendered: Vec<String> = args.iter().map(|a| a.to_string()).collect();
        state.debug_messages.push((name, rendered));
    }
    // Godot's `debug()` suspends the game and hands the editor a stack. Patina
    // cannot suspend a frame mid-step, so the break is surfaced as the paused
    // state plus an Errors-tab entry: the editor learns the game broke and why,
    // which is the observable half of the contract.
    if let Some(brk) = gdscript_interop::interpreter::take_engine_debugger_break() {
        state.debug_state = "paused".to_string();
        let kind = if brk.is_error_breakpoint {
            "error"
        } else {
            "breakpoint"
        };
        let language = brk.language.unwrap_or_else(|| "GDScript".to_string());
        state.debug_errors.push((
            kind.to_string(),
            format!(
                "{language}: execution broke ({}continuable)",
                if brk.can_continue { "" } else { "not " }
            ),
        ));
    }
}

fn advance_running_main_loop(state: &mut EditorState) -> u64 {
    // pat-nzgdu.171: Movie Maker records at a stable, fixed timestep. time_scale
    // must not change how much game time each captured frame advances, or the
    // recording would speed up/stutter, so movie mode uses the raw fixed delta.
    let delta = if state.movie_mode {
        state.delta_time
    } else {
        state.delta_time * state.runtime_time_scale
    };
    let capture = state.movie_mode;
    let dt = state.delta_time;
    // The engine-owned InputState is populated by api_input_key_down/up via
    // push_event(). The bridge in MainLoop::step() converts it to the
    // script-facing InputSnapshot automatically. We still set a manual
    // snapshot as a fallback for any keys that didn't map to a typed Key.
    //
    // ⚠️ That fallback has to be conditional (pat-s3rrv.15). `MainLoop::step`
    // runs its bridge only `if !self.tree.has_input_snapshot()`
    // (gdscene/src/main_loop.rs:2688), so setting a manual snapshot
    // *unconditionally* — as this did — suppressed the engine bridge on every
    // frame. Scripts then saw only this string-keyed snapshot, which has no
    // notion of modifiers, so `Input.is_action_just_pressed("ui_copy")` could
    // never be true no matter how faithfully the browser's Ctrl bit was
    // forwarded. The comment above always described a fallback; the code was an
    // override.
    //
    // So: hand over the manual snapshot only when it carries a key the engine
    // could not type, which is the case it was written for. Otherwise stay out
    // of the way and let the engine's own `InputState` — the one that ran the
    // `KeyCombo` modifier test — reach the scripts.
    let untyped_key_pressed = state
        .pressed_keys
        .iter()
        .any(|name| gdplatform::input::Key::from_name(name).is_none());
    let input_snapshot = state.make_input_snapshot();
    // pat-s3rrv.27: reconcile the thread-local `EngineDebugger` with the
    // session's intent BEFORE stepping, because scripts run inside `step()` and
    // must observe an attached debugger on *this* thread. Frames arrive here
    // from either the driver thread or a `/api/runtime/step` connection thread,
    // and `attach()` is idempotent, so doing it every frame is both cheap and
    // the only thing that is correct on all of them. Attaching in the `play`
    // handler instead would bind a connection thread that dies with the
    // response — the feature would look wired and be inert.
    bind_engine_debugger(state);
    // Publish the served game view's size to the running loop every frame
    // (pat-s3rrv.120). `set_viewport_size` drives `resize_root_window`, which
    // recomputes the content scale, republishes the mirrored root-window
    // properties and emits `size_changed`.
    //
    // ⚠️ Every frame is correct here because `resize_root_window` early-outs on
    // an unchanged size — so this costs a comparison per frame and fires
    // `size_changed` only on a real resize. Doing it in the `play` handler
    // instead would capture the size once at boot and never see the browser
    // resize the canvas, which is the state this bead is about.
    let (view_w, view_h) = (state.render_width, state.render_height);
    if let Some(ref mut main_loop) = state.run_main_loop {
        main_loop.set_viewport_size(view_w, view_h);
        if untyped_key_pressed {
            main_loop.set_input(input_snapshot);
        }
        let output = main_loop.step(delta);
        state.runtime_frame_count = output.frame_count;
        // Record one frame per step while Movie Maker is active (this runs for
        // both the auto-driver and the manual /api/runtime/step path).
        if capture {
            state.movie_frames.push(MovieFrame {
                index: output.frame_count,
                time: output.frame_count as f64 * dt,
            });
        }
    }
    // pat-s3rrv.27: drain what this frame's scripts told the debugger, on the
    // same thread that just ran them.
    drain_engine_debugger_into(state);
    // Clear per-frame input after scripts have run.
    state.clear_frame_input();
    let frame_count = state.runtime_frame_count;
    // Godot: `get_tree().quit()` ends the run at the frame boundary — the frame
    // that asked completes, then the loop stops. In the editor that means Play
    // tears down exactly as the Stop button does (pat-0q2kx.47). Read before the
    // teardown, which resets the counter, so the caller still reports the frame
    // the scene quit on.
    let quit_requested = state
        .run_main_loop
        .as_ref()
        .map(|ml| ml.tree().should_quit())
        .unwrap_or(false);
    if quit_requested {
        stop_running_instance(state);
        state.add_log("info", "Runtime: scene called get_tree().quit()");
    }
    frame_count
}

fn api_runtime_step(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    if !state.is_paused {
        send_error(stream, 400, "not paused");
        return;
    }
    let frame = advance_running_main_loop(&mut state);
    send_json(stream, &format!(r#"{{"ok":true,"frame_count":{frame}}}"#));
}

/// pat-nzgdu.171: `GET /api/runtime/movie` — the recorded Movie Maker frame
/// sequence for the current or just-finished run, downloadable as JSON.
/// `frame_count` equals the number of frames stepped while movie mode was
/// active (the acceptance's "N captured frames for N stepped frames").
fn api_runtime_movie(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let state = state.lock().unwrap();
    let frames = state
        .movie_frames
        .iter()
        .map(|f| format!(r#"{{"index":{},"time":{}}}"#, f.index, f.time))
        .collect::<Vec<_>>()
        .join(",");
    let fps = (1.0 / state.delta_time).round() as u64;
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"movie_mode":{},"frame_count":{},"fps":{},"frames":[{}]}}"#,
            state.movie_mode,
            state.movie_frames.len(),
            fps,
            frames
        ),
    );
}

fn api_runtime_status(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let state = state.lock().unwrap();
    let running = state.is_running;
    let paused = state.is_paused;
    let frame_count = state.runtime_frame_count;
    let fps = if state.delta_time > 0.0 {
        1.0 / state.delta_time
    } else {
        0.0
    };
    send_json(
        stream,
        &format!(
            r#"{{"running":{running},"paused":{paused},"frame_count":{frame_count},"fps":{fps:.1},"suspended":{},"time_scale":{:.2},"muted":{},"camera_override":{},"hide_selection":{},"input_mode":"{}","midi_open":{}}}"#,
            state.runtime_suspended,
            state.runtime_time_scale,
            state.runtime_muted,
            state.runtime_camera_override,
            state.runtime_hide_selection,
            state.runtime_input_mode,
            // Whether the game called `OS.open_midi_inputs()` (pat-s3rrv.176).
            //
            // ⚠️ This exists so the CLIENT can gate `navigator.requestMIDIAccess()`
            // on it. Godot only starts the platform MIDI driver when a game asks
            // for it, and on the web that call is what raises a browser
            // permission prompt — requesting unconditionally would prompt every
            // user who ever pressed Play, for a device almost none of them have.
            gdscript_interop::midi_ports::is_open()
        ),
    );
}

/// `GET /api/runtime/node?path=<node_path>` — reads a node's **live** properties
/// from the running scene (the play-mode [`MainLoop`]'s tree), resolved by its
/// absolute node path (e.g. `/root/Main/Player`). This is the runtime
/// counterpart to `GET /api/node/<id>`: `/api/node` inspects the frozen editor
/// scene, whereas this reflects the values a running scene's scripts mutate each
/// frame — Godot's remote scene-tree inspector during Play. Script member
/// variables are synced onto the node every time a script method runs
/// (`call_script_with_access`), so a `_process`-incremented variable is
/// observable here as the continuous driver (pat-nzgdu.19) advances it
/// (pat-nzgdu.23).
///
/// Returns 400 when no scene is playing and 404 when the path resolves to no
/// node in the running tree.
/// `GET /api/runtime/scene` — the RUNNING clone's tree, for the Scene dock's
/// Remote tab (pat-0q2kx.72).
///
/// `/api/scene` keeps serving the EDIT tree: play runs on a clone stored in
/// `run_main_loop`, so nodes a script spawns in `_ready` exist only here. Before
/// this route the dock had no way to see them — it showed the pre-play tree and
/// the running game was invisible.
fn api_runtime_scene(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let state = state.lock().unwrap();
        if !state.is_running {
            send_error(stream, 400, "not running");
            return;
        }
        let main_loop = match state.run_main_loop.as_ref() {
            Some(ml) => ml,
            None => {
                send_error(stream, 400, "not running");
                return;
            }
        };
        let tree = main_loop.tree();
        let root_id = tree.root_id();
        let tree_json = node_to_json_tree(tree, root_id);
        format!(r#"{{"ok":true,"remote":true,"tree":{tree_json}}}"#)
    };
    send_json(stream, &json);
}

fn api_runtime_node(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let path = match query_param(query, "path") {
        Some(p) => url_decode(p),
        None => {
            send_error(stream, 400, "missing path parameter");
            return;
        }
    };
    let json = {
        let state = state.lock().unwrap();
        if !state.is_running {
            send_error(stream, 400, "not running");
            return;
        }
        let main_loop = match state.run_main_loop.as_ref() {
            Some(ml) => ml,
            None => {
                send_error(stream, 400, "not running");
                return;
            }
        };
        let tree = main_loop.tree();
        let node_id = match tree.get_node_by_path(&path) {
            Some(id) => id,
            None => {
                send_error(stream, 404, "node not found");
                return;
            }
        };
        node_properties_json(tree, node_id, None).to_string()
    };
    send_json(stream, &json);
}

// --- pat-j9yqh: game-view runtime toolbar controls ---

/// `POST /api/runtime/suspend` — force-pause at the SceneTree level (Suspend).
/// Body `{"suspended":true}`; omit to toggle.
fn api_runtime_suspend(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mut s = state.lock().unwrap();
    s.runtime_suspended = p
        .get("suspended")
        .and_then(|v| v.as_bool())
        .unwrap_or(!s.runtime_suspended);
    s.is_paused = s.runtime_suspended;
    send_json(
        stream,
        &format!(r#"{{"ok":true,"suspended":{}}}"#, s.runtime_suspended),
    );
}

/// `POST /api/runtime/time_scale` — set the game time scale. Body
/// `{"scale":0.5}`; omit/0 resets to 1.0.
fn api_runtime_time_scale(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let scale = p
        .get("scale")
        .and_then(|v| v.as_f64())
        .filter(|v| *v > 0.0)
        .unwrap_or(1.0);
    let mut s = state.lock().unwrap();
    s.runtime_time_scale = scale;
    send_json(stream, &format!(r#"{{"ok":true,"time_scale":{scale:.2}}}"#));
}

/// `POST /api/runtime/mute` — mute/unmute game audio. Body `{"muted":true}`.
fn api_runtime_mute(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mut s = state.lock().unwrap();
    s.runtime_muted = p
        .get("muted")
        .and_then(|v| v.as_bool())
        .unwrap_or(!s.runtime_muted);
    send_json(
        stream,
        &format!(r#"{{"ok":true,"muted":{}}}"#, s.runtime_muted),
    );
}

/// `POST /api/runtime/camera_override` — toggle the in-game camera override.
fn api_runtime_camera_override(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mut s = state.lock().unwrap();
    s.runtime_camera_override = p
        .get("enabled")
        .and_then(|v| v.as_bool())
        .unwrap_or(!s.runtime_camera_override);
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"camera_override":{}}}"#,
            s.runtime_camera_override
        ),
    );
}

/// `POST /api/runtime/hide_selection` — toggle selection visibility in-game.
fn api_runtime_hide_selection(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mut s = state.lock().unwrap();
    s.runtime_hide_selection = p
        .get("hidden")
        .and_then(|v| v.as_bool())
        .unwrap_or(!s.runtime_hide_selection);
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"hide_selection":{}}}"#,
            s.runtime_hide_selection
        ),
    );
}

/// `POST /api/runtime/input_mode` — set the game-view interaction mode.
/// Body `{"mode":"input"|"2d"|"3d"}`.
fn api_runtime_input_mode(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let mode = p.get("mode").and_then(|v| v.as_str()).unwrap_or("input");
    let mode = if matches!(mode, "input" | "2d" | "3d") {
        mode
    } else {
        "input"
    };
    state.lock().unwrap().runtime_input_mode = mode.to_string();
    send_json(stream, &format!(r#"{{"ok":true,"input_mode":"{mode}"}}"#));
}

// ---------------------------------------------------------------------------
// Scene instancing endpoint
// ---------------------------------------------------------------------------

/// `POST /api/scene/instance` — instances a .tscn file as a child of a node.
///
/// Body: `{"path": "path/to/scene.tscn", "parent_id": 123}`
/// Returns: `{"id": <root_node_id>}`
fn api_instance_scene(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let path = match parsed.get("path").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };

    let parent_raw = match parsed.get("parent_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing parent_id");
            return;
        }
    };

    // Read the .tscn file.
    let source = match std::fs::read_to_string(&path) {
        Ok(s) => s,
        Err(e) => {
            send_error(stream, 400, &format!("failed to read: {e}"));
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let parent_id = match find_node_by_raw_id(&state.scene_tree, parent_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "parent not found");
            return;
        }
    };

    let mut cmd = EditorCommand::InstanceScene {
        parent_id,
        tscn_source: source,
        created_ids: Vec::new(),
        root_id: None,
        source_path: Some(path.clone()),
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }

    let root_id = match &cmd {
        EditorCommand::InstanceScene { root_id, .. } => root_id.unwrap(),
        _ => unreachable!(),
    };

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log("info", format!("Instanced scene from '{}'", path));

    let json = format!(r#"{{"id":{}}}"#, root_id.raw());
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// Viewport asset drop endpoint
// ---------------------------------------------------------------------------

/// `POST /api/viewport/drop` — handles an asset dropped onto the viewport.
///
/// Body: `{"asset_type": "scene"|"texture"|"audio", "path": "...", "parent_id": 123, "pixel_x": 100, "pixel_y": 200}`
/// Returns: `{"id": <created_node_id>}`
fn api_viewport_drop(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let asset_type = match parsed.get("asset_type").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing asset_type");
            return;
        }
    };
    let path = match parsed.get("path").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    let parent_raw = match parsed.get("parent_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing parent_id");
            return;
        }
    };
    let pixel_x = parsed
        .get("pixel_x")
        .and_then(|v| v.as_f64())
        .unwrap_or(0.0) as f32;
    let pixel_y = parsed
        .get("pixel_y")
        .and_then(|v| v.as_f64())
        .unwrap_or(0.0) as f32;

    match asset_type.as_str() {
        "scene" => {
            // Instance the .tscn scene and set position
            let source = match std::fs::read_to_string(&path) {
                Ok(s) => s,
                Err(e) => {
                    send_error(stream, 400, &format!("failed to read: {e}"));
                    return;
                }
            };

            let mut state = state.lock().unwrap();
            let parent_id = match find_node_by_raw_id(&state.scene_tree, parent_raw) {
                Some(id) => id,
                None => {
                    send_error(stream, 404, "parent not found");
                    return;
                }
            };

            let world_pos = pixel_to_world_pos(&state, pixel_x, pixel_y);

            let mut cmd = EditorCommand::InstanceScene {
                parent_id,
                tscn_source: source,
                created_ids: Vec::new(),
                root_id: None,
                source_path: Some(path.clone()),
            };

            if let Err(e) = cmd.execute(&mut state.scene_tree) {
                send_error(stream, 500, &e.to_string());
                return;
            }

            let root_id = match &cmd {
                EditorCommand::InstanceScene { root_id, .. } => root_id.unwrap(),
                _ => unreachable!(),
            };

            // Set the instanced root's position to the drop location
            if let Some(node) = state.scene_tree.get_node_mut(root_id) {
                node.set_property(
                    "position",
                    Variant::Vector2(Vector2::new(world_pos.x, world_pos.y)),
                );
            }

            state.undo_stack.push(cmd);
            state.redo_stack.clear();
            state.scene_modified = true;
            state.add_log(
                "info",
                format!(
                    "Dropped scene '{}' at ({:.0}, {:.0})",
                    path, world_pos.x, world_pos.y
                ),
            );

            let json = format!(r#"{{"id":{}}}"#, root_id.raw());
            send_json(stream, &json);
        }
        "texture" => {
            // Create a Sprite2D with the texture path
            let mut state = state.lock().unwrap();
            let parent_id = match find_node_by_raw_id(&state.scene_tree, parent_raw) {
                Some(id) => id,
                None => {
                    send_error(stream, 404, "parent not found");
                    return;
                }
            };

            let world_pos = pixel_to_world_pos(&state, pixel_x, pixel_y);

            // Derive a node name from the filename
            let node_name = std::path::Path::new(&path)
                .file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| "Sprite2D".to_string());

            let mut cmd = EditorCommand::AddNode {
                parent_id,
                name: node_name.clone(),
                class_name: "Sprite2D".to_string(),
                created_id: None,
            };

            if let Err(e) = cmd.execute(&mut state.scene_tree) {
                send_error(stream, 500, &e.to_string());
                return;
            }

            let created_id = match &cmd {
                EditorCommand::AddNode { created_id, .. } => created_id.unwrap(),
                _ => unreachable!(),
            };

            // Set position and texture
            if let Some(node) = state.scene_tree.get_node_mut(created_id) {
                node.set_property(
                    "position",
                    Variant::Vector2(Vector2::new(world_pos.x, world_pos.y)),
                );
                node.set_property("texture", Variant::String(format!("res://{}", path)));
            }

            state.undo_stack.push(cmd);
            state.redo_stack.clear();
            state.scene_modified = true;
            state.add_log(
                "info",
                format!("Created Sprite2D '{}' from '{}'", node_name, path),
            );

            let json = format!(r#"{{"id":{}}}"#, created_id.raw());
            send_json(stream, &json);
        }
        "audio" => {
            // Create an AudioStreamPlayer with the audio path
            let mut state = state.lock().unwrap();
            let parent_id = match find_node_by_raw_id(&state.scene_tree, parent_raw) {
                Some(id) => id,
                None => {
                    send_error(stream, 404, "parent not found");
                    return;
                }
            };

            let node_name = std::path::Path::new(&path)
                .file_stem()
                .map(|s| s.to_string_lossy().to_string())
                .unwrap_or_else(|| "AudioStreamPlayer".to_string());

            let mut cmd = EditorCommand::AddNode {
                parent_id,
                name: node_name.clone(),
                class_name: "AudioStreamPlayer".to_string(),
                created_id: None,
            };

            if let Err(e) = cmd.execute(&mut state.scene_tree) {
                send_error(stream, 500, &e.to_string());
                return;
            }

            let created_id = match &cmd {
                EditorCommand::AddNode { created_id, .. } => created_id.unwrap(),
                _ => unreachable!(),
            };

            if let Some(node) = state.scene_tree.get_node_mut(created_id) {
                node.set_property("stream", Variant::String(format!("res://{}", path)));
            }

            state.undo_stack.push(cmd);
            state.redo_stack.clear();
            state.scene_modified = true;
            state.add_log(
                "info",
                format!("Created AudioStreamPlayer '{}' from '{}'", node_name, path),
            );

            let json = format!(r#"{{"id":{}}}"#, created_id.raw());
            send_json(stream, &json);
        }
        _ => {
            send_error(
                stream,
                400,
                &format!("unsupported asset_type: {}", asset_type),
            );
        }
    }
}

/// Convert pixel coordinates to world-space position using current viewport settings.
fn pixel_to_world_pos(state: &EditorState, pixel_x: f32, pixel_y: f32) -> Vector2 {
    let offset = crate::scene_renderer::camera_offset_with_zoom_pan(
        &state.scene_tree,
        state.viewport_width,
        state.viewport_height,
        state.viewport_zoom,
        state.viewport_pan,
    );
    let z = state.viewport_zoom as f32;
    Vector2::new((pixel_x - offset.x) / z, (pixel_y - offset.y) / z)
}

// ---------------------------------------------------------------------------
// Collision shape resize endpoint
// ---------------------------------------------------------------------------

/// `POST /api/viewport/shape_resize` — resizes a collision shape.
///
/// Body: `{"node_id": 123, "handle": "radius", "value": 50.0}`
///    or `{"node_id": 123, "handle": "extents", "value": [30, 20]}`
// ---------------------------------------------------------------------------
// Path2D / Polygon2D / Line2D point editing (pat-0q2kx.77)
//
// Godot gives each of these a point editor in the 2D viewport: add, move and
// delete vertices, with every edit a single undo action
// (`editor/scene/2d/path_2d_editor_plugin.cpp`,
// `editor/scene/2d/abstract_polygon_2d_editor.cpp`). Patina had none of it, on
// either side of the wire.
//
// A Path2D's points live on its Curve2D SUB-RESOURCE, flattened onto the node as
// `__curve__points` exactly as a collision shape is flattened to `__shape__*`.
// Polygon2D and Line2D hold theirs directly, on `polygon` and `points`.
// ---------------------------------------------------------------------------

/// The property holding `node`'s editable point list, by class.
///
/// Returns `None` for a class with no point editor, so the routes 400 instead of
/// inventing a property on an unrelated node.
fn point_property_for(class_name: &str) -> Option<&'static str> {
    match class_name {
        "Path2D" => Some("__curve__points"),
        "Polygon2D" => Some("polygon"),
        "Line2D" => Some("points"),
        _ => None,
    }
}

/// Reads a point list, accepting both the packed and generic spellings.
///
/// A `.tscn` yields `PackedVector2Array`; a hand-built node may hold a generic
/// `Array` of `Vector2`. Both are real inputs, so both are read.
fn read_point_list(tree: &SceneTree, node_id: NodeId, property: &str) -> Vec<Vector2> {
    match tree.get_node(node_id).map(|n| n.get_property(property)) {
        Some(Variant::PackedVector2Array(v)) => v,
        Some(Variant::Array(items)) => items
            .into_iter()
            .filter_map(|v| match v {
                Variant::Vector2(p) => Some(p),
                _ => None,
            })
            .collect(),
        _ => Vec::new(),
    }
}

/// Resolves the node and its point property, answering the request on failure.
fn point_target(
    state: &Arc<Mutex<EditorState>>,
    body: &str,
    stream: &mut TcpStream,
) -> Option<(serde_json::Value, NodeId, &'static str)> {
    let parsed = parse_json_body(body)?;
    let raw = parsed.get("node_id").and_then(|v| v.as_u64())?;
    let s = state.lock().unwrap();
    let node_id = find_node_by_raw_id(&s.scene_tree, raw)?;
    let class = s.scene_tree.get_node(node_id)?.class_name().to_string();
    let property = point_property_for(&class)?;
    drop(s);
    let _ = stream;
    Some((parsed, node_id, property))
}

/// Applies a new point list as one undoable command and answers with the count.
fn commit_point_list(
    state: &Arc<Mutex<EditorState>>,
    node_id: NodeId,
    property: &str,
    points: Vec<Vector2>,
    stream: &mut TcpStream,
) {
    let count = points.len();
    let mut s = state.lock().unwrap();
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: property.to_string(),
        new_value: Variant::PackedVector2Array(points),
        old_value: Variant::Nil,
    };
    if let Err(e) = cmd.execute(&mut s.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }
    s.undo_stack.push(cmd);
    s.redo_stack.clear();
    s.scene_modified = true;
    send_json(stream, &format!(r#"{{"ok":true,"count":{count}}}"#));
}

/// `POST /api/path2d/point/add` — appends (or inserts at `index`) a point.
///
/// Shared by Polygon2D and Line2D: the gesture and the undo shape are identical
/// and only the backing property differs, which `point_property_for` resolves.
fn api_point_add(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some((parsed, node_id, property)) = point_target(state, body, stream) else {
        send_error(stream, 400, "node has no editable point list");
        return;
    };
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let mut points = {
        let s = state.lock().unwrap();
        read_point_list(&s.scene_tree, node_id, property)
    };
    // An out-of-range index appends rather than failing, matching Godot's
    // "add at end" default when no insertion point is given.
    let index = parsed
        .get("index")
        .and_then(|v| v.as_u64())
        .map(|i| i as usize)
        .filter(|i| *i <= points.len())
        .unwrap_or(points.len());
    points.insert(index, Vector2::new(x, y));
    commit_point_list(state, node_id, property, points, stream);
}

/// `POST /api/path2d/point/move` — moves the point at `index`.
fn api_point_move(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some((parsed, node_id, property)) = point_target(state, body, stream) else {
        send_error(stream, 400, "node has no editable point list");
        return;
    };
    let index = parsed.get("index").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    let x = parsed.get("x").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let y = parsed.get("y").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let mut points = {
        let s = state.lock().unwrap();
        read_point_list(&s.scene_tree, node_id, property)
    };
    if index >= points.len() {
        send_error(stream, 404, "point index out of range");
        return;
    }
    points[index] = Vector2::new(x, y);
    commit_point_list(state, node_id, property, points, stream);
}

/// `POST /api/path2d/point/remove` — deletes the point at `index`.
fn api_point_remove(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some((parsed, node_id, property)) = point_target(state, body, stream) else {
        send_error(stream, 400, "node has no editable point list");
        return;
    };
    let index = parsed.get("index").and_then(|v| v.as_u64()).unwrap_or(0) as usize;
    let mut points = {
        let s = state.lock().unwrap();
        read_point_list(&s.scene_tree, node_id, property)
    };
    if index >= points.len() {
        send_error(stream, 404, "point index out of range");
        return;
    }
    points.remove(index);
    commit_point_list(state, node_id, property, points, stream);
}

/// `GET /api/viewport/points?node_id=N` — the node's editable points, so the
/// client can draw a handle on each without guessing at the property name.
fn api_get_points(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let Some(raw) = query_param(query, "node_id").and_then(|v| v.parse::<u64>().ok()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let s = state.lock().unwrap();
    let Some(node_id) = find_node_by_raw_id(&s.scene_tree, raw) else {
        send_error(stream, 404, "node not found");
        return;
    };
    let class = s
        .scene_tree
        .get_node(node_id)
        .map(|n| n.class_name().to_string())
        .unwrap_or_default();
    let Some(property) = point_property_for(&class) else {
        send_json(stream, r#"{"ok":true,"editable":false,"points":[]}"#);
        return;
    };
    let points = read_point_list(&s.scene_tree, node_id, property);
    let list: Vec<String> = points
        .iter()
        .map(|p| format!("[{},{}]", p.x, p.y))
        .collect();
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"editable":true,"class":"{class}","property":"{property}","points":[{}]}}"#,
            list.join(",")
        ),
    );
}

/// `GET /api/viewport/shape_handles?node_id=N` — the draggable handles for a
/// selected CollisionShape2D, so the client can draw them where Godot does.
///
/// Godot places one handle per resizable dimension of the shape class
/// (`collision_shape_2d_editor_plugin.cpp`); the handle NAME is what
/// `/api/viewport/shape_resize` takes back.
fn api_shape_handles(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let Some(raw) = query_param(query, "node_id").and_then(|v| v.parse::<u64>().ok()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let s = state.lock().unwrap();
    let Some(node_id) = find_node_by_raw_id(&s.scene_tree, raw) else {
        send_error(stream, 404, "node not found");
        return;
    };
    let Some(node) = s.scene_tree.get_node(node_id) else {
        send_error(stream, 404, "node not found");
        return;
    };
    if node.class_name() != "CollisionShape2D" {
        send_json(stream, r#"{"ok":true,"editable":false,"handles":[]}"#);
        return;
    }
    // The shape class comes from the flattened companion for a loaded scene, or
    // straight off `shape` for a hand-built node.
    let shape_class = match node.get_property("__shape__class") {
        Variant::String(c) => c,
        _ => match node.get_property("shape") {
            Variant::String(c) if !c.starts_with("SubResource:") => c,
            _ => String::new(),
        },
    };
    let num = |key: &str, default: f32| -> f32 {
        match node.get_property(&format!("__shape__{key}")) {
            Variant::Float(f) => f as f32,
            Variant::Int(i) => i as f32,
            _ => default,
        }
    };
    let size = match node.get_property("__shape__size") {
        Variant::Vector2(v) => v,
        _ => Vector2::new(20.0, 20.0),
    };

    // Each handle is (name, local offset from the node's origin).
    let handles: Vec<(&str, Vector2)> = match shape_class.as_str() {
        "CircleShape2D" => vec![("radius", Vector2::new(num("radius", 10.0), 0.0))],
        "RectangleShape2D" => vec![
            ("extents", Vector2::new(size.x / 2.0, 0.0)),
            ("extents", Vector2::new(0.0, size.y / 2.0)),
        ],
        "CapsuleShape2D" => vec![
            ("radius", Vector2::new(num("radius", 10.0), 0.0)),
            ("height", Vector2::new(0.0, num("height", 20.0) / 2.0)),
        ],
        _ => Vec::new(),
    };
    let list: Vec<String> = handles
        .iter()
        .map(|(name, p)| format!(r#"{{"handle":"{name}","x":{},"y":{}}}"#, p.x, p.y))
        .collect();
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"editable":true,"shape":"{shape_class}","handles":[{}]}}"#,
            list.join(",")
        ),
    );
}

fn api_shape_resize(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let node_raw = match parsed.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };

    let handle = match parsed.get("handle").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing handle");
            return;
        }
    };

    let mut state = state.lock().unwrap();
    let node_id = match find_node_by_raw_id(&state.scene_tree, node_raw) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };

    // Build the appropriate property set command based on handle type.
    let (property, new_value) = match handle.as_str() {
        "radius" => {
            let val = match parsed.get("value").and_then(|v| v.as_f64()) {
                Some(v) => v,
                None => {
                    send_error(stream, 400, "missing numeric value for radius");
                    return;
                }
            };
            // ⚠️ `__shape__radius`, not `shape_radius`: the flattened companion
            // is what `physics_server::shape_from_node` reads and what the
            // `.tscn` sub-resource body is written from. The old made-up name
            // was read by nothing at all (pat-0q2kx.77).
            ("__shape__radius".to_string(), Variant::Float(val))
        }
        "extents" => {
            let arr = match parsed.get("value").and_then(|v| v.as_array()) {
                Some(v) => v,
                None => {
                    send_error(stream, 400, "missing array value for extents");
                    return;
                }
            };
            if arr.len() != 2 {
                send_error(stream, 400, "extents must be [x, y]");
                return;
            }
            let x = arr[0].as_f64().unwrap_or(0.0) as f32;
            let y = arr[1].as_f64().unwrap_or(0.0) as f32;
            // Godot 4's RectangleShape2D property is `size`, not `extents`
            // (`extents` was the Godot 3 spelling and is half the size).
            (
                "__shape__size".to_string(),
                Variant::Vector2(Vector2::new(x, y)),
            )
        }
        "height" => {
            let val = match parsed.get("value").and_then(|v| v.as_f64()) {
                Some(v) => v,
                None => {
                    send_error(stream, 400, "missing numeric value for height");
                    return;
                }
            };
            ("__shape__height".to_string(), Variant::Float(val))
        }
        _ => {
            send_error(stream, 400, &format!("unknown handle type: {handle}"));
            return;
        }
    };

    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property: property.clone(),
        new_value: new_value.clone(),
        old_value: Variant::Nil,
    };

    if let Err(e) = cmd.execute(&mut state.scene_tree) {
        send_error(stream, 500, &e.to_string());
        return;
    }

    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    state.add_log(
        "info",
        format!("Shape resize: {} on node {}", handle, node_raw),
    );

    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// Input API endpoints
// ---------------------------------------------------------------------------

fn api_input_key_down(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    let key = match v["key"].as_str() {
        Some(k) => k.to_string(),
        None => {
            send_error(stream, 400, "missing key");
            return;
        }
    };
    if !state.pressed_keys.contains(&key) {
        state.just_pressed_keys.insert(key.clone());
    }
    state.pressed_keys.insert(key.clone());
    // The browser's real modifier state, as Godot's web platform layer reads it
    // off the KeyboardEvent (upstream/godot/platform/web/js/libs/library_godot_input.js
    // forwards `e.shiftKey`/`ctrlKey`/`altKey`/`metaKey` into
    // `InputEventWithModifiers`) — pat-s3rrv.15.
    //
    // These were hard-coded `false` here, which quietly killed **every**
    // modifier-bound builtin action in the only interactive runtime:
    // `KeyCombo::modifiers_satisfied_by` (gdplatform/src/input.rs:1285) is
    // consulted on each press, so `ui_copy` (Ctrl+C), `ui_undo` (Ctrl+Z),
    // `ui_focus_prev` (Shift+Tab) and the rest could never match. Nothing else
    // on the path was broken — the action resolution and the press/echo
    // bookkeeping were already correct — so reading the three flags off the
    // request is the whole fix.
    let modifier = |name: &str| v[name].as_bool().unwrap_or(false);
    // Route through engine-owned InputState when MainLoop is active.
    if let Some(ref mut main_loop) = state.run_main_loop {
        if let Some(typed_key) = gdplatform::input::Key::from_name(&key) {
            main_loop.push_event(gdplatform::InputEvent::Key {
                key: typed_key,
                pressed: true,
                shift: modifier("shift"),
                ctrl: modifier("ctrl"),
                alt: modifier("alt"),
            });
        }
    }
    send_json(stream, r#"{"ok":true}"#);
}

fn api_input_key_up(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    let key = match v["key"].as_str() {
        Some(k) => k.to_string(),
        None => {
            send_error(stream, 400, "missing key");
            return;
        }
    };
    state.pressed_keys.remove(&key);
    state.just_released_keys.insert(key.clone());
    // Modifiers on the release too (pat-s3rrv.15). Godot only applies the
    // modifier test to a *press* — `gdplatform/src/input.rs:1283-1288` lets a
    // release match regardless, so the action can drop even when the user let
    // go of Ctrl before the key — but the flags are still carried so a consumer
    // reading the event sees what the browser actually reported.
    let modifier = |name: &str| v[name].as_bool().unwrap_or(false);
    // Route through engine-owned InputState when MainLoop is active.
    if let Some(ref mut main_loop) = state.run_main_loop {
        if let Some(typed_key) = gdplatform::input::Key::from_name(&key) {
            main_loop.push_event(gdplatform::InputEvent::Key {
                key: typed_key,
                pressed: false,
                shift: modifier("shift"),
                ctrl: modifier("ctrl"),
                alt: modifier("alt"),
            });
        }
    }
    send_json(stream, r#"{"ok":true}"#);
}

fn api_input_mouse_move(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    // While the pointer is locked the browser reports only `movementX/movementY`
    // — `clientX/clientY` freeze — so the client posts `{dx, dy}` instead of
    // `{x, y}` (pat-0q2kx.90). Godot's captured semantics are the same: the
    // event carries `relative` and `position` does not move
    // (platform/web/display_server_web.cpp, MOUSE_MODE_CAPTURED).
    let captured = matches!(
        state
            .run_main_loop
            .as_ref()
            .map(|m| m.input_state().mouse_mode()),
        Some(gdplatform::input::MouseMode::Captured)
    );
    let relative_only = v["dx"].is_number() || v["dy"].is_number();

    let (x, y, rel_x, rel_y) = if relative_only {
        let dx = v["dx"].as_f64().unwrap_or(0.0);
        let dy = v["dy"].as_f64().unwrap_or(0.0);
        let (px, py) = state.mouse_position;
        if captured {
            // Position stays frozen where it was when the lock was taken.
            (px, py, dx, dy)
        } else {
            // A relative post outside capture still moves the pointer, so a
            // client that keeps posting deltas through an unlock is not stuck.
            (px + dx, py + dy, dx, dy)
        }
    } else {
        let x = match v["x"].as_f64() {
            Some(x) => x,
            None => {
                send_error(stream, 400, "missing x");
                return;
            }
        };
        let y = match v["y"].as_f64() {
            Some(y) => y,
            None => {
                send_error(stream, 400, "missing y");
                return;
            }
        };
        let prev = state.mouse_position;
        if captured {
            // An absolute post that slipped in while captured must not teleport
            // the frozen position; only its delta is meaningful.
            (prev.0, prev.1, x - prev.0, y - prev.1)
        } else {
            (x, y, x - prev.0, y - prev.1)
        }
    };

    state.mouse_position = (x, y);
    // pat-s3rrv.76: a PointerEvent carries stylus data that a MouseEvent does
    // not. Recorded on the tree just before the motion event is pushed, so
    // `_input` sees Godot's pressure/tilt/pen_inverted instead of the zeros
    // `input_event_to_variant` used to hardcode.
    //
    // ⚠️ Only written when the payload ACTUALLY carries pen data. Writing
    // unconditionally would reset pressure to 0.0 on every ordinary mouse move,
    // which a script reads as "the pen was lifted" rather than "no new data" —
    // and the values are sticky precisely so they survive events that omit them.
    let has_pen = v["pressure"].is_number()
        || v["tilt_x"].is_number()
        || v["tilt_y"].is_number()
        || v["pen_inverted"].is_boolean();
    if has_pen {
        if let Some(ref mut main_loop) = state.run_main_loop {
            main_loop
                .tree_mut()
                .set_pen_state(gdscene::scene_tree::PenState {
                    pressure: v["pressure"].as_f64().unwrap_or(0.0) as f32,
                    tilt: gdcore::math::Vector2::new(
                        v["tilt_x"].as_f64().unwrap_or(0.0) as f32,
                        v["tilt_y"].as_f64().unwrap_or(0.0) as f32,
                    ),
                    inverted: v["pen_inverted"].as_bool().unwrap_or(false),
                });
        }
    }
    // Motion carries the frame-to-frame delta, as Godot's
    // InputEventMouseMotion.relative does (pat-0q2kx.23).
    if let Some(ref mut main_loop) = state.run_main_loop {
        main_loop.push_event(gdplatform::InputEvent::MouseMotion {
            position: gdcore::math::Vector2::new(x as f32, y as f32),
            relative: gdcore::math::Vector2::new(rel_x as f32, rel_y as f32),
        });
    }
    send_json(stream, r#"{"ok":true}"#);
}

/// Feeds a browser `wheel` event into the running `MainLoop` (pat-s3rrv.76).
///
/// A wheel notch is not a DOM `button`, so it cannot go through the mouse_down
/// route: the browser reports it as a `wheel` event carrying deltas. Godot turns
/// each notch into a `MOUSE_BUTTON_WHEEL_*` press **and release** in the same
/// frame, which is what makes `_input` see a discrete notch rather than a button
/// that latches down forever — so both are pushed here.
///
/// ⚠️ deltaY is POSITIVE when scrolling DOWN in the DOM, so positive maps to
/// `WheelDown`. Getting this backwards inverts every scroll in the engine and
/// still "works", which is why the sign is named rather than left implicit.
fn api_input_mouse_wheel(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    let dy = v["delta_y"].as_f64().unwrap_or(0.0);
    let dx = v["delta_x"].as_f64().unwrap_or(0.0);
    let mut buttons: Vec<gdplatform::input::MouseButton> = Vec::new();
    if dy > 0.0 {
        buttons.push(gdplatform::input::MouseButton::WheelDown);
    } else if dy < 0.0 {
        buttons.push(gdplatform::input::MouseButton::WheelUp);
    }
    if dx > 0.0 {
        buttons.push(gdplatform::input::MouseButton::WheelRight);
    } else if dx < 0.0 {
        buttons.push(gdplatform::input::MouseButton::WheelLeft);
    }
    if buttons.is_empty() {
        // A zero-delta wheel event is not an error; it simply moved nothing.
        send_json(stream, r#"{"ok":true}"#);
        return;
    }
    let (x, y) = state.mouse_position;
    if let Some(ref mut main_loop) = state.run_main_loop {
        for button in buttons {
            for pressed in [true, false] {
                main_loop.push_event(gdplatform::InputEvent::MouseButton {
                    button,
                    pressed,
                    position: gdcore::math::Vector2::new(x as f32, y as f32),
                });
            }
        }
    }
    send_json(stream, r#"{"ok":true}"#);
}

fn api_input_mouse_down(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    // 0..=4 are the DOM buttons: left, middle, right, back, forward. The cap
    // used to be 2, which rejected the thumb buttons at the door — so mapping
    // them in `push_mouse_button_event` was not enough on its own, the endpoint
    // refused them first (pat-s3rrv.76).
    let button = match v["button"].as_u64() {
        Some(b) if b <= 4 => b as u8,
        _ => {
            send_error(stream, 400, "invalid button (0-4)");
            return;
        }
    };
    state.mouse_buttons.insert(button);
    push_mouse_button_event(&mut state, button, true);
    send_json(stream, r#"{"ok":true}"#);
}

/// Feeds a browser mouse button into the running `MainLoop` as a real
/// `InputEvent::MouseButton` (pat-0q2kx.23).
///
/// These routes previously only mutated `EditorState`, so nothing ever reached
/// `SceneTree::push_input` — `_input` never saw a mouse event and the GUI stage
/// added in pat-0q2kx.18 had no events to route.
///
/// Browser `MouseEvent.button` is 0=left, 1=middle, 2=right, 3=back, 4=forward;
/// Patina's `MouseButton` enum is named, so the mapping is explicit rather than
/// the numeric 1/3/2 Godot uses internally.
///
/// ⚠️ 3 and 4 are the thumb buttons, and dropping them was silent: the `_ =>
/// return` below discarded them before they reached the running game, so a
/// project binding `back`/`forward` saw nothing and had no error to look at
/// (pat-s3rrv.76). The browser's names are the reverse of Godot's numbering —
/// DOM 3 ("back") is `XBUTTON1` (8), DOM 4 ("forward") is `XBUTTON2` (9).
fn push_mouse_button_event(state: &mut EditorState, button: u8, pressed: bool) {
    let btn = match button {
        0 => gdplatform::input::MouseButton::Left,
        1 => gdplatform::input::MouseButton::Middle,
        2 => gdplatform::input::MouseButton::Right,
        3 => gdplatform::input::MouseButton::XButton1,
        4 => gdplatform::input::MouseButton::XButton2,
        _ => return,
    };
    let (x, y) = state.mouse_position;
    if let Some(ref mut main_loop) = state.run_main_loop {
        main_loop.push_event(gdplatform::InputEvent::MouseButton {
            button: btn,
            pressed,
            position: gdcore::math::Vector2::new(x as f32, y as f32),
        });
    }
}

fn api_input_mouse_up(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    // 0..=4 are the DOM buttons: left, middle, right, back, forward. The cap
    // used to be 2, which rejected the thumb buttons at the door — so mapping
    // them in `push_mouse_button_event` was not enough on its own, the endpoint
    // refused them first (pat-s3rrv.76).
    let button = match v["button"].as_u64() {
        Some(b) if b <= 4 => b as u8,
        _ => {
            send_error(stream, 400, "invalid button (0-4)");
            return;
        }
    };
    state.mouse_buttons.remove(&button);
    push_mouse_button_event(&mut state, button, false);
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/runtime/input/touch` — the browser touch pipeline (pat-s3rrv.77).
///
/// Body is one DOM touch event's changed-touches list plus its phase:
/// `{"phase":"start"|"move"|"end"|"cancel","touches":[{"identifier",…}]}`.
///
/// Each entry becomes an `InputEvent::ScreenTouch` (start/end/cancel) or
/// `InputEvent::ScreenDrag` (move), pushed through `MainLoop::push_event` so it
/// travels the whole input pipeline — `_input`, the GUI stage, and, when
/// `emulate_mouse_from_touch` is on, the synthetic mouse event that lets a touch
/// press a Button.
fn api_input_touch(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    let phase = v["phase"].as_str().unwrap_or("").to_string();
    if !matches!(phase.as_str(), "start" | "move" | "end" | "cancel") {
        send_error(stream, 400, "phase must be start|move|end|cancel");
        return;
    }
    let touches = match v["touches"].as_array() {
        Some(list) if !list.is_empty() => list.clone(),
        // An empty changed-touches list is a malformed frame, not a no-op: the
        // browser only fires these events when something changed.
        _ => {
            send_error(stream, 400, "touches must be a non-empty array");
            return;
        }
    };

    let Some(main_loop) = state.run_main_loop.as_mut() else {
        send_error(stream, 400, "not running");
        return;
    };

    let mut pushed = 0usize;
    for t in &touches {
        let index = match t["identifier"].as_i64() {
            // The browser hands out arbitrary identifiers, including negative
            // ones on some engines; a finger index is unsigned.
            Some(i) if i >= 0 => i as u32,
            _ => continue,
        };
        let position = gdcore::math::Vector2::new(
            t["x"].as_f64().unwrap_or(0.0) as f32,
            t["y"].as_f64().unwrap_or(0.0) as f32,
        );
        let event = match phase.as_str() {
            "move" => {
                // ⚠️ Read BEFORE the push: `push_event` updates the stored
                // position, so asking afterwards yields a zero delta every time.
                let previous = main_loop
                    .input_state()
                    .touch_position(index)
                    .unwrap_or(position);
                let relative = position - previous;
                gdplatform::InputEvent::ScreenDrag {
                    index,
                    position,
                    relative,
                    // Godot derives velocity from the event's own timing; with
                    // one event per browser frame the per-frame delta IS the
                    // velocity in the units a script compares against.
                    velocity: relative,
                    pressure: t["force"].as_f64().unwrap_or(0.0) as f32,
                    tilt: gdcore::math::Vector2::new(
                        t["tiltX"].as_f64().unwrap_or(0.0) as f32,
                        t["tiltY"].as_f64().unwrap_or(0.0) as f32,
                    ),
                }
            }
            other => {
                let pressed = other == "start";
                gdplatform::InputEvent::ScreenTouch {
                    index,
                    position,
                    pressed,
                    // ⚠️ Asked BEFORE the push, which overwrites the very
                    // last-press frame the answer is computed from.
                    double_tap: pressed && main_loop.input_state().would_be_double_tap(index),
                    // A `touchcancel` is a lift the user did not make — Godot
                    // flags it so a script can abandon a gesture instead of
                    // completing it.
                    canceled: other == "cancel",
                }
            }
        };
        main_loop.push_event(event);
        pushed += 1;
    }

    send_json(stream, &format!(r#"{{"ok":true,"events":{pushed}}}"#));
}

/// `POST /api/runtime/input/gesture` — one pinch or pan gesture frame
/// (pat-s3rrv.234).
///
/// Body: `{"kind":"magnify","x":…,"y":…,"factor":…}` or
/// `{"kind":"pan","x":…,"y":…,"dx":…,"dy":…}`.
///
/// The `InputEvent` variants and the script-facing objects both already
/// existed; what was missing was any way for a browser to reach them, so a
/// pinch on the game view produced nothing at all. This is that producer.
fn api_input_gesture(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    let kind = v["kind"].as_str().unwrap_or("").to_string();
    if !matches!(kind.as_str(), "magnify" | "pan") {
        send_error(stream, 400, "kind must be magnify|pan");
        return;
    }
    let position = gdcore::math::Vector2::new(
        v["x"].as_f64().unwrap_or(0.0) as f32,
        v["y"].as_f64().unwrap_or(0.0) as f32,
    );

    let Some(main_loop) = state.run_main_loop.as_mut() else {
        send_error(stream, 400, "not running");
        return;
    };

    let event = if kind == "magnify" {
        gdplatform::InputEvent::MagnifyGesture {
            position,
            // Godot's `factor` defaults to 1.0 — the identity scale. Defaulting
            // to 0.0 would read as "shrink to nothing" on a malformed frame,
            // which is a silent scene-destroying value rather than a no-op.
            factor: v["factor"].as_f64().unwrap_or(1.0) as f32,
        }
    } else {
        gdplatform::InputEvent::PanGesture {
            position,
            delta: gdcore::math::Vector2::new(
                v["dx"].as_f64().unwrap_or(0.0) as f32,
                v["dy"].as_f64().unwrap_or(0.0) as f32,
            ),
        }
    };
    main_loop.push_event(event);

    send_json(stream, r#"{"ok":true,"events":1}"#);
}

fn api_input_clear_frame(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    state.clear_frame_input();
    send_json(stream, r#"{"ok":true}"#);
}

/// Smallest axis movement that counts as a change worth emitting an event for.
///
/// Browser sticks jitter by tiny amounts at rest; without a floor every poll
/// would push a JoypadMotion event and drown `_input`. Godot's web layer
/// compares against the previous reported value the same way.
const GAMEPAD_AXIS_EPSILON: f32 = 0.001;

/// `POST /api/runtime/input/gamepad` — applies one browser gamepad poll
/// (pat-0q2kx.88).
///
/// Body: `{"device":0,"buttons":[bool,…],"axes":[f32,…],"connected":true}` —
/// one `navigator.getGamepads()` entry in W3C standard-mapping order.
///
/// This is the producer that `InputState::apply_standard_gamepad_frame` was
/// written for and never had: the normalizer and its tests existed, but nothing
/// outside `#[cfg(test)]` ever called it, so a browser controller could not
/// reach a running scene at all.
///
/// The browser reports absolute state every poll while Godot's web layer emits
/// one event per *transition*, so this diffs against the previous poll
/// (`EditorState::gamepad_prev`) and pushes a `GamepadButton` / `GamepadAxis`
/// event only where something changed. Those go through
/// [`MainLoop::push_event`], which both updates `InputState` (so
/// `just_pressed` and any bound action fire) and queues the event for `_input`
/// dispatch on the next step. The full frame then goes through
/// `apply_standard_gamepad_frame`, which marks the pad connected and levels the
/// remaining button/axis state.
fn api_input_gamepad(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };
    let device = v["device"].as_u64().unwrap_or(0) as u32;
    // A poll with no `connected` key is a connected pad; the client only sends
    // `connected:false` on a `gamepaddisconnected` event.
    let connected = v["connected"].as_bool().unwrap_or(true);

    if !connected {
        state.gamepad_prev.remove(&device);
        if let Some(ref mut main_loop) = state.run_main_loop {
            main_loop.input_state_mut().disconnect_joypad(device);
        }
        send_json(stream, r#"{"ok":true,"connected":false}"#);
        return;
    }

    let buttons: Vec<bool> = v["buttons"]
        .as_array()
        .map(|a| a.iter().map(|b| b.as_bool().unwrap_or(false)).collect())
        .unwrap_or_default();
    let axes: Vec<f32> = v["axes"]
        .as_array()
        .map(|a| a.iter().map(|x| x.as_f64().unwrap_or(0.0) as f32).collect())
        .unwrap_or_default();

    // Cloned so the immutable borrow of `state` ends before `run_main_loop` is
    // borrowed mutably below.
    let prev = state.gamepad_prev.get(&device).cloned();
    let mut events = 0usize;

    if let Some(ref mut main_loop) = state.run_main_loop {
        for (index, &pressed) in buttons.iter().enumerate() {
            let was = prev
                .as_ref()
                .and_then(|(b, _)| b.get(index).copied())
                .unwrap_or(false);
            if was == pressed {
                continue;
            }
            if let Some(button) = gdplatform::input::GamepadButton::from_standard(index) {
                main_loop.push_event(gdplatform::InputEvent::GamepadButton {
                    button,
                    pressed,
                    gamepad_id: device,
                });
                events += 1;
            }
        }
        for (index, &value) in axes.iter().enumerate() {
            let was = prev
                .as_ref()
                .and_then(|(_, a)| a.get(index).copied())
                .unwrap_or(0.0);
            if (was - value).abs() < GAMEPAD_AXIS_EPSILON {
                continue;
            }
            if let Some(axis) = gdplatform::input::GamepadAxis::from_standard(index) {
                main_loop.push_event(gdplatform::InputEvent::GamepadAxis {
                    axis,
                    value,
                    gamepad_id: device,
                });
                events += 1;
            }
        }
        // Marks the pad connected and levels the whole frame through the same
        // normalizer physical devices use.
        main_loop
            .input_state_mut()
            .apply_standard_gamepad_frame(device, &buttons, &axes);
    }

    state.gamepad_prev.insert(device, (buttons, axes));
    send_json(
        stream,
        &format!(r#"{{"ok":true,"connected":true,"events":{events}}}"#),
    );
}

/// `POST /api/runtime/input/midi` — the client forwarding Web MIDI
/// (pat-0q2kx.246).
///
/// Body: `{"data":[144,60,100]}` — the bytes of `MIDIMessageEvent.data`, status
/// byte first, exactly as the browser hands them over — plus an optional
/// `"device"` port index and an optional `"ports"` array naming the inputs the
/// client can see.
///
/// `ports` rides this route rather than getting its own because the browser
/// surfaces names and messages from the same `requestMIDIAccess` promise.
/// Splitting them would let a script receive a message from a port that
/// `OS.get_connected_midi_inputs()` does not list.
fn api_input_midi(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let mut state = state.lock().unwrap();
    if !state.is_running {
        send_error(stream, 400, "not running");
        return;
    }
    let v: serde_json::Value = match serde_json::from_str(body) {
        Ok(v) => v,
        Err(_) => {
            send_error(stream, 400, "invalid json");
            return;
        }
    };

    // Reported independently of any message, so a client that has MIDI access
    // but no traffic yet still populates `OS.get_connected_midi_inputs()` —
    // which is the order the browser actually delivers things in.
    if let Some(ports) = v["ports"].as_array() {
        gdscript_interop::midi_ports::set_input_names(
            ports
                .iter()
                .filter_map(|p| p.as_str())
                .map(str::to_string)
                .collect::<Vec<_>>(),
        );
    }

    let device = v["device"].as_u64().unwrap_or(0) as u32;
    let packet: Vec<u8> = v["data"]
        .as_array()
        .map(|a| {
            a.iter()
                .filter_map(|b| b.as_u64())
                .map(|b| b as u8)
                .collect()
        })
        .unwrap_or_default();

    // A ports-only report carries no packet and is not an error.
    if packet.is_empty() {
        send_json(stream, r#"{"ok":true,"events":0}"#);
        return;
    }

    // Decoding lives in `gdplatform` so the wire format and the event share one
    // implementation. An undecodable packet is refused here rather than padded:
    // padding `[0x90, 60]` would produce NOTE_ON with velocity 0, which is the
    // conventional spelling of NOTE_OFF — the opposite of what was played.
    let Some(event) = gdplatform::input::decode_midi_message(&packet, device) else {
        send_error(stream, 400, "undecodable midi packet");
        return;
    };
    let mut events = 0usize;
    if let Some(ref mut main_loop) = state.run_main_loop {
        main_loop.push_event(event);
        events = 1;
    }
    send_json(stream, &format!(r#"{{"ok":true,"events":{events}}}"#));
}

/// `POST /api/runtime/input/mouse_mode` — the client reporting the **actual**
/// pointer-lock state back to the engine (pat-0q2kx.90).
///
/// Body: `{"mouse_mode": 0}` using Godot's `MOUSE_MODE_*` values.
///
/// This exists because a `requestPointerLock()` can be refused (no user gesture)
/// or dropped by the browser (Esc, tab switch) without the engine hearing about
/// it. Without this the engine would keep believing it held a lock it had lost,
/// and every subsequent motion event would be treated as captured — freezing the
/// pointer for good. Godot's web build has the same round trip via its
/// `pointerlockchange` callback.
fn api_input_mouse_mode(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let v = parse_json_body(body).unwrap_or(serde_json::Value::Null);
    let Some(mode) = v
        .get("mouse_mode")
        .and_then(|m| m.as_i64())
        .and_then(gdplatform::input::MouseMode::from_godot)
    else {
        send_error(stream, 400, "invalid mouse_mode");
        return;
    };
    let mut state = state.lock().unwrap();
    if let Some(ref mut main_loop) = state.run_main_loop {
        main_loop.input_state_mut().set_mouse_mode(mode);
        // Mirror onto the tree so a script's `Input.get_mouse_mode()` agrees
        // with what the browser is actually doing.
        main_loop
            .tree_mut()
            .set_input_mouse_mode_mirror(mode.to_godot());
    }
    send_json(
        stream,
        &format!(r#"{{"ok":true,"mouse_mode":{}}}"#, mode.to_godot()),
    );
}

fn api_input_state(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let state = state.lock().unwrap();
    let mut pressed: Vec<&String> = state.pressed_keys.iter().collect();
    pressed.sort();
    let mut just_pressed: Vec<&String> = state.just_pressed_keys.iter().collect();
    just_pressed.sort();
    let mut mouse_btns: Vec<u8> = state.mouse_buttons.iter().copied().collect();
    mouse_btns.sort();

    // Build actions object with sorted keys for deterministic output
    let mut actions = String::from("{");
    let mut action_names: Vec<&String> = state.input_map.keys().collect();
    action_names.sort();
    let mut first = true;
    for action in &action_names {
        if !first {
            actions.push(',');
        }
        first = false;
        let pressed_val = state.is_action_pressed(action);
        actions.push_str(&format!(r#""{}": {}"#, action, pressed_val));
    }
    actions.push('}');

    // Joypads + pending rumble (pat-0q2kx.88). The client polls this while Play
    // runs and forwards each entry to that pad's
    // `vibrationActuator.playEffect('dual-rumble')` — the only way engine-side
    // `Input.start_joy_vibration` can reach real hardware in a browser.
    let (joypads, vibration) = match state.run_main_loop.as_ref() {
        Some(main_loop) => {
            let input = main_loop.input_state();
            let ids = input.connected_joypads();
            let entries: Vec<String> = ids
                .iter()
                .filter_map(|&d| {
                    input.joy_vibration(d).map(|(weak, strong, duration)| {
                        format!(
                            r#""{d}":{{"weak":{weak},"strong":{strong},"duration":{duration}}}"#
                        )
                    })
                })
                .collect();
            (
                ids.iter()
                    .map(|d| d.to_string())
                    .collect::<Vec<_>>()
                    .join(","),
                entries.join(","),
            )
        }
        None => (String::new(), String::new()),
    };

    // Mouse mode + cursor shape (pat-0q2kx.90). This is the client contract that
    // makes `Input.set_mouse_mode(MOUSE_MODE_CAPTURED)` reach the browser: the
    // game view polls this payload and calls `requestPointerLock()` /
    // `exitPointerLock()` and sets the CSS `cursor` from it. Nothing carried the
    // mode out of the engine before, so pointer lock could never be requested.
    let (mouse_mode, cursor_shape, cursor_css, cursor_url) = match state.run_main_loop.as_ref() {
        Some(main_loop) => {
            let shape = main_loop.cursor().current_shape();
            let custom = main_loop
                .cursor()
                .active_custom_cursor_path()
                .map(|(path, hx, hy)| format!(r#"{{"path":"{path}","hotspot":[{hx},{hy}]}}"#))
                .unwrap_or_else(|| "null".to_string());
            (
                main_loop.input_state().mouse_mode().to_godot(),
                shape as i64,
                shape.css_name(),
                custom,
            )
        }
        // Not running: report Godot's defaults rather than omitting the keys, so
        // the client's parse path is the same either way.
        None => (
            0,
            0,
            gdplatform::cursor::CursorShape::Arrow.css_name(),
            "null".to_string(),
        ),
    };

    let json = format!(
        r#"{{"pressed_keys":[{}],"just_pressed":[{}],"mouse_position":[{},{}],"mouse_buttons":[{}],"actions":{},"joypads":[{joypads}],"vibration":{{{vibration}}},"mouse_mode":{mouse_mode},"cursor_shape":{cursor_shape},"cursor_css":"{cursor_css}","custom_cursor":{cursor_url}}}"#,
        pressed
            .iter()
            .map(|k| format!(r#""{}""#, k))
            .collect::<Vec<_>>()
            .join(","),
        just_pressed
            .iter()
            .map(|k| format!(r#""{}""#, k))
            .collect::<Vec<_>>()
            .join(","),
        state.mouse_position.0,
        state.mouse_position.1,
        mouse_btns
            .iter()
            .map(|b| b.to_string())
            .collect::<Vec<_>>()
            .join(","),
        actions,
    );
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// TileMap paint toolset (pat-0q2kx.75)
//
// Godot's tiles editor offers paint, line, rect, bucket, picker and eraser
// tools, every operation a single undo step, and stores the result on the
// layer's `tile_map_data` property so it survives a save. Patina had the paint
// and rect ops as routes with no client, no line or bucket at all, and a grid
// store that was never populated from — nor written back to — the scene.
// ---------------------------------------------------------------------------

/// Whether a node is one of the tile-layer classes the tools apply to.
fn is_tilemap_class(class_name: &str) -> bool {
    class_name == "TileMapLayer" || class_name == "TileMap"
}

/// Populates `tile_grid_store` from every tile layer in the current scene.
///
/// Called on scene load, mirroring `sync_animations_from_scene`. Before this the
/// store was never filled from a scene, so every paint into a freshly-opened
/// `.tscn` hit `get_mut(nid) == None` and was silently discarded.
fn sync_tile_grids_from_scene(state: &mut EditorState) {
    let mut ids = Vec::new();
    state
        .scene_tree
        .collect_subtree_top_down(state.scene_tree.root_id(), &mut ids);
    for nid in ids {
        let Some(node) = state.scene_tree.get_node(nid) else {
            continue;
        };
        if !is_tilemap_class(node.class_name()) {
            continue;
        }
        let Variant::PackedByteArray(bytes) = node.get_property("tile_map_data") else {
            continue;
        };
        let (w, h) = gdscene::tilemap::tile_map_data_extent(&bytes);
        // An empty layer still gets a canvas so the first paint lands somewhere.
        let (w, h) = (w.max(TILE_GRID_MIN), h.max(TILE_GRID_MIN));
        state.tile_grid_store.insert(
            nid,
            gdscene::tilemap::TileGrid::from_tile_map_data(&bytes, w, h),
        );
    }
}

/// The canvas a fresh or newly-grown grid is given, in cells.
const TILE_GRID_MIN: usize = 32;

/// Ensures `nid` has a grid large enough to hold cell `(x, y)`.
///
/// ⚠️ Growth happens BEFORE the command runs and is deliberately not undone:
/// enlarging only adds empty cells, so undoing the paint still restores the
/// cell to 0 and the layer looks exactly as it did. Godot's TileMapLayer has no
/// bounds at all; this grid does, and silently dropping a paint outside them
/// would be worse than a canvas that only ever grows.
fn ensure_tile_grid(state: &mut EditorState, nid: NodeId, x: i32, y: i32) {
    let need_w = if x >= 0 { x as usize + 1 } else { 0 };
    let need_h = if y >= 0 { y as usize + 1 } else { 0 };
    match state.tile_grid_store.get_mut(nid) {
        Some(g) => {
            if need_w > g.width || need_h > g.height {
                g.resize(g.width.max(need_w), g.height.max(need_h));
            }
        }
        None => {
            let g = gdscene::tilemap::TileGrid::new(
                need_w.max(TILE_GRID_MIN),
                need_h.max(TILE_GRID_MIN),
            );
            state.tile_grid_store.insert(nid, g);
        }
    }
}

/// Writes the node's grid back onto its `tile_map_data` property.
///
/// This is what makes painting persist: the property is Godot's own
/// PackedByteArray format, which the existing `.tscn` writer already emits and
/// the loader already parses — so no new serializer is involved. Called after
/// every mutation, including undo/redo, so the property never drifts from the
/// grid the editor is showing.
fn writeback_tile_grid(state: &mut EditorState, nid: NodeId) {
    let Some(grid) = state.tile_grid_store.get(nid) else {
        return;
    };
    // Rebuild Godot's sparse cell map from the dense grid, re-attaching each
    // cell's transform bits. A cell whose tile has since been erased drops its
    // alternative with it, because the record is not emitted at all.
    let alts = state.tile_alternatives.get(&nid);
    let mut cells: std::collections::HashMap<gdcore::math::Vector2i, gdscene::tilemap::TileData> =
        std::collections::HashMap::new();
    for y in 0..grid.height {
        for x in 0..grid.width {
            let t = grid.cells[y * grid.width + x];
            if t == 0 {
                continue;
            }
            let (cx, cy) = (x as i32, y as i32);
            let mut data = gdscene::tilemap::TileData::new(t);
            if let Some(a) = alts.and_then(|m| m.get(&(cx, cy))) {
                data.alternative_id = *a;
            }
            cells.insert(gdcore::math::Vector2i::new(cx, cy), data);
        }
    }
    let bytes = gdscene::tilemap::encode_tile_map_data(&cells);
    if let Some(node) = state.scene_tree.get_node_mut(nid) {
        node.set_property("tile_map_data", Variant::PackedByteArray(bytes));
    }
}

/// Records (or clears) the transform bits a paint placed on a cell.
fn set_tile_alternative(state: &mut EditorState, nid: NodeId, x: i32, y: i32, alternative: i32) {
    let per_node = state.tile_alternatives.entry(nid).or_default();
    if alternative == 0 {
        // Not stored as 0: an absent entry and a zero entry mean the same thing,
        // and letting the map grow one entry per painted cell would be waste.
        per_node.remove(&(x, y));
    } else {
        per_node.insert((x, y), alternative);
    }
}

/// Cells on the Bresenham line between two grid coordinates, endpoints included.
///
/// Godot's line tool paints a connected run of cells rather than a mathematical
/// segment, which is what Bresenham gives (`tile_map_layer_editor.cpp`).
fn tile_line_cells(x1: i32, y1: i32, x2: i32, y2: i32) -> Vec<(i32, i32)> {
    let mut cells = Vec::new();
    let (dx, dy) = ((x2 - x1).abs(), -(y2 - y1).abs());
    let (sx, sy) = (if x1 < x2 { 1 } else { -1 }, if y1 < y2 { 1 } else { -1 });
    let (mut x, mut y) = (x1, y1);
    let mut err = dx + dy;
    loop {
        cells.push((x, y));
        if x == x2 && y == y2 {
            break;
        }
        let e2 = 2 * err;
        if e2 >= dy {
            err += dy;
            x += sx;
        }
        if e2 <= dx {
            err += dx;
            y += sy;
        }
    }
    cells
}

/// The 4-connected run of cells sharing `(x, y)`'s current tile.
///
/// ⚠️ Returns empty when the target tile already equals `tile_id`; without that
/// guard the flood would still enqueue every neighbour and walk the whole grid
/// to paint nothing.
fn tile_bucket_cells(
    grid: &gdscene::tilemap::TileGrid,
    x: i32,
    y: i32,
    tile_id: i32,
) -> Vec<(i32, i32)> {
    let Some(target) = grid.get(x, y) else {
        return Vec::new();
    };
    if target == tile_id {
        return Vec::new();
    }
    let mut out = Vec::new();
    let mut seen = std::collections::HashSet::new();
    let mut stack = vec![(x, y)];
    seen.insert((x, y));
    while let Some((cx, cy)) = stack.pop() {
        if grid.get(cx, cy) != Some(target) {
            continue;
        }
        out.push((cx, cy));
        for (nx, ny) in [(cx + 1, cy), (cx - 1, cy), (cx, cy + 1), (cx, cy - 1)] {
            if grid.get(nx, ny) == Some(target) && seen.insert((nx, ny)) {
                stack.push((nx, ny));
            }
        }
    }
    out
}

/// Applies a multi-cell tile edit as ONE undo entry.
///
/// Godot commits line/bucket/rect drags as a single UndoRedo action; a batch of
/// individual paint posts would instead need one Ctrl-Z per cell.
fn apply_tile_cells(
    state: &mut EditorState,
    nid: NodeId,
    label: &str,
    cells: &[(i32, i32)],
    tile_id: i32,
) -> usize {
    for &(x, y) in cells {
        ensure_tile_grid(state, nid, x, y);
        // These tools place plain tiles; a cell they cover must shed whatever
        // transform a previous paint left on it.
        set_tile_alternative(state, nid, x, y, 0);
    }
    let commands: Vec<EditorCommand> = cells
        .iter()
        .map(|&(x, y)| EditorCommand::TileMapPaint {
            node_id: nid,
            x,
            y,
            tile_id,
            old_tile_id: 0,
        })
        .collect();
    let mut cmd = EditorCommand::Group {
        label: label.to_string(),
        commands,
    };
    let _ = cmd.execute_tilemap(&mut state.tile_grid_store);
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    writeback_tile_grid(state, nid);
    cells.len()
}

fn api_tilemap_paint(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "bad json");
            return;
        }
    };
    let nr = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let x = p.get("x").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let y = p.get("y").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let tid = p.get("tile_id").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    // Godot's flip/rotate live in the alternative-tile id's low bits.
    let alt = p.get("alternative").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let mut s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, nr) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "not found");
            return;
        }
    };
    ensure_tile_grid(&mut s, nid, x, y);
    set_tile_alternative(&mut s, nid, x, y, alt);
    let mut cmd = EditorCommand::TileMapPaint {
        node_id: nid,
        x,
        y,
        tile_id: tid,
        old_tile_id: 0,
    };
    let _ = cmd.execute_tilemap(&mut s.tile_grid_store);
    s.undo_stack.push(cmd);
    s.redo_stack.clear();
    s.scene_modified = true;
    writeback_tile_grid(&mut s, nid);
    send_json(stream, r#"{"ok":true}"#);
}

fn api_tilemap_erase(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "bad json");
            return;
        }
    };
    let nr = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let x = p.get("x").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let y = p.get("y").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let mut s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, nr) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "not found");
            return;
        }
    };
    ensure_tile_grid(&mut s, nid, x, y);
    // An erased cell must not keep the flip/rotate of whatever used to be there,
    // or repainting it would silently inherit the old transform.
    set_tile_alternative(&mut s, nid, x, y, 0);
    let mut cmd = EditorCommand::TileMapPaint {
        node_id: nid,
        x,
        y,
        // Erasing IS painting tile 0 — the grid's "no tile" value, which
        // `to_tile_map_data` then omits from the saved bytes entirely.
        tile_id: 0,
        old_tile_id: 0,
    };
    let _ = cmd.execute_tilemap(&mut s.tile_grid_store);
    s.undo_stack.push(cmd);
    s.redo_stack.clear();
    s.scene_modified = true;
    writeback_tile_grid(&mut s, nid);
    send_json(stream, r#"{"ok":true}"#);
}

fn api_tilemap_fill(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "bad json");
            return;
        }
    };
    let nr = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let x1 = p.get("x1").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let y1 = p.get("y1").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let x2 = p.get("x2").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let y2 = p.get("y2").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let tid = p.get("tile_id").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let bucket = p.get("mode").and_then(|v| v.as_str()) == Some("bucket");
    let mut s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, nr) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "not found");
            return;
        }
    };

    // Godot's bucket tool floods the contiguous run of like tiles under the
    // cursor; the rectangle form below is the rect-drag tool. Both live on this
    // route because they are the same user gesture ("fill this with that").
    if bucket {
        let bx = p.get("x").and_then(|v| v.as_i64()).unwrap_or(x1 as i64) as i32;
        let by = p.get("y").and_then(|v| v.as_i64()).unwrap_or(y1 as i64) as i32;
        ensure_tile_grid(&mut s, nid, bx, by);
        let cells = match s.tile_grid_store.get(nid) {
            Some(g) => tile_bucket_cells(g, bx, by, tid),
            None => Vec::new(),
        };
        let painted = apply_tile_cells(&mut s, nid, "Bucket Fill", &cells, tid);
        send_json(stream, &format!(r#"{{"ok":true,"cells":{painted}}}"#));
        return;
    }

    ensure_tile_grid(&mut s, nid, x1.max(x2), y1.max(y2));
    let mut cmd = EditorCommand::TileMapFill {
        node_id: nid,
        x1,
        y1,
        x2,
        y2,
        tile_id: tid,
        old_tiles: Vec::new(),
    };
    let _ = cmd.execute_tilemap(&mut s.tile_grid_store);
    s.undo_stack.push(cmd);
    s.redo_stack.clear();
    s.scene_modified = true;
    writeback_tile_grid(&mut s, nid);
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/tilemap/line` — paints the Bresenham line between two cells as a
/// single undo entry (Godot's line tool).
fn api_tilemap_line(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some(p) = parse_json_body(body) else {
        send_error(stream, 400, "bad json");
        return;
    };
    let Some(nr) = p.get("node_id").and_then(|v| v.as_u64()) else {
        send_error(stream, 400, "missing node_id");
        return;
    };
    let x1 = p.get("x1").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let y1 = p.get("y1").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let x2 = p.get("x2").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let y2 = p.get("y2").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let tid = p.get("tile_id").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let mut s = state.lock().unwrap();
    let Some(nid) = find_node_by_raw_id(&s.scene_tree, nr) else {
        send_error(stream, 404, "not found");
        return;
    };
    let cells = tile_line_cells(x1, y1, x2, y2);
    let painted = apply_tile_cells(&mut s, nid, "Paint Line", &cells, tid);
    send_json(stream, &format!(r#"{{"ok":true,"cells":{painted}}}"#));
}

fn api_tilemap_data(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let nr: u64 = query
        .split('&')
        .find_map(|p| {
            let (k, v) = p.split_once('=')?;
            if k == "node_id" {
                v.parse().ok()
            } else {
                None
            }
        })
        .unwrap_or(0);
    if nr == 0 {
        send_error(stream, 400, "missing node_id");
        return;
    }
    let s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, nr) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "not found");
            return;
        }
    };
    match s.tile_grid_store.get(nid) {
        Some(g) => send_json(stream, &g.to_json().to_string()),
        None => send_error(stream, 404, "no tilemap data"),
    }
}

fn api_tilemap_resize(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "bad json");
            return;
        }
    };
    let nr = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let w = match p.get("width").and_then(|v| v.as_u64()) {
        Some(v) => v as usize,
        None => {
            send_error(stream, 400, "missing width");
            return;
        }
    };
    let h = match p.get("height").and_then(|v| v.as_u64()) {
        Some(v) => v as usize,
        None => {
            send_error(stream, 400, "missing height");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, nr) {
        Some(id) => id,
        None => {
            send_error(stream, 404, "not found");
            return;
        }
    };
    let mut cmd = EditorCommand::TileMapResize {
        node_id: nid,
        new_width: w,
        new_height: h,
        old_width: 0,
        old_height: 0,
        old_cells: Vec::new(),
    };
    let _ = cmd.execute_tilemap(&mut s.tile_grid_store);
    s.undo_stack.push(cmd);
    s.redo_stack.clear();
    s.scene_modified = true;
    send_json(stream, r#"{"ok":true}"#);
}

fn api_tilemap_tileset(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    let ts = match &s.tile_grid_store.tileset {
        Some(ts) => ts,
        None => {
            send_json(stream, r#"{"tiles":[]}"#);
            return;
        }
    };
    let tiles: Vec<serde_json::Value> = ts.tile_ids_sorted().iter().filter_map(|&id| { let t = ts.get_tile(id)?; Some(serde_json::json!({"id":t.id,"name":t.name,"color":format!("#{:02X}{:02X}{:02X}",(t.color.r*255.0) as u8,(t.color.g*255.0) as u8,(t.color.b*255.0) as u8),"collision":t.collision})) }).collect();
    send_json(
        stream,
        &serde_json::json!({"cell_size":[ts.cell_size.x,ts.cell_size.y],"tiles":tiles}).to_string(),
    );
}

// ---------------------------------------------------------------------------
// pat-s3rrv.65: TileSet atlas-source editor
//
// Godot's TileSet editor (editor/scene/2d/tiles/tile_set_atlas_source_editor.cpp)
// assigns an atlas texture to a source, slices it into tiles, and paints
// per-tile TileData. Patina had no TileSet AUTHORING at all: the one endpoint,
// `GET /api/tilemap/tileset`, reports the editor's own flat colour palette from
// `TileGridStore`, which has nothing to do with the TileSet resource on the
// selected `TileMapLayer`. Painting worked; defining what you painted did not.
//
// These routes read and write the node's flattened `__tile_set__*` /
// `__tile_physics_*` / `__tile_custom_data_*` companions — the same properties
// `packed_scene` writes on load, `tile_set_from_properties` reads, and
// `physics_server::register_tilemap_bodies` already consumes. So an edit here
// lands in the saved `.tscn` and is honoured by the runtime without any new
// runtime path.
// ---------------------------------------------------------------------------

/// Reads a `[x, y]` JSON pair as a [`Vector2i`].
fn json_vec2i(v: Option<&serde_json::Value>) -> Option<Vector2i> {
    let arr = v?.as_array()?;
    if arr.len() != 2 {
        return None;
    }
    Some(Vector2i::new(
        arr[0].as_f64()? as i32,
        arr[1].as_f64()? as i32,
    ))
}

/// Applies one property write to `node_id` as an undoable editor command.
///
/// Every TileSet edit goes through `EditorCommand::SetProperty` rather than
/// touching the node directly, so it joins the undo stack and marks the scene
/// modified exactly like an inspector edit — a direct write would save fine and
/// be silently un-undoable.
fn tileset_set_property(
    state: &mut EditorState,
    node_id: NodeId,
    property: String,
    new_value: Variant,
) -> Result<(), String> {
    let mut cmd = EditorCommand::SetProperty {
        node_id,
        property,
        new_value,
        old_value: Variant::Nil,
    };
    cmd.execute(&mut state.scene_tree)
        .map_err(|e| e.to_string())?;
    state.undo_stack.push(cmd);
    state.redo_stack.clear();
    state.scene_modified = true;
    Ok(())
}

/// Adds `source_id` to a node's `PackedInt32Array` id list, preserving order.
///
/// ⚠️ Used for BOTH `__tile_set__source_ids` and `__tile_physics_sources__`,
/// and forgetting the second is the subtle failure this feature invites:
/// `tile_collision_infos` returns an empty vec the moment `physics_sources` is
/// empty, so a perfectly authored collision polygon produces **no body at all**
/// and the tile reads as "collision does not work" rather than "the source was
/// never registered".
/// Drops `source_id` from a `__tile_*_sources__` list (pat-s3rrv.65).
///
/// The mirror of [`tileset_push_source_id`]. Without it a navigation toggle is
/// one-way: `tile_navigation_polygons` keys off the list, so a tile switched
/// back off would keep contributing a walkable region for the rest of the
/// session and after every save.
fn tileset_remove_source_id(
    state: &mut EditorState,
    node_id: NodeId,
    list_property: &str,
    source_id: i32,
) -> Result<(), String> {
    let mut ids = match state
        .scene_tree
        .get_node(node_id)
        .map(|n| n.get_property(list_property))
    {
        Some(Variant::PackedInt32Array(v)) => v,
        _ => return Ok(()),
    };
    if !ids.contains(&source_id) {
        return Ok(());
    }
    ids.retain(|id| *id != source_id);
    tileset_set_property(
        state,
        node_id,
        list_property.to_string(),
        Variant::PackedInt32Array(ids),
    )
}

fn tileset_push_source_id(
    state: &mut EditorState,
    node_id: NodeId,
    list_property: &str,
    source_id: i32,
) -> Result<(), String> {
    let mut ids = match state
        .scene_tree
        .get_node(node_id)
        .map(|n| n.get_property(list_property))
    {
        Some(Variant::PackedInt32Array(v)) => v,
        _ => Vec::new(),
    };
    if ids.contains(&source_id) {
        return Ok(());
    }
    ids.push(source_id);
    ids.sort_unstable();
    tileset_set_property(
        state,
        node_id,
        list_property.to_string(),
        Variant::PackedInt32Array(ids),
    )
}

/// Resolves the `node_id` query/body parameter to a `TileMapLayer` node.
///
/// Rejects a node of the wrong class rather than writing tile companions onto,
/// say, a Sprite2D — those would save into the `.tscn` and be read by nothing.
fn tileset_target_node(state: &EditorState, raw: u64) -> Result<NodeId, (u16, String)> {
    let nid =
        find_node_by_raw_id(&state.scene_tree, raw).ok_or((404, "node not found".to_string()))?;
    let class = state
        .scene_tree
        .get_node(nid)
        .map(|n| n.class_name().to_string())
        .unwrap_or_default();
    if !matches!(class.as_str(), "TileMapLayer" | "TileMap") {
        return Err((
            400,
            format!("node {raw} is a {class}, not a TileMapLayer — tile set companions on it would be read by nothing"),
        ));
    }
    Ok(nid)
}

/// `GET /api/tileset/source?node_id=N` — the atlas sources of a TileMapLayer.
fn api_tileset_source_get(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let raw: u64 = match query_param(query, "node_id").and_then(|v| v.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let s = state.lock().unwrap();
    let nid = match tileset_target_node(&s, raw) {
        Ok(v) => v,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };
    let Some(node) = s.scene_tree.get_node(nid) else {
        send_error(stream, 404, "node not found");
        return;
    };
    let get = |k: &str| node.get_property(k);

    let source_ids = tilemap::tile_set_source_ids(&get(tilemap::TILE_SET_SOURCE_IDS));
    let physics_sources = match get(tilemap::TILE_PHYSICS_SOURCES) {
        Variant::PackedInt32Array(v) => v,
        _ => Vec::new(),
    };
    let tile_size = match get(tilemap::TILE_SET_TILE_SIZE) {
        Variant::Vector2i(v) => v,
        _ => Vector2i::new(16, 16),
    };

    let sources: Vec<serde_json::Value> = source_ids
        .iter()
        .filter_map(|&id| {
            let Variant::String(texture) = get(&tilemap::tile_set_source_key(id, "texture")) else {
                return None;
            };
            let v2 =
                |suffix: &str, dflt: Vector2i| match get(&tilemap::tile_set_source_key(id, suffix))
                {
                    Variant::Vector2i(v) => v,
                    _ => dflt,
                };
            // ⚠️ Computed BEFORE the `json!` call, not inline: a `{ … }` in a
            // value position is parsed by `json!` as a nested JSON object, not
            // as a Rust block.
            let region = v2("texture_region_size", Vector2i::new(16, 16));
            let margins = v2("margins", Vector2i::ZERO);
            let separation = v2("separation", Vector2i::ZERO);
            Some(serde_json::json!({
                "id": id,
                "texture": texture,
                "region_size": [region.x, region.y],
                "margins": [margins.x, margins.y],
                "separation": [separation.x, separation.y],
                "has_collision": physics_sources.contains(&id),
            }))
        })
        .collect();

    send_json(
        stream,
        &serde_json::json!({
            "node_id": raw,
            "tile_size": [tile_size.x, tile_size.y],
            "custom_data_layers": tileset_custom_data_layers(node),
            "sources": sources,
        })
        .to_string(),
    );
}

/// The tile set's custom data layer names, in index order.
fn tileset_custom_data_layers(node: &Node) -> Vec<String> {
    match node.get_property(tilemap::TILE_CUSTOM_DATA_LAYERS) {
        Variant::PackedStringArray(v) => v,
        Variant::Array(items) => items
            .iter()
            .filter_map(|v| match v {
                Variant::String(s) => Some(s.clone()),
                _ => None,
            })
            .collect(),
        _ => Vec::new(),
    }
}

/// `POST /api/tileset/source` — assign an atlas texture to a source id.
///
/// Body: `{"node_id":N,"source_id":S,"texture":"res://atlas.png",
///         "region_size":[16,16],"margins":[0,0],"separation":[0,0],
///         "tile_size":[16,16],"custom_data_layers":["damage"]}`
fn api_tileset_source_set(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let raw = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let source_id = match p.get("source_id").and_then(|v| v.as_i64()) {
        Some(v) => v as i32,
        None => {
            send_error(stream, 400, "missing source_id");
            return;
        }
    };
    let texture = match p.get("texture").and_then(|v| v.as_str()) {
        Some(v) => v.to_string(),
        None => {
            send_error(stream, 400, "missing texture");
            return;
        }
    };

    let mut s = state.lock().unwrap();
    let nid = match tileset_target_node(&s, raw) {
        Ok(v) => v,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };

    // Godot's TileSet defaults: 16x16 cells and 16x16 atlas regions.
    let tile_size = json_vec2i(p.get("tile_size")).unwrap_or(Vector2i::new(16, 16));
    let region = json_vec2i(p.get("region_size")).unwrap_or(Vector2i::new(16, 16));
    let margins = json_vec2i(p.get("margins")).unwrap_or(Vector2i::ZERO);
    let separation = json_vec2i(p.get("separation")).unwrap_or(Vector2i::ZERO);

    let writes: Vec<(String, Variant)> = vec![
        (
            tilemap::TILE_SET_TILE_SIZE.to_string(),
            Variant::Vector2i(tile_size),
        ),
        (
            tilemap::tile_set_source_key(source_id, "texture"),
            Variant::String(texture.clone()),
        ),
        (
            tilemap::tile_set_source_key(source_id, "texture_region_size"),
            Variant::Vector2i(region),
        ),
        (
            tilemap::tile_set_source_key(source_id, "margins"),
            Variant::Vector2i(margins),
        ),
        (
            tilemap::tile_set_source_key(source_id, "separation"),
            Variant::Vector2i(separation),
        ),
    ];
    for (key, value) in writes {
        if let Err(e) = tileset_set_property(&mut s, nid, key, value) {
            send_error(stream, 500, &e);
            return;
        }
    }
    // Without this the source exists but `tile_set_from_properties` never walks
    // it — `source_ids` is the list it iterates.
    if let Err(e) = tileset_push_source_id(&mut s, nid, tilemap::TILE_SET_SOURCE_IDS, source_id) {
        send_error(stream, 500, &e);
        return;
    }

    if let Some(layers) = p.get("custom_data_layers").and_then(|v| v.as_array()) {
        let names: Vec<String> = layers
            .iter()
            .filter_map(|v| v.as_str().map(|s| s.to_string()))
            .collect();
        if let Err(e) = tileset_set_property(
            &mut s,
            nid,
            tilemap::TILE_CUSTOM_DATA_LAYERS.to_string(),
            Variant::PackedStringArray(names),
        ) {
            send_error(stream, 500, &e);
            return;
        }
    }

    s.add_log(
        "info",
        format!("TileSet: atlas source {source_id} -> {texture}"),
    );
    let event =
        format!(r#"{{"type":"tileset_source_changed","node_id":{raw},"source_id":{source_id}}}"#);
    publish_event(&mut s, event);
    send_json(stream, r#"{"ok":true}"#);
}

/// `GET /api/tileset/tile?node_id=N&source_id=S` — the atlas grid and the
/// per-tile data authored on it.
fn api_tileset_tile_get(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let raw: u64 = match query_param(query, "node_id").and_then(|v| v.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let source_id: i32 = match query_param(query, "source_id").and_then(|v| v.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing source_id");
            return;
        }
    };
    let s = state.lock().unwrap();
    let nid = match tileset_target_node(&s, raw) {
        Ok(v) => v,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };
    let Some(node) = s.scene_tree.get_node(nid) else {
        send_error(stream, 404, "node not found");
        return;
    };

    let layers = tileset_custom_data_layers(node);
    // Report every tile that carries authored data. Enumerating the whole atlas
    // grid would need the texture's pixel size, which the editor does not have
    // here; the client draws the grid from `region_size` and overlays these.
    let mut tiles: Vec<serde_json::Value> = Vec::new();
    for (name, value) in node.properties() {
        let Some(atlas) = tilemap::tile_physics_points_atlas(name, source_id) else {
            continue;
        };
        let polygon = match value {
            Variant::PackedVector2Array(pts) => pts.clone(),
            _ => Vec::new(),
        };
        let one_way = matches!(
            node.get_property(&tilemap::tile_physics_one_way_key(source_id, atlas)),
            Variant::Bool(true)
        );
        let custom: serde_json::Map<String, serde_json::Value> = layers
            .iter()
            .filter_map(|layer| {
                let v = node.get_property(&tilemap::tile_custom_data_key(source_id, atlas, layer));
                if v.is_nil() {
                    return None;
                }
                Some((layer.clone(), serde_json::Value::String(v.to_string())))
            })
            .collect();
        tiles.push(serde_json::json!({
            "atlas": [atlas.x, atlas.y],
            "collision": polygon.iter().map(|p| serde_json::json!([p.x, p.y])).collect::<Vec<_>>(),
            "one_way": one_way,
            "custom_data": custom,
        }));
    }
    // Deterministic order so the client's grid does not reshuffle between polls
    // — a HashMap walk over the node's properties is not stable.
    tiles.sort_by_key(|t| {
        let a = &t["atlas"];
        (a[1].as_i64().unwrap_or(0), a[0].as_i64().unwrap_or(0))
    });

    send_json(
        stream,
        &serde_json::json!({
            "node_id": raw,
            "source_id": source_id,
            "custom_data_layers": layers,
            "tiles": tiles,
        })
        .to_string(),
    );
}

/// `POST /api/tileset/tile/data` — set one tile's collision and custom data.
///
/// Body: `{"node_id":N,"source_id":S,"atlas":[0,0],
///         "collision_rect":[x,y,w,h] | "collision_polygon":[[x,y],…] |
///         "full_cell_collision":true | "clear_collision":true,
///         "one_way":false, "custom_data":{"damage":"5"}}`
fn api_tileset_tile_data(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let raw = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let source_id = match p.get("source_id").and_then(|v| v.as_i64()) {
        Some(v) => v as i32,
        None => {
            send_error(stream, 400, "missing source_id");
            return;
        }
    };
    let atlas = json_vec2i(p.get("atlas")).unwrap_or(Vector2i::ZERO);

    let mut s = state.lock().unwrap();
    let nid = match tileset_target_node(&s, raw) {
        Ok(v) => v,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };
    let tile_size = match s
        .scene_tree
        .get_node(nid)
        .map(|n| n.get_property(tilemap::TILE_SET_TILE_SIZE))
    {
        Some(Variant::Vector2i(v)) => v,
        _ => Vector2i::new(16, 16),
    };

    // -- collision ----------------------------------------------------------
    //
    // ⚠️ Points are tile-local and CENTRED on the tile, Godot's convention and
    // what `gdphysics2d::tilemap_collision` expects. `collision_rect_polygon`
    // is the only place that shape is built, so the editor cannot drift from
    // the runtime.
    let mut touched_collision = false;
    if p.get("clear_collision").and_then(|v| v.as_bool()) == Some(true) {
        if let Err(e) = tileset_set_property(
            &mut s,
            nid,
            tilemap::tile_physics_points_key(source_id, atlas),
            Variant::PackedVector2Array(Vec::new()),
        ) {
            send_error(stream, 500, &e);
            return;
        }
        touched_collision = true;
    } else {
        let polygon = if p.get("full_cell_collision").and_then(|v| v.as_bool()) == Some(true) {
            Some(tilemap::full_cell_collision_polygon(tile_size))
        } else if let Some(r) = p.get("collision_rect").and_then(|v| v.as_array()) {
            if r.len() != 4 {
                send_error(stream, 400, "collision_rect must be [x, y, w, h]");
                return;
            }
            let f = |i: usize| r[i].as_f64().unwrap_or(0.0) as f32;
            Some(tilemap::collision_rect_polygon(Rect2::new(
                Vector2::new(f(0), f(1)),
                Vector2::new(f(2), f(3)),
            )))
        } else {
            p.get("collision_polygon")
                .and_then(|v| v.as_array())
                .map(|pts| {
                    pts.iter()
                        .filter_map(|pt| {
                            let a = pt.as_array()?;
                            Some(Vector2::new(
                                a.first()?.as_f64()? as f32,
                                a.get(1)?.as_f64()? as f32,
                            ))
                        })
                        .collect::<Vec<Vector2>>()
                })
        };
        if let Some(polygon) = polygon {
            if let Err(e) = tileset_set_property(
                &mut s,
                nid,
                tilemap::tile_physics_points_key(source_id, atlas),
                Variant::PackedVector2Array(polygon),
            ) {
                send_error(stream, 500, &e);
                return;
            }
            touched_collision = true;
        }
    }

    if let Some(one_way) = p.get("one_way").and_then(|v| v.as_bool()) {
        if let Err(e) = tileset_set_property(
            &mut s,
            nid,
            tilemap::tile_physics_one_way_key(source_id, atlas),
            Variant::Bool(one_way),
        ) {
            send_error(stream, 500, &e);
            return;
        }
        touched_collision = true;
    }

    // ⚠️ THE STEP THAT MAKES IT REAL. `tile_collision_infos` bails out the
    // moment `physics_sources` is empty, so without registering the source the
    // polygon above is stored, saved, reloaded — and produces no body at all.
    if touched_collision {
        if let Err(e) =
            tileset_push_source_id(&mut s, nid, tilemap::TILE_PHYSICS_SOURCES, source_id)
        {
            send_error(stream, 500, &e);
            return;
        }
    }

    // -- navigation ---------------------------------------------------------
    //
    // ⚠️ TWO ways this differs from the collision block above, both easy to get
    // wrong by copying it:
    //
    //  1. Points are tile-local from the TOP-LEFT corner, NOT centred on the
    //     tile. `tile_navigation_polygons` adds the cell's corner to every
    //     point, and the saver rebases to Godot's centred form on the way out.
    //     Sending centred points here puts the walkable area a half-tile off.
    //  2. Patina holds ONE polygon per LAYER, where Godot holds one per
    //     `TileData` — so `atlas` is deliberately not part of the key. Posting a
    //     second tile's polygon REPLACES the first rather than adding to it.
    let mut touched_navigation = false;
    if let Some(points) = p.get("navigation_polygon").and_then(|v| v.as_array()) {
        let polygon: Vec<Vector2> = points
            .iter()
            .filter_map(|pt| {
                let a = pt.as_array()?;
                Some(Vector2::new(
                    a.first()?.as_f64()? as f32,
                    a.get(1)?.as_f64()? as f32,
                ))
            })
            .collect();
        if !polygon.is_empty() && polygon.len() < 3 {
            send_error(stream, 400, "navigation_polygon needs at least 3 points");
            return;
        }
        if let Err(e) = tileset_set_property(
            &mut s,
            nid,
            tilemap::TILE_NAV_POLYGON.to_string(),
            Variant::PackedVector2Array(polygon),
        ) {
            send_error(stream, 500, &e);
            return;
        }
        touched_navigation = true;
    }
    match p.get("navigation").and_then(|v| v.as_bool()) {
        // ⚠️ THE STEP THAT MAKES IT REAL, the navigation twin of the physics
        // source registration above: `tile_navigation_polygons` returns nothing
        // at all while the source list is empty, so a polygon stored without
        // this produces no walkable region — saved, reloaded, and inert.
        Some(true) => touched_navigation = true,
        Some(false) => {
            if let Err(e) =
                tileset_remove_source_id(&mut s, nid, tilemap::TILE_NAV_SOURCES, source_id)
            {
                send_error(stream, 500, &e);
                return;
            }
            touched_navigation = false;
        }
        None => {}
    }
    if touched_navigation {
        if let Err(e) = tileset_push_source_id(&mut s, nid, tilemap::TILE_NAV_SOURCES, source_id) {
            send_error(stream, 500, &e);
            return;
        }
    }

    // -- occlusion ----------------------------------------------------------
    //
    // The occlusion twin of the navigation block above, and deliberately the
    // same shape: `tilemap.rs` documents `__tile_occluder_polygon__` as
    // TOP-LEFT relative like the navigation polygon (NOT tile-centred like the
    // physics points), one polygon per LAYER, and an empty polygon meaning
    // "the whole tile occludes" — Godot's default for an occlusion-enabled
    // tile.
    //
    // ⚠️ The saver and the loader have both handled occlusion since this bead's
    // first pass; only this route was missing, so a scene could carry tile
    // occlusion that no editor action could author (pat-s3rrv.65).
    let mut touched_occlusion = false;
    if let Some(points) = p.get("occluder_polygon").and_then(|v| v.as_array()) {
        let polygon: Vec<Vector2> = points
            .iter()
            .filter_map(|pt| {
                let a = pt.as_array()?;
                Some(Vector2::new(
                    a.first()?.as_f64()? as f32,
                    a.get(1)?.as_f64()? as f32,
                ))
            })
            .collect();
        if !polygon.is_empty() && polygon.len() < 3 {
            send_error(stream, 400, "occluder_polygon needs at least 3 points");
            return;
        }
        if let Err(e) = tileset_set_property(
            &mut s,
            nid,
            tilemap::TILE_OCCLUDER_POLYGON.to_string(),
            Variant::PackedVector2Array(polygon),
        ) {
            send_error(stream, 500, &e);
            return;
        }
        touched_occlusion = true;
    }
    match p.get("occlusion").and_then(|v| v.as_bool()) {
        // ⚠️ The step that makes it real, exactly as for navigation:
        // `tile_occluder_polygons` returns nothing at all while the source list
        // is empty, so a polygon stored without this is saved, reloaded, and
        // casts no shadow.
        Some(true) => touched_occlusion = true,
        Some(false) => {
            if let Err(e) =
                tileset_remove_source_id(&mut s, nid, tilemap::TILE_OCCLUDER_SOURCES, source_id)
            {
                send_error(stream, 500, &e);
                return;
            }
            touched_occlusion = false;
        }
        None => {}
    }
    if touched_occlusion {
        if let Err(e) =
            tileset_push_source_id(&mut s, nid, tilemap::TILE_OCCLUDER_SOURCES, source_id)
        {
            send_error(stream, 500, &e);
            return;
        }
    }

    // -- custom data --------------------------------------------------------
    if let Some(map) = p.get("custom_data").and_then(|v| v.as_object()) {
        let mut layers = s
            .scene_tree
            .get_node(nid)
            .map(tileset_custom_data_layers)
            .unwrap_or_default();
        for (layer, value) in map {
            let variant = match value {
                serde_json::Value::Bool(b) => Variant::Bool(*b),
                serde_json::Value::Number(n) if n.is_i64() => Variant::Int(n.as_i64().unwrap_or(0)),
                serde_json::Value::Number(n) => Variant::Float(n.as_f64().unwrap_or(0.0)),
                other => Variant::String(match other.as_str() {
                    Some(t) => t.to_string(),
                    None => other.to_string(),
                }),
            };
            if let Err(e) = tileset_set_property(
                &mut s,
                nid,
                tilemap::tile_custom_data_key(source_id, atlas, layer),
                variant,
            ) {
                send_error(stream, 500, &e);
                return;
            }
            // A value on an undeclared layer is unreachable from script:
            // `TileData.get_custom_data(name)` looks the name up in the layer
            // list, so declare it on first use rather than storing an orphan.
            if !layers.iter().any(|l| l == layer) {
                layers.push(layer.clone());
                if let Err(e) = tileset_set_property(
                    &mut s,
                    nid,
                    tilemap::TILE_CUSTOM_DATA_LAYERS.to_string(),
                    Variant::PackedStringArray(layers.clone()),
                ) {
                    send_error(stream, 500, &e);
                    return;
                }
            }
        }
    }

    s.add_log(
        "info",
        format!(
            "TileSet: tile ({}, {}) of source {source_id}",
            atlas.x, atlas.y
        ),
    );
    let event = format!(
        r#"{{"type":"tileset_tile_changed","node_id":{raw},"source_id":{source_id},"atlas":[{},{}]}}"#,
        atlas.x, atlas.y
    );
    publish_event(&mut s, event);
    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// pat-r5p: Transform gizmo - axis-constrained drag, rotate, scale
// ---------------------------------------------------------------------------

/// `POST /api/viewport/drag_axis` -- drag constrained to X or Y axis.
fn api_viewport_drag_axis(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let dx = p.get("dx").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let dy = p.get("dy").and_then(|v| v.as_f64()).unwrap_or(0.0) as f32;
    let axis = p
        .get("axis")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let mut s = state.lock().unwrap();
    let z = s.viewport_zoom as f32;
    let (wdx, wdy) = match axis.as_str() {
        "x" => (dx / z, 0.0),
        "y" => (0.0, dy / z),
        _ => (dx / z, dy / z),
    };
    if let Some(nid) = s.selected_node {
        let cur_pos = s
            .scene_tree
            .get_node(nid)
            .map(|n| match n.get_property("position") {
                Variant::Vector2(v) => v,
                _ => Vector2::ZERO,
            })
            .unwrap_or(Vector2::ZERO);
        let candidate = Vector2::new(cur_pos.x + wdx, cur_pos.y + wdy);
        let settings = s.display_settings.clone();
        let (new_pos, guides) = apply_snap(&s.scene_tree, &settings, &s.guides, nid, candidate);
        s.snap_guides = guides;
        if let Some(n) = s.scene_tree.get_node_mut(nid) {
            n.set_property("position", Variant::Vector2(new_pos));
        }
    }
    s.transform_axis_constraint = if axis.is_empty() { None } else { Some(axis) };
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/viewport/rotate_node` -- rotate the selected node.
fn api_viewport_rotate_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let delta_angle = p.get("delta").and_then(|v| v.as_f64()).unwrap_or(0.0);
    let mut s = state.lock().unwrap();
    if let Some(nid) = s.selected_node {
        if let Some(n) = s.scene_tree.get_node_mut(nid) {
            let rotation = match n.get_property("rotation") {
                Variant::Float(v) => v,
                _ => 0.0,
            };
            n.set_property("rotation", Variant::Float(rotation + delta_angle));
        }
        send_json(stream, r#"{"ok":true}"#);
    } else {
        send_error(stream, 400, "no node selected");
    }
}

/// `POST /api/viewport/scale_node` -- scale the selected node.
fn api_viewport_scale_node(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let sx = p.get("sx").and_then(|v| v.as_f64()).unwrap_or(1.0);
    let sy = p.get("sy").and_then(|v| v.as_f64()).unwrap_or(1.0);
    let mut s = state.lock().unwrap();
    if let Some(nid) = s.selected_node {
        if let Some(n) = s.scene_tree.get_node_mut(nid) {
            let scale = match n.get_property("scale") {
                Variant::Vector2(v) => v,
                _ => Vector2::new(1.0, 1.0),
            };
            n.set_property(
                "scale",
                Variant::Vector2(Vector2::new(
                    (scale.x as f64 * sx) as f32,
                    (scale.y as f64 * sy) as f32,
                )),
            );
        }
        send_json(stream, r#"{"ok":true}"#);
    } else {
        send_error(stream, 400, "no node selected");
    }
}

// ---------------------------------------------------------------------------
// @tool scripts + addon EditorPlugins (pat-0q2kx.76)
//
// In Godot a `@tool` script executes in the EDITOR as well as at runtime, and
// enabling an addon instantiates the EditorPlugin named by its `plugin.cfg`,
// with the enabled list persisted to `project.godot [editor_plugins]`.
//
// Patina had neither: `api_toggle_plugin` flipped a bool on a list that was
// initialised empty and never populated from disk, so the toggle could not even
// find a plugin to flip, and no `@tool` code ran in edit mode at all.
// ---------------------------------------------------------------------------

/// Reads `project.godot`, applies `edit`, and writes it back.
///
/// Returns false when the project has no readable `project.godot` — callers
/// treat that as "nothing to persist to" rather than an error, so an editor
/// session with no project open still toggles in memory.
fn update_project_file(project_root: &str, edit: impl FnOnce(&mut GodotProjectFile)) -> bool {
    let path = std::path::Path::new(project_root).join("project.godot");
    let Ok(text) = std::fs::read_to_string(&path) else {
        return false;
    };
    let Ok(mut pf) = GodotProjectFile::parse(&text) else {
        return false;
    };
    edit(&mut pf);
    std::fs::write(&path, pf.to_text()).is_ok()
}

/// The `[editor_plugins] enabled` list, or empty when there is no project file.
fn enabled_plugin_paths(project_root: &str) -> Vec<String> {
    let path = std::path::Path::new(project_root).join("project.godot");
    std::fs::read_to_string(path)
        .ok()
        .and_then(|t| GodotProjectFile::parse(&t).ok())
        .map(|pf| pf.enabled_editor_plugins())
        .unwrap_or_default()
}

/// Scans `addons/*/plugin.cfg` and builds the plugin list.
///
/// ⚠️ This is the step that was missing entirely: `state.plugins` started as
/// `Vec::new()` and nothing ever filled it, so `POST /api/plugins/toggle`
/// always answered 404 no matter what the project contained.
fn discover_plugins(project_root: &str) -> Vec<PluginEntry> {
    let enabled = enabled_plugin_paths(project_root);
    let addons = std::path::Path::new(project_root).join("addons");
    let Ok(entries) = std::fs::read_dir(&addons) else {
        return Vec::new();
    };
    let mut found: Vec<PluginEntry> = Vec::new();
    for entry in entries.flatten() {
        let dir = entry.path();
        let cfg = dir.join("plugin.cfg");
        if !cfg.is_file() {
            continue;
        }
        let Some(folder) = dir.file_name().and_then(|f| f.to_str()) else {
            continue;
        };
        // plugin.cfg is the same INI dialect as project.godot, so it reuses the
        // same parser rather than growing a second one.
        let text = std::fs::read_to_string(&cfg).unwrap_or_default();
        let pf = GodotProjectFile::parse(&text).unwrap_or(GodotProjectFile {
            sections: HashMap::new(),
        });
        let unquote = |v: Option<&str>| v.unwrap_or("").trim().trim_matches('"').to_string();
        let name = {
            let n = unquote(pf.get("plugin", "name"));
            if n.is_empty() {
                folder.to_string()
            } else {
                n
            }
        };
        let res_cfg = format!("res://addons/{folder}/plugin.cfg");
        found.push(PluginEntry {
            enabled: enabled.iter().any(|p| p == &res_cfg),
            name,
            folder: folder.to_string(),
            cfg_path: res_cfg,
            script: unquote(pf.get("plugin", "script")),
            description: unquote(pf.get("plugin", "description")),
            version: unquote(pf.get("plugin", "version")),
        });
    }
    // Stable order so the settings list does not reshuffle between requests.
    found.sort_by(|a, b| a.folder.cmp(&b.folder));
    found
}

/// Instantiates an enabled plugin's EditorPlugin script and starts it.
///
/// Godot calls `_enter_tree` then `_enable_plugin` when a plugin is switched on
/// (`editor/plugins/editor_plugin.cpp`). Whatever the script prints is routed to
/// the Output panel, which is how a user sees that their addon actually ran.
fn start_editor_plugin(state: &mut EditorState, folder: &str, script: &str) {
    let Some(root) = state.project_root.clone() else {
        return;
    };
    if script.is_empty() {
        state.add_log(
            "warn",
            format!("Plugin '{folder}' has no script= in plugin.cfg; nothing to run"),
        );
        return;
    }
    // `script=` is relative to the addon folder (Godot's convention).
    let path = std::path::Path::new(&root)
        .join("addons")
        .join(folder)
        .join(script.trim_start_matches("res://"));
    let source = match std::fs::read_to_string(&path) {
        Ok(s) => s,
        Err(e) => {
            state.add_log(
                "error",
                format!("Plugin '{folder}': cannot read {}: {e}", path.display()),
            );
            return;
        }
    };
    // The plugin is not a scene node, so it gets the edit tree's root as its
    // host id — enough for `get_node`-free plugin code, which is what an
    // EditorPlugin's _enter_tree normally is.
    let host = state.scene_tree.root_id();
    let mut instance = match GDScriptNodeInstance::from_source(&source, host) {
        Ok(i) => i,
        Err(e) => {
            state.add_log("error", format!("Plugin '{folder}' parse error: {e}"));
            return;
        }
    };
    for method in ["_enter_tree", "_enable_plugin"] {
        if instance.has_method(method) {
            if let Err(e) = instance.call_method(method, &[]) {
                state.add_log("error", format!("Plugin '{folder}' {method} failed: {e:?}"));
            }
        }
    }
    for line in instance.take_output() {
        state.add_log("info", line);
    }
    state.add_log("info", format!("Plugin enabled: {folder}"));
    state.active_plugins.insert(folder.to_string(), instance);
}

/// Mirrors Godot's `_disable_plugin` / `_exit_tree` on switch-off.
fn stop_editor_plugin(state: &mut EditorState, folder: &str) {
    let Some(mut instance) = state.active_plugins.remove(folder) else {
        return;
    };
    for method in ["_disable_plugin", "_exit_tree"] {
        if instance.has_method(method) {
            let _ = instance.call_method(method, &[]);
        }
    }
    for line in instance.take_output() {
        state.add_log("info", line);
    }
    state.add_log("info", format!("Plugin disabled: {folder}"));
}

/// Refreshes the plugin list from disk and starts everything already enabled.
///
/// Called when a project is opened, so an enabled plugin survives a server
/// restart — the bead's persistence clause is only observable through this.
fn sync_plugins_from_project(state: &mut EditorState) {
    let Some(root) = state.project_root.clone() else {
        return;
    };
    state.plugins = discover_plugins(&root);
    let to_start: Vec<(String, String)> = state
        .plugins
        .iter()
        .filter(|p| p.enabled)
        .map(|p| (p.folder.clone(), p.script.clone()))
        .collect();
    for (folder, script) in to_start {
        start_editor_plugin(state, &folder, &script);
    }
}

/// Instantiates the `@tool` scripts in the current EDIT tree and runs `_ready`.
///
/// Godot runs a `@tool` script in the editor exactly as it would at runtime; a
/// script WITHOUT the annotation stays inert while editing, which is why this
/// filters on `is_tool()` rather than attaching everything.
fn sync_tool_scripts_from_scene(state: &mut EditorState) {
    // A `@tool` script running here is running *in the editor*, which is
    // exactly what `Engine.is_editor_hint()` reports. Nothing set this flag
    // before, so every tool script saw `false` and took its runtime branch
    // (pat-0q2kx.121).
    gdscript_interop::set_engine_editor_hint(true);
    // Dropping the previous scene's instances is what stops a closed scene's
    // tool script from continuing to tick against a tree it no longer belongs
    // to.
    state.tool_scripts.clear();
    let Some(root) = state.project_root.clone() else {
        return;
    };

    let mut candidates: Vec<(NodeId, String)> = Vec::new();
    for node_id in state.scene_tree.all_nodes_in_tree_order() {
        if let Some(node) = state.scene_tree.get_node(node_id) {
            if let Variant::String(res_path) = node.get_property("_script_path") {
                candidates.push((node_id, res_path));
            }
        }
    }

    for (node_id, res_path) in candidates {
        let relative = res_path.strip_prefix("res://").unwrap_or(&res_path);
        let path = std::path::Path::new(&root).join(relative);
        let Ok(source) = std::fs::read_to_string(&path) else {
            continue;
        };
        let mut instance = match GDScriptNodeInstance::from_source(&source, node_id) {
            Ok(i) => i,
            Err(e) => {
                state.add_log("error", format!("@tool parse error in {res_path}: {e}"));
                continue;
            }
        };
        if !instance.is_tool() {
            continue;
        }
        if instance.has_method("_ready") {
            if let Err(e) = instance.call_method("_ready", &[]) {
                state.add_log("error", format!("@tool {res_path} _ready failed: {e:?}"));
            }
        }
        for line in instance.take_output() {
            state.add_log("info", line);
        }
        state.tool_scripts.insert(node_id, instance);
    }
}

/// Ticks every running `@tool` script's `_process` against the edit tree.
///
/// Godot drives tool scripts from the editor's idle frame, which is what lets an
/// `@tool` `_process` animate something in the edit viewport.
pub fn process_tool_scripts(state: &mut EditorState, delta: f64) {
    // Same as the `_ready` path: an editor idle tick is editor context, so
    // `Engine.is_editor_hint()` must be true inside `_process` (pat-0q2kx.121).
    gdscript_interop::set_engine_editor_hint(true);
    let ids: Vec<NodeId> = state.tool_scripts.keys().copied().collect();
    let mut output: Vec<String> = Vec::new();
    for id in ids {
        let Some(instance) = state.tool_scripts.get_mut(&id) else {
            continue;
        };
        if !instance.has_method("_process") {
            continue;
        }
        let err = instance
            .call_method("_process", &[Variant::Float(delta)])
            .err();
        output.extend(instance.take_output());
        if let Some(e) = err {
            output.push(format!("@tool _process failed: {e:?}"));
        }
    }
    for line in output {
        state.add_log("info", line);
    }
}

/// `GET /api/plugins` — returns the list of registered editor plugins.
fn api_get_plugins(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    // pat-s3rrv.66: `_get_plugin_name` and `_has_main_screen` are answered by
    // the plugin SCRIPT, so they can only be read off the live instance —
    // `plugin.cfg` carries neither. A plugin that is listed but not enabled has
    // no instance, and keeps its cfg name.
    let folders: Vec<String> = s.plugins.iter().map(|p| p.folder.clone()).collect();
    let mut rows: Vec<serde_json::Value> = Vec::with_capacity(folders.len());
    for (i, folder) in folders.iter().enumerate() {
        let mut row = match serde_json::to_value(&s.plugins[i]) {
            Ok(v) => v,
            Err(_) => continue,
        };
        if s.active_plugins.contains_key(folder) {
            let name = plugin_display_name(&mut s, folder);
            let main_screen = plugin_has_main_screen(&mut s, folder);
            if let Some(obj) = row.as_object_mut() {
                obj.insert("name".to_string(), serde_json::Value::String(name));
                obj.insert(
                    "main_screen".to_string(),
                    serde_json::Value::Bool(main_screen),
                );
            }
        }
        rows.push(row);
    }
    let j = serde_json::to_string(&rows).unwrap_or_else(|_| "[]".to_string());
    send_json(stream, &format!(r#"{{"plugins":{j}}}"#));
}

// ---------------------------------------------------------------------------
// pat-sbdts: Editor settings dialog — keybindings + plugin toggle endpoints
// ---------------------------------------------------------------------------

/// `GET /api/keybindings` -- returns the list of editor keybindings.
fn api_get_keybindings(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    let j = serde_json::to_string(&s.keybindings).unwrap_or_else(|_| "[]".to_string());
    send_json(stream, &format!(r#"{{"keybindings":{j}}}"#));
}

/// `POST /api/keybindings` -- update a single keybinding by action name.
/// Body: `{"action":"undo","keys":"Ctrl+Shift+Z"}`
fn api_set_keybinding(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let action = match p.get("action").and_then(|v| v.as_str()) {
        Some(a) => a,
        None => {
            send_error(stream, 400, "missing 'action'");
            return;
        }
    };
    let keys = match p.get("keys").and_then(|v| v.as_str()) {
        Some(k) => k,
        None => {
            send_error(stream, 400, "missing 'keys'");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    if let Some(kb) = s.keybindings.iter_mut().find(|kb| kb.action == action) {
        kb.keys = keys.to_string();
        send_json(stream, r#"{"ok":true}"#);
    } else {
        send_error(stream, 404, "keybinding action not found");
    }
}

/// `POST /api/plugins/toggle` -- toggle a plugin's enabled state.
/// Body: `{"name":"Tilemap","enabled":true}`
fn api_toggle_plugin(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let name = match p.get("name").and_then(|v| v.as_str()) {
        Some(n) => n,
        None => {
            send_error(stream, 400, "missing 'name'");
            return;
        }
    };
    let enabled = match p.get("enabled").and_then(|v| v.as_bool()) {
        Some(e) => e,
        None => {
            send_error(stream, 400, "missing 'enabled'");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    // Accept the display name, the folder, or the cfg path: the settings UI
    // shows the name, while `project.godot` and Godot's own API speak in cfg
    // paths.
    let found = s
        .plugins
        .iter_mut()
        .find(|pl| pl.name == name || pl.folder == name || pl.cfg_path == name);
    let Some(plugin) = found else {
        send_error(stream, 404, "plugin not found");
        return;
    };
    plugin.enabled = enabled;
    let folder = plugin.folder.clone();
    let script = plugin.script.clone();

    // Persist the whole enabled set, not just this entry: `[editor_plugins]
    // enabled` is one array, so it has to be rewritten as a unit.
    let paths: Vec<String> = s
        .plugins
        .iter()
        .filter(|p| p.enabled)
        .map(|p| p.cfg_path.clone())
        .collect();
    let mut persisted = false;
    if let Some(root) = s.project_root.clone() {
        persisted = update_project_file(&root, |pf| pf.set_enabled_editor_plugins(&paths));
    }

    if enabled {
        start_editor_plugin(&mut s, &folder, &script);
    } else {
        stop_editor_plugin(&mut s, &folder);
    }
    send_json(
        stream,
        &format!(r#"{{"ok":true,"enabled":{enabled},"persisted":{persisted}}}"#),
    );
}

