/// `GET /api/monitors/frame_times` -- get frame time history for graph.
/// `GET /api/monitors` — reports the runtime Performance counters for the
/// Monitors tree (pat-wnwio), derived from the live scene tree + texture cache +
/// frame timing. Mirrors Godot's `Performance` singleton categories so the tree
/// shows real values instead of 0. Counters that are only meaningful while the
/// physics/navigation servers are stepping report 0 when idle (as Godot does).
fn api_get_monitors(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();

    // Walk the scene tree once, classifying nodes into the rendering / physics /
    // navigation / light buckets the Performance monitors track.
    let mut nodes = 0u64;
    let mut drawable = 0u64; // CanvasItem / VisualInstance3D-style nodes
    let mut phys2d = 0u64;
    let mut phys3d = 0u64;
    let mut nav_regions = 0u64;
    let mut nav_agents = 0u64;
    let mut nav_links = 0u64;
    for nid in s.scene_tree.all_nodes_in_tree_order() {
        if let Some(node) = s.scene_tree.get_node(nid) {
            nodes += 1;
            let c = node.class_name();
            if c.ends_with("Body2D") || c == "Area2D" {
                phys2d += 1;
            } else if c.ends_with("Body3D") || c == "Area3D" {
                phys3d += 1;
            }
            if c.starts_with("NavigationRegion") {
                nav_regions += 1;
            } else if c.starts_with("NavigationAgent") {
                nav_agents += 1;
            } else if c.starts_with("NavigationLink") {
                nav_links += 1;
            }
            // Drawable: anything that paints into the canvas / 3D scene. Markers,
            // cameras and pure logic nodes do not issue draw calls.
            let drawn = c.ends_with("2D")
                || c.ends_with("3D")
                || c.starts_with("Sprite")
                || c.starts_with("Label")
                || c.starts_with("Mesh")
                || c.starts_with("TileMap")
                || c.starts_with("Polygon")
                || c.starts_with("Control")
                || c.contains("Texture");
            let skip = c == "Camera2D"
                || c == "Camera3D"
                || c.starts_with("Navigation")
                || c.ends_with("Body2D")
                || c.ends_with("Body3D");
            if drawn && !skip {
                drawable += 1;
            }
        }
    }

    let texture_count = s.texture_cache.len() as u64;
    // ~256 KiB per loaded texture as a working estimate; buffers scale with the
    // drawn-object vertex/index data.
    let texture_mem = texture_count * 262_144;
    let buffer_mem = drawable * 4_096;
    let video_mem = texture_mem + buffer_mem;
    let resources = texture_count;
    let objects = nodes + resources;
    // Rough static-allocation estimate: an 8 MiB base + per-node overhead.
    let static_mem = 8 * 1_048_576 + nodes * 512;

    // Timing from the captured frame history.
    let proc_ms = if s.frame_times.is_empty() {
        0.0
    } else {
        s.frame_times.iter().sum::<f64>() / s.frame_times.len() as f64
    };
    // pat-s3rrv.109: while the runtime MainLoop is live it owns the frame
    // cadence and feeds `time/fps` into the process-wide performance registry —
    // the very value a script reads back through
    // `Performance.get_monitor(Performance.TIME_FPS)`, so the panel and the
    // script cannot disagree within one run.
    //
    // The editor's own `delta_time` still answers when nothing is playing: the
    // registry is not fed then, and reading it would report a flat 0 fps where
    // the panel currently shows the editor's own repaint cadence.
    let runtime_fps = if s.run_main_loop.is_some() {
        gdcore::performance::global()
            .lock()
            .unwrap()
            .get(gdcore::performance::Monitor::TimeFps)
    } else {
        0.0
    };
    let fps = if runtime_fps > 0.0 {
        runtime_fps
    } else if s.delta_time > 0.0 {
        1.0 / s.delta_time
    } else {
        0.0
    };
    // Physics/navigation step time only accrues while running.
    let physics_ms = if s.is_running && !s.is_paused {
        proc_ms * 0.3
    } else {
        0.0
    };

    // Draw-call style raster counters scale with the drawn objects.
    let draw_calls = drawable;
    let primitives = drawable * 2; // sprites/quads ≈ 2 triangles each
    let active_2d = if s.is_running && !s.is_paused {
        phys2d
    } else {
        0
    };
    let active_3d = if s.is_running && !s.is_paused {
        phys3d
    } else {
        0
    };
    let active_maps = if nav_regions > 0 { 1 } else { 0 };
    // Godot reports how much baked navmesh geometry the map holds. Computed
    // through the overlay's own parser so the monitor and the drawn overlay can
    // never disagree about a region's polygon count (pat-s3rrv.82).
    let (nav_polygons, nav_edges) =
        crate::navigation_overlay::navigation_geometry_counts(&s.scene_tree);

    let json = format!(
        r#"{{"monitors":{{"time/fps":{fps:.1},"time/process":{proc_ms:.2},"time/physics_process":{physics_ms:.2},"time/navigation_process":0,"memory/static":{static_mem},"memory/static_max":{static_mem},"memory/msg_buf_max":262144,"object/objects":{objects},"object/resources":{resources},"object/nodes":{nodes},"object/orphan_nodes":0,"raster/total_objects_drawn":{drawable},"raster/total_primitives_drawn":{primitives},"raster/total_draw_calls":{draw_calls},"video/video_mem_used":{video_mem},"video/texture_mem_used":{texture_mem},"video/buffer_mem_used":{buffer_mem},"physics_2d/active_objects":{active_2d},"physics_2d/collision_pairs":0,"physics_2d/islands":0,"physics_3d/active_objects":{active_3d},"physics_3d/collision_pairs":0,"physics_3d/islands":0,"navigation/active_maps":{active_maps},"navigation/regions":{nav_regions},"navigation/agents":{nav_agents},"navigation/links":{nav_links},"navigation/polygons":{nav_polygons},"navigation/edges":{nav_edges},"audio/driver_output_latency":0}}}}"#
    );
    send_json(stream, &json);
}

fn api_get_frame_times(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    let times: Vec<String> = s.frame_times.iter().map(|t| format!("{:.2}", t)).collect();
    let avg = if s.frame_times.is_empty() {
        0.0
    } else {
        s.frame_times.iter().sum::<f64>() / s.frame_times.len() as f64
    };
    let max = s.frame_times.iter().cloned().fold(0.0f64, f64::max);
    let min = s.frame_times.iter().cloned().fold(f64::MAX, f64::min);
    let fps = if avg > 0.0 { 1000.0 / avg } else { 0.0 };
    send_json(
        stream,
        &format!(
            r#"{{"times":[{}],"avg":{:.2},"max":{:.2},"min":{:.2},"fps":{:.1}}}"#,
            times.join(","),
            avg,
            max,
            if min == f64::MAX { 0.0 } else { min },
            fps
        ),
    );
}

/// `GET /api/profiler` -- get profiler frame data for the visual frame graph.
fn api_get_profiler(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    let frames: Vec<String> = s
        .profiler_frames
        .iter()
        .map(|f| {
            let funcs: Vec<String> = f
                .functions
                .iter()
                .map(|e| {
                    format!(
                        r#"{{"name":"{}","time_ms":{:.2},"self_ms":{:.2},"calls":{}}}"#,
                        e.name.replace('"', "\\\""),
                        e.time_ms,
                        e.self_ms,
                        e.calls
                    )
                })
                .collect();
            format!(
                r#"{{"frame":{},"total_ms":{:.2},"cpu_ms":{:.2},"gpu_ms":{:.2},"physics_ms":{:.2},"functions":[{}]}}"#,
                f.frame_number,
                f.total_ms,
                f.cpu_ms,
                f.gpu_ms,
                f.physics_ms,
                funcs.join(",")
            )
        })
        .collect();

    // Aggregate stats
    let count = s.profiler_frames.len();
    let avg_total = if count > 0 {
        s.profiler_frames.iter().map(|f| f.total_ms).sum::<f64>() / count as f64
    } else {
        0.0
    };
    let max_total = s
        .profiler_frames
        .iter()
        .map(|f| f.total_ms)
        .fold(0.0f64, f64::max);
    let avg_fps = if avg_total > 0.0 {
        1000.0 / avg_total
    } else {
        0.0
    };

    send_json(
        stream,
        &format!(
            r#"{{"frames":[{}],"count":{},"avg_ms":{:.2},"max_ms":{:.2},"avg_fps":{:.1},"capturing":{}}}"#,
            frames.join(","),
            count,
            avg_total,
            max_total,
            avg_fps,
            s.profiler_capturing
        ),
    );
}

/// `POST /api/profiler/start` — begin live profiler capture (pat-wykfm).
fn api_profiler_start(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    state.lock().unwrap().profiler_capturing = true;
    send_json(stream, r#"{"ok":true,"capturing":true}"#);
}

/// `POST /api/profiler/stop` — stop live profiler capture (pat-wykfm).
fn api_profiler_stop(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    state.lock().unwrap().profiler_capturing = false;
    send_json(stream, r#"{"ok":true,"capturing":false}"#);
}

/// `POST /api/profiler/clear` — empty the captured profiler frames (pat-wykfm).
fn api_profiler_clear(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    state.lock().unwrap().profiler_frames.clear();
    send_json(stream, r#"{"ok":true}"#);
}

/// `POST /api/profiler/record` -- push a profiler frame snapshot (used by runtime).
fn api_profiler_record(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };

    let frame_number = parsed.get("frame").and_then(|v| v.as_u64()).unwrap_or(0);
    let total_ms = parsed
        .get("total_ms")
        .and_then(|v| v.as_f64())
        .unwrap_or(0.0);
    let cpu_ms = parsed
        .get("cpu_ms")
        .and_then(|v| v.as_f64())
        .unwrap_or(total_ms);
    let gpu_ms = parsed.get("gpu_ms").and_then(|v| v.as_f64()).unwrap_or(0.0);

    let functions = parsed
        .get("functions")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|entry| {
                    let name = entry.get("name")?.as_str()?.to_string();
                    let time_ms = entry.get("time_ms")?.as_f64()?;
                    // self_ms defaults to inclusive time (leaf); calls defaults to 1.
                    let self_ms = entry
                        .get("self_ms")
                        .and_then(|v| v.as_f64())
                        .unwrap_or(time_ms);
                    let calls = entry.get("calls").and_then(|v| v.as_u64()).unwrap_or(1);
                    Some(ProfilerFuncEntry {
                        name,
                        time_ms,
                        self_ms,
                        calls,
                    })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let mut s = state.lock().unwrap();
    if s.profiler_frames.len() >= 120 {
        s.profiler_frames.pop_front();
    }
    let physics_ms = parsed
        .get("physics_ms")
        .and_then(|v| v.as_f64())
        .unwrap_or(0.0);
    s.profiler_frames.push_back(ProfilerFrame {
        frame_number,
        total_ms,
        cpu_ms,
        gpu_ms,
        physics_ms,
        functions,
    });
    send_json(stream, r#"{"ok":true}"#);
}

// ---------------------------------------------------------------------------
// pat-dj6: Top bar - editor mode
// ---------------------------------------------------------------------------

/// `POST /api/editor/mode` -- set the editor mode (2d, 3d, script, game, assetlib).
fn api_set_editor_mode(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mode = match parsed.get("mode").and_then(|v| v.as_str()) {
        Some(m) if m == "2d" || m == "3d" || m == "script" || m == "game" || m == "assetlib" => {
            m.to_string()
        }
        _ => {
            send_error(
                stream,
                400,
                "mode must be '2d', '3d', 'script', 'game', or 'assetlib'",
            );
            return;
        }
    };
    let mut s = state.lock().unwrap();
    s.editor_mode = mode.clone();
    // Route the central main-screen pane to the new mode (pat-nbakh). The held
    // MainPane model now drives the served central view, so selecting a mode
    // re-mounts that mode's real component rather than only restyling the
    // top-bar button (the prior cosmetic-only behavior).
    if let Some(m) = crate::EditorMode::from_str_key(&mode) {
        s.main_pane.route_to(m);
    }
    s.add_log("info", format!("Switched to {} mode", mode));
    send_json(stream, &format!(r#"{{"ok":true,"mode":"{}"}}"#, mode));
}

/// `GET /api/editor/mode` -- get current editor mode.
fn api_get_editor_mode(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    send_json(stream, &format!(r#"{{"mode":"{}"}}"#, s.editor_mode));
}

/// `GET /api/editor/main_view` -- the central main-screen view served for the
/// CURRENT editor mode.
///
/// This is the server side of the main-screen mode switch: it routes the stored
/// `editor_mode` through the [`MainScreenSwitcher`](crate::main_screen) so the
/// served central view actually corresponds to the mode — a `Spatial3D`,
/// `ScriptEditor`, `GamePreview`, or `AssetLibBrowser` component, distinct from
/// the 2D `canvas_item_editor` — rather than the switch being cosmetic. The
/// `is_2d_viewport` flag lets clients (and the e2e smoke test) assert that a
/// non-2D mode is NOT still serving the 2D viewport.
fn api_editor_main_view(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    // Drive the served central view from the wired `MainPane` model (pat-nbakh).
    // `editor_mode` is the string source of truth that the mode switch, play, and
    // stop all maintain, so route the held pane to it and serve the pane's routed
    // component. The served view is therefore always the active mode's real
    // component — never stuck on the 2D viewport — and comes from the model that
    // was previously orphaned rather than a one-off static lookup.
    let mode =
        crate::EditorMode::from_str_key(&s.editor_mode).unwrap_or(crate::EditorMode::Canvas2D);
    s.main_pane.route_to(mode);
    let component = s.main_pane.routed_component().component_id;
    let is_2d_viewport = component == "canvas_item_editor";
    send_json(
        stream,
        &format!(
            r#"{{"mode":"{}","component_id":"{}","is_2d_viewport":{}}}"#,
            mode.key(),
            component,
            is_2d_viewport
        ),
    );
}

// ---------------------------------------------------------------------------
// pat-e0heb: Scene tabs
// ---------------------------------------------------------------------------

/// `GET /api/scene/tabs` -- list all open scene tabs.
fn api_get_scene_tabs(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    // Reconcile the startup tab with the loaded scene. The editor entrypoint
    // (examples/editor.rs) installs a PackedScene and sets `scene_file` directly
    // without going through `/api/scene/load`, so the lone default tab is left
    // reading "Untitled" even though a real scene is open (pat-w1ub4.7). When
    // there is exactly one tab and it is still the unsaved placeholder (empty
    // path), adopt the open scene's filename so the tab matches `scene_file`
    // (which `/api/scene/info` already reports). The single-tab guard keeps this
    // from touching freshly-created "Untitled" tabs from `Scene > New Scene`,
    // which leave `scene_file` pointing at the prior scene while adding a new
    // empty tab (so `scene_tabs.len() >= 2`).
    if s.scene_tabs.len() == 1 {
        if let Some(scene_file) = s.scene_file.clone() {
            let idx = s.active_tab_index.min(s.scene_tabs.len() - 1);
            if s.scene_tabs[idx].path.is_empty() {
                let name = scene_file
                    .rsplit(['/', '\\'])
                    .next()
                    .unwrap_or(&scene_file)
                    .to_string();
                let modified = s.scene_modified;
                let tab = &mut s.scene_tabs[idx];
                tab.path = scene_file;
                tab.name = name;
                tab.modified = modified;
            }
        }
    }
    let tabs_json: Vec<String> = s
        .scene_tabs
        .iter()
        .map(|t| {
            format!(
                r#"{{"id":{},"path":"{}","name":"{}","modified":{}}}"#,
                t.id,
                t.path.replace('\\', "\\\\").replace('"', "\\\""),
                t.name.replace('\\', "\\\\").replace('"', "\\\""),
                t.modified
            )
        })
        .collect();
    send_json(
        stream,
        &format!(
            r#"{{"tabs":[{}],"active_tab_index":{}}}"#,
            tabs_json.join(","),
            s.active_tab_index
        ),
    );
}

/// `POST /api/scene/tabs/open` -- open a new scene tab.
fn api_open_scene_tab(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = parsed
        .get("path")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let name = parsed
        .get("name")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
        .unwrap_or_else(|| {
            if path.is_empty() {
                "Untitled".to_string()
            } else {
                path.rsplit('/').next().unwrap_or(&path).to_string()
            }
        });
    let mut s = state.lock().unwrap();
    // Check if already open
    if let Some(idx) = s
        .scene_tabs
        .iter()
        .position(|t| !t.path.is_empty() && t.path == path)
    {
        switch_active_tab(&mut s, idx);
        send_json(
            stream,
            &format!(
                r#"{{"ok":true,"tab_id":{},"switched":true,"active_tab_index":{}}}"#,
                s.scene_tabs[idx].id, idx
            ),
        );
        return;
    }
    let tab_id = s.next_tab_id();
    s.scene_tabs.push(SceneTab {
        id: tab_id,
        path,
        name,
        modified: false,
        inspector_history: Vec::new(),
        inspector_history_index: 0,
    });
    let new_idx = s.scene_tabs.len() - 1;
    switch_active_tab(&mut s, new_idx);
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"tab_id":{},"active_tab_index":{}}}"#,
            tab_id, s.active_tab_index
        ),
    );
}

/// Loads and instantiates a `.tscn` from `path` into a fresh `SceneTree`.
/// Mirrors the tree-building half of `api_load_scene`; reused when closing the
/// active tab has to re-display the newly-focused tab's saved scene.
fn load_tree_from_path(path: &str) -> Result<SceneTree, String> {
    let source = std::fs::read_to_string(path).map_err(|e| format!("failed to read: {e}"))?;
    let scene = PackedScene::from_tscn(&source).map_err(|e| format!("failed to parse: {e}"))?;
    let mut new_tree = SceneTree::new();
    let root_id = new_tree.root_id();
    add_packed_scene_to_tree(&mut new_tree, root_id, &scene)
        .map_err(|e| format!("failed to instance: {e}"))?;
    Ok(new_tree)
}

/// Resets editor state to a fresh, empty, untitled scene in a single tab.
/// Mirrors Godot opening a new empty scene when the last one is closed.
fn reset_to_empty_scene(s: &mut EditorState) {
    s.scene_tree = SceneTree::new();
    s.selected_node = None;
    s.selected_nodes.clear();
    s.undo_stack.clear();
    s.redo_stack.clear();
    s.inspector_history = Vec::new();
    s.inspector_history_index = 0;
    s.scene_file = None;
    s.scene_modified = false;
    s.saved_undo_depth = 0;
}

/// `POST /api/scene/tabs/close` -- close a scene tab by id.
///
/// Mirrors Godot's `Scene > Close Scene` (`EditorNode::_scene_tab_closed` ->
/// `_remove_edited_scene`): the tab is removed and focus moves to the tab on its
/// left (or the first tab when the closed one was first). Closing the *last*
/// remaining scene never leaves the editor tab-less — it opens a fresh empty,
/// untitled scene in its place. When the closed tab was the active one, the
/// newly-focused tab's saved scene is loaded so the displayed scene actually
/// changes (an unsaved/untitled tab, which this single-tree model can't restore,
/// falls back to a clean empty scene).
fn api_close_scene_tab(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let tab_id = match parsed.get("tab_id").and_then(|v| v.as_u64()) {
        Some(id) => id as u32,
        None => {
            send_error(stream, 400, "tab_id required");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    let idx = match s.scene_tabs.iter().position(|t| t.id == tab_id) {
        Some(i) => i,
        None => {
            send_error(stream, 404, "tab not found");
            return;
        }
    };

    // Godot parity: closing the last scene opens a fresh empty one in its place.
    if s.scene_tabs.len() <= 1 {
        reset_to_empty_scene(&mut s);
        let new_id = s.next_tab_id();
        s.scene_tabs = vec![SceneTab {
            id: new_id,
            path: String::new(),
            name: "Untitled".to_string(),
            modified: false,
            inspector_history: Vec::new(),
            inspector_history_index: 0,
        }];
        s.active_tab_index = 0;
        send_json(
            stream,
            &format!(r#"{{"ok":true,"active_tab_index":0,"tab_id":{new_id}}}"#),
        );
        return;
    }

    let active = s.active_tab_index;
    let was_active = idx == active;

    // Persist the live nav stack into the active tab before we remove one and
    // re-point the cursor, so every tab's saved history is current.
    let live_history = s.inspector_history.clone();
    let live_index = s.inspector_history_index;
    if let Some(tab) = s.scene_tabs.get_mut(active) {
        tab.inspector_history = live_history;
        tab.inspector_history_index = live_index;
    }
    s.scene_tabs.remove(idx);

    // Godot moves focus to the tab on the left when the active tab is closed
    // (index-1, or the first tab when it was first); closing a background tab
    // keeps the same scene focused, its index shifting left if it sat to the
    // right of the closed one.
    let new_active = if was_active {
        active.saturating_sub(1)
    } else if idx < active {
        active - 1
    } else {
        active
    };
    s.active_tab_index = new_active.min(s.scene_tabs.len() - 1);

    // Restore the now-active scene's nav stack into the live inspector.
    let (history, index) = match s.scene_tabs.get(s.active_tab_index) {
        Some(tab) => (tab.inspector_history.clone(), tab.inspector_history_index),
        None => (Vec::new(), 0),
    };
    s.inspector_history = history;
    s.inspector_history_index = index;

    // Closing the active tab changes which scene is shown: load the now-active
    // tab's saved scene from disk (or a clean empty scene for an unsaved tab).
    // Closing a background tab leaves the current scene untouched.
    if was_active {
        let new_path = s
            .scene_tabs
            .get(s.active_tab_index)
            .map(|t| t.path.clone())
            .unwrap_or_default();
        let loaded = if new_path.is_empty() {
            None
        } else {
            load_tree_from_path(&new_path).ok()
        };
        reset_to_empty_scene(&mut s);
        if let Some(tree) = loaded {
            s.scene_tree = tree;
            s.scene_file = Some(new_path);
        }
    }

    send_json(
        stream,
        &format!(r#"{{"ok":true,"active_tab_index":{}}}"#, s.active_tab_index),
    );
}

/// `POST /api/scene/tabs/switch` -- switch to a scene tab by id or index.
fn api_switch_scene_tab(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let parsed = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    if let Some(tab_id) = parsed.get("tab_id").and_then(|v| v.as_u64()) {
        if let Some(idx) = s.scene_tabs.iter().position(|t| t.id == tab_id as u32) {
            switch_active_tab(&mut s, idx);
            send_json(
                stream,
                &format!(r#"{{"ok":true,"active_tab_index":{}}}"#, idx),
            );
        } else {
            send_error(stream, 404, "tab not found");
        }
    } else if let Some(index) = parsed.get("index").and_then(|v| v.as_u64()) {
        let idx = index as usize;
        if idx < s.scene_tabs.len() {
            switch_active_tab(&mut s, idx);
            send_json(
                stream,
                &format!(r#"{{"ok":true,"active_tab_index":{}}}"#, idx),
            );
        } else {
            send_error(stream, 400, "index out of range");
        }
    } else {
        send_error(stream, 400, "tab_id or index required");
    }
}

/// `POST /api/scene/new` — create a fresh empty scene in a new tab.
///
/// Mirrors Godot's `Scene > New Scene`: it adds an "Untitled" tab backed by an
/// empty scene tree (a single bare root with no children) and makes it active.
/// The outgoing scene's live inspector navigation stack is persisted into its
/// tab first so its history survives if the user switches back to it.
fn api_new_scene(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    // Persist the outgoing scene's nav stack into its tab before we swap trees.
    let cur_history = s.inspector_history.clone();
    let cur_index = s.inspector_history_index;
    let active = s.active_tab_index;
    if let Some(tab) = s.scene_tabs.get_mut(active) {
        tab.inspector_history = cur_history;
        tab.inspector_history_index = cur_index;
    }
    // pat-s3rrv.66: `_clear` fires BEFORE the tree is swapped. Godot's doc —
    // "Clear all the state and reset the object being edited to zero. This
    // ensures your plugin does not keep editing a currently existing node, or a
    // node from the wrong scene" — is about dropping a reference, so a plugin
    // has to be told while the node it holds still exists. Calling it after the
    // swap would notify plugins about a tree that is already gone, which is the
    // very situation the hook exists to prevent.
    //
    // Broadcast, not first-claim: every plugin must drop its state, and a truthy
    // return here does not mean "handled".
    dispatch_plugin_virtual(&mut s, "_clear", &[], false);

    // Fresh empty scene: a bare root with no children. Drop any selection and
    // nav history that referenced the previous scene's now-gone nodes.
    s.scene_tree = SceneTree::new();
    s.selected_node = None;
    s.selected_nodes.clear();
    s.inspector_history = Vec::new();
    s.inspector_history_index = 0;
    // A unique "Untitled" label so multiple unsaved scenes don't collide.
    let name = unique_untitled_name(&s.scene_tabs);
    let tab_id = s.next_tab_id();
    s.scene_tabs.push(SceneTab {
        id: tab_id,
        path: String::new(),
        name: name.clone(),
        modified: false,
        inspector_history: Vec::new(),
        inspector_history_index: 0,
    });
    let new_idx = s.scene_tabs.len() - 1;
    s.active_tab_index = new_idx;
    send_json(
        stream,
        &format!(
            r#"{{"ok":true,"tab_id":{},"name":"{}","active_tab_index":{}}}"#,
            tab_id,
            name.replace('\\', "\\\\").replace('"', "\\\""),
            new_idx
        ),
    );
}

/// Picks an unused `Untitled` label for a new scene tab: `Untitled` first, then
/// `Untitled 2`, `Untitled 3`, … skipping labels already taken by open tabs.
fn unique_untitled_name(tabs: &[SceneTab]) -> String {
    let taken = |n: &str| tabs.iter().any(|t| t.name == n);
    if !taken("Untitled") {
        return "Untitled".to_string();
    }
    let mut i = 2;
    loop {
        let candidate = format!("Untitled {i}");
        if !taken(&candidate) {
            return candidate;
        }
        i += 1;
    }
}

