/// `POST /api/viewport/set_mode` — sets the viewport tool mode.
fn api_set_viewport_mode(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let mode_str = match p.get("mode").and_then(|v| v.as_str()) {
        Some(m) => m,
        None => {
            send_error(stream, 400, "missing mode");
            return;
        }
    };
    let mode = match ViewportMode::from_str_name(mode_str) {
        Some(m) => m,
        None => {
            send_error(stream, 400, "invalid mode");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    s.viewport_mode = mode;
    s.add_log("info", format!("Viewport mode: {}", mode.as_str()));
    send_json(
        stream,
        &format!(r#"{{"ok":true,"mode":"{}"}}"#, mode.as_str()),
    );
}

/// `GET /api/viewport/mode` — returns the current viewport tool mode.
fn api_get_viewport_mode(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    send_json(
        stream,
        &format!(r#"{{"mode":"{}"}}"#, s.viewport_mode.as_str()),
    );
}

/// `GET /api/node/script?node_id=<id>` — returns the script source for a node.
fn api_get_node_script(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let raw_id: u64 = match query_param(query, "node_id").and_then(|s| s.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing or invalid node_id");
            return;
        }
    };
    let s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, raw_id) {
        Some(n) => n,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    let node = s.scene_tree.get_node(nid).unwrap();
    let script_path = match node.get_property("_script_path") {
        Variant::String(sp) => sp,
        _ => {
            send_json(stream, r#"{"has_script":false,"path":"","source":""}"#);
            return;
        }
    };
    let cwd = std::env::current_dir().unwrap_or_default();
    let file_path = if let Some(stripped) = script_path.strip_prefix("res://") {
        cwd.join(stripped)
    } else {
        std::path::PathBuf::from(&script_path)
    };
    let source = std::fs::read_to_string(&file_path).unwrap_or_default();
    let json = serde_json::json!({ "has_script": true, "path": script_path, "source": source });
    send_json(stream, &json.to_string());
}

/// `GET /api/script/main_view?node_id=<id>` — the SCRIPT main-screen view for a
/// node. When the node has an attached script, returns the editable, syntax-
/// highlighted code pane wired to save: the script's `path`, on-disk `source`,
/// `editable: true`, the `save_endpoint` edits POST back to, and a `language`
/// hint so the pane highlights. A node with no script returns `has_script:
/// false` plus the empty `prompt` the pane shows in place of a code pane
/// (pat-yxe4s).
fn api_script_main_view(state: &Arc<Mutex<EditorState>>, query: &str, stream: &mut TcpStream) {
    let raw_id: u64 = match query_param(query, "node_id").and_then(|s| s.parse().ok()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing or invalid node_id");
            return;
        }
    };
    let s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, raw_id) {
        Some(n) => n,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    let node = match s.scene_tree.get_node(nid) {
        Some(n) => n,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    let script_path = match node.get_property("_script_path") {
        Variant::String(sp) if !sp.trim().is_empty() => sp,
        _ => {
            // No attached script: the pane shows the empty prompt instead of a
            // code editor.
            send_json(
                stream,
                &serde_json::json!({
                    "has_script": false,
                    "editable": false,
                    "prompt": crate::script_main_view::EMPTY_PROMPT,
                })
                .to_string(),
            );
            return;
        }
    };
    // Load the script source from disk (res:// resolves relative to cwd).
    let cwd = std::env::current_dir().unwrap_or_default();
    let file_path = if let Some(stripped) = script_path.strip_prefix("res://") {
        cwd.join(stripped)
    } else {
        std::path::PathBuf::from(&script_path)
    };
    let (source, exists) = match std::fs::read_to_string(&file_path) {
        Ok(c) => (c, true),
        Err(_) => (String::new(), false),
    };
    let lines = source.lines().count();
    send_json(
        stream,
        &serde_json::json!({
            "has_script": true,
            "path": script_path,
            "source": source,
            "exists": exists,
            "lines": lines,
            "editable": true,
            "language": "gdscript",
            "save_endpoint": "/api/script/save",
        })
        .to_string(),
    );
}

/// `GET /api/search?q=<query>` — searches all .gd script files for a string.
/// Walks `root` collecting `(path, contents)` for every file whose extension is
/// in `exts`, skipping dotfiles and `target/`.
///
/// Shared by search and replace_all so the two cannot disagree about which
/// files are in scope — a replace that considered a different file set than the
/// search that produced the preview would rewrite something the user never saw.
fn collect_searchable_files(
    root: &std::path::Path,
    exts: &[String],
    depth: usize,
    out: &mut Vec<(String, String)>,
) {
    if depth > 6 {
        return;
    }
    let Ok(entries) = std::fs::read_dir(root) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = entry.file_name().to_string_lossy().to_string();
        if name.starts_with('.') || name == "target" {
            continue;
        }
        if path.is_dir() {
            collect_searchable_files(&path, exts, depth + 1, out);
        } else {
            let matches_ext = exts
                .iter()
                .any(|e| name.ends_with(&format!(".{}", e.trim_start_matches('.'))));
            if matches_ext {
                if let Ok(content) = std::fs::read_to_string(&path) {
                    out.push((path.display().to_string(), content));
                }
            }
        }
    }
}

/// Parses the `ext` query parameter (`gd,tscn`) into a list, defaulting to `gd`.
fn parse_ext_filter(raw: Option<String>) -> Vec<String> {
    let list: Vec<String> = raw
        .unwrap_or_default()
        .split(',')
        .map(|s| s.trim().trim_start_matches('.').to_string())
        .filter(|s| !s.is_empty())
        .collect();
    if list.is_empty() {
        vec!["gd".to_string()]
    } else {
        list
    }
}

/// `GET /api/search?q=&folder=&ext=&case=` — Find in Files.
///
/// Returns results GROUPED PER FILE with line *and column* and the full line
/// text, which is what the results panel needs to render Godot's per-file
/// grouping and to open a file at the exact caret position (pat-0q2kx.168).
/// The previous shape was a flat list of `{file, line, text}` with no column
/// and no grouping, and it hardcoded `.gd` with a case-sensitive `contains`.
///
/// The matching itself delegates to `find_in_files::find_in_files`, which
/// already implemented case folding, columns and multiple matches per line —
/// it simply had no caller.
fn api_search_scripts(query: &str, stream: &mut TcpStream) {
    let search = match query_param(query, "q") {
        Some(q) => url_decode(q),
        None => {
            send_error(stream, 400, "missing q parameter");
            return;
        }
    };
    if search.is_empty() {
        send_json(stream, r#"{"results":[]}"#);
        return;
    }

    let exts = parse_ext_filter(query_param(query, "ext").map(url_decode));
    // `case=1` opts into case-sensitive matching; Godot's dialog defaults off.
    let case_sensitive = matches!(query_param(query, "case"), Some("1") | Some("true"));
    let cwd = std::env::current_dir().unwrap_or_default();
    // A `folder` scope is resolved under the project root; an absolute or
    // escaping path would let a search read outside the project.
    let root = match query_param(query, "folder").map(url_decode) {
        Some(f) if !f.is_empty() && !f.contains("..") => cwd.join(f.trim_start_matches('/')),
        _ => cwd.clone(),
    };

    let mut files = Vec::new();
    collect_searchable_files(&root, &exts, 0, &mut files);
    let borrowed: Vec<(&str, &str)> = files
        .iter()
        .map(|(p, c)| (p.as_str(), c.as_str()))
        .collect();
    let groups = crate::find_in_files::find_in_files(
        &borrowed,
        &search,
        crate::find_in_files::SearchOptions { case_sensitive },
    );

    let results: Vec<serde_json::Value> = groups
        .iter()
        .map(|g| {
            serde_json::json!({
                "file": g.path,
                "matches": g.matches.iter().map(|m| serde_json::json!({
                    "line": m.line,
                    "column": m.column,
                    "line_text": m.context,
                })).collect::<Vec<_>>(),
            })
        })
        .collect();
    let total: usize = groups.iter().map(|g| g.matches.len()).sum();
    send_json(
        stream,
        &serde_json::json!({"results": results, "total": total}).to_string(),
    );
}

/// `POST /api/search/replace_all {term, replacement, files?, case?}` —
/// Replace in Files.
///
/// Rewrites matched occurrences on disk and reports per-file counts. When
/// `files` is omitted every searchable file under the project is considered, so
/// the dialog can replace across the whole result set without echoing it back.
///
/// A file is only written when its contents actually changed, so an unaffected
/// file keeps its original mtime and bytes.
fn api_search_replace_all(body: &str, stream: &mut TcpStream) {
    let Some(payload) = parse_json_body(body) else {
        send_error(stream, 400, "invalid JSON body");
        return;
    };
    let term = payload
        .get("term")
        .and_then(|v| v.as_str())
        .unwrap_or_default()
        .to_string();
    if term.is_empty() {
        send_error(stream, 400, "missing term");
        return;
    }
    let replacement = payload
        .get("replacement")
        .and_then(|v| v.as_str())
        .unwrap_or_default()
        .to_string();
    let case_sensitive = payload
        .get("case")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let cwd = std::env::current_dir().unwrap_or_default();
    let explicit: Vec<String> = payload
        .get("files")
        .and_then(|v| v.as_array())
        .map(|a| {
            a.iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect()
        })
        .unwrap_or_default();

    let mut candidates: Vec<(String, String)> = Vec::new();
    if explicit.is_empty() {
        collect_searchable_files(&cwd, &parse_ext_filter(None), 0, &mut candidates);
    } else {
        for f in explicit {
            // Reject traversal: a replace is a write, so scope matters more here
            // than for search.
            if f.contains("..") {
                continue;
            }
            let path = if std::path::Path::new(&f).is_absolute() {
                std::path::PathBuf::from(&f)
            } else {
                cwd.join(&f)
            };
            if let Ok(content) = std::fs::read_to_string(&path) {
                candidates.push((path.display().to_string(), content));
            }
        }
    }

    let mut changed = Vec::new();
    let mut total = 0usize;
    for (path, content) in &candidates {
        let (updated, count) = replace_occurrences(content, &term, &replacement, case_sensitive);
        if count == 0 {
            continue;
        }
        if std::fs::write(path, &updated).is_ok() {
            total += count;
            changed.push(serde_json::json!({"file": path, "count": count}));
        }
    }
    send_json(
        stream,
        &serde_json::json!({"files": changed, "total": total}).to_string(),
    );
}

/// Replaces every occurrence of `term`, returning the new text and the count.
///
/// Case-insensitive mode matches on a lowercased copy but splices from the
/// ORIGINAL text, so the surrounding bytes — including their original casing —
/// are preserved exactly. Naively lowercasing the whole file would "replace"
/// by destroying every other character's case.
fn replace_occurrences(
    content: &str,
    term: &str,
    replacement: &str,
    case_sensitive: bool,
) -> (String, usize) {
    if term.is_empty() {
        return (content.to_string(), 0);
    }
    if case_sensitive {
        let count = content.matches(term).count();
        return (content.replace(term, replacement), count);
    }
    let haystack = content.to_lowercase();
    let needle = term.to_lowercase();
    let mut out = String::with_capacity(content.len());
    let mut count = 0usize;
    let mut cursor = 0usize;
    while let Some(rel) = haystack[cursor..].find(&needle) {
        let at = cursor + rel;
        out.push_str(&content[cursor..at]);
        out.push_str(replacement);
        cursor = at + needle.len();
        count += 1;
    }
    out.push_str(&content[cursor..]);
    (out, count)
}

/// Legacy flat-list walker, retained for the older callers below.
#[allow(dead_code)]
fn api_search_scripts_legacy(query: &str, stream: &mut TcpStream) {
    let search = match query_param(query, "q") {
        Some(q) => url_decode(q),
        None => {
            send_error(stream, 400, "missing q parameter");
            return;
        }
    };
    if search.is_empty() {
        send_json(stream, r#"{"results":[]}"#);
        return;
    }
    let cwd = std::env::current_dir().unwrap_or_default();
    let mut results = Vec::new();
    fn search_dir(
        dir: &std::path::Path,
        query: &str,
        results: &mut Vec<serde_json::Value>,
        depth: usize,
    ) {
        if depth > 6 {
            return;
        }
        let entries = match std::fs::read_dir(dir) {
            Ok(e) => e,
            Err(_) => return,
        };
        for entry in entries.flatten() {
            let path = entry.path();
            let name = entry.file_name().to_string_lossy().to_string();
            if name.starts_with('.') || name == "target" {
                continue;
            }
            if path.is_dir() {
                search_dir(&path, query, results, depth + 1);
            } else if name.ends_with(".gd") {
                if let Ok(content) = std::fs::read_to_string(&path) {
                    for (i, line) in content.lines().enumerate() {
                        if line.contains(query) {
                            results.push(serde_json::json!({
                                "file": path.display().to_string(),
                                "line": i + 1,
                                "text": line.trim()
                            }));
                        }
                    }
                }
            }
        }
    }
    search_dir(&cwd, &search, &mut results, 0);
    send_json(stream, &serde_json::json!({"results": results}).to_string());
}

/// `POST /api/signal/disconnect` — disconnects a signal from a node.
fn api_disconnect_signal(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let node_raw = match p.get("node_id").and_then(|v| v.as_u64()) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "missing node_id");
            return;
        }
    };
    let signal = match p.get("signal").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => {
            send_error(stream, 400, "missing signal");
            return;
        }
    };
    let mut s = state.lock().unwrap();
    let nid = match find_node_by_raw_id(&s.scene_tree, node_raw) {
        Some(n) => n,
        None => {
            send_error(stream, 404, "node not found");
            return;
        }
    };
    let node = s.scene_tree.get_node_mut(nid).unwrap();
    let connections = match node.get_property("signal_connections") {
        Variant::String(c) => c,
        _ => String::new(),
    };
    let updated: Vec<&str> = connections
        .split(';')
        .filter(|entry| !entry.is_empty() && !entry.contains(&signal))
        .collect();
    node.set_property("signal_connections", Variant::String(updated.join(";")));
    s.add_log(
        "info",
        format!("Signal disconnected: {} on node {}", signal, node_raw),
    );
    send_json(stream, r#"{"ok":true}"#);
}

/// Resolves a script `path` (either a `res://` virtual path or a filesystem
/// path) to an on-disk path, requiring a `.gd` extension. Returns `Err` with an
/// HTTP status + message on failure.
fn resolve_gd_path(raw_path: &str) -> Result<std::path::PathBuf, (u16, String)> {
    let file_path = if let Some(stripped) = raw_path.strip_prefix("res://") {
        let cwd = std::env::current_dir().unwrap_or_default();
        cwd.join(stripped)
    } else {
        std::path::PathBuf::from(raw_path)
    };
    match file_path.extension().and_then(|e| e.to_str()) {
        Some("gd") => Ok(file_path),
        _ => Err((400, "only .gd files are supported".to_string())),
    }
}

/// `POST /api/signal/goto_method` — resolves a signal connection to a navigation
/// target so the editor can open the receiver script at the connected method's
/// definition (pat-jwuv1.4). Body: `{"path","method"}`. Returns `{"script",
/// "line"}` (1-based) on success, or 404 if the method is not defined.
fn api_signal_goto_method(body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let raw_path = match p.get("path").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    let method = match p.get("method").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => {
            send_error(stream, 400, "missing method");
            return;
        }
    };
    let file_path = match resolve_gd_path(&raw_path) {
        Ok(fp) => fp,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };
    let content = match std::fs::read_to_string(&file_path) {
        Ok(c) => c,
        Err(e) => {
            send_error(stream, 404, &format!("failed to read script: {e}"));
            return;
        }
    };
    let conn = crate::signal_goto_method::Connection {
        signal: p
            .get("signal")
            .and_then(|v| v.as_str())
            .unwrap_or_default()
            .to_string(),
        target_script: raw_path.clone(),
        method: method.clone(),
    };
    match crate::signal_goto_method::navigate(&conn, &content) {
        Some(target) => {
            let json = serde_json::json!({
                "script": target.script,
                "line": target.line,
            });
            send_json(stream, &json.to_string());
        }
        None => send_error(stream, 404, "method not defined in script"),
    }
}

/// `POST /api/signal/autocreate_receiver` — appends a correctly-signatured
/// receiver method stub to the target script when the connected method does not
/// yet exist (pat-jwuv1.4). Body: `{"path","method","params":[..]}`. Returns
/// `{"created":true}` (and writes the file) when a stub was appended, or
/// `{"created":false}` when the method already exists.
fn api_signal_autocreate_receiver(body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let raw_path = match p.get("path").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    let method = match p.get("method").and_then(|v| v.as_str()) {
        Some(s) => s.to_string(),
        None => {
            send_error(stream, 400, "missing method");
            return;
        }
    };
    let params: Vec<String> = p
        .get("params")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|v| v.as_str().map(|s| s.to_string()))
                .collect()
        })
        .unwrap_or_default();
    let file_path = match resolve_gd_path(&raw_path) {
        Ok(fp) => fp,
        Err((code, msg)) => {
            send_error(stream, code, &msg);
            return;
        }
    };
    // The receiver script must exist for the connection to target it.
    let content = match std::fs::read_to_string(&file_path) {
        Ok(c) => c,
        Err(e) => {
            send_error(stream, 404, &format!("failed to read script: {e}"));
            return;
        }
    };
    let param_refs: Vec<&str> = params.iter().map(|s| s.as_str()).collect();
    match crate::signal_receiver_stub::append_receiver(&content, &method, &param_refs) {
        Some(updated) => match std::fs::write(&file_path, &updated) {
            Ok(()) => {
                let json = serde_json::json!({ "created": true, "method": method });
                send_json(stream, &json.to_string());
            }
            Err(e) => send_error(stream, 500, &format!("failed to write script: {e}")),
        },
        None => {
            let json = serde_json::json!({ "created": false, "method": method });
            send_json(stream, &json.to_string());
        }
    }
}

/// `POST /api/output/clear` — clears the script output log.
fn api_clear_output(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let mut s = state.lock().unwrap();
    s.output_entries.clear();
    send_json(stream, r#"{"ok":true}"#);
}

/// `GET /api/output` — returns script output log entries.
fn api_get_output(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let s = state.lock().unwrap();
    let entries: Vec<&String> = s.output_entries.iter().collect();
    send_json(stream, &serde_json::json!({"entries": entries}).to_string());
}

// ---------------------------------------------------------------------------
// pat-kj4: Project settings
// ---------------------------------------------------------------------------

/// `GET /api/project_settings` — returns project settings organized by category (pat-c4zlm).
// -- Project Settings ▸ Autoload (pat-0q2kx.73) -----------------------------
//
// Godot's Autoload tab adds script/scene singletons and persists them to
// `project.godot`'s `[autoload]` section. Patina's play path already consumed
// that section (`instantiate_play_autoloads`) and `autoload_manager.rs` already
// had the list logic — but nothing connected them, so the section could only be
// edited by hand.

/// Reads `project.godot` and its `[autoload]` section. Returns the manager plus
/// the file's current text, so a write can splice without losing other sections.
fn load_autoloads(root: &std::path::Path) -> (crate::autoload_manager::AutoloadManager, String) {
    let path = root.join("project.godot");
    let text = std::fs::read_to_string(path).unwrap_or_default();
    (
        crate::autoload_manager::AutoloadManager::from_project_godot_section(&text),
        text,
    )
}

/// Writes `mgr` back into `project.godot`, preserving every other section.
fn save_autoloads(
    root: &std::path::Path,
    mgr: &crate::autoload_manager::AutoloadManager,
    original: &str,
) -> std::io::Result<()> {
    std::fs::write(
        root.join("project.godot"),
        mgr.splice_into_project_godot(original),
    )
}

/// Serializes the autoload list the way the settings dialog consumes it.
fn autoloads_json(mgr: &crate::autoload_manager::AutoloadManager) -> String {
    let rows: Vec<serde_json::Value> = mgr
        .names()
        .iter()
        .filter_map(|n| mgr.get(n))
        .map(|a| serde_json::json!({ "name": a.name, "path": a.path, "enabled": a.enabled }))
        .collect();
    serde_json::json!({ "ok": true, "autoloads": rows }).to_string()
}

/// `GET /api/autoloads` — the project's autoloads, in load order.
fn api_get_autoloads(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let root = fs_project_root(state);
    let (mgr, _) = load_autoloads(&root);
    send_json(stream, &autoloads_json(&mgr));
}

/// `POST /api/autoloads` — `{"action":"add|remove|toggle|move_up|move_down",
/// "name":"Game","path":"res://game.gd","enabled":true}`.
///
/// Every action rewrites `project.godot`, so the next play picks the change up
/// without an editor restart.
fn api_post_autoloads(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let action = p.get("action").and_then(|v| v.as_str()).unwrap_or("add");
    let name = p.get("name").and_then(|v| v.as_str()).unwrap_or("").trim();
    if name.is_empty() {
        send_error(stream, 400, "missing name");
        return;
    }

    let root = fs_project_root(state);
    let (mut mgr, original) = load_autoloads(&root);

    let ok = match action {
        "add" => {
            let path = p.get("path").and_then(|v| v.as_str()).unwrap_or("").trim();
            if path.is_empty() {
                send_error(stream, 400, "missing path");
                return;
            }
            mgr.add(name, path)
        }
        "remove" => mgr.remove(name),
        "toggle" => {
            let enabled = p
                .get("enabled")
                .and_then(|v| v.as_bool())
                // Absent means "flip it", which is what a checkbox click sends.
                .unwrap_or_else(|| !mgr.get(name).map(|a| a.enabled).unwrap_or(false));
            mgr.set_enabled(name, enabled)
        }
        "move_up" => mgr.move_up(name),
        "move_down" => mgr.move_down(name),
        other => {
            send_error(stream, 400, &format!("unknown action '{other}'"));
            return;
        }
    };
    if !ok {
        // A duplicate add or an unknown name — a 409 rather than a silent no-op,
        // so the dialog can say why nothing happened.
        send_error(
            stream,
            409,
            &format!("'{action}' did not apply to '{name}'"),
        );
        return;
    }

    if let Err(e) = save_autoloads(&root, &mgr, &original) {
        send_error(stream, 500, &format!("failed to write project.godot: {e}"));
        return;
    }
    send_json(stream, &autoloads_json(&mgr));
}

