/// `POST /api/project_settings` — updates project settings (pat-c4zlm).
fn api_set_project_settings(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let json = {
        let mut s = state.lock().unwrap();
        // Application
        if let Some(v) = p.get("project_name").and_then(|v| v.as_str()) {
            s.project_name = v.to_string();
        }
        if let Some(v) = p.get("description").and_then(|v| v.as_str()) {
            s.project_description = v.to_string();
        }
        if let Some(v) = p.get("icon").and_then(|v| v.as_str()) {
            s.project_icon = v.to_string();
        }
        if let Some(v) = p.get("main_scene").and_then(|v| v.as_str()) {
            s.project_main_scene = v.to_string();
        }
        // Display
        if let Some(v) = p.get("resolution_w").and_then(|v| v.as_u64()) {
            s.project_resolution_w = v as u32;
        }
        if let Some(v) = p.get("resolution_h").and_then(|v| v.as_u64()) {
            s.project_resolution_h = v as u32;
        }
        if let Some(v) = p.get("stretch_mode").and_then(|v| v.as_str()) {
            s.project_stretch_mode = v.to_string();
        }
        if let Some(v) = p.get("stretch_aspect").and_then(|v| v.as_str()) {
            s.project_stretch_aspect = v.to_string();
        }
        if let Some(v) = p.get("fullscreen").and_then(|v| v.as_bool()) {
            s.project_fullscreen = v;
        }
        if let Some(v) = p.get("vsync").and_then(|v| v.as_bool()) {
            s.project_vsync = v;
        }
        // Input devices (pat-s3rrv.77)
        if let Some(v) = p.get("emulate_mouse_from_touch").and_then(|v| v.as_bool()) {
            s.project_emulate_mouse_from_touch = v;
        }
        if let Some(v) = p.get("emulate_touch_from_mouse").and_then(|v| v.as_bool()) {
            s.project_emulate_touch_from_mouse = v;
        }
        // Physics
        if let Some(v) = p.get("physics_fps").and_then(|v| v.as_u64()) {
            s.project_physics_fps = v as u32;
        }
        if let Some(v) = p.get("gravity").and_then(|v| v.as_f64()) {
            s.project_gravity = v;
        }
        if let Some(v) = p.get("linear_damp").and_then(|v| v.as_f64()) {
            s.project_linear_damp = v;
        }
        if let Some(v) = p.get("angular_damp").and_then(|v| v.as_f64()) {
            s.project_angular_damp = v;
        }
        // Audio
        if let Some(v) = p.get("bus_layout").and_then(|v| v.as_str()) {
            s.project_bus_layout = v.to_string();
        }
        if let Some(v) = p.get("master_volume_db").and_then(|v| v.as_f64()) {
            s.project_master_volume_db = v;
        }
        if let Some(v) = p.get("audio_input").and_then(|v| v.as_bool()) {
            s.project_audio_input = v;
        }
        // Rendering
        if let Some(v) = p.get("renderer").and_then(|v| v.as_str()) {
            s.project_renderer = v.to_string();
        }
        if let Some(v) = p.get("anti_aliasing").and_then(|v| v.as_str()) {
            s.project_anti_aliasing = v.to_string();
        }
        if let Some(v) = p.get("environment_default").and_then(|v| v.as_str()) {
            s.project_environment_default = v.to_string();
        }
        serde_json::json!({ "ok": true }).to_string()
    };
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// Audio bus layout editor (bottom-panel Audio tab, Godot AudioBusLayout parity)
// ---------------------------------------------------------------------------

/// The effect types offered by the bus "Add Effect" dropdown, matching Godot's
/// built-in `AudioEffect` list.
const AUDIO_EFFECT_TYPES: &[&str] = &[
    "Amplify",
    "BandLimit",
    "BandPass",
    "Capture",
    "Chorus",
    "Compressor",
    "Delay",
    "Distortion",
    "EQ",
    "EQ6",
    "EQ10",
    "EQ21",
    "Filter",
    "HighPass",
    "HighShelf",
    "Limiter",
    "LowPass",
    "LowShelf",
    "Notch",
    "Panner",
    "Phaser",
    "PitchShift",
    "Record",
    "Reverb",
    "SpectrumAnalyzer",
    "StereoEnhance",
];

/// Serializes the current audio bus layout (plus the available effect catalog
/// and layout file path) to the JSON the Audio panel renders from.
fn audio_layout_json(s: &EditorState) -> String {
    let buses: Vec<serde_json::Value> = s
        .audio_bus_layout
        .buses()
        .iter()
        .enumerate()
        .map(|(i, bus)| {
            let effects: Vec<serde_json::Value> = bus
                .effects
                .iter()
                .map(|fx| serde_json::json!({ "name": fx.name, "enabled": fx.enabled }))
                .collect();
            serde_json::json!({
                "index": i,
                "name": bus.name,
                "volume_db": bus.volume_db,
                "muted": bus.muted,
                "soloed": bus.soloed,
                "bypassed": bus.bypassed,
                "is_master": i == 0,
                "output": s.audio_bus_layout.output_of(i),
                "effects": effects,
            })
        })
        .collect();
    serde_json::json!({
        "ok": true,
        "layout_path": s.project_bus_layout,
        "effect_types": AUDIO_EFFECT_TYPES,
        "buses": buses,
    })
    .to_string()
}

/// Sends the current audio bus layout back to the client.
fn send_audio_layout(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let s = state.lock().unwrap();
        audio_layout_json(&s)
    };
    send_json(stream, &json);
}

/// Parses the body and reads `index` (the target bus) as a `usize`.
fn audio_body_index(body: &str) -> Option<(serde_json::Value, usize)> {
    let p = parse_json_body(body)?;
    let index = p.get("index").and_then(|v| v.as_u64())? as usize;
    Some((p, index))
}

/// `GET /api/audio/buses` — returns the full audio bus layout.
fn api_audio_get(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    send_audio_layout(state, stream);
}

/// `POST /api/audio/bus/add` — adds a new bus (default name `New Bus N`).
fn api_audio_add_bus(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let json = {
        let mut s = state.lock().unwrap();
        let name = parse_json_body(body)
            .as_ref()
            .and_then(|p| p.get("name").and_then(|v| v.as_str()).map(str::to_string))
            .unwrap_or_else(|| format!("New Bus {}", s.audio_bus_layout.len()));
        s.audio_bus_layout.add_bus(name);
        audio_layout_json(&s)
    };
    send_json(stream, &json);
}

