/// `POST /api/audio/layout/load_default` — resets to a lone `Master` bus.
/// The project's bus-layout file.
///
/// Godot stores the path in the `audio/buses/default_bus_layout` project
/// setting; `res://default_bus_layout.tres` is its default and the path the
/// runner's boot-time loader already reads
/// (`patina-runner`'s bootstrap), so writing here is what makes an edit in the
/// panel audible in Play (pat-s3rrv.52).
fn audio_layout_path(state: &EditorState) -> Option<std::path::PathBuf> {
    state
        .project_root
        .as_ref()
        .map(|root| std::path::Path::new(root).join("default_bus_layout.tres"))
}

/// `POST /api/audio/layout/save` — writes the layout to the project's
/// `default_bus_layout.tres`.
///
/// Until this existed the Save button called `logMessage(...)` and nothing
/// else: the panel's whole model lived in `EditorState` and never reached
/// disk, so nothing the user did in it could ever be heard in the game.
fn api_audio_save_layout(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let (path, text, json) = {
        let s = state.lock().unwrap();
        let Some(path) = audio_layout_path(&s) else {
            send_error(stream, 400, "no project open");
            return;
        };
        (path, s.audio_bus_layout.to_tres(), audio_layout_json(&s))
    };
    if let Err(err) = std::fs::write(&path, text) {
        send_error(
            stream,
            500,
            &format!("could not write {}: {err}", path.display()),
        );
        return;
    }
    send_json(stream, &json);
}

/// `POST /api/audio/layout/load` — replaces the layout with the project's
/// `default_bus_layout.tres`.
///
/// A missing file is NOT an error: a project that has never saved a layout is
/// the common case, and Godot shows the default layout for it rather than
/// refusing to open the panel.
fn api_audio_load_layout(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let path = {
        let s = state.lock().unwrap();
        let Some(path) = audio_layout_path(&s) else {
            send_error(stream, 400, "no project open");
            return;
        };
        path
    };
    let text = std::fs::read_to_string(&path).unwrap_or_default();
    let json = {
        let mut s = state.lock().unwrap();
        if !text.trim().is_empty() {
            s.audio_bus_layout = crate::audio_bus_layout::AudioBusLayout::from_tres(&text);
        }
        audio_layout_json(&s)
    };
    send_json(stream, &json);
}

/// `POST /api/audio/effect/swap` — reorders two effects within one bus.
///
/// Effect order is audible (a filter before a reverb is not the same sound as
/// one after it), so this is a real edit and it is what the panel's drag
/// handles post. Mirrors Godot's `AudioServer.swap_bus_effects`.
fn api_audio_swap_effects(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let Some((p, index)) = audio_body_index(body) else {
        send_error(stream, 400, "missing index");
        return;
    };
    let from = p.get("from").and_then(|v| v.as_u64());
    let to = p.get("to").and_then(|v| v.as_u64());
    let (Some(from), Some(to)) = (from, to) else {
        send_error(stream, 400, "missing from/to");
        return;
    };
    let json = {
        let mut s = state.lock().unwrap();
        if !s
            .audio_bus_layout
            .swap_effects(index, from as usize, to as usize)
        {
            send_error(stream, 400, "effect slot out of range");
            return;
        }
        audio_layout_json(&s)
    };
    send_json(stream, &json);
}

/// `GET /api/audio/peaks` — live per-bus peak levels for the panel's VU meters.
///
/// Reads the RUNNING game's mixer (`EditorState::run_main_loop`), which is the
/// only place real levels exist. The panel used to derive its meters from each
/// bus's fader value, so a meter moved when you dragged the slider and stayed
/// still when the game got loud — the opposite of what a meter reports.
///
/// With nothing playing there is no mixer to read, so the response is empty and
/// the panel shows the floor. That is the honest reading: an idle editor is
/// silent. It is NOT a stub — start a scene and these numbers move.
fn api_audio_get_peaks(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let peaks = {
        let s = state.lock().unwrap();
        s.run_main_loop
            .as_ref()
            .map(|ml| ml.audio_bridge().bus_peaks_db())
            .unwrap_or_default()
    };
    let buses: Vec<serde_json::Value> = peaks
        .iter()
        .map(|(l, r)| serde_json::json!({ "left_db": l, "right_db": r }))
        .collect();
    let playing = !buses.is_empty();
    send_json(
        stream,
        &serde_json::json!({ "playing": playing, "buses": buses }).to_string(),
    );
}

fn api_audio_load_default(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let json = {
        let mut s = state.lock().unwrap();
        s.audio_bus_layout.reset_to_default();
        audio_layout_json(&s)
    };
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// pat-db37w: Project Settings > Input Map tab (live wiring of systems_input_map)
// ---------------------------------------------------------------------------

/// `GET /api/input_map` — returns the project's input map as JSON, built from
/// the live `EditorState::input_map` via the [`InputMap`](crate::input_map::InputMap)
/// model. This is what the Project Settings > Input Map tab loads.
fn api_get_input_map(state: &Arc<Mutex<EditorState>>, stream: &mut TcpStream) {
    let state = state.lock().unwrap();
    let map = crate::input_map::InputMap::from_runtime_map(&state.input_map);
    send_json(stream, &map.to_json());
}

/// `POST /api/input_map` — edits the project's input map in the running editor.
///
/// Body commands (used by the Input Map dialog):
///   `{"action":"jump","keys":["Space"]}`  upsert an action bound to these keys
///   `{"action":"jump","remove":true}`      remove the action
///
/// Edits go through the [`InputMap`](crate::input_map::InputMap) model and are
/// projected back into `EditorState::input_map`, so the change takes effect at
/// runtime immediately (`is_action_pressed`) and survives subsequent reads.
fn api_set_input_map(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let action = match p.get("action").and_then(|v| v.as_str()) {
        Some(a) if !a.is_empty() => a.to_string(),
        _ => {
            send_error(stream, 400, "missing action");
            return;
        }
    };

    let json = {
        let mut s = state.lock().unwrap();
        let mut map = crate::input_map::InputMap::from_runtime_map(&s.input_map);
        let remove = p.get("remove").and_then(|v| v.as_bool()).unwrap_or(false);
        if remove {
            map.remove_action(&action);
        } else {
            // Replace this action's bindings with exactly the requested keys.
            map.remove_action(&action);
            map.add_action(action.clone());
            if let Some(keys) = p.get("keys").and_then(|v| v.as_array()) {
                for key in keys.iter().filter_map(|k| k.as_str()) {
                    map.bind(&action, crate::input_map::InputEvent::Key(key.to_string()));
                }
            }
        }
        s.input_map = map.to_runtime_map();
        map.to_json()
    };
    send_json(stream, &json);
}

// ---------------------------------------------------------------------------
// pat-flr: Filesystem operations
// ---------------------------------------------------------------------------

/// `POST /api/filesystem/rename` — renames a file or directory.
/// Rewrites every `[ext_resource path="<old>"]` reference to `<new>` across the
/// project, returning the `res://` paths actually changed (pat-0q2kx.70).
///
/// This is the half of Godot's `FileSystemDock::_try_move_item` that keeps
/// scenes working across a rename: without it the file moves and every scene
/// pointing at it silently loses its texture/script/mesh.
///
/// The match is on the **quoted** path (`"res://a.png"`), which is how the text
/// format writes it. Matching the bare substring would also rewrite
/// `res://a.png.import` and any longer path that merely starts with the old one.
fn remap_ext_resource_paths(root: &std::path::Path, old_res: &str, new_res: &str) -> Vec<String> {
    let mut updated = Vec::new();
    if old_res == new_res {
        return updated;
    }
    let needle = format!("\"{old_res}\"");
    let replacement = format!("\"{new_res}\"");
    for owner in file_owners(root, old_res) {
        let Ok(abs) = resolve_res_path(root, &owner) else {
            continue;
        };
        let Ok(content) = std::fs::read_to_string(&abs) else {
            continue;
        };
        if !content.contains(&needle) {
            continue;
        }
        let rewritten = content.replace(&needle, &replacement);
        if std::fs::write(&abs, rewritten).is_ok() {
            updated.push(owner);
        }
    }
    updated
}

fn api_filesystem_rename(state: &Arc<Mutex<EditorState>>, body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let old_path = match p.get("old_path").and_then(|v| v.as_str()) {
        Some(p) => p.to_string(),
        None => {
            send_error(stream, 400, "missing old_path");
            return;
        }
    };
    let new_name = match p.get("new_name").and_then(|v| v.as_str()) {
        Some(n) => n.to_string(),
        None => {
            send_error(stream, 400, "missing new_name");
            return;
        }
    };
    // pat-aivim: sandbox the existing path AND reject any `new_name` that
    // contains path separators or traversal segments — otherwise a caller
    // could rename a sandboxed file into an arbitrary location.
    let resolved = match sandbox_path(&old_path) {
        Ok(p) => p,
        Err(why) => {
            send_sandbox_violation(stream, why);
            return;
        }
    };
    if new_name.contains('/') || new_name.contains('\\') || new_name.split('/').any(|s| s == "..") {
        send_sandbox_violation(stream, "new_name contains path separator or traversal");
        return;
    }
    if !resolved.exists() {
        send_error(stream, 404, "file not found");
        return;
    }
    let cwd = std::env::current_dir().unwrap_or_default();
    let new_path = resolved.parent().unwrap_or(&cwd).join(&new_name);
    if let Err(e) = std::fs::rename(&resolved, &new_path) {
        send_error(stream, 500, &format!("rename failed: {e}"));
        return;
    }

    // FileSystemDock.files_moved (pat-s3rrv.226) — an addon connects this to
    // follow renames. Emitted only after the rename actually succeeded, and
    // with the paths a script speaks: the ORIGINAL request path and the new
    // name, not the sandbox-resolved absolute paths, which mean nothing to a
    // script and would leak the host layout.
    gdscript_interop::emit_filesystem_dock_signal(
        "files_moved",
        vec![
            gdvariant::Variant::String(old_path.clone()),
            gdvariant::Variant::String(new_name.clone()),
        ],
    );

    // Godot rewrites every dependent scene/resource as part of the move, so a
    // rename never breaks the scenes that reference the file (pat-0q2kx.70).
    // The reverse-dependency scan already existed for the file-info endpoint;
    // it just had no caller here.
    //
    // Both `res://` forms come from the request rather than from the filesystem:
    // the old file no longer exists to canonicalize, and the caller's path is
    // exactly the string the scenes were written with.
    let root = fs_project_root(state);
    let old_res = normalize_res_path(&old_path);
    let new_res = {
        let rel = old_res.trim_start_matches("res://");
        match rel.rsplit_once('/') {
            Some((dir, _)) => format!("res://{dir}/{new_name}"),
            None => format!("res://{new_name}"),
        }
    };
    let updated = remap_ext_resource_paths(&root, &old_res, &new_res);

    let list = updated
        .iter()
        .map(|s| format!(r#""{}""#, s.replace('\\', "\\\\").replace('"', "\\\"")))
        .collect::<Vec<_>>()
        .join(",");
    send_json(
        stream,
        &format!(r#"{{"ok":true,"updated_files":[{list}]}}"#),
    );
}

/// Ensures a caller-supplied path carries the `res://` prefix.
fn normalize_res_path(path: &str) -> String {
    if path.starts_with("res://") {
        path.to_string()
    } else {
        format!("res://{}", path.trim_start_matches('/'))
    }
}

/// `POST /api/filesystem/delete` — deletes a file or empty directory.
fn api_filesystem_delete(body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = match p.get("path").and_then(|v| v.as_str()) {
        Some(p) => p.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    // pat-aivim: sandbox the target to the project root.
    let resolved = match sandbox_path(&path) {
        Ok(p) => p,
        Err(why) => {
            send_sandbox_violation(stream, why);
            return;
        }
    };
    if !resolved.exists() {
        send_error(stream, 404, "file not found");
        return;
    }
    let result = if resolved.is_dir() {
        std::fs::remove_dir(&resolved)
    } else {
        std::fs::remove_file(&resolved)
    };
    match result {
        Ok(_) => send_json(stream, r#"{"ok":true}"#),
        Err(e) => send_error(stream, 500, &format!("delete failed: {e}")),
    }
}

/// `POST /api/filesystem/mkdir` — creates a new directory.
fn api_filesystem_mkdir(body: &str, stream: &mut TcpStream) {
    let p = match parse_json_body(body) {
        Some(v) => v,
        None => {
            send_error(stream, 400, "invalid JSON");
            return;
        }
    };
    let path = match p.get("path").and_then(|v| v.as_str()) {
        Some(p) => p.to_string(),
        None => {
            send_error(stream, 400, "missing path");
            return;
        }
    };
    // pat-aivim: sandbox the target to the project root.
    let resolved = match sandbox_path(&path) {
        Ok(p) => p,
        Err(why) => {
            send_sandbox_violation(stream, why);
            return;
        }
    };
    match std::fs::create_dir_all(&resolved) {
        Ok(_) => send_json(stream, r#"{"ok":true}"#),
        Err(e) => send_error(stream, 500, &format!("mkdir failed: {e}")),
    }
}

